module.exports = "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>黄金震荡指数 - 网格马丁行情判断</title>\n<style>\n  :root{--bg:#0b0e14;--card:#121620;--card2:#161b26;--bd:#212838;--tx:#e6eaf2;--mut:#7d899e;--gold:#eab308;--green:#10b981;--red:#f43f5e;--yel:#f59e0b}\n  *{box-sizing:border-box}\n  html{scroll-behavior:smooth}\n  body{margin:0;background:var(--bg);color:var(--tx);font:14px/1.55 -apple-system,BlinkMacSystemFont,\"Segoe UI\",\"Microsoft YaHei\",sans-serif}\n  header{position:sticky;top:0;z-index:50;background:rgba(11,14,20,0.92);backdrop-filter:blur(10px);display:flex;flex-wrap:nowrap;gap:12px;align-items:center;justify-content:space-between;padding:10px 24px;border-bottom:1px solid var(--bd)}\n  header>div:first-child{min-width:0;flex:1}\n  h1{margin:0;font-size:18px;color:#f8fafc;letter-spacing:.3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n  h1 b{color:var(--gold)}\n  .sub{color:var(--mut);font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n  .btns{display:flex;gap:8px;flex-wrap:wrap;align-items:center}\n  header .btns{flex-wrap:nowrap;flex-shrink:0}\n  button{background:var(--card2);color:var(--tx);border:1px solid var(--bd);padding:7px 13px;border-radius:7px;cursor:pointer;font-size:12.5px;transition:all .15s;white-space:nowrap}\n  button:hover{border-color:var(--gold);color:#fff}\n  button.pri{background:var(--gold);color:#141004;border-color:var(--gold);font-weight:600}\n  button.pri:hover{filter:brightness(1.08);color:#000}\n  button.on{background:rgba(234,179,8,0.15);color:var(--gold);border-color:rgba(234,179,8,0.5);font-weight:600}\n  button:disabled{opacity:.5;cursor:wait}\n  .layout{display:grid;grid-template-columns:224px minmax(0,1fr);max-width:1680px;margin:0 auto}\n  aside.sidenav{position:sticky;top:61px;height:calc(100vh - 61px);overflow-y:auto;overflow-x:hidden;padding:12px 10px;border-right:1px solid var(--bd);background:#0e121a;display:flex;flex-direction:column;gap:2px;scrollbar-width:thin;scrollbar-color:#212838 transparent}\n  aside.sidenav:hover{scrollbar-color:rgba(234,179,8,0.45) transparent}\n  aside.sidenav::-webkit-scrollbar{width:4px}\n  aside.sidenav::-webkit-scrollbar-track{background:transparent}\n  aside.sidenav::-webkit-scrollbar-thumb{background:rgba(125,137,158,0.2);border-radius:99px}\n  aside.sidenav:hover::-webkit-scrollbar-thumb{background:rgba(234,179,8,0.5)}\n  /* 全局与监控框极细暗黑滚动条美化（解决特朗普言论监控等区域右侧滚动条生硬问题） */\n  *{scrollbar-width:thin;scrollbar-color:#232b3d transparent}\n  *::-webkit-scrollbar{width:5px;height:5px}\n  *::-webkit-scrollbar-track{background:rgba(11,14,20,0.35);border-radius:99px}\n  *::-webkit-scrollbar-thumb{background:rgba(125,137,158,0.22);border-radius:99px;transition:background .2s}\n  *::-webkit-scrollbar-thumb:hover{background:rgba(234,179,8,0.58)}\n  .thin-scroll{scrollbar-width:thin;scrollbar-color:#263044 transparent}\n  .thin-scroll:hover{scrollbar-color:rgba(234,179,8,0.5) transparent}\n  aside.sidenav .ng{font-size:11px;color:#5c667a;margin:10px 8px 3px;font-weight:600;letter-spacing:.6px;text-transform:uppercase}\n  aside.sidenav .ng:first-child{margin-top:0}\n  aside.sidenav a{display:flex;justify-content:space-between;align-items:center;gap:6px;padding:6px 9px;border-radius:6px;color:#b8c2d4;text-decoration:none;font-size:12.5px;border:1px solid transparent;transition:all .15s;min-width:0}\n  aside.sidenav a span:first-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n  aside.sidenav a:hover,aside.sidenav a.active{background:var(--card2);border-color:#2c364b;color:#fff}\n  main{padding:18px 22px;display:grid;gap:16px;min-width:0}\n  @media(max-width:960px){.layout{grid-template-columns:1fr}aside.sidenav{position:static;height:auto;flex-direction:row;flex-wrap:wrap;border-right:none;border-bottom:1px solid var(--bd)}.sidenav .ng{width:100%}header{flex-wrap:wrap}}\n  section[id],div[id^=\"ind-\"]{scroll-margin-top:72px}\n  .card{background:var(--card);border:1px solid var(--bd);border-radius:12px;padding:16px 18px;overflow:hidden;min-width:0}\n  .card h2{margin:0 0 12px;font-size:15px;color:#f1f5f9;font-weight:600;word-break:break-word;display:flex;align-items:center;gap:8px;flex-wrap:wrap}\n  .screen-card{min-height:calc(100vh - 92px);display:flex;flex-direction:column;justify-content:space-between;padding:18px 20px}\n  .chart-wrap{flex:1;min-height:420px;display:flex;flex-direction:column;margin:10px 0}\n  .big-svg{width:100%;height:calc(100vh - 295px);min-height:400px;max-height:660px;display:block;background:#0d1118;border:1px solid var(--bd);border-radius:10px;cursor:crosshair;user-select:none}\n  /* 语义色克制化：仅核心结论使用柔和描边胶囊，辅助标签全部使用低调深灰 */\n  .RANGE{background:rgba(16,185,129,0.12);color:#34d399;border:1px solid rgba(16,185,129,0.28)}\n  .TREND{background:rgba(244,63,94,0.13);color:#fb7185;border:1px solid rgba(244,63,94,0.3)}\n  .MIXED{background:rgba(245,158,11,0.12);color:#fbbf24;border:1px solid rgba(245,158,11,0.28)}\n  .NEUT{background:#181f2c;color:#94a3b8;border:1px solid #263042}\n  .UP{background:#161e2b;color:#34d399;border:1px solid #233142}\n  .DOWN{background:#161e2b;color:#fb7185;border:1px solid #233142}\n  /* 核心三大焦点看板 */\n  .hero-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(290px,1fr));gap:14px;margin-bottom:14px}\n  .hero-box{background:var(--card2);border:1px solid var(--bd);border-radius:10px;padding:16px;position:relative;overflow:hidden;min-width:0}\n  .hero-box.hl-green{border-top:3px solid var(--green)}\n  .hero-box.hl-yel{border-top:3px solid var(--yel)}\n  .hero-box.hl-red{border-top:3px solid var(--red)}\n  .hero-box.hl-gold{border-top:3px solid var(--gold)}\n  .hero-lbl{font-size:12px;color:var(--mut);font-weight:500;display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:6px}\n  .hero-val{font-size:38px;font-weight:800;line-height:1.1;letter-spacing:-.5px;color:#fff;margin:4px 0 8px;display:flex;align-items:baseline;gap:8px;flex-wrap:wrap}\n  /* 前排异动监控卡片 */\n  .anom-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:10px;margin-top:10px}\n  .anom-card{background:#151924;border:1px solid var(--bd);border-left:3px solid var(--yel);border-radius:8px;padding:10px 12px;display:flex;flex-direction:column;gap:4px;cursor:pointer;transition:transform .12s,border-color .12s}\n  .anom-card:hover{border-color:var(--gold);transform:translateY(-1px)}\n  .anom-card.sev-high{background:rgba(244,63,94,0.06);border-color:rgba(244,63,94,0.28);border-left:3px solid var(--red)}\n  .anom-card.sev-med{background:rgba(245,158,11,0.05);border-color:rgba(245,158,11,0.25);border-left:3px solid var(--yel)}\n  .vgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:14px}\n  .vbox{background:var(--card2);border:1px solid var(--bd);border-radius:10px;padding:14px;overflow:hidden;min-width:0}\n  .vhead{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;flex-wrap:wrap;gap:8px;min-width:0}\n  .vnum{font-size:32px;font-weight:800;line-height:1.15;word-break:break-word}\n  .fcgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(215px,1fr));gap:12px}\n  .fccard{background:var(--card2);border:1px solid var(--bd);border-radius:10px;padding:12px;display:flex;flex-direction:column;gap:8px;overflow:hidden;min-width:0}\n  .fchead{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;border-bottom:1px solid var(--bd);padding-bottom:6px}\n  .fcscore{font-size:24px;font-weight:700;color:#fff}\n  .fcparts{display:grid;grid-template-columns:1fr 1fr;gap:4px 8px;font-size:12px;color:var(--mut)}\n  .fcevs{font-size:11px;color:var(--mut);border-top:1px solid var(--bd);padding-top:6px;margin-top:auto;word-break:break-word}\n  .tfidx-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(215px,1fr));gap:10px;margin-top:12px}\n  .tfcard{background:var(--card2);border:1px solid var(--bd);border-radius:10px;padding:12px;cursor:pointer;transition:border-color .15s;overflow:hidden;min-width:0}\n  .tfcard:hover{border-color:#3b4760}\n  /* 大图顶部标签栏严格水平对齐且自适应防溢出 */\n  .meta-strip{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:10px}\n  .mchip{display:inline-flex;align-items:center;flex-wrap:wrap;gap:6px;min-height:32px;padding:4px 11px;max-width:100%;background:var(--card2);border:1px solid var(--bd);border-radius:7px;font-size:12.5px;line-height:1.2}\n  .mchip b{font-size:13.5px;color:#fff}\n  .mchip .big-num{font-size:19px;font-weight:800;color:var(--gold)}\n  .grid3{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:16px}\n  table{width:100%;border-collapse:collapse}\n  th,td{padding:7px 9px;text-align:left;border-bottom:1px solid var(--bd);font-size:13px}\n  th{color:var(--mut);font-weight:500;font-size:12px}\n  .pill{padding:0 8px;min-height:21px;line-height:19px;border-radius:6px;font-size:11.5px;font-weight:600;display:inline-flex;align-items:center;vertical-align:middle;max-width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex-shrink:0}\n  .live-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--green);margin-right:5px;box-shadow:0 0 6px var(--green)}\n  ul{margin:6px 0 0;padding-left:18px;color:var(--mut)}\n  .err{color:#fb7185}\n  .star{color:var(--gold)}\n  .imp{background:rgba(234,179,8,0.06)}\n  .tfblock{margin-bottom:18px;padding-bottom:14px;border-bottom:1px solid var(--bd)}.tfblock:last-child{border-bottom:none}.tfh{margin-bottom:10px;font-size:14px;display:flex;flex-wrap:wrap;gap:8px;align-items:center}\n  .gauges{display:grid;grid-template-columns:repeat(auto-fit,minmax(265px,1fr));gap:12px 18px}\n  .g{min-width:0;padding:8px 10px;background:var(--card2);border:1px solid var(--bd);border-radius:8px}\n  .g.g-warn{border-color:rgba(245,158,11,0.35)}\n  .g.g-err{border-color:rgba(244,63,94,0.4);background:rgba(244,63,94,0.04)}\n  .g .gh{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:4px 8px;font-size:12.5px;margin-bottom:6px}\n  .g .gh a{color:#cbd5e1;text-decoration:none}\n  .g .gh a:hover{color:var(--gold)}\n  /* 进度条降噪：底槽柔和暗色，仅游标与当前段突出 */\n  .bar{position:relative;display:flex;height:8px;border-radius:99px;background:#1a2130;overflow:visible}\n  .bar>div:not(.mk){height:100%;opacity:.22;transition:opacity .2s}.bar>div:first-child{border-radius:99px 0 0 99px}.bar>div:nth-last-child(2){border-radius:0 99px 99px 0}\n  .bar>div.z-active{opacity:.85}\n  .mk{position:absolute;top:-4px;width:6px;height:16px;margin-left:-3px;background:#fff;border-radius:3px;box-shadow:0 0 6px rgba(255,255,255,0.9),0 0 2px #000}\n  .ticks{position:relative;height:13px;font-size:10px;color:#5c667a;margin-top:3px}.ticks span{position:absolute;transform:translateX(-50%)}\n  .zp{padding:1px 7px;border-radius:5px;font-size:11px;font-weight:600}\n  .sm{font-size:12px}\n  .legend{display:flex;gap:14px;flex-wrap:wrap;font-size:12px;color:var(--mut);align-items:center}.legend i{display:inline-block;width:10px;height:10px;border-radius:3px;margin-right:4px;vertical-align:middle}\n  .mut{color:var(--mut)}\n  .num{color:var(--tx);text-decoration:none;border-bottom:1px dotted rgba(234,179,8,0.4)}.num:hover{color:var(--gold)}\n  th a,.card h2 a{color:#f1f5f9;text-decoration:none;border-bottom:1px dashed var(--mut)}\n  .tol-bar{display:flex;flex-wrap:wrap;gap:12px;align-items:center;background:var(--card2);border:1px solid var(--bd);border-radius:10px;padding:10px 14px;margin-bottom:10px}\n  .tol-slider{width:200px;accent-color:var(--gold);cursor:pointer;height:5px}\n  .tol-presets button{padding:4px 9px;font-size:12px}\n  details.clean-fold>summary{cursor:pointer;color:var(--mut);font-size:12px;user-select:none;padding:4px 0}\n  details.clean-fold>summary:hover{color:var(--tx)}\n  /* 仅针对 1M/5M 震荡指数与价格数字本身的持续背景高亮动画 */\n  .num-chip{display:inline-block;padding:1px 6px;border-radius:6px;transition:background-color .2s}\n  @keyframes numFlashBg {\n    0%   { background-color: rgba(16, 185, 129, 0.5); color: #fff; box-shadow: 0 0 10px rgba(16, 185, 129, 0.6); }\n    45%  { background-color: rgba(234, 179, 8, 0.4); color: #fff; }\n    85%  { background-color: rgba(16, 185, 129, 0.18); }\n    100% { background-color: transparent; }\n  }\n  .flash-num { animation: numFlashBg 4.5s ease-out; }\n  #toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:var(--green);color:#04170f;padding:10px 20px;border-radius:8px;display:none;font-weight:600;z-index:100}\n</style>\n</head>\n<body>\n<header>\n  <div>\n    <h1>🥇 <b>黄金震荡指数</b> <span class=\"mut sm\" style=\"font-weight:400\">· 网格马丁量化决策台</span></h1>\n    <div class=\"sub\" id=\"meta\">加载中…</div>\n  </div>\n  <div class=\"btns\" style=\"align-items:center\">\n    <div style=\"display:flex;align-items:center;gap:6px;background:#111722;border:1px solid var(--bd);padding:4px 9px;border-radius:8px;font-size:12px\">\n      <button id=\"btnVoiceToggle\" class=\"sm\" onclick=\"toggleVoiceAlert()\" style=\"padding:3px 8px;font-weight:700\">🔊 语音报警: 开</button>\n      <span class=\"mut xs\">敏感度:</span>\n      <select id=\"voiceSensSelect\" onchange=\"updateVoiceCfg()\" style=\"background:var(--bg);color:var(--gold);border:1px solid var(--bd);border-radius:5px;padding:2px 5px;font-size:11.5px;font-weight:700\" title=\"自行设定语音报警触发敏感度，避免频繁打扰\">\n        <option value=\"1\">Lv1 仅极高危保命 (推荐)</option>\n        <option value=\"2\">Lv2 中高危均衡报警</option>\n        <option value=\"3\">Lv3 高灵敏盯盘模式</option>\n        <option value=\"0\">Lv0 仅手动重磅倒计时锁</option>\n      </select>\n      <span class=\"mut xs\">冷却:</span>\n      <select id=\"voiceCoolSelect\" onchange=\"updateVoiceCfg()\" style=\"background:var(--bg);color:#cbd5e1;border:1px solid var(--bd);border-radius:5px;padding:2px 5px;font-size:11.5px\" title=\"同一类型预警在冷却时间内不重复播报\">\n        <option value=\"15\">15分钟</option>\n        <option value=\"5\">5分钟</option>\n        <option value=\"30\">30分钟</option>\n        <option value=\"60\">60分钟</option>\n      </select>\n      <button class=\"sm\" onclick=\"testVoiceAlert()\" style=\"padding:2px 7px\" title=\"测试浏览器中文语音播报是否正常\">🔈 试听</button>\n    </div>\n    <button id=\"btnMt4Guide\" onclick=\"toggleMt4Guide()\" style=\"border-color:rgba(56,189,248,0.55);color:#38bdf8;font-weight:800\" title=\"点击打开 MT4 实盘数据实时同步接入指南与下载脚本\">🔌 MT4实盘同步(点击接入)</button>\n    <button id=\"btnFast\">⚡ 立即刷新实时数据</button>\n    <button class=\"pri\" id=\"btnFetch\">🔄 全量刷新</button>\n    <button class=\"pri\" id=\"btnCopy\">📋 一键复制(发给AI)</button>\n  </div>\n</header>\n<div class=\"layout\">\n  <aside class=\"sidenav\" id=\"sidenav\">\n    <div class=\"ng\">核心决策</div>\n    <a href=\"#masterDecisionSec\"><span>🧭 一锤定音总决策</span><span id=\"nav-master\" class=\"pill RANGE\">-</span></a>\n    <a href=\"#mt4CurveSec\"><span>💰 MT4余额/净值/收益图</span><span id=\"nav-mt4\" class=\"pill NEUT\">未连</span></a>\n    <a href=\"#topSessionSec\"><span>🕒 时段 & 重磅红灯锁</span><span id=\"nav-sess\" class=\"pill NEUT\">-</span></a>\n    <a href=\"#tolSec\"><span>🛡️ 净敞口推演(可开关)</span><span id=\"nav-ea\" class=\"pill NEUT\">关</span></a>\n    <a href=\"#anomalySec\"><span>⚡ 实时异动监控</span><span id=\"nav-anom\" class=\"pill NEUT\">0项</span></a>\n    <a href=\"#keyLevelsSec\"><span>🎯 清算位插针雷区</span><span id=\"nav-klv\" class=\"pill NEUT\">-</span></a>\n    <a href=\"#verdict\"><span>📊 核心震荡总览</span><span id=\"nav-run\" class=\"pill MIXED\">-</span></a>\n    <a href=\"#entrySec\"><span>🚦 是否适合入场图</span><span id=\"nav-entry\" class=\"pill MIXED\">-</span></a>\n    <a href=\"#forecastSec\"><span>🔮 未来5日预测</span></a>\n    <div class=\"ng\">大图趋势 (一图一屏)</div>\n    <a href=\"#chart-1M\"><span>📈 1M 震荡大图 ⚡</span><span id=\"nav-1M\" class=\"pill NEUT\">-</span></a>\n    <a href=\"#chart-5M\"><span>📈 5M 震荡大图 ⚡</span><span id=\"nav-5M\" class=\"pill NEUT\">-</span></a>\n    <a href=\"#chart-15M\"><span>📈 15M 震荡大图</span><span id=\"nav-15M\" class=\"pill NEUT\">-</span></a>\n    <a href=\"#chart-1H\"><span>📈 1H 震荡大图</span><span id=\"nav-1H\" class=\"pill NEUT\">-</span></a>\n    <a href=\"#chart-4H\"><span>📈 4H 震荡大图</span><span id=\"nav-4H\" class=\"pill NEUT\">-</span></a>\n    <div class=\"ng\">分周期指标明细</div>\n    <a href=\"#ind-1M\"><span>🎛️ 1M 指标进度条</span></a>\n    <a href=\"#ind-5M\"><span>🎛️ 5M 指标进度条</span></a>\n    <a href=\"#ind-15M\"><span>🎛️ 15M 指标进度条</span></a>\n    <a href=\"#ind-1H\"><span>🎛️ 1H 指标进度条</span></a>\n    <a href=\"#ind-4H\"><span>🎛️ 4H 指标进度条</span></a>\n    <a href=\"#ind-1D\"><span>🎛️ 1D 日线指标</span></a>\n    <div class=\"ng\">情绪、宏观与日历</div>\n    <a href=\"#sentimentSec\"><span>📊 散户反指情绪</span><span id=\"nav-sent\" class=\"pill NEUT\">-</span></a>\n    <a href=\"#attentionSec\"><span>🔥 黄金受关注度</span><span id=\"nav-attn\" class=\"pill NEUT\">-</span></a>\n    <a href=\"#trumpSec\"><span>🦅 特朗普言论监控</span><span id=\"nav-trump\" class=\"pill NEUT\">-</span></a>\n    <a href=\"#macroSec\"><span>🌐 跨市场长周期备查</span><span id=\"nav-macro\" class=\"pill NEUT\">-</span></a>\n    <a href=\"#sessionSec\"><span>🕒 时段说明 & GVZ</span></a>\n    <a href=\"#calSec\"><span>📅 金十经济周历</span></a>\n    <a href=\"#sources\"><span>🔗 数据源验证</span></a>\n  </aside>\n  <main>\n    <section class=\"card\" id=\"topSessionSec\">\n      <div id=\"topSessionDynamic\"></div>\n      <div id=\"topEventEditorBar\" style=\"margin-top:12px;padding:10px 12px;background:rgba(15,20,30,0.92);border:1px solid rgba(244,63,94,0.4);border-radius:9px\">\n        <div style=\"display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:8px\">\n          <div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap\">\n            <b style=\"color:#fda4af;font-size:13px\">⏱️ 重磅数据「前 30 分钟 ~ 后 15 分钟」自动红灯倒计时锁（支持添加多个 · 直接投射至上方24h时间轴）</b>\n            <span id=\"customLockStatusBadge\" class=\"pill RANGE\">🟢 当前无激活的红灯锁</span>\n          </div>\n          <div id=\"voiceLastLog\" class=\"xs mut\" style=\"margin-left:auto\">🔊 语音就绪：触发高危阈值或进入数据前30分钟将自动播报</div>\n        </div>\n        <div id=\"customEventList\" style=\"display:flex;flex-wrap:wrap;gap:8px;margin-bottom:8px\"></div>\n        <div style=\"display:flex;align-items:center;flex-wrap:wrap;gap:8px;font-size:12px\">\n          <label style=\"font-weight:700;color:#fff\">➕ 手动新增锁定时点(北京时间):</label>\n          <input type=\"time\" id=\"newEvTimeInput\" value=\"20:30\" style=\"background:var(--bg);color:var(--gold);border:1px solid var(--gold);padding:4px 8px;border-radius:6px;font-size:13px;font-weight:800\">\n          <input type=\"text\" id=\"newEvTitleInput\" placeholder=\"输入重磅事件名称，如：美国CPI / 初请失业金 / 非农 / 鲍威尔讲话\" style=\"width:270px;background:var(--bg);color:#fff;border:1px solid var(--bd);padding:5px 8px;border-radius:6px;font-size:12.5px\">\n          <label class=\"xs mut\" style=\"display:flex;align-items:center;gap:3px\">提前锁(分):<input type=\"number\" id=\"newEvPreInput\" value=\"30\" min=\"5\" max=\"120\" step=\"5\" style=\"width:44px;background:var(--bg);color:#fff;border:1px solid var(--bd);padding:3px 4px;border-radius:4px\"></label>\n          <label class=\"xs mut\" style=\"display:flex;align-items:center;gap:3px\">延后锁(分):<input type=\"number\" id=\"newEvPostInput\" value=\"15\" min=\"5\" max=\"120\" step=\"5\" style=\"width:44px;background:var(--bg);color:#fff;border:1px solid var(--bd);padding:3px 4px;border-radius:4px\"></label>\n          <button class=\"pri sm\" onclick=\"addCustomLockEvent()\">➕ 添加至时间轴红灯锁</button>\n          <div class=\"btns\" style=\"margin-left:auto\">\n            <button class=\"sm\" onclick=\"quickAddLockEvent('20:30','美国20:30重磅数据(CPI/初请/非农)')\">+20:30美盘数据</button>\n            <button class=\"sm\" onclick=\"quickAddLockEvent('21:45','美国21:45 PMI数据')\">+21:45 PMI</button>\n            <button class=\"sm\" onclick=\"quickAddLockEvent('22:00','美国22:00 ISM/信心指数/联储官员')\">+22:00美盘数据</button>\n            <button class=\"sm\" onclick=\"quickAddLockEvent('02:00','美联储02:00利率决议/纪要')\">+02:00美联储</button>\n            <button class=\"sm\" onclick=\"importJin10TodayLocks()\" title=\"自动把今日金十周历中★★★以上美国/重磅数据一键加入红灯锁\">📥 导入今日金十★★★</button>\n            <button class=\"sm\" onclick=\"clearCustomLockEvents()\" style=\"color:#fb7185\">🗑️ 清空</button>\n          </div>\n        </div>\n      </div>\n    </section>\n    <section class=\"card\" id=\"mt4GuideSec\" style=\"display:none;border:1.5px solid rgba(56,189,248,0.55);background:linear-gradient(135deg,rgba(14,116,144,0.14),rgba(15,20,30,0.97))\">\n      <div class=\"vhead\" style=\"margin-bottom:10px\">\n        <div style=\"display:flex;align-items:center;gap:10px;flex-wrap:wrap\">\n          <h2 style=\"margin:0;color:#38bdf8\">🔌 MT4 实盘账户 & 马丁持仓实时同步接入中心 (每 3 秒自动推送 · 100%只读零交易干预)</h2>\n          <span id=\"mt4StatusPill\" class=\"pill NEUT\">等待 MT4 脚本推送数据...</span>\n        </div>\n        <div class=\"btns\">\n          <button class=\"pri sm\" onclick=\"downloadMt4Script('script')\" style=\"background:#0284c7;border-color:#38bdf8;color:#fff;font-weight:800\" title=\"放入 MQL4\\Scripts，可与马丁EA挂在同一张图\">📥 下载【脚本版】GoldDashboardSyncScript.mq4 → Scripts</button>\n          <button class=\"sm\" onclick=\"copyMt4ScriptCode('script')\" style=\"border-color:#38bdf8;color:#38bdf8;font-weight:700\">📋 复制脚本版源码</button>\n          <button class=\"pri sm\" onclick=\"downloadMt4Script('ea')\" style=\"background:#7c3aed;border-color:#a78bfa;color:#fff;font-weight:800\" title=\"放入 MQL4\\Experts，需单独一张图表\">📥 下载【EA版】GoldDashboardSync.mq4 → Experts</button>\n          <button class=\"sm\" onclick=\"copyMt4ScriptCode('ea')\" style=\"border-color:#a78bfa;color:#a78bfa;font-weight:700\">📋 复制EA版源码</button>\n          <button class=\"sm\" onclick=\"simulateMt4Push()\" title=\"模拟推送一笔假测试账号数据(#8861092)，仅用于预览界面效果\">🧪 模拟演示数据</button>\n          <button class=\"sm\" onclick=\"clearMt4Data()\" style=\"color:#fb7185;border-color:rgba(244,63,94,0.45)\" title=\"清除模拟测试数据，等待您的真实MT4账号推送\">🗑️ 清除测试数据</button>\n          <button class=\"sm\" onclick=\"toggleMt4Guide()\">✖ 收起面板</button>\n        </div>\n      </div>\n      <div id=\"mt4LiveDetailBar\" style=\"margin-bottom:10px;padding:9px 12px;background:rgba(12,16,24,0.88);border:1px solid rgba(56,189,248,0.35);border-radius:8px;font-size:12.5px;color:#cbd5e1\">\n        ⚪ 当前尚未收到 MT4 终端推送。按下方 <b>3 步极简配置（仅需 1 分钟）</b> 挂上只读同步脚本后，您的 <b>账户余额、净值、Buy/Sell 各几层、各多少手、多空持仓均价、实时浮盈亏、回本止盈目标价</b> 将每 3 秒自动同步到本网站全部决策模块！\n      </div>\n      <div class=\"grid3\" style=\"gap:10px;font-size:12px;line-height:1.6\">\n        <div style=\"background:rgba(15,20,30,0.9);border:1px solid var(--bd);border-radius:8px;padding:10px 12px\">\n          <b style=\"color:var(--gold);font-size:13px\">第一步：添加 MT4 WebRequest 白名单</b>\n          <div style=\"margin-top:5px;color:#cbd5e1\">\n            1. 打开您的 MT4 顶部菜单：<b>工具(T) → 选项(O) → EA交易</b><br>\n            2. 勾选 <b style=\"color:#34d399\">☑ 允许 WebRequest 用于所列 URL</b><br>\n            3. 双击下方空白行，粘贴本网站地址并回车：<br>\n            <code id=\"mt4WhitelistUrl\" style=\"display:inline-block;margin-top:4px;padding:2px 7px;background:#090d14;border:1px solid #38bdf8;border-radius:4px;color:#38bdf8;font-weight:800;user-select:all\">http://localhost:3000</code>\n            <button class=\"sm\" onclick=\"copyMt4WhitelistUrl()\" style=\"padding:1px 6px;margin-left:4px;font-size:11px\">复制地址</button>\n          </div>\n        </div>\n        <div style=\"background:rgba(15,20,30,0.9);border:1px solid var(--bd);border-radius:8px;padding:10px 12px\">\n          <b style=\"color:var(--gold);font-size:13px\">第二步：放入只读同步脚本并编译</b>\n          <div style=\"margin-top:5px;color:#cbd5e1\">\n            1. 点击右上角下载：<b style=\"color:#38bdf8\">【脚本版】→ 放入 MQL4\\Scripts</b>（可与马丁EA挂同一张图）；或 <b style=\"color:#a78bfa\">【EA版】→ 放入 MQL4\\Experts</b>（需单独图表）。<b style=\"color:#fda4af\">两个文件不要放错文件夹！</b><br>\n            2. 在 MT4 点击 <b>文件(F) → 打开数据文件夹 → MQL4 → Experts</b>，把文件放进去<br>\n            3. 在 MT4 左侧「导航器 → EA交易」右键点击 <b>刷新</b>（或双击用 MetaEditor 按 F7 编译）\n          </div>\n        </div>\n        <div style=\"background:rgba(15,20,30,0.9);border:1px solid var(--bd);border-radius:8px;padding:10px 12px\">\n          <b style=\"color:var(--gold);font-size:13px\">第三步：新开一张空白 XAUUSD 图表挂载（不顶替原马丁EA！）</b>\n          <div style=\"margin-top:5px;color:#cbd5e1\">\n            💡 <b>关键技巧</b>：MT4 单张图表只能挂 1 个 EA。为了<b>完全不影响您正在跑的马丁 EA</b>：<br>\n            1. 在 MT4 新打开<b>第 2 张空白的 XAUUSD 图表窗口</b>（周期任意）<br>\n            2. 把 <b style=\"color:#34d399\">GoldDashboardSync</b> 拖到这张新图表上点确定！<br>\n            3. 脚本通过 <code style=\"color:#93c5fd\">OrdersTotal()</code> 跨图表读取全账户黄金持仓，<b>100%只读（绝不下单/改单/平仓）</b>！\n          </div>\n        </div>\n      </div>\n      <div style=\"margin-top:10px;padding:9px 12px;background:rgba(124,58,237,0.12);border:1px solid rgba(167,139,250,0.5);border-radius:8px;font-size:12px;line-height:1.7;color:#cbd5e1\">\n        <b style=\"color:#c4b5fd\">☁️ 想让 Vercel 线上网址也同步？</b>（Vercel 无状态，需一个免费 Redis 做中转）<br>\n        ① Vercel 项目 → <b>Storage → Create → Upstash for Redis</b>（免费档）并 Connect 到本项目，会自动注入 <code>KV_REST_API_URL</code> / <code>KV_REST_API_TOKEN</code>；<br>\n        ② （推荐）Settings → Environment Variables 新增 <code>MT4_TOKEN</code> = 自定义口令，并在 MT4 脚本参数 <code>SyncToken</code> 填同样口令，防止别人乱推数据；<br>\n        ③ Redeploy 后，MT4 白名单与脚本 <code>DashboardUrl</code> 都填您的 Vercel 域名（脚本由 Vercel 页面下载则已自动填好）。\n      </div>\n    </section>\n    <section class=\"card\" id=\"masterDecisionSec\"></section>\n    <section class=\"card\" id=\"mt4CurveSec\" style=\"display:none\"></section>\n    <section class=\"card\" id=\"tolSec\">\n      <div class=\"vhead\" style=\"margin-bottom:0\">\n        <div style=\"display:flex;align-items:center;gap:10px;flex-wrap:wrap\">\n          <h2 style=\"margin:0\">🛡️ M1双向追踪倍投马丁EA · 多空净敞口风控推演与实时操作指令台</h2>\n          <span class=\"mut sm\" id=\"tolSecCollapsedHint\">(已按需默认收起 · 想用时随时点击右侧开关打开，不用时保持关闭不占屏幕)</span>\n        </div>\n        <div style=\"display:flex;align-items:center;gap:8px\">\n          <span class=\"pill NEUT\" id=\"eaParamBadge\" style=\"display:none\">当前策略: 0.02起 · K_Lot 1.38 · 封顶1.32手 · 24层 · 步长1.0$</span>\n          <button id=\"btnToggleTolSec\" class=\"sm pri\" onclick=\"toggleTolSec()\" style=\"font-weight:800;padding:4px 12px\">🔘 开关：点击打开推演台 (当前已关闭)</button>\n        </div>\n      </div>\n      <div id=\"tolSecBody\" style=\"display:none;margin-top:12px;padding-top:10px;border-top:1px solid var(--bd)\">\n      <div class=\"tol-bar\" style=\"justify-content:space-between\">\n        <div style=\"display:flex;align-items:center;flex-wrap:wrap;gap:9px\">\n          <div style=\"display:flex;align-items:center;gap:5px\">\n            <label style=\"font-weight:700;color:#fff\">💰 账户余额($):</label>\n            <input type=\"number\" id=\"accBalInput\" min=\"100\" max=\"500000\" step=\"100\" value=\"2700\" style=\"width:78px;background:var(--bg);color:var(--gold);border:1px solid var(--gold);padding:5px 7px;border-radius:6px;font-size:14px;font-weight:800\">\n          </div>\n          <div class=\"btns tol-presets\">\n            <button onclick=\"setAccountBal(2000)\" title=\"2000$账户 (风控线1500$)\">2000$</button>\n            <button onclick=\"setAccountBal(2700)\" title=\"您实盘当前余额 ~2700$\">2700$(实盘)</button>\n            <button onclick=\"setAccountBal(3500)\" title=\"MaxLoss=3500$\">3500$</button>\n          </div>\n          <div style=\"display:flex;align-items:center;gap:5px;padding-left:6px;border-left:1px solid var(--bd)\">\n            <label style=\"font-weight:700;color:#f59e0b\" title=\"用于公式 D = 可亏金额 / (净敞口N × 100)，例如1500美金爆仓/止损线\">🛡️ 可亏/爆仓线($):</label>\n            <input type=\"number\" id=\"riskLossInput\" min=\"50\" max=\"500000\" step=\"100\" value=\"1500\" style=\"width:72px;background:var(--bg);color:#f59e0b;border:1px solid rgba(245,158,11,0.6);padding:5px 6px;border-radius:6px;font-size:14px;font-weight:800\" title=\"例如1500美金爆仓/风控线：净敞口0.5手可抗30$(3000点)，净敞口1.0手可抗15$(1500点)\">\n          </div>\n          <div style=\"display:flex;align-items:center;gap:5px;padding-left:6px;border-left:1px solid var(--bd)\">\n            <label style=\"font-weight:700;color:#34d399\">📈 买单总手数(Buy):</label>\n            <input type=\"number\" id=\"buyLotsInput\" min=\"0\" max=\"100\" step=\"0.01\" value=\"0.45\" style=\"width:64px;background:var(--bg);color:#34d399;border:1px solid rgba(16,185,129,0.55);padding:5px 6px;border-radius:6px;font-size:14px;font-weight:800\" title=\"填入MT4/MT5显示的当前买单(Buy)合计总手数\">\n          </div>\n          <div style=\"display:flex;align-items:center;gap:5px\">\n            <label style=\"font-weight:700;color:#fb7185\">📉 卖单总手数(Sell):</label>\n            <input type=\"number\" id=\"sellLotsInput\" min=\"0\" max=\"100\" step=\"0.01\" value=\"0.02\" style=\"width:64px;background:var(--bg);color:#fb7185;border:1px solid rgba(244,63,94,0.55);padding:5px 6px;border-radius:6px;font-size:14px;font-weight:800\" title=\"填入MT4/MT5显示的当前卖单(Sell)合计总手数\">\n          </div>\n          <span class=\"pill MIXED\" id=\"lotDetectBadge\" style=\"font-size:12px;padding:4px 10px\">⚖️ 净敞口 N=0.43手 ($43/美金) · 买7层/卖1层</span>\n          <div style=\"display:flex;align-items:center;gap:4px;padding-left:6px;border-left:1px solid var(--bd)\">\n            <label class=\"mut sm\">单边层数:</label>\n            <input type=\"number\" id=\"curLayerInput\" min=\"1\" max=\"50\" step=\"1\" value=\"7\" style=\"width:44px;background:var(--bg);color:var(--gold);border:1px solid var(--bd);padding:4px 5px;border-radius:6px;font-size:13px;font-weight:700\" title=\"由买单/卖单手数反推的单边最高层数\">\n          </div>\n          <div style=\"display:flex;align-items:center;gap:4px;padding-left:6px;border-left:1px solid var(--bd)\">\n            <label class=\"mut sm\">预付款($):</label>\n            <input type=\"number\" id=\"usedMarginInput\" min=\"1\" max=\"100000\" step=\"1\" value=\"14\" style=\"width:52px;background:var(--bg);color:#fff;border:1px solid var(--bd);padding:4px 5px;border-radius:6px;font-size:13px;font-weight:700\" title=\"填入MT4/MT5显示的已用预付款(如14美金)\">\n          </div>\n          <button class=\"pri\" id=\"btnCalcAccount\">🧮 重算净敞口 & 指令</button>\n        </div>\n        <div style=\"display:flex;align-items:center;flex-wrap:wrap;gap:8px\">\n          <span class=\"mut sm\">净敞口可抗单边区间: <b id=\"tolValTxt\" style=\"color:var(--gold);font-size:15px\">34.9</b><b style=\"color:var(--gold)\">$</b></span>\n          <input type=\"range\" id=\"tolSlider\" class=\"tol-slider\" min=\"5\" max=\"150\" step=\"0.5\" value=\"34.9\" style=\"width:100px\" title=\"由 D = 可亏金额 / (净敞口N × 100) 自动推算，也可手动微调\">\n          <input type=\"number\" id=\"tolInput\" min=\"3\" max=\"300\" step=\"0.5\" value=\"34.9\" style=\"width:60px;background:var(--bg);color:var(--tx);border:1px solid var(--bd);padding:4px 6px;border-radius:6px;font-size:12.5px\">\n          <button class=\"sm\" id=\"btnCalcTol\">微调区间</button>\n        </div>\n      </div>\n      <div id=\"lotQuickStrip\" style=\"margin-bottom:10px;padding:8px 11px;background:rgba(15,19,28,0.85);border:1px solid var(--bd);border-radius:8px;font-size:12px;display:flex;flex-direction:column;gap:6px\"></div>\n      <details class=\"clean-fold\" id=\"fold-ea-params\" ontoggle=\"window.OPEN_FOLDS&&(window.OPEN_FOLDS[this.id]=this.open)\" style=\"margin-bottom:10px\">\n        <summary>⚙️ 点击展开/修改：多空持仓均价精确浮亏计算 & EA 底层倍投参数 (支持填入多单/空单均价直接算实时净浮亏)</summary>\n        <div style=\"margin-top:8px;padding:10px 12px;background:var(--card2);border:1px solid var(--bd);border-radius:8px;display:flex;flex-wrap:wrap;gap:12px;align-items:center;font-size:12.5px\">\n          <label style=\"color:#34d399;font-weight:700\">多单均价($可选): <input type=\"number\" id=\"buyAvgPxInput\" value=\"0\" step=\"0.1\" min=\"0\" placeholder=\"0=自动\" style=\"width:74px;background:var(--bg);color:#34d399;border:1px solid rgba(16,185,129,0.5);padding:3px 6px;border-radius:4px\" title=\"填入多单持仓均价(0表示不填)，结合现价直接算多单浮盈亏 = 多单手数×100×(现价-均价)\"></label>\n          <label style=\"color:#fb7185;font-weight:700\">空单均价($可选): <input type=\"number\" id=\"sellAvgPxInput\" value=\"0\" step=\"0.1\" min=\"0\" placeholder=\"0=自动\" style=\"width:74px;background:var(--bg);color:#fb7185;border:1px solid rgba(244,63,94,0.5);padding:3px 6px;border-radius:4px\" title=\"填入空单持仓均价(0表示不填)，结合现价直接算空单浮盈亏 = 空单手数×100×(均价-现价)\"></label>\n          <label>平台强平比例(%): <input type=\"number\" id=\"stopOutPctInput\" value=\"20\" step=\"5\" min=\"0\" max=\"100\" style=\"width:52px;background:var(--bg);color:#fff;border:1px solid var(--bd);padding:3px 6px;border-radius:4px\" title=\"1000倍杠杆常见强平比例为20%或50%\"></label>\n          <label>起始手数(lot): <input type=\"number\" id=\"eaLot\" value=\"0.02\" step=\"0.01\" min=\"0.01\" style=\"width:56px;background:var(--bg);color:#fff;border:1px solid var(--bd);padding:3px 6px;border-radius:4px\"></label>\n          <label>倍投系数(K_Lot): <input type=\"number\" id=\"eaK\" value=\"1.38\" step=\"0.01\" min=\"1.05\" style=\"width:58px;background:var(--bg);color:#fff;border:1px solid var(--bd);padding:3px 6px;border-radius:4px\"></label>\n          <label>单笔封顶(Maxlot): <input type=\"number\" id=\"eaMaxLot\" value=\"1.32\" step=\"0.01\" min=\"0.1\" style=\"width:60px;background:var(--bg);color:#fff;border:1px solid var(--bd);padding:3px 6px;border-radius:4px\"></label>\n          <label>最大层数(Totals): <input type=\"number\" id=\"eaTotals\" value=\"24\" step=\"1\" min=\"5\" max=\"60\" style=\"width:52px;background:var(--bg);color:#fff;border:1px solid var(--bd);padding:3px 6px;border-radius:4px\"></label>\n          <label>加仓间距(Step$): <input type=\"number\" id=\"eaStep\" value=\"1.00\" step=\"0.1\" min=\"0.2\" style=\"width:56px;background:var(--bg);color:#fff;border:1px solid var(--bd);padding:3px 6px;border-radius:4px\"></label>\n          <label>每层止盈(StopProfit$): <input type=\"number\" id=\"eaTp\" value=\"4.0\" step=\"0.5\" min=\"1\" style=\"width:54px;background:var(--bg);color:#fff;border:1px solid var(--bd);padding:3px 6px;border-radius:4px\"></label>\n          <div class=\"btns\" style=\"margin-left:auto\">\n            <button class=\"sm\" onclick=\"applyEaPreset('cur')\">套用当前实盘 (2700$ / 可亏1500$ / Maxlot 1.32)</button>\n            <button class=\"sm\" onclick=\"applyEaPreset('bal2000')\">2000$账户 + 净敞口0.5手 (抗30$/3000点)</button>\n            <button class=\"sm\" onclick=\"applyEaPreset('log')\">日志原参数 (Maxlot 3.50 / 50层)</button>\n          </div>\n        </div>\n      </details>\n      <div id=\"eaActionBox\"></div>\n      <div id=\"tolResult\" style=\"margin-top:12px\"></div>\n      </div>\n    </section>\n    <section class=\"card\" id=\"anomalySec\"></section>\n    <section class=\"card\" id=\"keyLevelsSec\"></section>\n    <section class=\"card\" id=\"verdict\"></section>\n    <section class=\"card\" id=\"entrySec\"></section>\n    <section class=\"card\" id=\"forecastSec\"></section>\n    <div id=\"bigCharts\"></div>\n    <section class=\"card\" id=\"tfSec\"><h2>🎛️ 分周期 10 项技术指标明细 <span class=\"mut sm\" style=\"font-weight:400\">(正常指标自动静默为深灰，仅触发趋势/极值预警的指标高亮提示)</span></h2><div id=\"tf\"></div></section>\n    <section class=\"card\" id=\"sentimentSec\"></section>\n    <section class=\"card\" id=\"attentionSec\"></section>\n    <section class=\"card\" id=\"trumpSec\"></section>\n    <section class=\"card\" id=\"macroSec\"></section>\n    <section class=\"grid3\" id=\"sessionSec\">\n      <div class=\"card\" id=\"session\"></div>\n      <div class=\"card\" id=\"gvz\"></div>\n    </section>\n    <section class=\"card\" id=\"calSec\">\n      <div style=\"display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:10px\">\n        <h2 style=\"margin:0\"><a href=\"https://www.jin10.com/minipro/index.html#/pages_sub/weeklyEconomic/weeklyEconomic?maxWidth=800&id=calendar&mode=weekly\" target=\"_blank\" rel=\"noopener\">📅 金十数据经济周历 (官网 1:1 同步) 🔗</a> <span class=\"mut sm\" style=\"font-weight:400\">(数据来自 <a id=\"calApi\" target=\"_blank\" rel=\"noopener\">金十周历接口 🔗</a>)</span></h2>\n        <div class=\"btns\">\n          <button class=\"sm on\" id=\"calModeWeek\" onclick=\"setCalRange('week')\">📅 本周全部7天(周一至周日)</button>\n          <button class=\"sm\" id=\"calMode2d\" onclick=\"setCalRange('2d')\">📍 仅看今明两日</button>\n          <button class=\"sm\" id=\"calModeToday\" onclick=\"setCalRange('today')\">📌 仅看今日</button>\n          <label class=\"mut sm\" style=\"margin-left:6px\"><input type=\"checkbox\" id=\"onlyImp\" checked> 仅看 ★3 以上</label>\n        </div>\n      </div>\n      <div id=\"cal\"></div>\n    </section>\n    <section class=\"card mut\" style=\"font-size:12px\">\n      阈值参考: ADX&lt;20 震荡 / &gt;25 趋势; CHOP&gt;61.8 震荡 / &lt;38.2 趋势; ATR(14)/ATR(100) &lt;0.82 挤压 / &gt;1.25 扩张。仅供参考,不构成投资建议。\n    </section>\n    <section class=\"card\" id=\"sources\">\n      <h2>数据来源(点击跳转)</h2>\n      <div class=\"btns\" id=\"srcBtns\"></div>\n    </section>\n  </main>\n</div>\n<div id=\"toast\"></div>\n<script>\n  const wkd = (() => { const n = new Date(Date.now() + 8 * 3600e3), m = n.getTime() - ((n.getUTCDay() + 6) % 7) * 86400e3, f = (t) => new Date(t).toISOString().slice(0, 10); return [f(m), f(m + 6 * 86400e3)]; })();\n  const WK = wkd;\n  const SRC = [\n    ['现货黄金 XAUUSD 实时行情(0延迟)', 'https://wallstreetcn.com/markets/codes/XAUUSD.OTC'],\n    ['实时K线接口 XAUUSD 1M(0延迟)', 'https://api-ddc-wscn.awtmt.com/market/kline?prod_code=XAUUSD&tick_count=600&period_type=60&fields=tick_at,open_px,close_px,high_px,low_px'],\n    ['实时K线接口 XAUUSD 5M(0延迟)', 'https://api-ddc-wscn.awtmt.com/market/kline?prod_code=XAUUSD&tick_count=600&period_type=300&fields=tick_at,open_px,close_px,high_px,low_px'],\n    ['实时K线接口 XAUUSD 15M(0延迟)', 'https://api-ddc-wscn.awtmt.com/market/kline?prod_code=XAUUSD&tick_count=600&period_type=900&fields=tick_at,open_px,close_px,high_px,low_px'],\n    ['实时K线接口 XAUUSD 1H(0延迟)', 'https://api-ddc-wscn.awtmt.com/market/kline?prod_code=XAUUSD&tick_count=600&period_type=3600&fields=tick_at,open_px,close_px,high_px,low_px'],\n    ['实时K线接口 XAUUSD 4H(0延迟)', 'https://api-ddc-wscn.awtmt.com/market/kline?prod_code=XAUUSD&tick_count=600&period_type=14400&fields=tick_at,open_px,close_px,high_px,low_px'],\n    ['实时K线接口 XAUUSD 1D(10年)', 'https://api-ddc-wscn.awtmt.com/market/kline?prod_code=XAUUSD&tick_count=2600&period_type=86400&fields=tick_at,open_px,close_px,high_px,low_px'],\n    ['金十数据经济周历', 'https://www.jin10.com/minipro/index.html#/pages_sub/weeklyEconomic/weeklyEconomic?maxWidth=800&id=calendar&mode=weekly'],\n    ['金十数据经济日历', 'https://rili.jin10.com/'],\n    ['金十周历数据接口(本周)', 'https://rili-open-api.jin10.com/data/week_info?start_date=' + WK[0] + '&end_date=' + WK[1] + '&include_holiday=true'],\n    ['Yahoo GVZ 波动率指数', 'https://finance.yahoo.com/quote/%5EGVZ/'],\n    ['K线接口 GVZ', 'https://query1.finance.yahoo.com/v8/finance/chart/%5EGVZ?interval=1d&range=1y'],\n    ['Yahoo 黄金期货 GC=F(备用)', 'https://finance.yahoo.com/quote/GC%3DF/'],\n    ['TradingView XAUUSD', 'https://www.tradingview.com/symbols/XAUUSD/'],\n    ['TradingView GVZ', 'https://www.tradingview.com/symbols/CBOE-GVZ/'],\n  ];\n  document.getElementById('srcBtns').innerHTML = SRC.map(([n, u]) => `<a href=\"${u}\" target=\"_blank\" rel=\"noopener\" title=\"${u}\"><button>🔗 ${n}</button></a>`).join('');\n</script>\n<script>\nlet D = null;\nlet ACC_BAL = Number(localStorage.getItem('gold_acc_bal')) || 2700; // 默认账户余额 2700 美元\nlet RISK_LOSS_USD = Number(localStorage.getItem('gold_risk_loss')) || 1500; // 默认可亏/爆仓参考线 1500 美元 (对应 D = 1500 / (N * 100))\nlet BUY_LOTS = localStorage.getItem('gold_buy_lots') != null ? Number(localStorage.getItem('gold_buy_lots')) : 0.45; // 默认当前买单总手数 0.45手(7层)\nlet SELL_LOTS = localStorage.getItem('gold_sell_lots') != null ? Number(localStorage.getItem('gold_sell_lots')) : 0.02; // 默认当前卖单总手数 0.02手(1层)\nlet BUY_AVG_PX = Number(localStorage.getItem('gold_buy_avg_px')) || 0; // 可选：多单持仓均价(0=未填)\nlet SELL_AVG_PX = Number(localStorage.getItem('gold_sell_avg_px')) || 0; // 可选：空单持仓均价(0=未填)\nlet STOP_OUT_PCT = localStorage.getItem('gold_stop_out_pct') != null ? Number(localStorage.getItem('gold_stop_out_pct')) : 20; // 强平比例默认20%\nlet CUR_LAYERS = Number(localStorage.getItem('gold_cur_layers')) || 7; // 默认单边最高层数 7 层 (累计0.45手)\nlet USED_MARGIN = Number(localStorage.getItem('gold_used_margin')) || 14; // 默认已用预付款 14 美元 (2700/14 ≈ 19286%)\nlet EA_CFG = {\n  lot: Number(localStorage.getItem('gold_ea_lot')) || 0.02,\n  kLot: Number(localStorage.getItem('gold_ea_klot')) || 1.38,\n  maxLot: Number(localStorage.getItem('gold_ea_maxlot')) || 1.32,\n  totals: Number(localStorage.getItem('gold_ea_totals')) || 24,\n  stepUsd: Number(localStorage.getItem('gold_ea_step')) || 1.00,\n  tpPerOrder: Number(localStorage.getItem('gold_ea_tp')) || 4.0\n};\nlet TOL = Number(localStorage.getItem('gold_tol')) || 34.9; // 由净敞口公式 D = L / (N * 100) 推演出的抗单边跨度(美元)\nconst SHOW_CANDLE = {}; // 各周期大图是否显示黄金价格蜡烛图(默认全不显示, 点击按钮才开启)\nconst CHART_PTS = {};   // 缓存各周期大图的坐标与数据供十字准星使用\nwindow.OPEN_FOLDS = {}; // 持久化记录所有 <details> 展开状态，防止 15秒/3分钟数据刷新时自动合上\nwindow.SCROLL_POS = {}; // 持久化记录内部滚动容器的滚动条位置\n\nfunction saveUiState() {\n  if (!document.querySelectorAll) return;\n  document.querySelectorAll('details').forEach((el, idx) => {\n    const key = el.id || el.getAttribute('data-fold-id') || ('fold-idx-' + idx);\n    window.OPEN_FOLDS[key] = !!el.open;\n  });\n  ['trumpScrollBox', 'eaLayerScrollBox'].forEach((id) => {\n    const el = document.getElementById(id);\n    if (el && el.scrollTop != null) window.SCROLL_POS[id] = el.scrollTop;\n  });\n}\n\nfunction restoreUiState() {\n  if (!document.querySelectorAll) return;\n  document.querySelectorAll('details').forEach((el, idx) => {\n    const key = el.id || el.getAttribute('data-fold-id') || ('fold-idx-' + idx);\n    if (window.OPEN_FOLDS[key]) el.open = true;\n  });\n  ['trumpScrollBox', 'eaLayerScrollBox'].forEach((id) => {\n    const el = document.getElementById(id);\n    if (el && window.SCROLL_POS[id] != null) el.scrollTop = window.SCROLL_POS[id];\n  });\n}\n\nconst API = {\n  '1M': 'https://api-ddc-wscn.awtmt.com/market/kline?prod_code=XAUUSD&tick_count=600&period_type=60&fields=tick_at,open_px,close_px,high_px,low_px',\n  '5M': 'https://api-ddc-wscn.awtmt.com/market/kline?prod_code=XAUUSD&tick_count=600&period_type=300&fields=tick_at,open_px,close_px,high_px,low_px',\n  '15M': 'https://api-ddc-wscn.awtmt.com/market/kline?prod_code=XAUUSD&tick_count=600&period_type=900&fields=tick_at,open_px,close_px,high_px,low_px',\n  '1H': 'https://api-ddc-wscn.awtmt.com/market/kline?prod_code=XAUUSD&tick_count=600&period_type=3600&fields=tick_at,open_px,close_px,high_px,low_px',\n  '4H': 'https://api-ddc-wscn.awtmt.com/market/kline?prod_code=XAUUSD&tick_count=600&period_type=14400&fields=tick_at,open_px,close_px,high_px,low_px',\n  '1D': 'https://api-ddc-wscn.awtmt.com/market/kline?prod_code=XAUUSD&tick_count=2600&period_type=86400&fields=tick_at,open_px,close_px,high_px,low_px',\n  GVZ: 'https://query1.finance.yahoo.com/v8/finance/chart/%5EGVZ?interval=1d&range=1y'\n};\nconst lk = (u, t) => '<a class=\"num\" href=\"' + u + '\" target=\"_blank\" rel=\"noopener\" title=\"点击打开数据源验证: ' + u + '\">' + t + '</a>';\nconst $ = (id) => document.getElementById(id);\nconst fmtBJ = (ts) => new Date(ts * 1000).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false, month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }).replace(/\\//g, '-');\nconst f2 = (v) => v == null || isNaN(v) ? '-' : Number(v).toFixed(2);\nconst toast = (m) => { const t = $('toast'); t.textContent = m; t.style.display = 'block'; setTimeout(() => t.style.display = 'none', 1800); };\n\nfunction clamp(x, a = 0, b = 100) { return Math.max(a, Math.min(b, x)); }\nfunction r1(x) { return Math.round(x * 10) / 10; }\nfunction r2(x) { return Math.round(x * 100) / 100; }\nfunction lerp(x, pts) {\n  if (x <= pts[0][0]) return pts[0][1];\n  for (let i = 1; i < pts.length; i++) {\n    if (x <= pts[i][0]) {\n      const [x0, y0] = pts[i - 1], [x1, y1] = pts[i];\n      return y0 + (y1 - y0) * (x - x0) / (x1 - x0);\n    }\n  }\n  return pts[pts.length - 1][1];\n}\nfunction levelFor(x, dir) {\n  if (x == null) return { name: '-', cls: 'MIXED', advice: '' };\n  const dTxt = dir === 'UP' ? '·📈上涨趋势' : dir === 'DOWN' ? '·📉下跌趋势' : '';\n  const dAdv = dir === 'UP' ? '(当前上涨趋势,严禁逆势空单死扛)' : dir === 'DOWN' ? '(当前下跌趋势,严禁逆势多单死扛)' : '';\n  if (x >= 70) return { name: '强震荡(合理区间内)', cls: 'RANGE', advice: '波幅在设定区间内,适合正常运行网格/马丁' };\n  if (x >= 55) return { name: '偏震荡(合理区间内)', cls: 'RANGE', advice: '波幅可控,可运行常规网格参数,注意风控' };\n  if (x >= 45) return { name: '过渡' + dTxt, cls: 'MIXED', advice: '接近区间边界,建议减仓、放大网格间距' };\n  if (x >= 30) return { name: '偏单边' + dTxt, cls: 'TREND', advice: '超出合理震荡区间或趋势走强,暂停新开网格' + dAdv };\n  return { name: '强单边' + dTxt, cls: 'TREND', advice: '严重超出合理区间/单边爆发,停止网格/马丁' + dAdv };\n}\nconst TF_SPAN_SCALE = { '1M': 0.45, '5M': 0.75, '15M': 1.0, '1H': 1.85, '4H': 3.2, '1D': 5.5 };\nfunction adjBySpan(rawIdx, span, tol, tf) {\n  if (rawIdx == null) return null;\n  if (!span || !tol) return rawIdx;\n  const scale = TF_SPAN_SCALE[tf] || 1.0;\n  // 市场客观震荡指数校准基准：单波15M容忍度保底按12$计算并按周期时间跨度缩放，防止小资金账户余额导致全站震荡指数变成0\n  const effTol = Math.max(12.0, Number(tol) || 14.2) * scale;\n  const ratio = span / effTol;\n  const spanScore = lerp(ratio, [[0.4, 100], [0.8, 85], [1.0, 68], [1.3, 48], [1.7, 25], [2.4, 10]]);\n  let v = 0.68 * rawIdx + 0.32 * spanScore;\n  if (ratio > 1.35) v -= Math.min(18, (ratio - 1.35) * 14);\n  return r1(clamp(v, 15, 98));\n}\n\n// ========== M1 双向追踪挂单倍投马丁 EA 账户风控与层数推演模型 ==========\n// 公式: L_n = min(Maxlot, round(lot * K_Lot^n, 2)), Step = 100点(1.00$), StopProfit = 4.0$ * 层数\nfunction calcEaModel(bal = ACC_BAL, cfg = EA_CFG, curL = CUR_LAYERS, usedMargin = USED_MARGIN) {\n  const step = Math.max(0.1, Number(cfg.stepUsd) || 1.0);\n  const totals = Math.max(1, Math.min(60, Math.round(Number(cfg.totals) || 24)));\n  const lot0 = Math.max(0.01, Number(cfg.lot) || 0.02);\n  const kLot = Math.max(1.0, Number(cfg.kLot) || 1.38);\n  const maxLot = Math.max(lot0, Number(cfg.maxLot) || 1.32);\n  const tpUnit = Math.max(0.5, Number(cfg.tpPerOrder) || 4.0);\n  const marginIn = Math.max(1, Number(usedMargin) || 14);\n\n  const layers = [];\n  let cumLot = 0;\n  for (let i = 0; i < totals; i++) {\n    const rawL = lot0 * Math.pow(kLot, i);\n    const l = Math.min(maxLot, Math.round(rawL * 100) / 100);\n    cumLot = Math.round((cumLot + l) * 100) / 100;\n    const distUsd = r1(i * step); // 距离首层(n=1)的价格单边跨度($)\n    // 当价格到达第 i+1 层开仓价时，前 i 层持仓的理论单边累计浮亏($)：每1手波动1美元=100美元\n    let ddUsd = 0;\n    for (let j = 0; j < i; j++) {\n      ddUsd += layers[j].lot * (i - j) * step * 100;\n    }\n    ddUsd = Math.round(ddUsd * 100) / 100;\n    const lossPerUsd = Math.round(cumLot * 100 * 100) / 100; // 该层持仓下，每波动1美元盈亏($)\n    const tpUsd = Math.round((i + 1) * tpUnit * 100) / 100;  // 整组止盈所需浮盈(StopProfit=4.0 * 层数)\n    // 从当前第 i+1 层开仓价需要回调多少美元，才能让该方向整组浮盈达到 tpUsd 并全部平仓重置\n    const pullbackUsd = lossPerUsd > 0 ? Math.round(((ddUsd + tpUsd) / lossPerUsd) * 100) / 100 : 0;\n    const ddPct = bal > 0 ? Math.round((ddUsd / bal) * 1000) / 10 : 0;\n    // 在该层数(cumLot)下，账户 65% 安全可扛总跨度 与 100% 强平极限总跨度\n    const layerSafeSpan = r1(distUsd + Math.max(0, bal * 0.65 - ddUsd) / lossPerUsd);\n    const layerMaxSpan = r1(distUsd + Math.max(0, bal - ddUsd) / lossPerUsd);\n    // 按 7层(0.45手) 对应用户实盘 marginIn(14$) 折算各层预估预付款与预付款比例\n    const estMargin = r1(Math.max(2, marginIn * (cumLot / 0.45)));\n    const estMarginLevel = Math.round((Math.max(0, bal - ddUsd) / estMargin) * 100);\n    layers.push({\n      n: i + 1,\n      idx: i,\n      lot: l,\n      cumLot,\n      distUsd,\n      ddUsd,\n      ddPct,\n      lossPerUsd,\n      tpUsd,\n      pullbackUsd,\n      layerSafeSpan,\n      layerMaxSpan,\n      estMargin,\n      estMarginLevel,\n      isCapped: l >= maxLot - 1e-6\n    });\n  }\n\n  // 若不控层数、任由 EA 连续逆势死加到 24 层时的失控临界点 (仅供对比预警)\n  function uncontrolledSpanAtLoss(targetLoss) {\n    if (targetLoss <= 0) return { span: 0, layer: 1, cumLot: layers[0].cumLot, loss: 0, pullbackUsd: layers[0].pullbackUsd };\n    for (let i = 0; i < layers.length - 1; i++) {\n      const cur = layers[i], nxt = layers[i + 1];\n      if (targetLoss >= cur.ddUsd && targetLoss <= nxt.ddUsd) {\n        const extraLoss = targetLoss - cur.ddUsd;\n        const extraSpan = cur.lossPerUsd > 0 ? extraLoss / cur.lossPerUsd : 0;\n        const span = Math.round((cur.distUsd + extraSpan) * 100) / 100;\n        const pullback = cur.lossPerUsd > 0 ? Math.round(((targetLoss + cur.tpUsd) / cur.lossPerUsd) * 100) / 100 : 0;\n        return { span, layer: cur.n, cumLot: cur.cumLot, loss: Math.round(targetLoss), pullbackUsd: pullback };\n      }\n    }\n    const last = layers[layers.length - 1];\n    const extraLoss = Math.max(0, targetLoss - last.ddUsd);\n    const extraSpan = last.lossPerUsd > 0 ? extraLoss / last.lossPerUsd : 0;\n    const span = Math.round((last.distUsd + extraSpan) * 100) / 100;\n    const pullback = last.lossPerUsd > 0 ? Math.round(((targetLoss + last.tpUsd) / last.lossPerUsd) * 100) / 100 : 0;\n    return { span, layer: last.n, cumLot: last.cumLot, loss: Math.round(targetLoss), pullbackUsd: pullback, beyondMaxLayer: true };\n  }\n\n  const uncontrolledWarn = uncontrolledSpanAtLoss(bal * 0.65);\n  const uncontrolledHard = uncontrolledSpanAtLoss(bal * 1.00);\n  const fullLayer = layers[layers.length - 1];\n\n  // 根据单边总手数 (如买单 0.45手 或 卖单 0.02手) 自动精确反推当前处于第几层！\n  function inferLayerFromLots(sideLots) {\n    const v = Math.max(0, Number(sideLots) || 0);\n    if (v <= 0.005) return { layer: 0, cumLot: 0, lot: 0, ddUsd: 0, pullbackUsd: 0 };\n    let best = layers[0], minDiff = Math.abs(v - layers[0].cumLot);\n    for (const r of layers) {\n      const diff = Math.abs(v - r.cumLot);\n      if (diff <= minDiff) { minDiff = diff; best = r; }\n    }\n    return { layer: best.n, cumLot: best.cumLot, lot: best.lot, ddUsd: best.ddUsd, pullbackUsd: best.pullbackUsd, inputLots: v };\n  }\n\n  const buyLotsVal = Math.max(0, Number(BUY_LOTS) || 0);\n  const sellLotsVal = Math.max(0, Number(SELL_LOTS) || 0);\n  const buyInfo = inferLayerFromLots(buyLotsVal);\n  const sellInfo = inferLayerFromLots(sellLotsVal);\n  const totalBothLots = Math.round((buyLotsVal + sellLotsVal) * 100) / 100;\n\n  // 核心原则：马丁网格的“抗单边点数”不等于“累计总手数 × 点数”，而主要看多空对冲后的净敞口 N = |买单总手数 - 卖单总手数|！\n  const netLots = Math.round(Math.abs(buyLotsVal - sellLotsVal) * 100) / 100;\n  const isFullyHedged = netLots < 0.005;\n  const effNetLots = Math.max(0.02, netLots); // 防除零保护(完全锁仓时按0.02基准计算)\n  const netLossPerUsd = Math.round(effNetLots * 100 * 100) / 100; // 每波动 1 美元的真实净浮亏速度 ($/美金) = N * 100\n\n  const heavySide = buyLotsVal > sellLotsVal + 0.005 ? 'BUY' : sellLotsVal > buyLotsVal + 0.005 ? 'SELL' : 'EVEN';\n  const heavySideTxt = heavySide === 'BUY'\n    ? `净多头 +${f2(netLots)}手 (买${f2(buyLotsVal)}手[≈${buyInfo.layer}层] − 卖${f2(sellLotsVal)}手[≈${sellInfo.layer}层])`\n    : heavySide === 'SELL'\n    ? `净空头 -${f2(netLots)}手 (卖${f2(sellLotsVal)}手[≈${sellInfo.layer}层] − 买${f2(buyLotsVal)}手[≈${buyInfo.layer}层])`\n    : `完全锁仓对冲 净0手 (买${f2(buyLotsVal)}手 = 卖${f2(sellLotsVal)}手)`;\n\n  const curLayerNum = Math.max(1, Math.min(totals, Math.round(curL || Math.max(buyInfo.layer, sellInfo.layer) || 7)));\n  const curInfo = layers[curLayerNum - 1];\n\n  // 可选：若填入了多单均价 / 空单均价，按公式直接算实时净浮亏：\n  // 净浮亏 = 多单总手数 × 100 × (多单均价 − 现价) + 空单总手数 × 100 × (现价 − 空单均价)\n  const curPx = (D && D.timeframes && ((D.timeframes['1M'] && D.timeframes['1M'].price) || (D.timeframes['5M'] && D.timeframes['5M'].price))) || 0;\n  const buyAvgPx = Math.max(0, Number(BUY_AVG_PX) || 0);\n  const sellAvgPx = Math.max(0, Number(SELL_AVG_PX) || 0);\n  const hasAvgPx = (buyAvgPx > 0 || sellAvgPx > 0) && curPx > 0;\n  const buyFloatLoss = (buyAvgPx > 0 && curPx > 0) ? Math.round(buyLotsVal * 100 * (buyAvgPx - curPx) * 100) / 100 : 0;\n  const sellFloatLoss = (sellAvgPx > 0 && curPx > 0) ? Math.round(sellLotsVal * 100 * (curPx - sellAvgPx) * 100) / 100 : 0;\n  const actualNetFloatLoss = Math.round((buyFloatLoss + sellFloatLoss) * 100) / 100; // >0 为净浮亏，<0 为净浮盈\n\n  // 实盘预付款比例 (Margin Level = 余额或净值 / 已用预付款 * 100%)\n  const stopOutPct = Math.max(0, Math.min(100, Number(STOP_OUT_PCT) || 20));\n  const stopOutMarginUsd = Math.round(marginIn * (stopOutPct / 100) * 100) / 100;\n  const marginLevelBal = Math.round((bal / marginIn) * 100);\n  const eqNow = hasAvgPx ? Math.max(0, bal - actualNetFloatLoss) : bal;\n  const marginLevelEq = Math.round((eqNow / marginIn) * 100);\n\n  // 核心公式：1500 = N * 100 * D  =>  D = L / (N * 100) 美元 (折合 D * 100 点)\n  const riskLossUsd = Math.max(50, Math.min(bal * 2, Number(RISK_LOSS_USD) || Math.round(bal * 0.75)));\n  const remRiskBudget = hasAvgPx ? Math.max(0, riskLossUsd - Math.max(0, actualNetFloatLoss)) : riskLossUsd;\n  const remHardBudget = Math.max(0, eqNow - stopOutMarginUsd);\n\n  const comfortSpan = r1((riskLossUsd * 0.60) / netLossPerUsd);\n  const warnSpan = r1(remRiskBudget / netLossPerUsd);       // 按风控可亏线(如1500$)推算的抗单边美元数 D = L / (N*100)\n  const hardSpan = r1(bal / netLossPerUsd);                 // 按账户总本金(如2000$/2700$)推算的极限抗单边美元数 D_max = Bal / (N*100)\n  const hardSpanAfterStopOut = r1(remHardBudget / netLossPerUsd);\n\n  const comfort = { span: comfortSpan, pts: Math.round(comfortSpan * 100), layer: curLayerNum, cumLot: netLots, loss: Math.round(riskLossUsd * 0.60), pullbackUsd: curInfo.pullbackUsd };\n  const warn = { span: warnSpan, pts: Math.round(warnSpan * 100), layer: curLayerNum, cumLot: netLots, loss: Math.round(riskLossUsd), pullbackUsd: curInfo.pullbackUsd };\n  const hard = { span: hardSpan, pts: Math.round(hardSpan * 100), layer: curLayerNum, cumLot: netLots, loss: Math.round(bal), pullbackUsd: curInfo.pullbackUsd };\n\n  const remWarnSpan = Math.max(2.0, warnSpan);\n  const remHardSpan = Math.max(3.0, hardSpanAfterStopOut);\n  const remWarnLoss = Math.round(remRiskBudget);\n  const remHardLoss = Math.round(remHardBudget);\n\n  // 单边无对冲一条链(无另一方向盈利抵消、从首单0.02连续死加)在强平50%与20%下的理论极限\n  // 注：单边链到达第 k 层时，除了前面已建仓层的阶梯浮亏 ddUsd，平台保证金占用约 (cumLot / 0.45) * marginIn\n  const uncontrolled50 = uncontrolledSpanAtLoss(Math.max(100, bal * 0.85)); // 2000$ 账户强平50%下约 13.0$ (1300点)\n  const uncontrolled20 = uncontrolledSpanAtLoss(Math.max(100, bal * 0.96)); // 2000$ 账户强平20%下约 13.5~14.0$ (1400点)\n\n  // 生成不同净敞口 N (0.5手、1.0手、1.5手、2.0手、3.0手 + 当前净敞口) 的抗单边美元/点数对照表\n  const stdNetList = [0.25, 0.50, 1.00, 1.50, 2.00, 3.00];\n  if (effNetLots > 0 && !stdNetList.some((x) => Math.abs(x - effNetLots) < 0.015)) {\n    stdNetList.push(effNetLots);\n    stdNetList.sort((a, b) => a - b);\n  }\n  const netExposureTable = stdNetList.map((nLot) => {\n    const dRisk = Math.round((riskLossUsd / (nLot * 100)) * 100) / 100;\n    const dBal = Math.round((bal / (nLot * 100)) * 100) / 100;\n    return {\n      nLot,\n      lossPerUsd: Math.round(nLot * 100),\n      dRisk,\n      ptsRisk: Math.round(dRisk * 100),\n      dBal,\n      ptsBal: Math.round(dBal * 100),\n      isCurrent: Math.abs(nLot - effNetLots) < 0.015\n    };\n  });\n\n  return {\n    bal,\n    riskLossUsd,\n    usedMargin: marginIn,\n    stopOutPct,\n    stopOutMarginUsd,\n    marginLevelBal,\n    marginLevelEq,\n    buyLots: buyLotsVal,\n    sellLots: sellLotsVal,\n    buyAvgPx,\n    sellAvgPx,\n    hasAvgPx,\n    buyFloatLoss,\n    sellFloatLoss,\n    actualNetFloatLoss,\n    buyInfo,\n    sellInfo,\n    totalBothLots,\n    netLots,\n    effNetLots,\n    isFullyHedged,\n    netLossPerUsd,\n    heavySide,\n    heavySideTxt,\n    cfg: { lot: lot0, kLot, maxLot, totals, stepUsd: step, tpPerOrder: tpUnit },\n    layers,\n    netExposureTable,\n    comfort,\n    warn,\n    hard,\n    uncontrolledWarn,\n    uncontrolledHard,\n    uncontrolled50,\n    uncontrolled20,\n    fullLayer,\n    curLayerNum,\n    curInfo,\n    remWarnSpan,\n    remHardSpan,\n    remWarnLoss,\n    remHardLoss,\n    recommendedTol: Math.max(4, Math.min(250, r1(warnSpan)))\n  };\n}\n\n// ========== 基于 1M + 5M 为主(65%)、15M + 1H 为辅(35%) 的 EA 实时手动操作指令引擎 ==========\nfunction calcEaDirective(d, ea, adjMap, eMap) {\n  const t1 = (d.timeframes && d.timeframes['1M']) || {};\n  const t5 = (d.timeframes && d.timeframes['5M']) || {};\n  const t15 = (d.timeframes && d.timeframes['15M']) || {};\n  const t60 = (d.timeframes && d.timeframes['1H']) || {};\n  const price = t1.price || t5.price || t15.price || 0;\n\n  const adj1 = adjMap['1M'] ?? t1.rangeIndex ?? 60;\n  const adj5 = adjMap['5M'] ?? t5.rangeIndex ?? 60;\n  const adj15 = adjMap['15M'] ?? t15.rangeIndex ?? 60;\n  const adj60 = adjMap['1H'] ?? t60.rangeIndex ?? 60;\n\n  const e1 = (eMap['1M'] && eMap['1M'].last) || {};\n  const e5 = (eMap['5M'] && eMap['5M'].last) || {};\n  const e15 = (eMap['15M'] && eMap['15M'].last) || {};\n  const e60 = (eMap['1H'] && eMap['1H'].last) || {};\n\n  // 1M & 5M 核心短线触发指标 (权重 65%)\n  const fastIdx = r1(0.45 * adj1 + 0.55 * adj5);\n  const midIdx = r1(0.60 * adj15 + 0.40 * adj60);\n  const blendIdx = r1(0.65 * fastIdx + 0.35 * midIdx);\n\n  const drop1M = Number(e1.effDrop1 ?? t1.idxDrop1 ?? 0);\n  const drop5M = Number(e5.effDrop1 ?? t5.idxDrop1 ?? 0);\n  const drop15M = Number(e15.effDrop1 ?? t15.idxDrop1 ?? 0);\n  const fastDrop = r1(Math.max(drop1M, drop5M));\n  const maxDrop14Fast = r1(Math.max(t1.maxDrop14 || 0, t5.maxDrop14 || 0));\n\n  // 多空方向合力评分：以 1M + 5M 实时突破为主，结合 15M + 1H 趋势背景\n  let dirScore = 0; // 正数=单边上涨(利空空单Sell)，负数=单边下跌(利空多单Buy)\n  const dirVote = (tf, w) => {\n    if (!tf || tf.price == null) return 0;\n    let s = 0;\n    if (tf.trendDir === 'UP') s += 1.0;\n    else if (tf.trendDir === 'DOWN') s -= 1.0;\n    if ((tf.net14 || 0) > 0.3) s += 0.6;\n    else if ((tf.net14 || 0) < -0.3) s -= 0.6;\n    if ((tf.pdi || 0) > (tf.mdi || 0) + 3) s += 0.5;\n    else if ((tf.mdi || 0) > (tf.pdi || 0) + 3) s -= 0.5;\n    if (tf.ema50 && tf.price > tf.ema50) s += 0.3;\n    else if (tf.ema50 && tf.price < tf.ema50) s -= 0.3;\n    return s * w;\n  };\n  dirScore = r1(dirVote(t1, 0.30) + dirVote(t5, 0.35) + dirVote(t15, 0.22) + dirVote(t60, 0.13));\n  const domDir = dirScore >= 0.35 ? 'UP' : dirScore <= -0.35 ? 'DOWN' : (t5.trendDir !== 'FLAT' ? t5.trendDir : (t15.trendDir || 'FLAT'));\n  const domDirTxt = domDir === 'UP' ? '📈 单边向上突破/拉升' : domDir === 'DOWN' ? '📉 单边向下破位/急跌' : '↔️ 双向拉锯';\n\n  // 检查单边未回调净波幅是否逼近或超过当前账户($ACC_BAL)警戒跨度\n  const span1 = t1.span14 || 0, span5 = t5.span14 || 0, span15 = t15.span14 || 0, span60 = t60.span14 || 0;\n  // M1 马丁只要回调 1~3$ 即可整组止盈重置，因此真正威胁账户的是「1M近14分钟振幅」与「5M/15M净单边涨跌幅(net14)」\n  const oneWayMove = r1(Math.max(span1, Math.abs(t5.net14 || 0), Math.abs(t15.net14 || 0) * 0.65));\n  const spanWarnRatio = ea.remWarnSpan > 0 ? r1(oneWayMove / ea.remWarnSpan) : 0;\n\n  // 判断风险等级与具体手动操作指令 (以 1M+5M 为主触发 65%，参考 15M+1H 趋势 35%)\n  const curHighRisk = ea.curInfo.ddUsd >= ea.bal * 0.55 || ea.curLayerNum >= ea.uncontrolledWarn.layer;\n  const isAccountBreach = oneWayMove >= ea.remHardSpan || curHighRisk;\n  const isExtremeWhipsaw = (fastIdx < 32 && Math.abs(dirScore) < 0.35) || fastDrop >= 8.5;\n  const isTrendDanger = isAccountBreach || fastIdx < 50 || adj5 < 48 || (adj1 < 45 && adj5 < 54) || fastDrop >= 4.0 || (midIdx < 45 && fastIdx < 56) || spanWarnRatio >= 0.90;\n  const isWatch = !isExtremeWhipsaw && !isTrendDanger && (fastIdx < 58 || fastDrop >= 2.5 || midIdx < 52 || spanWarnRatio >= 0.70 || ea.curLayerNum >= Math.max(10, ea.uncontrolledWarn.layer - 2));\n\n  // 计算关键防守价位\n  const upWarnPx = price ? f2(price + ea.remWarnSpan) : '-';\n  const upHardPx = price ? f2(price + ea.remHardSpan) : '-';\n  const dnWarnPx = price ? f2(price - ea.remWarnSpan) : '-';\n  const dnHardPx = price ? f2(price - ea.remHardSpan) : '-';\n  const trailBuyPx = price ? f2(price + 0.60) : '-';\n  const trailSellPx = price ? f2(price - 0.60) : '-';\n\n  let state = 'AUTO_OK';\n  let needManual = false;\n  let badgeTxt = '🟢 无需手动操作 · 保持双向自动运行';\n  let badgeCls = 'RANGE';\n  let headline = '当前 1M/5M 震荡平稳，单边净波幅在账户安全容忍范围内，无需手动干预 EA';\n  let pauseSideTxt = '无需暂停（保持 Long & Short 双向挂单）';\n  let steps = [];\n  let resumeRule = '当前处于正常双向挂单状态；若后续 1M/5M 震荡指数跌破 50 或单次急跌 ≥ 4分，系统将立即提示锁方向。';\n\n  if (isExtremeWhipsaw) {\n    state = 'STOP_ALL';\n    needManual = true;\n    badgeTxt = '🛑 紧急手动操作 · 立即暂停EA自动交易 & 删双向挂单';\n    badgeCls = 'TREND';\n    const pauseDir = domDir === 'UP' ? '严禁开空单(Sell)及双向追单' : domDir === 'DOWN' ? '严禁开多单(Buy)及双向追单' : '严禁双向新开挂单';\n    pauseSideTxt = `🚨 立即暂停 EA 自动交易 (${pauseDir})`;\n    headline = `🚨 1M/5M 出现极端双向剧烈扫盘或指数闪崩（单次跌 ${fastDrop}分）：必须立即手动暂停 EA 并删除双向挂单！`;\n    steps = [\n      `<b>第一步（立即切断新挂单）</b>：在 MT4/MT5 顶部工具栏点击 <b>「自动交易 (AutoTrading)」切换为红色停止</b>，防止 <code>Step=100(1.00$)</code> 在极端剧烈波动中连续秒加仓。`,\n      `<b>第二步（删除追踪 Stop 挂单·关键！）</b>：立即在 MT4/MT5「终端 - 交易」栏中，<b>手动删除未成交的 <code>Buy Stop</code> 和 <code>Sell Stop</code> 挂单</b>（当前约在 ${trailBuyPx}$ / ${trailSellPx}$ 附近）。因为您的 EA 带有 <code>StepTrallOrders=100</code> 挂单追踪功能，不删挂单会在价格剧烈扫盘时把逆势首单 <code>0.02</code> 追到极端高位/低位成交！`,\n      `<b>第三步（现有持仓风控）</b>：${ea.curLayerNum > 0 ? `您当前已持仓 <b>${ea.curLayerNum} 层（累计 ${f2(ea.curInfo.cumLot)} 手，已浮亏约 $${f2(ea.curInfo.ddUsd)}）</b>，仅需黄金回调 <b>${f2(ea.curInfo.pullbackUsd)}$</b> 即可触发 <code>StopProfit=${f2(ea.curInfo.tpUsd)}$</code> 整组止盈平仓；若价格继续逆势超过 <b>${domDir === 'UP' ? upHardPx : dnHardPx}$</b>（再走 ${f2(ea.remHardSpan)}$）将触发 $${ea.bal} 强平线。` : `若场上仅有浅层持仓（1~4层），等待行情回调 <b>0.8~1.6$</b> 触发整组止盈后切勿再开新单；上方极限防线 <b>${upHardPx}$</b>、下方极限防线 <b>${dnHardPx}$</b>。`}`\n    ];\n    resumeRule = `需等待 <b>1M 与 5M 震荡指数同时回升至 ≥ 55</b>、单根K线指数跌幅回落至 ≤ 1.5分后，再重新开启 MT4/MT5「自动交易」。`;\n  } else if (isTrendDanger) {\n    needManual = true;\n    badgeCls = 'TREND';\n    const breachNote = isAccountBreach\n      ? `（🚨 且当前单边净波幅 ${f2(oneWayMove)}$ 已逼近/超出您 $${ea.bal} 账户的强平极限 ${f2(ea.remHardSpan)}$！）`\n      : `（当前单边推进约 ${f2(oneWayMove)}$，$${ea.bal} 账户安全上限为 ${f2(ea.remWarnSpan)}$）`;\n    if (domDir === 'UP') {\n      state = 'PAUSE_SELL';\n      badgeTxt = isAccountBreach ? '🛑 账户极危 · 立即禁空(Sell)或停EA' : '🚨 立即手动操作 · 暂停【开空单 Sell】';\n      pauseSideTxt = '🚫 立即暂停【开空单 (Sell)】· 仅允许做多 (Only Long) + 删除下方 Sell Stop 挂单';\n      headline = `⚠️ 1M/5M 主触发向上单边行情（15M/1H 趋势共振向上）${breachNote}：请立即手动暂停【开空单 Sell】，严防逆势摸顶连环加仓！`;\n      steps = [\n        `<b>第一步（在 EA 中禁止开空单 Sell）</b>：在 MT4/MT5 图表按 <code>F7</code> 打开 EA 设置 → 切换到 <b>「常规 (Common)」</b> 选项卡 → 将多空方向从 <code>Long & Short</code> 修改为 <b><code>Only Long (仅做多)</code></b>，点击确定${isAccountBreach ? '（由于当前波幅已超您账户极限，若已有深套空单建议直接点击顶部「自动交易」暂停全部加仓）' : ''}。`,\n        `<b>第二步（手动删除下方追踪 Sell Stop 挂单·必做！）</b>：在下方「交易」订单列表中，找到未成交的 <b><code>sell stop 0.02 XAUUSD</code>（当前约在 ${trailSellPx}$ 附近）右键删除</b>！<span class=\"mut\">（原因：您的 EA 参数 <code>StepTrallOrders=100</code> 会让未成交的 Sell Stop 每 1 美元跟着金价往上爬，一旦金价急涨后小幅回踩 0.6~1.0$ 就会在高位触发空单，随后若继续拉升就会陷入每 1.00$ 1.38倍逆势加空！）</span>`,\n        `<b>第三步（多单顺势收割 & 空单防守线）</b>：保留多单方向（<code>Buy Stop</code>）正常运行，利用上涨趋势每层吃 <code>StopProfit=4.0$</code> 快速止盈重置。${ea.curLayerNum > 0 ? `若当前已有被套空单（${ea.curLayerNum}层/${f2(ea.curInfo.cumLot)}手），需金价回落 <b>${f2(ea.curInfo.pullbackUsd)}$</b> 即可触发 $${f2(ea.curInfo.tpUsd)} 整组平仓；上方 65% 资金警戒价为 <b>${upWarnPx}$</b>，100% 强平极限价为 <b>${upHardPx}$</b>。` : `按您 $${ea.bal} 账户推算，上方 65% 警戒价位在 <b>${upWarnPx}$</b>（第 ${ea.warn.layer} 层），100% 极限价位在 <b>${upHardPx}$</b>（第 ${ea.hard.layer} 层）。`}`\n      ];\n      resumeRule = `当 <b>1M 与 5M 震荡指数双双回到 ≥ 55</b>（当前 1M=${adj1}, 5M=${adj5}），且 1M/5M 单次下跌速度 ≤ 1.5分、15M 停止创出新高时，再按 <code>F7</code> 改回 <code>Long & Short</code> 恢复空单。`;\n    } else if (domDir === 'DOWN') {\n      state = 'PAUSE_BUY';\n      badgeTxt = isAccountBreach ? '🛑 账户极危 · 立即禁多(Buy)或停EA' : '🚨 立即手动操作 · 暂停【开多单 Buy】';\n      pauseSideTxt = '🚫 立即暂停【开多单 (Buy)】· 仅允许做空 (Only Short) + 删除上方 Buy Stop 挂单';\n      headline = `⚠️ 1M/5M 主触发向下单边破位（15M/1H 趋势共振向下）${breachNote}：请立即手动暂停【开多单 Buy】，严防逆势抄底连环加仓！`;\n      steps = [\n        `<b>第一步（在 EA 中禁止开多单 Buy）</b>：在 MT4/MT5 图表按 <code>F7</code> 打开 EA 设置 → 切换到 <b>「常规 (Common)」</b> 选项卡 → 将多空方向从 <code>Long & Short</code> 修改为 <b><code>Only Short (仅做空)</code></b>，点击确定${isAccountBreach ? '（由于当前波幅已超您账户极限，若已有深套多单建议直接点击顶部「自动交易」暂停全部加仓）' : ''}。`,\n        `<b>第二步（手动删除上方追踪 Buy Stop 挂单·必做！）</b>：在下方「交易」订单列表中，找到未成交的 <b><code>buy stop 0.02 XAUUSD</code>（当前约在 ${trailBuyPx}$ 附近）右键删除</b>！<span class=\"mut\">（原因：您的 EA 参数 <code>StepTrallOrders=100</code> 会让未成交的 Buy Stop 跟着暴跌的价格一路往下移，一旦下跌途中小幅反抽 0.6~1.0$ 就会触发多单，随后若继续瀑布下跌就会每 1.00$ 按 1.38倍连环套牢多单！）</span>`,\n        `<b>第三步（空单顺势收割 & 多单防守线）</b>：保留空单方向（<code>Sell Stop</code>）正常运行，利用下跌趋势快速触发 <code>StopProfit=4.0$</code> 止盈重置。${ea.curLayerNum > 0 ? `若当前已有被套多单（${ea.curLayerNum}层/${f2(ea.curInfo.cumLot)}手），需金价反弹 <b>${f2(ea.curInfo.pullbackUsd)}$</b> 即可触发 $${f2(ea.curInfo.tpUsd)} 整组平仓；下方 65% 资金警戒价为 <b>${dnWarnPx}$</b>，100% 强平极限价为 <b>${dnHardPx}$</b>。` : `按您 $${ea.bal} 账户推算，下方 65% 警戒价位在 <b>${dnWarnPx}$</b>（第 ${ea.warn.layer} 层），100% 极限价位在 <b>${dnHardPx}$</b>（第 ${ea.hard.layer} 层）。`}`\n      ];\n      resumeRule = `当 <b>1M 与 5M 震荡指数双双回到 ≥ 55</b>（当前 1M=${adj1}, 5M=${adj5}），且 1M/5M 单次下跌速度 ≤ 1.5分、15M 企稳止跌时，再按 <code>F7</code> 改回 <code>Long & Short</code> 恢复多单。`;\n    } else {\n      state = 'PAUSE_BOTH_PEND';\n      badgeTxt = '⚠️ 立即手动操作 · 暂停新开首单 / 删双向挂单观望';\n      pauseSideTxt = '🚫 暂停新开双向首单 (删除未成交 Buy Stop & Sell Stop 挂单)';\n      headline = `⚠️ 1M/5M 波幅急剧扩大但多空双向剧烈扫盘：建议删除未成交双向 Stop 挂单，仅让已有持仓止盈出场！`;\n      steps = [\n        `<b>第一步（观察已有持仓）</b>：保持已有持仓等待 <code>StopProfit=4.0$ × 层数</code> 止盈平仓，但暂时不要让新方向开出首单 <code>0.02</code>。`,\n        `<b>第二步（删除未成交挂单）</b>：手动删除 <code>Buy Stop</code> (${trailBuyPx}$) 与 <code>Sell Stop</code> (${trailSellPx}$) 未成交挂单，避免上下扫盘两边同时被套。`,\n        `<b>第三步（防守区间）</b>：当前 $${ea.bal} 账户安全边界为上方 <b>${upWarnPx}$</b>、下方 <b>${dnWarnPx}$</b>（±${f2(ea.remWarnSpan)}$）。`\n      ];\n      resumeRule = `待 1M 与 5M 震荡指数回升至 ≥ 55 后恢复正常双向挂单。`;\n    }\n  } else if (isWatch) {\n    state = 'CAUTION_WATCH';\n    needManual = false;\n    badgeTxt = '🟡 一级戒备 · 准备手动锁方向';\n    badgeCls = 'MIXED';\n    const riskSide = domDir === 'UP' ? '【空单 Sell】' : domDir === 'DOWN' ? '【多单 Buy】' : '【逆势方向】';\n    const safeMode = domDir === 'UP' ? 'Only Long (仅做多)' : domDir === 'DOWN' ? 'Only Short (仅做空)' : '暂停挂单';\n    pauseSideTxt = `👀 暂不锁方向，但需重点盯防${riskSide}（若 1M/5M 跌破 50 则切为 ${safeMode}）`;\n    headline = `🟡 1M/5M 处于震荡向趋势过渡区（或 15M/1H 背景偏趋势）：当前可维持运行，但请做好暂停${riskSide}的准备`;\n    steps = [\n      `<b>当前状态（暂无需改动 EA，保持观察）</b>：1M(${adj1}分) / 5M(${adj5}分) 尚未触发硬性锁方向阈值，您的 <code>Step=100(1.00$)</code> + <code>StopProfit=4.0$</code> 仍可通过短线回撤完成整组止盈。`,\n      `<b>重点盯防方向（${riskSide}）</b>：当前多空合力偏向 <b>${domDirTxt}</b>。若接下来 1~3 分钟内 <b>1M 或 5M 震荡指数跌破 48~50</b>，或单根K线指数急跌 ≥ 4分，请立即按 <code>F7</code> 切换为 <b><code>${safeMode}</code></b> 并删除逆势 Stop 挂单。`,\n      `<b>账户安全余量</b>：按 $${ea.bal} 账户推算，当前价格 ${f2(price)}$ 距离 65% 资金警戒线还有 <b>±${f2(ea.remWarnSpan)}$</b>（上界 <b>${upWarnPx}$</b> / 下界 <b>${dnWarnPx}$</b>，最多可安全承接至第 <b>${ea.warn.layer}</b> 层）。`\n    ];\n    resumeRule = `若 1M/5M 指数重新回升至 ≥ 60，则解除戒备。`;\n  } else {\n    state = 'AUTO_OK';\n    needManual = false;\n    badgeTxt = '🟢 无需手动操作 · 黄金震荡收割期';\n    badgeCls = 'RANGE';\n    pauseSideTxt = '✅ 无需暂停（保持 Long & Short 双向 Buy Stop / Sell Stop 自动挂单与追踪）';\n    headline = `🟢 1M(${adj1}分) 与 5M(${adj5}分) 处于优质震荡区间，且 15M/1H 波幅远低于 $${ea.bal} 账户警戒线，无需任何手动操作！`;\n    steps = [\n      `<b>保持 EA 全自动双向运行</b>：当前短周期来回均值回归明显，非常适合您的 <code>FirstStep=50</code> 双向挂单 + <code>StepTrallOrders=100</code> 挂单追踪 + <code>StopProfit=4.0$ × 层数</code> 双向轮流止盈收割。`,\n      `<b>层数与回调预期</b>：当前 5M 近14根波幅仅 <b>${f2(span5)}$</b>、15M 近14根波幅 <b>${f2(span15)}$</b>，预计单边最多触发 <b>${Math.max(1, Math.min(ea.totals || 24, Math.ceil(span15 / ea.cfg.stepUsd)))} 层</b>（累计手数 ≤ ${f2((ea.layers[Math.min(ea.layers.length - 1, Math.max(0, Math.ceil(span15 / ea.cfg.stepUsd) - 1))] || ea.layers[0]).cumLot)} 手），仅需 <b>0.6~2.1$</b> 正常微幅回调即可整组止盈平仓并重置为 <code>0.02</code> 手。`,\n      `<b>账户安全边界</b>：您的 $${ea.bal} 账户可安全抗住 <b>${f2(ea.warn.span)}$</b>（第 <b>${ea.warn.layer}</b> 层，上下安全边界 <b>${dnWarnPx}$ ~ ${upWarnPx}$</b>），强平极限为 <b>${f2(ea.hard.span)}$</b>（第 <b>${ea.hard.layer}</b> 层）。`\n    ];\n    resumeRule = `保持当前设置即可；系统每 15 秒自动监测 1M/5M 突变并实时更新操作指令。`;\n  }\n\n  return {\n    state,\n    needManual,\n    badgeTxt,\n    badgeCls,\n    headline,\n    pauseSideTxt,\n    steps,\n    resumeRule,\n    fastIdx,\n    midIdx,\n    blendIdx,\n    adj1,\n    adj5,\n    adj15,\n    adj60,\n    drop1M,\n    drop5M,\n    drop15M,\n    fastDrop,\n    maxDrop14Fast,\n    domDir,\n    domDirTxt,\n    dirScore,\n    price,\n    upWarnPx,\n    upHardPx,\n    dnWarnPx,\n    dnHardPx,\n    trailBuyPx,\n    trailSellPx\n  };\n}\n\n// 仅对 1M 和 5M 的震荡指数与价格数字本身触发背景颜色高亮动画\nfunction triggerFlash() {\n  document.querySelectorAll('.fast-num').forEach((el) => {\n    el.classList.remove('flash-num');\n    void el.offsetWidth;\n    el.classList.add('flash-num');\n  });\n}\n\nconst LOCAL_DATA_CACHE_KEY = 'gold_dashboard_cache_v2';\nconst CUSTOM_EVENTS_STORAGE_KEY = 'gold_custom_events_v1';\nconst VOICE_CFG_STORAGE_KEY = 'gold_voice_cfg_v1';\n\n// ---------- 1. 重磅数据「前30分 ~ 后15分」手动红灯倒计时锁 (支持添加多个 + 投射至顶部24h时间轴) ----------\nlet CUSTOM_LOCK_EVENTS = [\n  { id: 'ev_default_2030', time: '20:30', title: '美盘20:30重磅数据窗口(CPI/初请/零售)', preMin: 30, postMin: 15, enabled: true }\n];\ntry {\n  const savedEv = JSON.parse(localStorage.getItem(CUSTOM_EVENTS_STORAGE_KEY) || 'null');\n  if (Array.isArray(savedEv)) CUSTOM_LOCK_EVENTS = savedEv;\n} catch (e) {}\n\nfunction saveCustomLockEvents() {\n  try { localStorage.setItem(CUSTOM_EVENTS_STORAGE_KEY, JSON.stringify(CUSTOM_LOCK_EVENTS)); } catch (e) {}\n}\n\nfunction getBjNowMinutes() {\n  const now = new Date();\n  const utcMs = now.getTime() + now.getTimezoneOffset() * 60000;\n  const bj = new Date(utcMs + 8 * 3600000);\n  return {\n    hh: bj.getHours(),\n    mm: bj.getMinutes(),\n    ss: bj.getSeconds(),\n    curMin: bj.getHours() * 60 + bj.getMinutes() + bj.getSeconds() / 60,\n    bjStr: String(bj.getHours()).padStart(2, '0') + ':' + String(bj.getMinutes()).padStart(2, '0') + ':' + String(bj.getSeconds()).padStart(2, '0')\n  };\n}\n\nfunction evalCustomLockState() {\n  const bj = getBjNowMinutes();\n  const curMin = bj.curMin;\n  const evaluated = CUSTOM_LOCK_EVENTS.map((ev) => {\n    const [eh, em] = (ev.time || '20:30').split(':').map(Number);\n    const evMin = (eh || 0) * 60 + (em || 0);\n    const pre = Number(ev.preMin) || 30;\n    const post = Number(ev.postMin) || 15;\n    const startMin = evMin - pre;\n    const endMin = evMin + post;\n    // 处理跨午夜差值（单位：分钟，正数表示未来，负数表示已过去）\n    let diffToEv = evMin - curMin;\n    if (diffToEv < -720) diffToEv += 1440;\n    if (diffToEv > 720) diffToEv -= 1440;\n\n    let state = 'WAIT'; // 'PRE_LOCK' | 'POST_LOCK' | 'WAIT' | 'DONE'\n    let badge = '';\n    let remainSec = 0;\n    if (!ev.enabled) {\n      state = 'DISABLED';\n      badge = '⏸️ 已暂停监控';\n    } else if (diffToEv >= 0 && diffToEv <= pre) {\n      state = 'PRE_LOCK';\n      remainSec = Math.max(0, Math.round(diffToEv * 60));\n      const m = Math.floor(remainSec / 60), s = remainSec % 60;\n      badge = `🚨 红灯锁已激活(前${pre}分) · 距公布仅剩 ${m}分${String(s).padStart(2, '0')}秒`;\n    } else if (diffToEv < 0 && Math.abs(diffToEv) <= post) {\n      state = 'POST_LOCK';\n      remainSec = Math.max(0, Math.round((post + diffToEv) * 60));\n      const m = Math.floor(remainSec / 60), s = remainSec % 60;\n      badge = `🛑 公布后脉冲锁(后${post}分) · 距解除剩 ${m}分${String(s).padStart(2, '0')}秒`;\n    } else if (diffToEv > pre) {\n      state = 'WAIT';\n      const toLockMin = Math.round(diffToEv - pre);\n      const h = Math.floor(toLockMin / 60), m = toLockMin % 60;\n      badge = `⏳ 距开启红灯锁还有 ${h > 0 ? h + '小时' : ''}${m}分钟`;\n    } else {\n      state = 'DONE';\n      badge = `✅ 今日窗口已过 (+${post}分已解除)`;\n    }\n\n    return {\n      ...ev,\n      evMin,\n      pre,\n      post,\n      startMin: (startMin + 1440) % 1440,\n      endMin: (endMin + 1440) % 1440,\n      rawStartMin: startMin,\n      rawEndMin: endMin,\n      diffToEv,\n      state,\n      badge,\n      isLocked: state === 'PRE_LOCK' || state === 'POST_LOCK'\n    };\n  });\n\n  const activeLocks = evaluated.filter((x) => x.isLocked);\n  const nextUpcoming = evaluated.filter((x) => x.enabled && x.state === 'WAIT').sort((a, b) => a.diffToEv - b.diffToEv)[0] || null;\n  return { bj, items: evaluated, activeLocks, nextUpcoming };\n}\n\nwindow.addCustomLockEvent = () => {\n  const timeEl = $('newEvTimeInput');\n  const titleEl = $('newEvTitleInput');\n  const preEl = $('newEvPreInput');\n  const postEl = $('newEvPostInput');\n  const time = (timeEl && timeEl.value) ? timeEl.value.trim() : '20:30';\n  const title = (titleEl && titleEl.value && titleEl.value.trim()) ? titleEl.value.trim() : `${time} 重点行情窗口`;\n  const preMin = Math.max(5, Math.min(180, parseInt(preEl && preEl.value, 10) || 30));\n  const postMin = Math.max(5, Math.min(180, parseInt(postEl && postEl.value, 10) || 15));\n  CUSTOM_LOCK_EVENTS.push({\n    id: 'ev_' + Date.now() + '_' + Math.random().toString(36).slice(2, 6),\n    time,\n    title,\n    preMin,\n    postMin,\n    enabled: true\n  });\n  CUSTOM_LOCK_EVENTS.sort((a, b) => a.time.localeCompare(b.time));\n  if (titleEl) titleEl.value = '';\n  saveCustomLockEvents();\n  if (D) render(); else renderCustomEventBar();\n};\n\nwindow.quickAddLockEvent = (time, title) => {\n  if (CUSTOM_LOCK_EVENTS.some((x) => x.time === time && x.title === title)) {\n    const t = $('toast');\n    if (t) { t.textContent = `已存在 ${time} ${title}`; t.style.display = 'block'; setTimeout(() => { t.style.display = 'none'; }, 2000); }\n    return;\n  }\n  CUSTOM_LOCK_EVENTS.push({\n    id: 'ev_' + Date.now() + '_' + Math.random().toString(36).slice(2, 6),\n    time,\n    title,\n    preMin: 30,\n    postMin: 15,\n    enabled: true\n  });\n  CUSTOM_LOCK_EVENTS.sort((a, b) => a.time.localeCompare(b.time));\n  saveCustomLockEvents();\n  if (D) render(); else renderCustomEventBar();\n};\n\nwindow.removeCustomLockEvent = (id) => {\n  CUSTOM_LOCK_EVENTS = CUSTOM_LOCK_EVENTS.filter((x) => x.id !== id);\n  saveCustomLockEvents();\n  if (D) render(); else renderCustomEventBar();\n};\n\nwindow.toggleCustomLockEvent = (id) => {\n  const item = CUSTOM_LOCK_EVENTS.find((x) => x.id === id);\n  if (item) item.enabled = !item.enabled;\n  saveCustomLockEvents();\n  if (D) render(); else renderCustomEventBar();\n};\n\nwindow.clearCustomLockEvents = () => {\n  CUSTOM_LOCK_EVENTS = [];\n  saveCustomLockEvents();\n  if (D) render(); else renderCustomEventBar();\n};\n\nwindow.importJin10TodayLocks = () => {\n  if (!D || !D.calendar || !Array.isArray(D.calendar.items)) return;\n  const bj = getBjNowMinutes();\n  const now = new Date(Date.now() + (new Date().getTimezoneOffset() * 60000) + 8 * 3600000);\n  const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;\n  let added = 0;\n  for (const e of D.calendar.items) {\n    if ((e.star || 0) >= 3 && e.kind !== 'holiday' && (e.time || '').startsWith(todayStr)) {\n      const hhmm = (e.time || '').slice(11, 16);\n      if (/^\\d{2}:\\d{2}$/.test(hhmm) && !CUSTOM_LOCK_EVENTS.some((x) => x.time === hhmm)) {\n        CUSTOM_LOCK_EVENTS.push({\n          id: 'ev_jin10_' + hhmm + '_' + Math.random().toString(36).slice(2, 5),\n          time: hhmm,\n          title: `[${e.country}] ${e.title.slice(0, 26)}`,\n          preMin: 30,\n          postMin: 15,\n          enabled: true\n        });\n        added++;\n      }\n    }\n  }\n  CUSTOM_LOCK_EVENTS.sort((a, b) => a.time.localeCompare(b.time));\n  saveCustomLockEvents();\n  const t = $('toast');\n  if (t) {\n    t.textContent = added > 0 ? `✅ 已导入今日 ${added} 个金十★★★重磅时点至顶部时间轴` : '今日暂无更多未添加的金十★★★重磅数据';\n    t.style.display = 'block';\n    setTimeout(() => { t.style.display = 'none'; }, 2600);\n  }\n  if (D) render(); else renderCustomEventBar();\n};\n\nfunction renderCustomEventBar() {\n  const st = evalCustomLockState();\n  const badgeEl = $('customLockStatusBadge');\n  const listEl = $('customEventList');\n  if (badgeEl) {\n    if (st.activeLocks.length) {\n      const top = st.activeLocks[0];\n      badgeEl.className = 'pill TREND';\n      badgeEl.textContent = `🚨 红灯锁生效中 (${st.activeLocks.length}项)：${top.time} ${top.title} · 严禁新开马丁逆势单！`;\n    } else if (st.nextUpcoming) {\n      badgeEl.className = 'pill MIXED';\n      badgeEl.textContent = `⏱️ 下一锁定窗口：${st.nextUpcoming.time} ${st.nextUpcoming.title} (${st.nextUpcoming.badge})`;\n    } else {\n      badgeEl.className = 'pill RANGE';\n      badgeEl.textContent = '🟢 当前无激活的重磅红灯锁';\n    }\n  }\n  if (listEl) {\n    if (!st.items.length) {\n      listEl.innerHTML = `<span class=\"xs mut\">暂未添加重磅锁定时点，可在下方输入时间(如 20:30)添加，或点击右侧快捷按钮一键加入时间轴。</span>`;\n    } else {\n      listEl.innerHTML = st.items.map((ev) => {\n        const isLock = ev.isLocked;\n        const borderCol = isLock ? '#f43f5e' : (ev.state === 'WAIT' ? 'rgba(245,158,11,0.55)' : 'var(--bd)');\n        const bgCol = isLock ? 'rgba(244,63,94,0.22)' : 'rgba(23,30,44,0.9)';\n        return `<div style=\"display:inline-flex;align-items:center;gap:7px;padding:5px 10px;border-radius:7px;border:1px solid ${borderCol};background:${bgCol};font-size:12px;opacity:${ev.enabled ? '1' : '0.55'}\">\n          <input type=\"checkbox\" ${ev.enabled ? 'checked' : ''} onchange=\"toggleCustomLockEvent('${ev.id}')\" title=\"勾选/取消启用该时点红灯锁\" style=\"cursor:pointer\">\n          <b style=\"color:var(--gold);font-size:13px\">${ev.time}</b>\n          <span style=\"color:#fff;font-weight:700\">${ev.title}</span>\n          <span class=\"xs mut\">[前${ev.pre}m~后${ev.post}m]</span>\n          <span class=\"pill ${isLock ? 'TREND' : (ev.state === 'WAIT' ? 'MIXED' : 'NEUT')}\" style=\"padding:1px 7px;font-size:11px\">${ev.badge}</span>\n          <button class=\"sm\" onclick=\"removeCustomLockEvent('${ev.id}')\" style=\"padding:0 5px;color:#fb7185;border:none;background:transparent;font-size:13px\" title=\"删除该锁定时点\">✕</button>\n        </div>`;\n      }).join('');\n    }\n  }\n  return st;\n}\n\n// ---------- 2. 浏览器语音报警系统 (支持自定义敏感度 Lv0~Lv3 与防打扰冷却时间) ----------\nlet VOICE_CFG = { enabled: true, sens: 1, cooldownMin: 15 };\ntry {\n  const savedV = JSON.parse(localStorage.getItem(VOICE_CFG_STORAGE_KEY) || 'null');\n  if (savedV && typeof savedV.enabled === 'boolean') VOICE_CFG = { ...VOICE_CFG, ...savedV };\n} catch (e) {}\n\nconst VOICE_HISTORY = {}; // key -> lastSpokenTimestampMs\n\nfunction syncVoiceUi() {\n  const btn = $('btnVoiceToggle');\n  const sEl = $('voiceSensSelect');\n  const cEl = $('voiceCoolSelect');\n  if (btn) {\n    btn.textContent = VOICE_CFG.enabled ? '🔊 语音报警: 开' : '🔇 语音报警: 关';\n    btn.style.borderColor = VOICE_CFG.enabled ? 'rgba(16,185,129,0.6)' : 'var(--bd)';\n    btn.style.color = VOICE_CFG.enabled ? '#34d399' : '#94a3b8';\n  }\n  if (sEl) sEl.value = String(VOICE_CFG.sens);\n  if (cEl) cEl.value = String(VOICE_CFG.cooldownMin);\n}\n\nwindow.toggleVoiceAlert = () => {\n  VOICE_CFG.enabled = !VOICE_CFG.enabled;\n  try { localStorage.setItem(VOICE_CFG_STORAGE_KEY, JSON.stringify(VOICE_CFG)); } catch (e) {}\n  syncVoiceUi();\n  if (VOICE_CFG.enabled) {\n    playVoiceNow('语音报警已开启，将按您设定的敏感度播报风控指令');\n  } else if (window.speechSynthesis) {\n    window.speechSynthesis.cancel();\n  }\n};\n\nwindow.updateVoiceCfg = () => {\n  const sEl = $('voiceSensSelect');\n  const cEl = $('voiceCoolSelect');\n  if (sEl) VOICE_CFG.sens = parseInt(sEl.value, 10);\n  if (cEl) VOICE_CFG.cooldownMin = parseInt(cEl.value, 10) || 15;\n  try { localStorage.setItem(VOICE_CFG_STORAGE_KEY, JSON.stringify(VOICE_CFG)); } catch (e) {}\n  syncVoiceUi();\n};\n\nfunction playBeep() {\n  try {\n    const Ctx = window.AudioContext || window.webkitAudioContext;\n    if (!Ctx) return;\n    const ctx = new Ctx();\n    const osc = ctx.createOscillator();\n    const gain = ctx.createGain();\n    osc.type = 'sine';\n    osc.frequency.setValueAtTime(880, ctx.currentTime);\n    osc.frequency.setValueAtTime(1174, ctx.currentTime + 0.12);\n    gain.gain.setValueAtTime(0.12, ctx.currentTime);\n    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.32);\n    osc.connect(gain);\n    gain.connect(ctx.destination);\n    osc.start();\n    osc.stop(ctx.currentTime + 0.33);\n  } catch (e) {}\n}\n\nfunction playVoiceNow(text) {\n  playBeep();\n  const logEl = $('voiceLastLog');\n  const bj = getBjNowMinutes();\n  if (logEl) {\n    logEl.innerHTML = `<span style=\"color:var(--gold)\">🔊 [${bj.bjStr} 已播报]</span>: ${text}`;\n  }\n  try {\n    if ('speechSynthesis' in window) {\n      window.speechSynthesis.cancel();\n      const u = new SpeechSynthesisUtterance(text);\n      u.lang = 'zh-CN';\n      u.rate = 1.08;\n      u.pitch = 1.0;\n      window.speechSynthesis.speak(u);\n    }\n  } catch (e) {}\n}\n\nwindow.testVoiceAlert = () => {\n  const sensNames = { 0: '仅重磅倒计时锁', 1: 'Lv1极高危保命档', 2: 'Lv2中高危均衡档', 3: 'Lv3高灵敏盯盘档' };\n  playVoiceNow(`黄金马丁风控语音测试正常，当前敏感度为${sensNames[VOICE_CFG.sens] || '默认'}，冷却时间${VOICE_CFG.cooldownMin}分钟。`);\n};\n\nfunction trySpeakAlert(key, reqSensLevel, text) {\n  if (!VOICE_CFG.enabled) return false;\n  // 若用户选择 Lv0(仅手动重磅倒计时锁)，则只播报 reqSensLevel === 0 的事件\n  if (VOICE_CFG.sens === 0 && reqSensLevel > 0) return false;\n  if (reqSensLevel > VOICE_CFG.sens) return false;\n\n  const now = Date.now();\n  const coolMs = (VOICE_CFG.cooldownMin || 15) * 60 * 1000;\n  if (VOICE_HISTORY[key] && (now - VOICE_HISTORY[key] < coolMs)) {\n    return false;\n  }\n  VOICE_HISTORY[key] = now;\n  playVoiceNow(text);\n  return true;\n}\n\nfunction evaluateVoiceAlerts(d, eaDir, lockState) {\n  if (!VOICE_CFG.enabled || !d) return;\n  // 优先级 0 (Lv0+): 手动重磅数据红灯倒计时锁\n  if (lockState && lockState.activeLocks && lockState.activeLocks.length) {\n    const top = lockState.activeLocks[0];\n    const modeKey = `lock_${top.id}_${top.state}`;\n    const msg = top.state === 'PRE_LOCK'\n      ? `红灯预警：距离${top.time}${top.title}公布不足${top.pre}分钟，已进入高危锁定期，建议暂停EA新开挂单并控制净敞口。`\n      : `脉冲预警：${top.title}刚刚公布，当前处于公布后${top.post}分钟剧烈插针期，严防双向扫损。`;\n    if (trySpeakAlert(modeKey, 0, msg)) return;\n  }\n\n  // 优先级 1 (Lv1+ 极高危保命): EA 触发立即暂停单边加仓指令\n  if (eaDir && eaDir.level === 'DANGER') {\n    if (trySpeakAlert('ea_danger_' + eaDir.pauseSideTxt, 1, `风控高危警报：${eaDir.pauseSideTxt}。${eaDir.headline}`)) return;\n  }\n\n  // 优先级 1 (Lv1+ 极高危保命): 1M 或 5M 单次暴跌 >= 8 分\n  const t1 = d.timeframes && d.timeframes['1M'];\n  const t5 = d.timeframes && d.timeframes['5M'];\n  if ((t1 && t1.idxDrop1 >= 8) || (t5 && t5.idxDrop1 >= 8)) {\n    const k = (t5 && t5.idxDrop1 >= 8) ? '5分钟' : '1分钟';\n    const drop = (t5 && t5.idxDrop1 >= 8) ? t5.idxDrop1 : t1.idxDrop1;\n    if (trySpeakAlert('plunge_severe_' + k, 1, `急跌警报：黄金${k}震荡指数单次急跌${drop}分，行情正在加速破位，请注意锁仓或暂停逆势马丁。`)) return;\n  }\n\n  // 优先级 1 (Lv1+ 极高危保命): 散户多空比极端拥挤 (>=74% 或 空头>=70%)\n  if (d.sentiment && (d.sentiment.retailLongPct >= 74 || d.sentiment.retailShortPct >= 70)) {\n    const isLongCrowd = d.sentiment.retailLongPct >= 74;\n    const msg = isLongCrowd\n      ? `散户反指警报：全市场散户做多比例高达百分之${d.sentiment.retailLongPct}，谨防主力向下砸盘逼多，切勿放任买单逆势加仓。`\n      : `散户反指警报：全市场散户做空比例高达百分之${d.sentiment.retailShortPct}，谨防主力向上拉升逼空，切勿放任卖单逆势加仓。`;\n    if (trySpeakAlert('sent_extreme_' + (isLongCrowd ? 'L' : 'S'), 1, msg)) return;\n  }\n\n  // 优先级 2 (Lv2+ 中高危均衡): 贴脸关键清算位 <= 1.8$\n  if (d.keyLevels && d.keyLevels.nearestDanger && d.keyLevels.nearestDanger.absDiff <= 1.8) {\n    const lv = d.keyLevels.nearestDanger;\n    if (trySpeakAlert('klv_' + lv.id, 2, `清算位雷区提醒：当前金价距离${lv.name}仅${lv.absDiff}美元，谨防触及止损池引发插针扫损。`)) return;\n  }\n\n  // 优先级 2 (Lv2+ 中高危均衡): 特朗普高危涉金言论 (近30分钟内)\n  if (d.trump && Array.isArray(d.trump.items)) {\n    const hotT = d.trump.items.find((x) => x.ageMin <= 30 && x.impact === 'HIGH' && x.isGoldRelevant);\n    if (hotT) {\n      if (trySpeakAlert('trump_' + hotT.id, 2, `突发重磅言论：检测到特朗普或关税联储高危快讯，${hotT.goldBias}，请留意盘面脉冲。`)) return;\n    }\n  }\n\n  // 优先级 3 (Lv3 高灵敏盯盘): 1M/5M 轻度急跌 >= 4.5分 或 关注度 >= 68\n  if ((t1 && t1.idxDrop1 >= 4.5) || (t5 && t5.idxDrop1 >= 4.5)) {\n    if (trySpeakAlert('plunge_mild', 3, `盯盘提醒：短周期震荡指数出现单次下滑，请留意K线波幅扩大。`)) return;\n  }\n}\n\n// ---------- 3. 「M1双向追踪倍投马丁EA · 多空净敞口风控推演台」显示/隐藏开关 (默认关闭收起，按需随时打开) ----------\nconst SHOW_TOL_STORAGE_KEY = 'gold_show_tol_sec_v1';\nlet SHOW_TOL_SEC = false; // 默认关闭，避免干扰视线\ntry {\n  const savedTolShow = localStorage.getItem(SHOW_TOL_STORAGE_KEY);\n  if (savedTolShow !== null) SHOW_TOL_SEC = savedTolShow === '1';\n} catch (e) {}\n\nfunction syncTolSecToggleUi() {\n  const bodyEl = $('tolSecBody');\n  const btnEl = $('btnToggleTolSec');\n  const badgeEl = $('eaParamBadge');\n  const hintEl = $('tolSecCollapsedHint');\n  const navEa = $('nav-ea');\n  if (bodyEl) bodyEl.style.display = SHOW_TOL_SEC ? 'block' : 'none';\n  if (badgeEl) badgeEl.style.display = SHOW_TOL_SEC ? 'inline-block' : 'none';\n  if (hintEl) hintEl.textContent = SHOW_TOL_SEC ? '(当前已展开 · 点击右侧开关可随时收起隐藏)' : '(已按需收起关闭 · 想用时点击右侧开关即可打开)';\n  if (btnEl) {\n    btnEl.textContent = SHOW_TOL_SEC ? '🔽 关闭隐藏此推演台 (当前已开启)' : '🔘 开启净敞口推演台 (当前已关闭)';\n    btnEl.className = SHOW_TOL_SEC ? 'sm' : 'sm pri';\n  }\n  if (!SHOW_TOL_SEC && navEa) {\n    navEa.textContent = '已关';\n    navEa.className = 'pill NEUT';\n  }\n}\n\nwindow.toggleTolSec = () => {\n  SHOW_TOL_SEC = !SHOW_TOL_SEC;\n  try { localStorage.setItem(SHOW_TOL_STORAGE_KEY, SHOW_TOL_SEC ? '1' : '0'); } catch (e) {}\n  syncTolSecToggleUi();\n};\n\n// 每秒刷新一次顶部手动重磅事件红灯锁倒计时（不发网络请求，纯本地零开销跳秒）\nsetInterval(() => {\n  const st = renderCustomEventBar();\n  if (D && st && st.activeLocks && st.activeLocks.length) {\n    evaluateVoiceAlerts(D, null, st);\n  }\n}, 1000);\n\n// 合并快刷返回的数据与本地已缓存的低频数据(1D日线/kNN/GVZ/金十周历)，确保快刷时低频模块永不丢失\nfunction mergeDashboardData(prev, incoming) {\n  if (!prev) return incoming;\n  if (!incoming || !incoming.timeframes) return prev;\n  const out = { ...prev, ...incoming };\n  out.timeframes = { ...(prev.timeframes || {}), ...(incoming.timeframes || {}) };\n  if (!incoming.gvz && prev.gvz) out.gvz = prev.gvz;\n  if (!incoming.attention && prev.attention) out.attention = prev.attention;\n  if (!incoming.sentiment && prev.sentiment) out.sentiment = prev.sentiment;\n  if (!incoming.keyLevels && prev.keyLevels) out.keyLevels = prev.keyLevels;\n  if (!incoming.pullback && prev.pullback) out.pullback = prev.pullback;\n  if ((!incoming.calendar || !incoming.calendar.items || !incoming.calendar.items.length) && prev.calendar && prev.calendar.items && prev.calendar.items.length) {\n    out.calendar = prev.calendar;\n  }\n  if (prev.model && incoming.model) {\n    out.model = {\n      ...prev.model,\n      ...incoming.model,\n      knn: incoming.model.knn || prev.model.knn,\n      sparks: { ...(prev.model.sparks || {}), ...(incoming.model.sparks || {}) }\n    };\n  }\n  return out;\n}\n\nasync function load(force, fastOnly = false, silentBg = false) {\n  const b = fastOnly ? $('btnFast') : $('btnFetch');\n  if (!fastOnly && !silentBg && b) { b.disabled = true; b.textContent = '获取中…'; }\n  try {\n    const q = force ? '?force=1' : (fastOnly ? '?fast=1' : '');\n    const r = await fetch('/api/data' + q);\n    const incoming = await r.json();\n    if (incoming && incoming.timeframes) {\n      D = mergeDashboardData(D, incoming);\n      try { localStorage.setItem(LOCAL_DATA_CACHE_KEY, JSON.stringify(D)); } catch (e) {}\n      render();\n      triggerFlash();\n      if (force) toast('已强制全量刷新最新数据');\n      // 如果当前缓存中还没有低频数据(1D日线或金十周历)，在后台静默补全一次低频数据，不阻塞界面\n      const missingSlow = !D.timeframes['1D'] || !D.calendar || !D.calendar.items || !D.calendar.items.length;\n      if (fastOnly && missingSlow && !window._bgSlowFetching) {\n        window._bgSlowFetching = true;\n        load(false, false, true).finally(() => { window._bgSlowFetching = false; });\n      }\n    }\n  } catch (e) {\n    if (!D && $('meta')) $('meta').innerHTML = '<span class=\"err\">获取失败: ' + e.message + '</span>';\n  }\n  if (!fastOnly && !silentBg && b) { b.disabled = false; b.textContent = '🔄 全量刷新所有数据'; }\n}\n\nconst G_ = '#2ecc8f', Y_ = '#f0b429', R_ = '#ef5b5b';\nconst PCT_ZONES = [[20, G_, '低'], [80, Y_, '中'], [100, R_, '高']];\nconst GAUGES = [\n  { name: 'ADX(14) 趋势强度', key: 'adx', max: 50, url: 'https://www.tradingview.com/scripts/search/ADX/', zones: [[20, G_, '低·震荡'], [25, Y_, '过渡'], [50, R_, '高·趋势']], tip: '<20 震荡, >25 趋势' },\n  { name: 'CHOP(14) 震荡指数', key: 'chop', max: 100, url: 'https://www.tradingview.com/scripts/search/CHOP/', zones: [[38.2, R_, '低·趋势'], [61.8, Y_, '中性'], [100, G_, '高·震荡']], tip: '>61.8 震荡, <38.2 趋势' },\n  { name: 'ATR比率 (14/100)', key: 'atrRatio', max: 2, url: 'https://www.tradingview.com/scripts/search/ATR%20Ratio/', zones: [[0.82, G_, '挤压'], [1.25, Y_, '正常'], [2, R_, '扩张']], sub: (t) => `ATR14 ${f2(t.atrFast)}$ / ATR100 ${f2(t.atrSlow)}$`, tip: '<0.82 挤压(蓄势), >1.25 扩张(趋势启动)' },\n  { name: '效率比 ER(20)', key: 'er', max: 1, url: 'https://www.tradingview.com/scripts/search/Efficiency%20Ratio/', zones: [[0.25, G_, '低·拉锯'], [0.5, Y_, '中性'], [1, R_, '高·单向']], tip: '净位移/路径长度, <0.25 来回震荡, >0.5 单向趋势' },\n  { name: '布林带宽分位(%)', key: 'bbwPct', max: 100, url: 'https://www.tradingview.com/scripts/search/Bollinger%20Bandwidth/', zones: PCT_ZONES, sub: (t) => `BBW ${t.bbw}%`, tip: '低=带宽收窄(挤压), 高=带宽张开' },\n  { name: 'ATR 历史分位(%)', key: 'atrPct', max: 100, url: 'https://www.tradingview.com/scripts/search/ATR/', zones: PCT_ZONES, tip: '当前波动在近期历史中的位置' },\n  { name: 'EMA50 偏离(ATR倍数)', key: 'emaDist', max: 4, abs: true, url: 'https://www.tradingview.com/scripts/search/EMA/', zones: [[1, G_, '贴近均线'], [2, Y_, '偏离'], [4, R_, '远离·趋势']], sub: (t) => `EMA50 ${f2(t.ema50)}$ (${t.emaDist >= 0 ? '价格在上方·偏多' : '价格在下方·偏空'})`, tip: '价格距EMA50越远越像单边' },\n  { name: 'RSI(14)', key: 'rsi', max: 100, url: 'https://www.tradingview.com/scripts/search/RSI/', zones: [[30, R_, '超卖·空头强'], [40, Y_, '偏弱'], [60, G_, '中枢·震荡'], [70, Y_, '偏强'], [100, R_, '超买·多头强']], tip: '40-60 中枢多为震荡, 极端区动能强' },\n  { name: '震荡指数单次跌幅(跳水预警)', key: 'idxDrop1', max: 20, url: 'https://wallstreetcn.com/markets/codes/XAUUSD.OTC', zones: [[4, G_, '平稳·安全'], [8, Y_, '异动·警惕'], [20, R_, '急跌·K线巨震']], sub: (t) => `单次变化 ${(t.idxChg1 ?? 0) >= 0 ? '+' : ''}${t.idxChg1 ?? 0}分 · 3根累计跌 ${t.idxDrop3 ?? 0}分 · 14根最大单次跌 ${t.maxDrop14 ?? 0}分(对应K线波幅${f2(t.maxDropBarSpan14)}$)`, tip: '震荡指数单次下跌达到一定幅度(≥8分)时K线波动极大,严禁入场' },\n  { name: '均线回归穿刺(20根穿MA20次数)', key: 'maCross20', max: 12, url: 'https://www.tradingview.com/scripts/search/MA%20Cross/', zones: [[1.5, R_, '单侧悬空·阴涨跌'], [4, Y_, '偶有回踩'], [12, G_, '高频穿线·极佳网格']], sub: (t) => `近20根K线触碰布林中轨 ${t.maCross20 ?? 0} 次 (${(t.maCross20 ?? 0) <= 1 ? '单侧不回头,警惕累单' : '围绕中轨来回震荡'})`, tip: '网格最怕单侧悬空阴涨阴跌(0~1次), 最喜欢围绕中轨高频来回穿刺(≥4次)' },\n];\nfunction gauge(g, v, apiUrl, sub) {\n  if (v == null) return `<div class=\"g\"><div class=\"gh\">${g.name}</div><span class=\"mut\">无数据</span></div>`;\n  const val = g.abs ? Math.abs(v) : v;\n  const pos = Math.max(0, Math.min(100, val / g.max * 100));\n  let prev = 0, zname = '', zcol = '', segs = '';\n  for (const [to, col, nm] of g.zones) {\n    const isHit = !zname && (val <= to || to === g.zones[g.zones.length - 1][0]);\n    if (isHit) { zname = nm; zcol = col; }\n    segs += `<div class=\"${isHit ? 'z-active' : ''}\" style=\"width:${(to - prev) / g.max * 100}%;background:${col}\" title=\"${nm}\"></div>`;\n    prev = to;\n  }\n  const isErr = zcol === R_;\n  const isWarn = zcol === Y_;\n  const cardCls = isErr ? 'g g-err' : isWarn ? 'g g-warn' : 'g';\n  const pillCls = isErr ? 'pill TREND' : isWarn ? 'pill MIXED' : 'pill NEUT';\n  const ticks = g.zones.slice(0, -1).map((z) => `<span style=\"left:${z[0] / g.max * 100}%\">${z[0]}</span>`).join('');\n  const title = g.url ? `<a href=\"${g.url}\" target=\"_blank\" rel=\"noopener\">${g.name}</a>` : g.name;\n  return `<div class=\"${cardCls}\" title=\"${g.tip || ''}\"><div class=\"gh\"><span>${title}</span><span><b style=\"color:#fff;margin-right:4px\">${lk(apiUrl, v)}</b><span class=\"${pillCls}\">${zname}</span></span></div>\n    <div class=\"bar\">${segs}<div class=\"mk\" style=\"left:${pos}%\"></div></div><div class=\"ticks\">${ticks}</div>${sub ? `<div class=\"mut sm\" style=\"margin-top:2px;font-size:11.5px\">${sub}</div>` : ''}</div>`;\n}\n\nconst IDX_ZONES = [[30, R_, '强单边'], [45, R_, '偏单边'], [55, Y_, '过渡'], [70, G_, '偏震荡'], [100, G_, '强震荡']];\nfunction idxBar(v) {\n  if (v == null) return '';\n  const pos = Math.max(0, Math.min(100, v));\n  let prev = 0, hit = false, segs = '';\n  for (const [to, col, nm] of IDX_ZONES) {\n    const isHit = !hit && (pos <= to || to === 100);\n    if (isHit) hit = true;\n    segs += `<div class=\"${isHit ? 'z-active' : ''}\" style=\"width:${to - prev}%;background:${col}\" title=\"${nm}\"></div>`;\n    prev = to;\n  }\n  const ticks = [30, 45, 55, 70].map((t) => `<span style=\"left:${t}%\">${t}</span>`).join('');\n  return `<div class=\"bar\" style=\"margin-top:6px\">${segs}<div class=\"mk\" style=\"left:${pos}%\"></div></div><div class=\"ticks\">${ticks}</div>`;\n}\n\n// 计算每个时间点的「入场/离场双线指数 (抗毛刺平滑快线 entryFast + EMA8 稳定慢均线 entrySlow)」及【🟢入场区间 / 🛡️均线护航等回调 / 🔴离场区间】\n// 核心改进：\n// 1) 过滤单根K线闪跌毛刺：对原始分做 3周期抗毛刺滤波得到「快线(entryFast)」，再计算 8周期指数移动平均得到「慢均线(entrySlow / EMA8)」；\n// 2) 防止“有时候入场指数降低，但很快又回去了”造成误离场：当快线短暂下探，但慢均线(EMA8)依然稳守在 ≥55分 以上时，判定为「🛡️ 假跌毛刺·均线护航中(拿住等回调)」，不轻易发离场假警报；\n// 3) 锯齿回调补偿：若近 10 根 K 线内虽有单边波动但已出现 ≥2.5$ 的有效反向回调(马丁可止盈清仓)，自动给入场指数补分。\nfunction calcEntrySeries(rawArr, tol, tf) {\n  if (!rawArr || !rawArr.length) return [];\n  let useTf = tf;\n  if (!useTf && rawArr.length >= 2) {\n    const dt = Math.abs((rawArr[1].t || 0) - (rawArr[0].t || 0));\n    useTf = dt <= 90 ? '1M' : dt <= 400 ? '5M' : dt <= 1200 ? '15M' : dt <= 5400 ? '1H' : '4H';\n  }\n  const base = rawArr.map((p) => ({ ...p, adjV: adjBySpan(p.v, p.span, tol, useTf) }));\n\n  // 第一步：计算每根 K 线的原始得分与锯齿回调补偿\n  const step1 = base.map((p, i) => {\n    const prev = i > 0 ? base[i - 1] : p;\n    const adjChg1 = r1(p.adjV - prev.adjV);\n    const adjDrop1 = r1(Math.max(0, prev.adjV - p.adjV));\n    const rawDrop1 = p.drop1 != null ? p.drop1 : r1(Math.max(0, prev.v - p.v));\n    const effDrop1 = r1(Math.max(rawDrop1, adjDrop1));\n    const effChg1 = p.chg1 != null && Math.abs(p.chg1) > Math.abs(adjChg1) ? p.chg1 : adjChg1;\n    let p3Max = p.adjV;\n    for (let j = Math.max(0, i - 3); j < i; j++) p3Max = Math.max(p3Max, base[j].adjV);\n    const effDrop3 = r1(Math.max(p.drop3 || 0, Math.max(0, p3Max - p.adjV)));\n    const barSpan = p.barSpan != null ? p.barSpan : +(((p.h ?? p.c) - (p.l ?? p.c)) || 0).toFixed(2);\n\n    // 检查近 10 根 K 线内是否有 >= 2.5$ 的有效回调（锯齿止盈基因补偿）\n    let winHi = p.h ?? p.c, winLo = p.l ?? p.c;\n    for (let j = Math.max(0, i - 9); j <= i; j++) {\n      const bj = base[j];\n      if ((bj.h ?? bj.c) > winHi) winHi = bj.h ?? bj.c;\n      if ((bj.l ?? bj.c) < winLo) winLo = bj.l ?? bj.c;\n    }\n    const curC = p.c ?? 0;\n    const bounceFromLo = Math.max(0, curC - winLo);\n    const dipFromHi = Math.max(0, winHi - curC);\n    const hasSawtoothPb = (winHi - winLo >= 4.0) && (bounceFromLo >= 2.4 && dipFromHi >= 2.4);\n\n    // 原始单根入场评分（温和扣分，避免单根K线直接砸穿30分造成剧烈毛刺）\n    let rawScore = p.adjV + (hasSawtoothPb ? 7 : 0);\n    if (effDrop1 >= 4.0) rawScore -= Math.min(18, (effDrop1 - 3.5) * 2.2);\n    if (effDrop3 >= 9.0) rawScore -= Math.min(14, (effDrop3 - 8.0) * 1.4);\n    if (tol > 0 && barSpan > tol * 0.35) rawScore -= Math.min(14, (barSpan / tol - 0.35) * 32);\n    const bbBreak = p.bbU != null && p.bbL != null && (p.c > p.bbU || p.c < p.bbL);\n    if (bbBreak) rawScore -= 6;\n    rawScore = r1(clamp(rawScore, 5, 98));\n\n    return { ...p, barSpan, effChg1, effDrop1, effDrop3, bbBreak, hasSawtoothPb, rawScore };\n  });\n\n  // 第二步：计算「抗毛刺快线 (entryFast, 3周期加权平滑)」与「稳定慢均线 (entrySlow, EMA8 指数均线)」\n  let emaSlow = step1[0].rawScore;\n  const alphaSlow = 2 / (8 + 1); // EMA8\n\n  const out = step1.map((p, i) => {\n    const r0 = p.rawScore;\n    const r1Prev = i >= 1 ? step1[i - 1].rawScore : r0;\n    const r2Prev = i >= 2 ? step1[i - 2].rawScore : r1Prev;\n    // 快线：3根K线加权滤波 (0.50, 0.32, 0.18)，既保留反应速度，又滤掉1分钟单根假插针毛刺\n    const entryFast = r1(clamp(0.50 * r0 + 0.32 * r1Prev + 0.18 * r2Prev, 5, 98));\n    // 慢均线：EMA8，作为判断入场/离场区间的核心定海神针\n    emaSlow = i === 0 ? entryFast : (alphaSlow * entryFast + (1 - alphaSlow) * emaSlow);\n    const entrySlow = r1(clamp(emaSlow, 5, 98));\n\n    // 主显示分数采用平滑快线 entryFast，但区间定性由「快线 + 慢均线(EMA8)」双线共同决定！\n    const entryScore = entryFast;\n\n    let entryState, entryTxt, entryCls, entryCol, entryReason, zoneName;\n    if (entrySlow >= 56 && entryFast >= 56) {\n      // 双线均在 56 分以上 -> 明确处于【🟢 入场区间】\n      entryState = 'OK';\n      zoneName = '🟢 入场区间';\n      entryTxt = '🟢 适合入场(双线共振)';\n      entryCls = 'RANGE';\n      entryCol = '#2ecc8f';\n      entryReason = `快线(${entryFast})与慢均线EMA8(${entrySlow})稳居入场区(≥56)，适合双向马丁运行`;\n    } else if (entrySlow >= 55 && entryFast >= 43 && p.effDrop3 < 12) {\n      // 快线短暂掉下56分，但慢均线(EMA8)依然稳守在 >=55分 -> 典型“闪跌假毛刺”，均线护航中，别乱离场！\n      entryState = 'OK';\n      zoneName = '🛡️ 均线护航(假跌过滤)';\n      entryTxt = '🛡️ 均线未破·拿住等回调';\n      entryCls = 'RANGE';\n      entryCol = '#38bdf8';\n      entryReason = `快线(${entryFast})短暂波动，但慢均线EMA8(${entrySlow})仍稳守安全区(≥55)，属假跌毛刺，无需离场`;\n    } else if ((entrySlow < 46 && entryFast < 46) || (entryFast < 38 && entrySlow < 51) || p.effDrop3 >= 14) {\n      // 双线跌破 46 分离场线，或连续重挫击穿均线 -> 真正进入【🔴 离场/锁仓区间】\n      entryState = 'NO';\n      zoneName = '🔴 离场/锁仓区间';\n      entryTxt = '🔴 离场/暂停加仓(双线破位)';\n      entryCls = 'TREND';\n      entryCol = '#ef5b5b';\n      entryReason = `快线(${entryFast})与慢均线EMA8(${entrySlow})双双跌入离场区(<46)，谨防无回调单边，建议暂停逆势加仓或锁仓`;\n    } else {\n      // 处于 46 ~ 56 之间的缓冲带 -> 【🟡 缓冲/等回调区间】\n      entryState = 'WAIT';\n      zoneName = '🟡 缓冲/等回调区';\n      entryTxt = '🟡 有单等回调·空仓观望';\n      entryCls = 'MIXED';\n      entryCol = '#f0b429';\n      entryReason = `双线处于46~56过渡缓冲带(快线${entryFast}/均线${entrySlow})，有单者等$2.7反抽平仓，空仓暂缓新开`;\n    }\n\n    return {\n      ...p,\n      entryScore,\n      entryFast,\n      entrySlow,\n      entryState,\n      zoneName,\n      entryTxt,\n      entryCls,\n      entryCol,\n      entryReason\n    };\n  });\n\n  // 第三步：标记区间切换信号点（用于 K 线与双线图上标注「🟢进场」与「🔴离场」）\n  for (let i = 1; i < out.length; i++) {\n    const cur = out[i], prv = out[i - 1];\n    if (cur.entryState === 'OK' && prv.entryState !== 'OK' && cur.entryFast >= 57) {\n      cur.switchTag = 'ENTRY'; // 切换到入场区\n    } else if (cur.entryState === 'NO' && prv.entryState !== 'NO') {\n      cur.switchTag = 'EXIT';  // 切换到离场区\n    }\n  }\n  return out;\n}\n\nlet ENTRY_CHART_TF = '5M'; // 独立「入场/离场双线 × K线对照大图」默认周期\nconst ENTRY_DEDICATED_PTS = {};\n\nwindow.setEntryChartTf = function(tf) {\n  ENTRY_CHART_TF = tf;\n  if (D) render();\n};\n\n// 专门的「🚦 入场/离场双线历史走势 × 黄金 K 线 1:1 上下对照大图」（上半图：黄金K线+入场/离场背景区间色带；下半图：快线+EMA8慢均线+入场/离场区间标注）\nfunction buildEntryKLineChartSvg(rawArr, tf) {\n  if (!rawArr || rawArr.length < 2) return '<div class=\"mut\">暂无该周期历史数据</div>';\n  const arr = calcEntrySeries(rawArr, TOL);\n  const W = 1200, H = 560, L = 66, R = 138, T = 26, B = 44;\n  const cw = W - L - R, n = arr.length;\n  const xOf = (i) => L + (i / (n - 1)) * cw;\n\n  // 上半屏 (canTop ~ canBot): 黄金 K 线图 + 入场/离场区间直投背景色带\n  // 下半屏 (entTop ~ entBot): 入场快线(青白) + EMA8慢均线(亮金粗线) + 入场区间(≥56绿) / 缓冲区间(46-56黄) / 离场区间(<46红)\n  const canTop = T, canH = 235, canBot = canTop + canH;\n  const entTop = canBot + 36, entH = H - B - entTop, entBot = entTop + entH;\n\n  let pMin = Infinity, pMax = -Infinity;\n  arr.forEach((p) => {\n    const hi = Math.max(p.h ?? p.c ?? -Infinity, p.bbU ?? -Infinity);\n    const lo = Math.min(p.l ?? p.c ?? Infinity, p.bbL ?? Infinity);\n    if (isFinite(hi) && hi > pMax) pMax = hi;\n    if (isFinite(lo) && lo < pMin) pMin = lo;\n  });\n  if (pMax <= pMin) { pMax += 1; pMin -= 1; }\n  const pad = (pMax - pMin) * 0.08;\n  pMax += pad; pMin -= pad;\n\n  const yPrice = (v) => canTop + (1 - (v - pMin) / (pMax - pMin)) * canH;\n  const yEnt = (v) => entTop + (1 - v / 100) * entH;\n\n  ENTRY_DEDICATED_PTS[tf] = { arr, W, H, L, R, T, B, cw, canTop, canH, canBot, entTop, entH, entBot, pMin, pMax };\n\n  // 1) K线背景：把当时的「🟢入场区间 / 🔴离场区间」直接以半透明色带投射在 K 线背后，一眼看清哪段K线该做、哪段K线该停！\n  const colW = cw / Math.max(1, n - 1);\n  const kZoneBands = arr.map((p, i) => {\n    const x = Math.max(L, xOf(i) - colW / 2);\n    const w = Math.min(W - R - x, colW + 0.6);\n    const bg = p.entryState === 'OK' ? '#10b981' : p.entryState === 'NO' ? '#f43f5e' : '#f59e0b';\n    const op = p.entryState === 'OK' ? 0.08 : p.entryState === 'NO' ? 0.13 : 0.04;\n    return `<rect x=\"${x.toFixed(1)}\" y=\"${canTop}\" width=\"${Math.max(1, w).toFixed(1)}\" height=\"${canH}\" fill=\"${bg}\" opacity=\"${op}\"/>`;\n  }).join('');\n\n  // 2) K线价格网格刻度与布林带\n  const pTicks = [0, 0.25, 0.5, 0.75, 1].map((f) => {\n    const pv = pMin + (1 - f) * (pMax - pMin), py = (canTop + f * canH).toFixed(1);\n    return `<line x1=\"${L}\" y1=\"${py}\" x2=\"${W - R}\" y2=\"${py}\" stroke=\"#262d3b\" stroke-width=\"1\" stroke-dasharray=\"3,3\" opacity=\"0.6\"/>\n      <text x=\"${L - 8}\" y=\"${+py + 4}\" text-anchor=\"end\" fill=\"#8a93a6\" font-size=\"11\">${pv.toFixed(1)}</text>\n      <text x=\"${W - R + 6}\" y=\"${+py + 4}\" fill=\"#cbd5e1\" font-size=\"11\">${pv.toFixed(2)}$</text>`;\n  }).join('');\n\n  const bbValid = arr.map((p, i) => ({ p, i })).filter(({ p }) => p.bbU != null && p.bbM != null && p.bbL != null);\n  let bbSvg = '';\n  if (bbValid.length >= 2) {\n    const uPts = bbValid.map(({ p, i }) => `${xOf(i).toFixed(1)},${yPrice(p.bbU).toFixed(1)}`);\n    const mPts = bbValid.map(({ p, i }) => `${xOf(i).toFixed(1)},${yPrice(p.bbM).toFixed(1)}`);\n    const lPts = bbValid.map(({ p, i }) => `${xOf(i).toFixed(1)},${yPrice(p.bbL).toFixed(1)}`);\n    bbSvg = `<polyline fill=\"none\" stroke=\"#58a6ff\" stroke-width=\"1.2\" points=\"${uPts.join(' ')}\" opacity=\"0.75\"/>\n      <polyline fill=\"none\" stroke=\"#f0b429\" stroke-width=\"1.3\" stroke-dasharray=\"4,3\" points=\"${mPts.join(' ')}\" opacity=\"0.85\"/>\n      <polyline fill=\"none\" stroke=\"#58a6ff\" stroke-width=\"1.2\" points=\"${lPts.join(' ')}\" opacity=\"0.75\"/>`;\n  }\n\n  // 3) K线蜡烛图 + 入场/离场切换标签直接标在 K 线上\n  const bw = Math.max(2.8, Math.min(8.5, cw / n * 0.68));\n  let lastTagIdx = -10;\n  const candles = arr.map((p, i) => {\n    const x = xOf(i), o = p.o ?? p.c, c = p.c, h = p.h ?? Math.max(o, c), l = p.l ?? Math.min(o, c);\n    const up = c >= o, col = up ? '#2ecc8f' : '#ef5b5b';\n    const yh = yPrice(h).toFixed(1), yl = yPrice(l).toFixed(1);\n    const yo = yPrice(o), yc = yPrice(c), yt = Math.min(yo, yc).toFixed(1), bh = Math.max(1.5, Math.abs(yc - yo)).toFixed(1);\n    let swSvg = '';\n    if (p.switchTag && (i - lastTagIdx >= 6)) {\n      lastTagIdx = i;\n      const isEn = p.switchTag === 'ENTRY';\n      const ty = isEn ? Math.min(canBot - 8, +yl + 14) : Math.max(canTop + 14, +yh - 8);\n      swSvg = `<text x=\"${x.toFixed(1)}\" y=\"${ty.toFixed(1)}\" text-anchor=\"middle\" fill=\"${isEn ? '#34d399' : '#fda4af'}\" font-size=\"10.5\" font-weight=\"bold\">${isEn ? '▲入场区' : '▼离场区'}</text>`;\n    }\n    return `<line x1=\"${x.toFixed(1)}\" y1=\"${yh}\" x2=\"${x.toFixed(1)}\" y2=\"${yl}\" stroke=\"${col}\" stroke-width=\"1.2\"/>\n      <rect x=\"${(x - bw / 2).toFixed(1)}\" y=\"${yt}\" width=\"${bw.toFixed(1)}\" height=\"${bh}\" fill=\"${col}\"/>${swSvg}`;\n  }).join('');\n\n  // 4) 下半屏：入场指数「快线 + EMA8慢均线」+ 清晰标注【🟢入场区间 ≥56】、【🟡缓冲等回调区 46-56】、【🔴离场区间 <46】\n  const eY56 = yEnt(56), eY46 = yEnt(46);\n  const entTicks = [100, 75, 56, 46, 25, 0].map((v) => {\n    const y = yEnt(v).toFixed(1);\n    const col = v === 56 ? '#10b981' : v === 46 ? '#f43f5e' : '#262d3b';\n    const sw = (v === 56 || v === 46) ? '1.8' : '1';\n    const dash = (v === 100 || v === 0) ? '' : 'stroke-dasharray=\"5,4\"';\n    return `<line x1=\"${L}\" y1=\"${y}\" x2=\"${W - R}\" y2=\"${y}\" stroke=\"${col}\" stroke-width=\"${sw}\" ${dash} opacity=\"0.85\"/>\n      <text x=\"${L - 8}\" y=\"${+y + 4}\" text-anchor=\"end\" fill=\"${v === 56 ? '#34d399' : v === 46 ? '#fb7185' : '#8a93a6'}\" font-size=\"11\" font-weight=\"${v === 56 || v === 46 ? 'bold' : 'normal'}\">${v}</text>`;\n  }).join('');\n\n  // 右侧醒目区间说明标签\n  const zoneRightLabels = `\n    <rect x=\"${W - R + 6}\" y=\"${((entTop + eY56) / 2 - 11).toFixed(1)}\" width=\"126\" height=\"22\" rx=\"4\" fill=\"rgba(16,185,129,0.18)\" stroke=\"#10b981\" stroke-width=\"1\"/>\n    <text x=\"${W - R + 69}\" y=\"${((entTop + eY56) / 2 + 4).toFixed(1)}\" text-anchor=\"middle\" fill=\"#34d399\" font-size=\"11\" font-weight=\"bold\">🟢 入场区间 (≥56分)</text>\n    <rect x=\"${W - R + 6}\" y=\"${((eY56 + eY46) / 2 - 10).toFixed(1)}\" width=\"126\" height=\"20\" rx=\"4\" fill=\"rgba(245,158,11,0.15)\" stroke=\"#f59e0b\" stroke-width=\"0.8\"/>\n    <text x=\"${W - R + 69}\" y=\"${((eY56 + eY46) / 2 + 4).toFixed(1)}\" text-anchor=\"middle\" fill=\"#fbbf24\" font-size=\"10.5\" font-weight=\"bold\">🟡 缓冲/等回调(46-56)</text>\n    <rect x=\"${W - R + 6}\" y=\"${((eY46 + entBot) / 2 - 11).toFixed(1)}\" width=\"126\" height=\"22\" rx=\"4\" fill=\"rgba(244,63,94,0.18)\" stroke=\"#f43f5e\" stroke-width=\"1\"/>\n    <text x=\"${W - R + 69}\" y=\"${((eY46 + entBot) / 2 + 4).toFixed(1)}\" text-anchor=\"middle\" fill=\"#fb7185\" font-size=\"11\" font-weight=\"bold\">🔴 离场区间 (&lt;46分)</text>\n  `;\n\n  // X轴时间垂直对齐线\n  const step = Math.max(1, Math.floor((n - 1) / 8));\n  const idxs = [];\n  for (let i = 0; i < n - 1; i += step) idxs.push(i);\n  idxs.push(n - 1);\n  const xGrid = idxs.map((i) => {\n    const x = xOf(i).toFixed(1), tm = fmtBJ(arr[i].t), p = arr[i];\n    return `<line x1=\"${x}\" y1=\"${canTop}\" x2=\"${x}\" y2=\"${entBot}\" stroke=\"#262d3b\" stroke-width=\"1\" stroke-dasharray=\"2,4\"/>\n      <text x=\"${x}\" y=\"${entBot + 18}\" text-anchor=\"middle\" fill=\"#c6cddb\" font-size=\"11.5\">${tm}</text>\n      <text x=\"${x}\" y=\"${entBot + 33}\" text-anchor=\"middle\" fill=\"${p.entryCol}\" font-size=\"10.5\" font-weight=\"bold\">${p.zoneName.slice(0, 6)}</text>`;\n  }).join('');\n\n  // 绘制下半屏底部状态色柱 + 快线(青白 #38bdf8) + 慢均线 EMA8(亮金粗线 #fbbf24)\n  const fastPts = arr.map((p, i) => `${xOf(i).toFixed(1)},${yEnt(p.entryFast).toFixed(1)}`).join(' ');\n  const slowPts = arr.map((p, i) => `${xOf(i).toFixed(1)},${yEnt(p.entrySlow).toFixed(1)}`).join(' ');\n  const ebw = Math.max(2.5, Math.min(7.5, cw / n * 0.65));\n  const entBars = arr.map((p, i) => {\n    const x = xOf(i), y = yEnt(p.entryFast), h = Math.max(2, entBot - y);\n    return `<rect x=\"${(x - ebw / 2).toFixed(1)}\" y=\"${y.toFixed(1)}\" width=\"${ebw.toFixed(1)}\" height=\"${h.toFixed(1)}\" fill=\"${p.entryCol}\" opacity=\"0.22\" rx=\"1\"/>`;\n  }).join('');\n\n  const lastP = arr[n - 1];\n  const lastX = xOf(n - 1).toFixed(1);\n  const lastFastY = yEnt(lastP.entryFast).toFixed(1);\n  const lastSlowY = yEnt(lastP.entrySlow).toFixed(1);\n\n  return `<svg class=\"big-svg\" id=\"svg-entry-ded-${tf}\" style=\"height:540px;min-height:480px;max-height:600px\" viewBox=\"0 0 ${W} ${H}\" preserveAspectRatio=\"none\" onmousemove=\"onEntryDedicatedMove(event,'${tf}')\" onmouseleave=\"onEntryDedicatedLeave('${tf}')\">\n    <!-- 上半屏：黄金 K 线图 + 入场/离场历史背景直投 -->\n    <text x=\"${L + 6}\" y=\"${canTop - 8}\" fill=\"#e8b84a\" font-size=\"12.5\" font-weight=\"bold\">🕯️ [${tf}周期] 现货黄金 K 线走势 × 历史入场/离场区间直投对照 (绿底=处于🟢入场区间 · 红底=处于🔴离场区间 · 黄虚线=MA20中轨)</text>\n    ${kZoneBands}${pTicks}${xGrid}${bbSvg}${candles}\n\n    <!-- 分割线与下半屏标题 -->\n    <line x1=\"${L}\" y1=\"${canBot + 14}\" x2=\"${W - R}\" y2=\"${canBot + 14}\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n    <text x=\"${L + 6}\" y=\"${entTop - 8}\" fill=\"#e8b84a\" font-size=\"12.5\" font-weight=\"bold\">🚦 [${tf}周期] 入场/离场「双线平滑指数」历史走势 (亮金粗线 = EMA8决策慢均线[定海神针] · 青白实线 = 3周期抗毛刺快线 · 蓝柱 = 均线护航过滤假跌)</text>\n\n    <!-- 下半屏：三大区间清晰背景色带 (≥56入场区间 / 46-56缓冲等回调区 / <46离场区间) -->\n    <rect x=\"${L}\" y=\"${entTop}\" width=\"${cw}\" height=\"${eY56 - entTop}\" fill=\"#10b981\" opacity=\"0.11\"/>\n    <rect x=\"${L}\" y=\"${eY56}\" width=\"${cw}\" height=\"${eY46 - eY56}\" fill=\"#f59e0b\" opacity=\"0.07\"/>\n    <rect x=\"${L}\" y=\"${eY46}\" width=\"${cw}\" height=\"${entBot - eY46}\" fill=\"#f43f5e\" opacity=\"0.12\"/>\n    <text x=\"${L + 10}\" y=\"${entTop + 18}\" fill=\"#34d399\" font-size=\"11.5\" font-weight=\"bold\" opacity=\"0.85\">▲ 🟢 入场安全区间 (≥56分：双线在此区间内可安心开启双向马丁)</text>\n    <text x=\"${L + 10}\" y=\"${entBot - 8}\" fill=\"#fda4af\" font-size=\"11.5\" font-weight=\"bold\" opacity=\"0.85\">▼ 🔴 离场/停EA高危区间 (&lt;46分：双线跌入此区代表持续单边，暂停逆势加仓或锁仓)</text>\n\n    ${entTicks}${zoneRightLabels}${entBars}\n    <!-- 青白色抗毛刺快线 (entryFast) -->\n    <polyline fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.9\" points=\"${fastPts}\" opacity=\"0.92\"/>\n    <!-- 亮金色粗实线 EMA8 慢均线 (entrySlow) -->\n    <polyline fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"3.2\" points=\"${slowPts}\"/>\n    <circle cx=\"${lastX}\" cy=\"${lastFastY}\" r=\"4.5\" fill=\"#38bdf8\" stroke=\"#0f1218\" stroke-width=\"1.2\"/>\n    <circle cx=\"${lastX}\" cy=\"${lastSlowY}\" r=\"6\" fill=\"#fbbf24\" stroke=\"#0f1218\" stroke-width=\"1.5\"/>\n    <text x=\"${(+lastX - 10).toFixed(1)}\" y=\"${Math.max(entTop + 16, Math.min(entBot - 10, +lastSlowY - 10)).toFixed(1)}\" text-anchor=\"end\" fill=\"#fbbf24\" font-size=\"12.5\" font-weight=\"bold\">当前慢均线 ${lastP.entrySlow}分 | 快线 ${lastP.entryFast}分 (${lastP.zoneName})</text>\n\n    <!-- 1:1 垂直联动十字准星 -->\n    <g id=\"xh-eded-${tf}\" style=\"display:none;pointer-events:none\">\n      <line id=\"xh-eded-v-${tf}\" x1=\"0\" y1=\"${canTop}\" x2=\"0\" y2=\"${entBot}\" stroke=\"#ffffff\" stroke-width=\"1.2\" stroke-dasharray=\"4,4\" opacity=\"0.9\"/>\n      <line id=\"xh-eded-h-${tf}\" x1=\"${L}\" y1=\"0\" x2=\"${W - R}\" y2=\"0\" stroke=\"#ffffff\" stroke-width=\"1\" stroke-dasharray=\"4,4\" opacity=\"0.75\"/>\n      <circle id=\"xh-eded-kdot-${tf}\" cx=\"0\" cy=\"0\" r=\"5.5\" fill=\"#ffffff\" stroke=\"#0f1218\" stroke-width=\"2\"/>\n      <circle id=\"xh-eded-fdot-${tf}\" cx=\"0\" cy=\"0\" r=\"5\" fill=\"#38bdf8\" stroke=\"#ffffff\" stroke-width=\"1.5\"/>\n      <circle id=\"xh-eded-sdot-${tf}\" cx=\"0\" cy=\"0\" r=\"6.5\" fill=\"#fbbf24\" stroke=\"#ffffff\" stroke-width=\"2\"/>\n      <rect id=\"xh-eded-xbg-${tf}\" x=\"0\" y=\"${entBot + 3}\" width=\"124\" height=\"20\" rx=\"4\" fill=\"#fbbf24\"/>\n      <text id=\"xh-eded-xtxt-${tf}\" x=\"0\" y=\"${entBot + 17}\" text-anchor=\"middle\" fill=\"#0f172a\" font-size=\"11.5\" font-weight=\"bold\"></text>\n      <rect id=\"xh-eded-tbg-${tf}\" x=\"0\" y=\"0\" width=\"530\" height=\"74\" rx=\"6\" fill=\"rgba(15,18,26,0.96)\" stroke=\"#fbbf24\" stroke-width=\"1.3\"/>\n      <text id=\"xh-eded-t1-${tf}\" x=\"0\" y=\"0\" fill=\"#fbbf24\" font-size=\"12.5\" font-weight=\"bold\"></text>\n      <text id=\"xh-eded-t2-${tf}\" x=\"0\" y=\"0\" fill=\"#34d399\" font-size=\"12.5\" font-weight=\"bold\"></text>\n      <text id=\"xh-eded-t3-${tf}\" x=\"0\" y=\"0\" fill=\"#e2e8f0\" font-size=\"12\"></text>\n    </g>\n  </svg>`;\n}\n\nwindow.onEntryDedicatedMove = function(ev, tf) {\n  const cfg = ENTRY_DEDICATED_PTS[tf];\n  const svg = $('svg-entry-ded-' + tf), g = $('xh-eded-' + tf);\n  if (!cfg || !svg || !g) return;\n  const rect = svg.getBoundingClientRect();\n  const mx = (ev.clientX - rect.left) / rect.width * cfg.W;\n  const my = (ev.clientY - rect.top) / rect.height * cfg.H;\n  const n = cfg.arr.length;\n  const idx = Math.max(0, Math.min(n - 1, Math.round((mx - cfg.L) / cfg.cw * (n - 1))));\n  const p = cfg.arr[idx];\n  const x = cfg.L + (idx / (n - 1)) * cfg.cw;\n  const yK = cfg.canTop + (1 - (p.c - cfg.pMin) / (cfg.pMax - cfg.pMin)) * cfg.canH;\n  const yF = cfg.entTop + (1 - p.entryFast / 100) * cfg.entH;\n  const yS = cfg.entTop + (1 - p.entrySlow / 100) * cfg.entH;\n  const hy = Math.max(cfg.canTop, Math.min(cfg.entBot, my));\n\n  g.style.display = 'block';\n  $('xh-eded-v-' + tf).setAttribute('x1', x); $('xh-eded-v-' + tf).setAttribute('x2', x);\n  $('xh-eded-h-' + tf).setAttribute('y1', hy); $('xh-eded-h-' + tf).setAttribute('y2', hy);\n  $('xh-eded-kdot-' + tf).setAttribute('cx', x); $('xh-eded-kdot-' + tf).setAttribute('cy', yK);\n  $('xh-eded-fdot-' + tf).setAttribute('cx', x); $('xh-eded-fdot-' + tf).setAttribute('cy', yF);\n  $('xh-eded-sdot-' + tf).setAttribute('cx', x); $('xh-eded-sdot-' + tf).setAttribute('cy', yS);\n\n  const tm = fmtBJ(p.t);\n  const xClamped = Math.max(cfg.L + 62, Math.min(cfg.W - cfg.R - 62, x));\n  $('xh-eded-xbg-' + tf).setAttribute('x', xClamped - 62);\n  $('xh-eded-xtxt-' + tf).setAttribute('x', xClamped);\n  $('xh-eded-xtxt-' + tf).textContent = tm;\n\n  const boxW = 530, boxH = 74;\n  const bx = x + 16 + boxW > cfg.W - cfg.R ? Math.max(cfg.L + 4, x - boxW - 16) : x + 16;\n  const by = Math.max(cfg.canTop + 6, Math.min(cfg.entBot - boxH - 6, hy - 36));\n  $('xh-eded-tbg-' + tf).setAttribute('x', bx); $('xh-eded-tbg-' + tf).setAttribute('y', by);\n  const t1 = $('xh-eded-t1-' + tf), t2 = $('xh-eded-t2-' + tf), t3 = $('xh-eded-t3-' + tf);\n  t1.setAttribute('x', bx + 10); t1.setAttribute('y', by + 20);\n  t2.setAttribute('x', bx + 10); t2.setAttribute('y', by + 42);\n  t3.setAttribute('x', bx + 10); t3.setAttribute('y', by + 62);\n  t1.textContent = `🕒 ${tm} | 黄金K线: 开$${f2(p.o)} 高$${f2(p.h)} 低$${f2(p.l)} 收$${f2(p.c)} (单根波幅 $${f2(p.barSpan)} / 14根波幅 $${f2(p.span)})`;\n  t2.setAttribute('fill', p.entryCol);\n  t2.textContent = `🚦 所在区间: 【${p.zoneName}】 | 慢均线(EMA8): ${p.entrySlow}分  ·  抗毛刺快线: ${p.entryFast}分`;\n  t3.textContent = `📌 决策原因: ${p.entryReason}`;\n};\n\nwindow.onEntryDedicatedLeave = function(tf) {\n  const g = $('xh-eded-' + tf);\n  if (g) g.style.display = 'none';\n};\n\n// 一图一屏大型 SVG 图表 (含: ①震荡指数+单次急跌标记 ②时间1:1对齐的「是否适合入场」双线时序图 ③可选K线蜡烛图+布林带)\nfunction bigChartSvg(rawArr, tf) {\n  if (!rawArr || rawArr.length < 2) return '<div class=\"mut\">暂无趋势数据</div>';\n  const showC = !!SHOW_CANDLE[tf];\n  const arr = calcEntrySeries(rawArr, TOL);\n  const W = 1200, H = showC ? 720 : 540, L = 66, R = 112, T = 24, B = 48;\n  const cw = W - L - R, n = arr.length;\n  const xOf = (i) => L + (i / (n - 1)) * cw;\n\n  // 面板1: 震荡指数走势图 | 面板2: 时间轴1:1对齐的「是否适合入场(快线+EMA8慢均线)」时序图 | 面板3(可选): 黄金K线蜡烛图+布林带\n  const idxTop = T, idxH = showC ? 210 : 255, idxBot = idxTop + idxH;\n  const entTop = idxBot + 32, entH = showC ? 155 : 175, entBot = entTop + entH;\n  const canTop = entBot + 32, canH = showC ? (H - B - canTop) : 0, canBot = canTop + canH;\n  const yIdx = (v) => idxTop + (1 - v / 100) * idxH;\n  const yEnt = (v) => entTop + (1 - v / 100) * entH;\n\n  let pMin = Infinity, pMax = -Infinity;\n  if (showC) {\n    arr.forEach((p) => {\n      const hi = Math.max(p.h ?? p.c ?? -Infinity, p.bbU ?? -Infinity);\n      const lo = Math.min(p.l ?? p.c ?? Infinity, p.bbL ?? Infinity);\n      if (isFinite(hi) && hi > pMax) pMax = hi;\n      if (isFinite(lo) && lo < pMin) pMin = lo;\n    });\n    if (pMax <= pMin) { pMax += 1; pMin -= 1; }\n    const pad = (pMax - pMin) * 0.06;\n    pMax += pad; pMin -= pad;\n  }\n  const yPrice = (v) => canTop + (1 - (v - pMin) / (pMax - pMin)) * canH;\n\n  // 保存几何信息供鼠标十字准星高频调用\n  CHART_PTS[tf] = { arr, W, H, L, R, T, B, cw, idxTop, idxH, idxBot, entTop, entH, entBot, canTop, canH, canBot, showC, pMin, pMax };\n\n  const pts = arr.map((p, i) => `${xOf(i).toFixed(1)},${yIdx(p.adjV).toFixed(1)}`).join(' ');\n  const rawPts = arr.map((p, i) => `${xOf(i).toFixed(1)},${yIdx(p.v).toFixed(1)}`).join(' ');\n  const area = `${xOf(0).toFixed(1)},${idxBot.toFixed(1)} ${pts} ${xOf(n - 1).toFixed(1)},${idxBot.toFixed(1)}`;\n  const y70 = yIdx(70), y55 = yIdx(55), y45 = yIdx(45), y30 = yIdx(30);\n\n  const yTicks = [100, 70, 55, 45, 30, 0].map((v) => {\n    const y = yIdx(v).toFixed(1);\n    const col = v === 55 || v === 70 ? '#2ecc8f' : v === 45 || v === 30 ? '#ef5b5b' : '#262d3b';\n    const dash = (v === 100 || v === 0) ? '' : 'stroke-dasharray=\"4,4\"';\n    return `<line x1=\"${L}\" y1=\"${y}\" x2=\"${W - R}\" y2=\"${y}\" stroke=\"${col}\" stroke-width=\"1\" ${dash} opacity=\"0.65\"/>\n      <text x=\"${L - 8}\" y=\"${+y + 4}\" text-anchor=\"end\" fill=\"#8a93a6\" font-size=\"11\">${v}</text>`;\n  }).join('');\n\n  const rLabels = [\n    [(yIdx(100) + y70) / 2, '强震荡(≥70)', '#2ecc8f'],\n    [(y70 + y55) / 2, '偏震荡(55-70)', '#2ecc8f'],\n    [(y55 + y45) / 2, '过渡(45-55)', '#f0b429'],\n    [(y45 + y30) / 2, '偏单边(30-45)', '#ef5b5b'],\n    [(y30 + yIdx(0)) / 2, '强单边(<30)', '#ef5b5b'],\n  ].map(([y, txt, c]) => `<text x=\"${W - R + 6}\" y=\"${y + 4}\" fill=\"${c}\" font-size=\"11\">${txt}</text>`).join('');\n\n  const step = Math.max(1, Math.floor((n - 1) / 7));\n  const idxs = [];\n  for (let i = 0; i < n - 1; i += step) idxs.push(i);\n  idxs.push(n - 1);\n  const gridBottom = showC ? canBot : entBot;\n  const xTicks = idxs.map((i) => {\n    const x = xOf(i).toFixed(1), tm = fmtBJ(arr[i].t), p = arr[i];\n    const stShort = p.entryState === 'OK' ? '🟢入场区' : p.entryState === 'WAIT' ? '🟡缓冲' : '🔴离场区';\n    return `<line x1=\"${x}\" y1=\"${T}\" x2=\"${x}\" y2=\"${gridBottom}\" stroke=\"#262d3b\" stroke-width=\"1\" stroke-dasharray=\"2,4\"/>\n      <line x1=\"${x}\" y1=\"${gridBottom}\" x2=\"${x}\" y2=\"${gridBottom + 5}\" stroke=\"#8a93a6\" stroke-width=\"1\"/>\n      <text x=\"${x}\" y=\"${gridBottom + 20}\" text-anchor=\"middle\" fill=\"#c6cddb\" font-size=\"12\">${tm}</text>\n      <text x=\"${x}\" y=\"${gridBottom + 36}\" text-anchor=\"middle\" fill=\"${p.entryCol}\" font-size=\"11\">${p.adjV}分·${stShort}</text>`;\n  }).join('');\n\n  // 震荡指数点 + 单次急跌跳水闪电标记 (当 effDrop1 >= 7 时标注 ⚡-跌幅)\n  const dots = arr.map((p, i) => {\n    const x = xOf(i), y = yIdx(p.adjV);\n    const col = p.adjV >= 55 ? '#2ecc8f' : p.adjV < 45 ? '#ef5b5b' : '#f0b429';\n    const isLast = i === n - 1;\n    const isPlunge = p.effDrop1 >= 7;\n    const dirTxt = p.dir === 'UP' ? '上涨趋势↑' : '下跌趋势↓';\n    const plungeTag = isPlunge\n      ? `<circle cx=\"${x.toFixed(1)}\" cy=\"${y.toFixed(1)}\" r=\"5\" fill=\"none\" stroke=\"#ff4d4f\" stroke-width=\"2\"/>\n         <text x=\"${x.toFixed(1)}\" y=\"${Math.max(idxTop + 12, y - 8).toFixed(1)}\" text-anchor=\"middle\" fill=\"#ff6b6b\" font-size=\"10\" font-weight=\"bold\">⚡-${p.effDrop1}</text>`\n      : '';\n    return `<circle cx=\"${x.toFixed(1)}\" cy=\"${y.toFixed(1)}\" r=\"${isLast ? 5.5 : 2.3}\" fill=\"${col}\" stroke=\"#0f1218\" stroke-width=\"1.2\"/>` +\n      plungeTag +\n      (isLast ? `<text x=\"${(x - 10).toFixed(1)}\" y=\"${Math.max(idxTop + 16, y - 12).toFixed(1)}\" text-anchor=\"end\" fill=\"#fff\" font-size=\"13\" font-weight=\"bold\">当前 ${p.adjV} (${p.adjV < 45 ? dirTxt : '震荡/过渡'})</text>` : '');\n  }).join('');\n\n  // 面板2: 时间轴 1:1 对齐的「入场/离场双线指数 (快线+EMA8慢均线)」时序图\n  const eY56 = yEnt(56), eY46 = yEnt(46);\n  const entTicks = [100, 56, 46, 0].map((v) => {\n    const y = yEnt(v).toFixed(1);\n    const col = v === 56 ? '#2ecc8f' : v === 46 ? '#ef5b5b' : '#262d3b';\n    const dash = (v === 100 || v === 0) ? '' : 'stroke-dasharray=\"4,4\"';\n    return `<line x1=\"${L}\" y1=\"${y}\" x2=\"${W - R}\" y2=\"${y}\" stroke=\"${col}\" stroke-width=\"1.2\" ${dash} opacity=\"0.75\"/>\n      <text x=\"${L - 8}\" y=\"${+y + 4}\" text-anchor=\"end\" fill=\"#8a93a6\" font-size=\"11\">${v}</text>`;\n  }).join('');\n  const entRLabels = [\n    [(entTop + eY56) / 2, '🟢入场区间(≥56)', '#2ecc8f'],\n    [(eY56 + eY46) / 2, '🟡缓冲等回调(46-56)', '#f0b429'],\n    [(eY46 + entBot) / 2, '🔴离场区间(<46)', '#ef5b5b'],\n  ].map(([y, txt, c]) => `<text x=\"${W - R + 6}\" y=\"${y + 4}\" fill=\"${c}\" font-size=\"11\" font-weight=\"600\">${txt}</text>`).join('');\n\n  const ebw = Math.max(3, Math.min(8.5, cw / n * 0.72));\n  const entBars = arr.map((p, i) => {\n    const x = xOf(i), y = yEnt(p.entryFast), h = Math.max(2, entBot - y);\n    return `<rect x=\"${(x - ebw / 2).toFixed(1)}\" y=\"${y.toFixed(1)}\" width=\"${ebw.toFixed(1)}\" height=\"${h.toFixed(1)}\" fill=\"${p.entryCol}\" opacity=\"0.28\" rx=\"1\"/>`;\n  }).join('');\n  const entFastPts = arr.map((p, i) => `${xOf(i).toFixed(1)},${yEnt(p.entryFast).toFixed(1)}`).join(' ');\n  const entSlowPts = arr.map((p, i) => `${xOf(i).toFixed(1)},${yEnt(p.entrySlow).toFixed(1)}`).join(' ');\n  const entDots = arr.map((p, i) => {\n    const x = xOf(i), y = yEnt(p.entrySlow), isLast = i === n - 1;\n    return isLast\n      ? `<circle cx=\"${x.toFixed(1)}\" cy=\"${yEnt(p.entryFast).toFixed(1)}\" r=\"4.5\" fill=\"#38bdf8\" stroke=\"#0f1218\" stroke-width=\"1\"/>\n         <circle cx=\"${x.toFixed(1)}\" cy=\"${y.toFixed(1)}\" r=\"5.5\" fill=\"#fbbf24\" stroke=\"#0f1218\" stroke-width=\"1.2\"/>\n         <text x=\"${(x - 10).toFixed(1)}\" y=\"${Math.max(entTop + 15, y - 10).toFixed(1)}\" text-anchor=\"end\" fill=\"${p.entryCol}\" font-size=\"12.5\" font-weight=\"bold\">当前: ${p.zoneName} (均线${p.entrySlow}/快线${p.entryFast})</text>`\n      : '';\n  }).join('');\n\n  const entryPanelSvg = `\n    <line x1=\"${L}\" y1=\"${idxBot + 14}\" x2=\"${W - R}\" y2=\"${idxBot + 14}\" stroke=\"#262d3b\" stroke-width=\"1.5\"/>\n    <text x=\"${L + 6}\" y=\"${entTop - 7}\" fill=\"#e8b84a\" font-size=\"12\" font-weight=\"bold\">🚦 入场/离场双线平滑时序图 (亮金粗线=EMA8慢均线 · 青白线=抗毛刺快线 | 🟢入场区间≥56 · 🟡缓冲等回调46-56 · 🔴离场区间&lt;46)</text>\n    <rect x=\"${L}\" y=\"${entTop}\" width=\"${cw}\" height=\"${eY56 - entTop}\" fill=\"#2ecc8f\" opacity=\"0.08\"/>\n    <rect x=\"${L}\" y=\"${eY56}\" width=\"${cw}\" height=\"${eY46 - eY56}\" fill=\"#f0b429\" opacity=\"0.05\"/>\n    <rect x=\"${L}\" y=\"${eY46}\" width=\"${cw}\" height=\"${entBot - eY46}\" fill=\"#ef5b5b\" opacity=\"0.08\"/>\n    ${entTicks}${entRLabels}${entBars}\n    <polyline fill=\"none\" stroke=\"#38bdf8\" stroke-width=\"1.6\" points=\"${entFastPts}\" opacity=\"0.9\"/>\n    <polyline fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"2.8\" points=\"${entSlowPts}\"/>\n    ${entDots}`;\n\n  // 面板3: 黄金价格 K 线蜡烛图 + 布林带 BB(20,2) 子面板 (仅当用户点击开启时渲染)\n  let candleSvg = '';\n  if (showC) {\n    const pTicks = [0, 0.25, 0.5, 0.75, 1].map((f) => {\n      const pv = pMin + (1 - f) * (pMax - pMin), py = (canTop + f * canH).toFixed(1);\n      return `<line x1=\"${L}\" y1=\"${py}\" x2=\"${W - R}\" y2=\"${py}\" stroke=\"#262d3b\" stroke-width=\"1\" stroke-dasharray=\"3,3\" opacity=\"0.6\"/>\n        <text x=\"${L - 8}\" y=\"${+py + 4}\" text-anchor=\"end\" fill=\"#8a93a6\" font-size=\"11\">${pv.toFixed(2)}</text>\n        <text x=\"${W - R + 6}\" y=\"${+py + 4}\" fill=\"#8a93a6\" font-size=\"11\">${pv.toFixed(2)}$</text>`;\n    }).join('');\n    const bbValid = arr.map((p, i) => ({ p, i })).filter(({ p }) => p.bbU != null && p.bbM != null && p.bbL != null);\n    let bbSvg = '';\n    if (bbValid.length >= 2) {\n      const uPts = bbValid.map(({ p, i }) => `${xOf(i).toFixed(1)},${yPrice(p.bbU).toFixed(1)}`);\n      const mPts = bbValid.map(({ p, i }) => `${xOf(i).toFixed(1)},${yPrice(p.bbM).toFixed(1)}`);\n      const lPts = bbValid.map(({ p, i }) => `${xOf(i).toFixed(1)},${yPrice(p.bbL).toFixed(1)}`);\n      const bandArea = [...uPts, ...lPts.slice().reverse()].join(' ');\n      bbSvg = `<polygon points=\"${bandArea}\" fill=\"#58a6ff\" opacity=\"0.09\"/>\n        <polyline fill=\"none\" stroke=\"#58a6ff\" stroke-width=\"1.35\" points=\"${uPts.join(' ')}\" opacity=\"0.9\"/>\n        <polyline fill=\"none\" stroke=\"#f0b429\" stroke-width=\"1.4\" stroke-dasharray=\"4,3\" points=\"${mPts.join(' ')}\" opacity=\"0.95\"/>\n        <polyline fill=\"none\" stroke=\"#58a6ff\" stroke-width=\"1.35\" points=\"${lPts.join(' ')}\" opacity=\"0.9\"/>`;\n    }\n    const bw = Math.max(2.5, Math.min(8, cw / n * 0.68));\n    const candles = arr.map((p, i) => {\n      const x = xOf(i), o = p.o ?? p.c, c = p.c, h = p.h ?? Math.max(o, c), l = p.l ?? Math.min(o, c);\n      const up = c >= o, col = up ? '#2ecc8f' : '#ef5b5b';\n      const yh = yPrice(h).toFixed(1), yl = yPrice(l).toFixed(1);\n      const yo = yPrice(o), yc = yPrice(c), yt = Math.min(yo, yc).toFixed(1), bh = Math.max(1.5, Math.abs(yc - yo)).toFixed(1);\n      return `<line x1=\"${x.toFixed(1)}\" y1=\"${yh}\" x2=\"${x.toFixed(1)}\" y2=\"${yl}\" stroke=\"${col}\" stroke-width=\"1.2\"/>\n        <rect x=\"${(x - bw / 2).toFixed(1)}\" y=\"${yt}\" width=\"${bw.toFixed(1)}\" height=\"${bh}\" fill=\"${col}\"/>`;\n    }).join('');\n    candleSvg = `<line x1=\"${L}\" y1=\"${entBot + 14}\" x2=\"${W - R}\" y2=\"${entBot + 14}\" stroke=\"#262d3b\" stroke-width=\"1.5\"/>\n      <text x=\"${L + 6}\" y=\"${canTop - 7}\" fill=\"#e8b84a\" font-size=\"12\" font-weight=\"bold\">🕯️ 现货黄金 XAUUSD K线蜡烛图 + 布林带 BB(20,2)  (0秒延迟实时 · 蓝实线=上下轨 · 黄虚线=中轨MA20)</text>\n      ${pTicks}${bbSvg}${candles}`;\n  }\n\n  return `<svg class=\"big-svg\" id=\"svg-${tf}\" style=\"height:${showC ? 'calc(100vh - 220px);min-height:580px;max-height:760px' : 'calc(100vh - 275px);min-height:460px;max-height:660px'}\" viewBox=\"0 0 ${W} ${H}\" preserveAspectRatio=\"none\" onmousemove=\"onChartMove(event,'${tf}')\" onmouseleave=\"onChartLeave('${tf}')\">\n    <defs>\n      <linearGradient id=\"ag-${tf}\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n        <stop offset=\"0%\" stop-color=\"#e8b84a\" stop-opacity=\"0.28\"/>\n        <stop offset=\"100%\" stop-color=\"#e8b84a\" stop-opacity=\"0.02\"/>\n      </linearGradient>\n    </defs>\n    <text x=\"${L + 6}\" y=\"${idxTop - 7}\" fill=\"#e8b84a\" font-size=\"12\" font-weight=\"bold\">📈 实时量化震荡指数走势 (金色实线=策略校准指数 · 灰虚线=原始指数 · ⚡=单次急跌≥7分跳水点)</text>\n    <rect x=\"${L}\" y=\"${idxTop}\" width=\"${cw}\" height=\"${y55 - idxTop}\" fill=\"#2ecc8f\" opacity=\"0.08\"/>\n    <rect x=\"${L}\" y=\"${y55}\" width=\"${cw}\" height=\"${y45 - y55}\" fill=\"#f0b429\" opacity=\"0.05\"/>\n    <rect x=\"${L}\" y=\"${y45}\" width=\"${cw}\" height=\"${idxBot - y45}\" fill=\"#ef5b5b\" opacity=\"0.08\"/>\n    ${yTicks}${rLabels}${xTicks}\n    <polygon points=\"${area}\" fill=\"url(#ag-${tf})\"/>\n    <polyline fill=\"none\" stroke=\"#8a93a6\" stroke-width=\"1.2\" stroke-dasharray=\"3,3\" points=\"${rawPts}\" opacity=\"0.6\"/>\n    <polyline fill=\"none\" stroke=\"#e8b84a\" stroke-width=\"2.6\" points=\"${pts}\"/>\n    ${dots}\n    ${entryPanelSvg}\n    ${candleSvg}\n    <!-- 十字准星交互层 -->\n    <g id=\"xh-${tf}\" style=\"display:none;pointer-events:none\">\n      <line id=\"xh-v-${tf}\" x1=\"0\" y1=\"${T}\" x2=\"0\" y2=\"${gridBottom}\" stroke=\"#ffffff\" stroke-width=\"1\" stroke-dasharray=\"4,4\" opacity=\"0.85\"/>\n      <line id=\"xh-h-${tf}\" x1=\"${L}\" y1=\"0\" x2=\"${W - R}\" y2=\"0\" stroke=\"#ffffff\" stroke-width=\"1\" stroke-dasharray=\"4,4\" opacity=\"0.85\"/>\n      <circle id=\"xh-dot-${tf}\" cx=\"0\" cy=\"0\" r=\"6\" fill=\"#e8b84a\" stroke=\"#fff\" stroke-width=\"2\"/>\n      <circle id=\"xh-edot-${tf}\" cx=\"0\" cy=\"0\" r=\"6\" fill=\"#2ecc8f\" stroke=\"#fff\" stroke-width=\"2\"/>\n      <!-- 底部时间标签 -->\n      <rect id=\"xh-xbg-${tf}\" x=\"0\" y=\"${gridBottom + 4}\" width=\"118\" height=\"22\" rx=\"4\" fill=\"#e8b84a\"/>\n      <text id=\"xh-xtxt-${tf}\" x=\"0\" y=\"${gridBottom + 19}\" text-anchor=\"middle\" fill=\"#121620\" font-size=\"12\" font-weight=\"bold\"></text>\n      <!-- 右侧Y轴实时标签 -->\n      <rect id=\"xh-ybg-${tf}\" x=\"${W - R + 2}\" y=\"0\" width=\"104\" height=\"22\" rx=\"4\" fill=\"#e8b84a\"/>\n      <text id=\"xh-ytxt-${tf}\" x=\"${W - R + 54}\" y=\"0\" text-anchor=\"middle\" fill=\"#121620\" font-size=\"12\" font-weight=\"bold\"></text>\n      <!-- 顶部悬浮详情框 -->\n      <rect id=\"xh-tbg-${tf}\" x=\"0\" y=\"0\" width=\"490\" height=\"88\" rx=\"6\" fill=\"rgba(15,18,24,0.95)\" stroke=\"#e8b84a\" stroke-width=\"1.2\"/>\n      <text id=\"xh-t1-${tf}\" x=\"0\" y=\"0\" fill=\"#e8b84a\" font-size=\"12.5\" font-weight=\"bold\"></text>\n      <text id=\"xh-t2-${tf}\" x=\"0\" y=\"0\" fill=\"#2ecc8f\" font-size=\"12.5\" font-weight=\"bold\"></text>\n      <text id=\"xh-t3-${tf}\" x=\"0\" y=\"0\" fill=\"#e6e9ef\" font-size=\"12\"></text>\n      <text id=\"xh-t4-${tf}\" x=\"0\" y=\"0\" fill=\"#58a6ff\" font-size=\"12\"></text>\n    </g>\n  </svg>`;\n}\n\n// 鼠标移动十字准星与实时数值浮窗\nwindow.onChartMove = function(ev, tf) {\n  const cfg = CHART_PTS[tf];\n  const svg = $('svg-' + tf), g = $('xh-' + tf);\n  if (!cfg || !svg || !g) return;\n  const rect = svg.getBoundingClientRect();\n  const mx = (ev.clientX - rect.left) / rect.width * cfg.W;\n  const my = (ev.clientY - rect.top) / rect.height * cfg.H;\n  const n = cfg.arr.length;\n  const idx = Math.max(0, Math.min(n - 1, Math.round((mx - cfg.L) / cfg.cw * (n - 1))));\n  const p = cfg.arr[idx];\n  const x = cfg.L + (idx / (n - 1)) * cfg.cw;\n  const yPoint = cfg.idxTop + (1 - p.adjV / 100) * cfg.idxH;\n  const yEntPoint = cfg.entTop + (1 - p.entryScore / 100) * cfg.entH;\n  const gridBottom = cfg.showC ? cfg.canBot : cfg.entBot;\n  const hy = Math.max(cfg.T, Math.min(gridBottom, my));\n\n  g.style.display = 'block';\n  const vLine = $('xh-v-' + tf), hLine = $('xh-h-' + tf), dot = $('xh-dot-' + tf), edot = $('xh-edot-' + tf);\n  vLine.setAttribute('x1', x); vLine.setAttribute('x2', x);\n  hLine.setAttribute('y1', hy); hLine.setAttribute('y2', hy);\n  dot.setAttribute('cx', x); dot.setAttribute('cy', yPoint);\n  edot.setAttribute('cx', x); edot.setAttribute('cy', yEntPoint);\n  edot.setAttribute('fill', p.entryCol);\n\n  // X轴时间标签\n  const tm = fmtBJ(p.t);\n  const xbg = $('xh-xbg-' + tf), xtxt = $('xh-xtxt-' + tf);\n  const xClamped = Math.max(cfg.L + 59, Math.min(cfg.W - cfg.R - 59, x));\n  xbg.setAttribute('x', xClamped - 59);\n  xtxt.setAttribute('x', xClamped);\n  xtxt.textContent = tm;\n\n  // Y轴标签 (按鼠标所在子面板显示对应刻度的实时值)\n  const ybg = $('xh-ybg-' + tf), ytxt = $('xh-ytxt-' + tf);\n  ybg.setAttribute('y', hy - 11);\n  ytxt.setAttribute('y', hy + 4);\n  if (cfg.showC && hy >= cfg.canTop) {\n    const pv = cfg.pMax - (hy - cfg.canTop) / cfg.canH * (cfg.pMax - cfg.pMin);\n    ytxt.textContent = pv.toFixed(2) + '$';\n  } else if (hy >= cfg.entTop && hy <= cfg.entBot) {\n    const evScore = clamp(100 - (hy - cfg.entTop) / cfg.entH * 100, 0, 100);\n    ytxt.textContent = '入场 ' + evScore.toFixed(1) + '分';\n  } else {\n    const iv = clamp(100 - (hy - cfg.idxTop) / cfg.idxH * 100, 0, 100);\n    ytxt.textContent = '指数 ' + iv.toFixed(1);\n  }\n\n  // 顶部详情浮窗 (含时间、震荡指数、单次跌幅、是否适合入场、K线与布林带)\n  const tbg = $('xh-tbg-' + tf), t1 = $('xh-t1-' + tf), t2 = $('xh-t2-' + tf), t3 = $('xh-t3-' + tf), t4 = $('xh-t4-' + tf);\n  const hasBB = p.bbU != null && p.bbM != null && p.bbL != null;\n  const boxW = 500, boxH = hasBB ? 88 : 68;\n  tbg.setAttribute('width', boxW);\n  tbg.setAttribute('height', boxH);\n  const bx = x + 16 + boxW > cfg.W - cfg.R ? Math.max(cfg.L + 4, x - boxW - 16) : x + 16;\n  const by = Math.max(cfg.T + 4, Math.min(gridBottom - boxH - 6, yPoint - 28));\n  tbg.setAttribute('x', bx); tbg.setAttribute('y', by);\n  t1.setAttribute('x', bx + 10); t1.setAttribute('y', by + 18);\n  t2.setAttribute('x', bx + 10); t2.setAttribute('y', by + 38);\n  t3.setAttribute('x', bx + 10); t3.setAttribute('y', by + 58);\n  t4.setAttribute('x', bx + 10); t4.setAttribute('y', by + 77);\n  const dirTxt = p.dir === 'UP' ? '📈上涨' : '📉下跌';\n  const chgStr = `${p.effChg1 >= 0 ? '+' : ''}${p.effChg1}分${p.effDrop1 >= 7 ? '(⚡急跌)' : ''}`;\n  t1.textContent = `🕒 ${tm}  |  震荡指数: ${p.adjV}分(原${p.v})  |  单次变化: ${chgStr}  |  ${dirTxt}`;\n  t2.setAttribute('fill', p.entryCol);\n  t2.textContent = `🚦 是否适合入场: ${p.entryTxt} (入场适宜度 ${p.entryScore}/100 · ${p.entryReason})`;\n  t3.textContent = `黄金K线: 开${f2(p.o)} 高${f2(p.h)} 低${f2(p.l)} 收${f2(p.c)}$ | 单根波幅:${f2(p.barSpan)}$ | 14根波幅:${f2(p.span)}$`;\n  t4.textContent = hasBB ? `布林带 BB(20,2): 上轨 ${f2(p.bbU)}$  ·  中轨 ${f2(p.bbM)}$  ·  下轨 ${f2(p.bbL)}$` : '';\n};\n\nwindow.onChartLeave = function(tf) {\n  const g = $('xh-' + tf);\n  if (g) g.style.display = 'none';\n};\n\nwindow.toggleCandle = function(tf) {\n  SHOW_CANDLE[tf] = !SHOW_CANDLE[tf];\n  render();\n};\n\nfunction render() {\n  if (!D) return;\n  const d = D;\n  const mt4 = d.mt4 && d.mt4.balance > 0 && (Date.now() - d.mt4.ts < 3600000) ? d.mt4 : null;\n  if (mt4) {\n    ACC_BAL = Math.round(mt4.balance);\n    BUY_LOTS = r2(mt4.buyLots);\n    SELL_LOTS = r2(mt4.sellLots);\n    BUY_AVG_PX = r2(mt4.buyAvgPrice || 0);\n    SELL_AVG_PX = r2(mt4.sellAvgPrice || 0);\n    USED_MARGIN = Math.max(1, Math.round(mt4.margin || 14));\n    CUR_LAYERS = Math.max(1, mt4.buyCount || 0, mt4.sellCount || 0);\n    syncEaInputs();\n  }\n  saveUiState();\n  const ea = calcEaModel(ACC_BAL, EA_CFG, CUR_LAYERS, USED_MARGIN);\n  if (mt4) {\n    TOL = ea.recommendedTol;\n    if ($('tolSlider')) $('tolSlider').value = TOL;\n    if ($('tolInput')) $('tolInput').value = TOL;\n    if ($('tolValTxt')) $('tolValTxt').textContent = f2(TOL);\n  }\n  updateMt4UiStatus(mt4, ea);\n  const fTime = new Date(d.fastUpdatedAt || d.updatedAt).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false });\n  const sTime = new Date(d.updatedAt).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false });\n  $('meta').innerHTML = `<span class=\"live-dot\"></span><b>全周期+跨市场实时(每15秒·0延迟): ${fTime}</b> · 日线/周历(每3分钟): ${sTime} · 账户: <b style=\"color:var(--gold)\">$${ACC_BAL}</b>(可亏线:$${ea.riskLossUsd}) · <b>净敞口 N=${f2(ea.netLots)}手</b>($${ea.netLossPerUsd}/$) · 预付款比例: <b style=\"color:var(--green)\">${ea.marginLevelBal}%</b>(${ea.usedMargin}$) · 可抗单边: <b style=\"color:var(--gold)\">${f2(TOL)}$ (${Math.round(TOL * 100)}点)</b> · 账户极限: <b style=\"color:var(--red)\">${f2(ea.hard.span)}$ (${ea.hard.pts}点)</b>` +\n    (d.errors.length ? ` · <span class=\"err\">异常: ${d.errors.join(' | ')}</span>` : '');\n\n  if ($('lotDetectBadge')) {\n    $('lotDetectBadge').innerHTML = `⚖️ <b>净敞口 N=${f2(ea.netLots)}手</b> ($${ea.netLossPerUsd}/美金) · 买<b>${f2(ea.buyLots)}手</b>(≈${ea.buyInfo.layer}层) − 卖<b>${f2(ea.sellLots)}手</b>(≈${ea.sellInfo.layer}层) · 双边共${f2(ea.totalBothLots)}手`;\n  }\n  if ($('lotQuickStrip')) {\n    const netChips = [0.25, 0.43, 0.50, 1.00, 1.50, 2.00, 3.00].map((nVal) => {\n      const active = Math.abs(ea.netLots - nVal) < 0.015;\n      const dRisk = r1(ea.riskLossUsd / (nVal * 100));\n      const pts = Math.round(dRisk * 100);\n      return `<span onclick=\"pickQuickNetLots(${nVal})\" style=\"cursor:pointer;padding:2px 8px;border-radius:5px;border:1px solid ${active ? '#34d399' : '#263042'};background:${active ? 'rgba(16,185,129,0.18)' : '#141923'};color:${active ? '#34d399' : '#cbd5e1'};font-weight:${active ? '700' : '400'}\" title=\"点击一键测试净敞口 N=${f2(nVal)}手：按可亏$${ea.riskLossUsd}算，D = ${ea.riskLossUsd} ÷ (${f2(nVal)}×100) = ${f2(dRisk)}$ (${pts}点)\">净<b>${f2(nVal)}</b>手 → 抗<b>${f2(dRisk)}$</b>(${pts}点)</span>`;\n    }).join('');\n    const chips = ea.layers.slice(0, 15).map((r) => {\n      const active = r.n === ea.curLayerNum;\n      return `<span onclick=\"pickQuickLayer(${r.n})\" style=\"cursor:pointer;padding:2px 7px;border-radius:5px;border:1px solid ${active ? 'var(--gold)' : '#263042'};background:${active ? 'rgba(234,179,8,0.18)' : '#141923'};color:${active ? 'var(--gold)' : '#cbd5e1'};font-weight:${active ? '700' : '400'}\" title=\"第${r.n}层：当层单笔 ${f2(r.lot)}手，单向加起来总手数=${f2(r.cumLot)}手。点击一键将该单边手数填入\">${r.n}层=<b>${f2(r.cumLot)}</b>手</span>`;\n    }).join('');\n    $('lotQuickStrip').innerHTML = `\n      <div style=\"display:flex;align-items:center;flex-wrap:wrap;gap:6px\">\n        <span style=\"color:#34d399;font-weight:700\">⚡ 多空净敞口 N=|买-卖| 抗单边速查 (公式: D = 可亏$${ea.riskLossUsd} ÷ [N×100]，点击一键代入)：</span>\n        ${netChips}\n      </div>\n      <div style=\"display:flex;align-items:center;flex-wrap:wrap;gap:6px;padding-top:4px;border-top:1px dashed rgba(255,255,255,0.07)\">\n        <span style=\"color:var(--gold);font-weight:700\">🔍 单边手数反推层数对照表 (单向加起来多少手 = 第几层，点击可填入)：</span>\n        ${chips}\n      </div>`;\n  }\n  const m = d.model;\n  if (m) {\n    const W = m.weights || { '1M': 0.05, '5M': 0.1, '15M': 0.2, '1H': 0.4, '4H': 0.25 };\n    const adjMap = {}, lvMap = {};\n    let sw = 0, ss = 0;\n    for (const k of ['1M', '5M', '15M', '1H', '4H', '1D']) {\n      const t = d.timeframes[k];\n      if (!t || t.rangeIndex == null) continue;\n      const adj = adjBySpan(t.rangeIndex, t.span14, TOL, k);\n      adjMap[k] = adj;\n      lvMap[k] = levelFor(adj, t.trendDir);\n      if (W[k]) { sw += W[k]; ss += adj * W[k]; }\n    }\n    const adjCurrent = sw ? r1(ss / sw) : m.current;\n    const rawDelta = clamp((m.run ?? m.current) - (m.current ?? 0), -18, 12);\n    const adjRun = r1(clamp(adjCurrent + rawDelta * 0.65, 16, 98));\n    const curLv = levelFor(adjCurrent, m.overallDir);\n    const runLv = levelFor(adjRun, m.overallDir);\n\n    // 预计算各周期入场序列\n    const eMap = {};\n    for (const k of ['1M', '5M', '15M', '1H', '4H']) {\n      const sp = (m.sparks && m.sparks[k]) || [];\n      const ser = calcEntrySeries(sp, TOL, k);\n      eMap[k] = { ser, last: ser[ser.length - 1] || { entryTxt: '-', entryCls: 'MIXED', entryScore: '-', entryState: 'WAIT', entryReason: '-', effDrop1: 0, effChg1: 0 } };\n    }\n    const mainEntry = (eMap['15M'] && eMap['15M'].last) || (eMap['1H'] && eMap['1H'].last);\n    if ($('nav-entry') && mainEntry) {\n      $('nav-entry').textContent = mainEntry.entryState === 'OK' ? '适合' : mainEntry.entryState === 'WAIT' ? '观望' : '禁入';\n      $('nav-entry').className = 'pill ' + mainEntry.entryCls;\n    }\n\n    // ========== 计算 EA 实时手动操作指令 (以 1M+5M 为主 65%，参考 15M+1H 35%) ==========\n    const eaDir = calcEaDirective(d, ea, adjMap, eMap);\n    if ($('nav-ea')) {\n      const navTxt = SHOW_TOL_SEC ? (eaDir.state === 'PAUSE_SELL' ? '禁空Sell' : eaDir.state === 'PAUSE_BUY' ? '禁多Buy' : eaDir.state === 'STOP_ALL' ? '紧急停EA' : eaDir.state === 'CAUTION_WATCH' ? '戒备观察' : '自动运行') : '已关';\n      $('nav-ea').textContent = navTxt;\n      $('nav-ea').className = SHOW_TOL_SEC ? ('pill ' + eaDir.badgeCls + ' fast-num') : 'pill NEUT';\n    }\n    syncTolSecToggleUi();\n\n    // ========== 渲染置顶「🧭 极简一锤定音总决策台」与「📈 MT4 实盘余额·净值·收益曲线 & 持仓生死线沙盘」 ==========\n    if ($('masterDecisionSec')) {\n      const pb = d.pullback || {\n        span90m: (d.timeframes['15M'] && d.timeframes['15M'].span14) || 5.0,\n        totalClears90m: 1,\n        maxPb90m: 3.0,\n        activeUnretraced: 2.5,\n        activeCurRetrace: 0.8,\n        needMoreForClear: 1.9,\n        pressureSideTxt: '多空均衡',\n        pattern: 'BOX_RANGE',\n        patternBadge: '🟢 良性震荡/带回调波段 (可做)',\n        patternCls: 'RANGE',\n        sawtoothBonus: 6,\n        reboundProb: 68,\n        reasons: ['盘面存在常态均值回归回调'],\n        holdDecision: '🟢 建议【继续拿着等 $2.7 反抽自动止盈平仓】',\n        holdAction: '当前未解套跨度较小，正常持有等待 EA 自动触发止盈清仓即可。',\n        holdCls: 'RANGE'\n      };\n      const lkNow = evalCustomLockState();\n      const hasRedLock = lkNow && lkNow.activeLocks && lkNow.activeLocks.length > 0;\n\n      // 合成全站唯一主指数：【马丁实盘可做总分 (0~100)】= 基础短周期震荡指数 + 锯齿回调修正加分(下跌10$但回调3$平仓了就加分！) - 红灯锁惩罚\n      const baseShortScore = Math.round(0.35 * (adjMap['1M'] || 60) + 0.40 * (adjMap['5M'] || 60) + 0.25 * (adjMap['15M'] || 60));\n      const rawMartingaleScore = baseShortScore + (pb.sawtoothBonus || 0) - (hasRedLock ? 25 : 0);\n      const martingaleScore = Math.max(5, Math.min(99, Math.round(rawMartingaleScore)));\n      const mCls = martingaleScore >= 60 ? 'RANGE' : martingaleScore >= 46 ? 'MIXED' : 'TREND';\n      const mStatusTxt = martingaleScore >= 60\n        ? '🟢 适合做马丁 (震荡或带3$回调的锯齿波段)'\n        : martingaleScore >= 46\n        ? '🟡 谨慎可做 (宽幅阶梯波段·注意控层)'\n        : '🔴 高危禁做 (无回调单边推土机或红灯锁)';\n\n      if ($('nav-master')) {\n        $('nav-master').textContent = `${martingaleScore}分`;\n        $('nav-master').className = 'pill ' + mCls + ' fast-num';\n      }\n\n      // 计算 MT4 实盘专属联动决策模型（精确到回本价、整组止盈价、100%预付款锁死价、50%/20%强平生死线）\n      const isMockAcc = mt4 ? !!(mt4.isMock || mt4.account === '8861092' || mt4.account === '1') : false;\n      const mt4Dec = mt4 ? calcMt4LiveDecision(d, mt4, pb, adjMap, lkNow, martingaleScore) : null;\n\n      if ($('nav-mt4')) {\n        if (mt4 && !isMockAcc) {\n          $('nav-mt4').textContent = mt4Dec ? `${mt4Dec.ddPct > 0 ? '-' + mt4Dec.ddPct + '%' : '盈利中'}` : '在线';\n          $('nav-mt4').className = 'pill ' + (mt4Dec ? mt4Dec.healthCls : 'RANGE');\n        } else {\n          $('nav-mt4').textContent = mt4 ? '演示' : '未连';\n          $('nav-mt4').className = 'pill NEUT';\n        }\n      }\n\n      // 场景 1（空仓/轻仓 或 实盘持仓风控加仓/锁仓指令）\n      let card2Title = '② 如果您现在【空仓 / 1~3层轻仓】：何时入场？';\n      let card2Badge = '入场决策';\n      let entryHeadline = '';\n      let entryDetail = '';\n      let entryBoxCls = 'RANGE';\n      let card2Footer = '💡 核心法则：只要不是「连续走 &gt;6$ 无 2.7$ 回调」的推土机行情，哪怕单边跌 10$ 只要中途能回调 3$ 平仓，本卡都会亮绿灯让您做！';\n\n      if (mt4Dec && mt4Dec.hasPositions && !isMockAcc) {\n        card2Title = `② 针对您实盘持仓 [买${mt4.buyCount}层/${f2(mt4.buyLots)}手 · 卖${mt4.sellCount}层/${f2(mt4.sellLots)}手]：加仓还是锁仓？`;\n        card2Badge = mt4Dec.posActionBadge;\n        entryHeadline = mt4Dec.posHeadline;\n        entryDetail = mt4Dec.posDetail;\n        entryBoxCls = mt4Dec.posCls;\n        card2Footer = mt4Dec.posFooter;\n      } else if (hasRedLock) {\n        const topLk = lkNow.activeLocks[0];\n        entryHeadline = `🔴 严禁现在新开 EA（正处于 ${topLk.time} 重磅红灯锁）`;\n        entryDetail = `当前处于【${topLk.title}】前${topLk.pre}分~后${topLk.post}分高危窗口，极易瞬间扫损拉出无回调单边，请等红灯锁解除后再入场！`;\n        entryBoxCls = 'TREND';\n      } else if (martingaleScore >= 60 && pb.pattern !== 'NO_PB_BULLDOZER') {\n        entryHeadline = `🟢 可以入场 / 保持双向 EA 开启 (${martingaleScore}分)`;\n        entryDetail = pb.totalClears90m >= 1 && pb.span90m >= 6.0\n          ? `✅ <b>锯齿回调识别生效</b>：虽然近90分钟总波幅走了 <b>$${f2(pb.span90m)}</b>，但中途已出现 <b>${pb.totalClears90m} 次 ≥$2.7 的有效回调</b>（最大回调 <b>$${f2(pb.maxPb90m)}</b>），马丁网格完全能平仓赚钱！当前未解套连续跨度仅 <b>$${f2(pb.activeUnretraced)}</b>，可以正常做！`\n          : `✅ 当前盘面未解套连续跨度仅 <b>$${f2(pb.activeUnretraced)}</b>，多空来回折返顺畅，非常适合双向马丁刷单止盈。`;\n        entryBoxCls = 'RANGE';\n      } else if (martingaleScore >= 46) {\n        entryHeadline = `🟡 先观望 5~10 分钟，等当前急走 K 线收稳再入场`;\n        entryDetail = `当前处于宽幅波动（本段连续未回调跨度 <b>$${f2(pb.activeUnretraced)}</b>），若空仓建议等 1M/5M 出现止跌/受阻阳阴线后再开启 EA。`;\n        entryBoxCls = 'MIXED';\n      } else {\n        entryHeadline = `🔴 禁止现在入场！（正处于无回调推土机单边）`;\n        entryDetail = `🚨 当前已连续单边运行 <b>$${f2(pb.activeUnretraced)}</b> 而中途最大回调不足 <b>$${f2(pb.activeMaxRetraceInLeg || 1.5)}</b>，马丁无法平仓重置，空仓者切勿此时进场接飞刀！`;\n        entryBoxCls = 'TREND';\n      }\n\n      // 场景 3（被套去留 或 实盘浮亏精确解套点位指令）\n      let card3Title = '③ 如果您【已被套浮亏 · 指数骤降来不及跑】：拿还是走？';\n      let card3Badge = `回调解套概率 ${pb.reboundProb}%`;\n      let card3Cls = pb.holdCls;\n      let card3Headline = pb.holdDecision;\n      let card3Detail = pb.holdAction.replace(/\\*\\*(.*?)\\*\\*/g, '<b style=\"color:var(--gold)\">$1</b>');\n      let card3FooterHtml = `\n        <span>当前受压: <b>${pb.pressureSideTxt}</b></span>\n        <span>已反抽: <b style=\"color:#34d399\">$${f2(pb.activeCurRetrace)}</b></span>\n        <span>距止盈平仓还差: <b style=\"color:var(--gold)\">$${f2(pb.needMoreForClear)}</b></span>`;\n\n      if (mt4Dec && mt4Dec.hasPositions && !isMockAcc) {\n        card3Title = `③ 您实盘净浮盈亏 [${mt4.totalPnl >= 0 ? '+' : ''}$${f2(mt4.totalPnl)} · 回撤${mt4Dec.ddPct}%]：去留与精确解套价`;\n        card3Badge = `解套概率 ${mt4Dec.liveReboundProb}%`;\n        card3Cls = mt4Dec.escapeCls;\n        card3Headline = mt4Dec.escapeHeadline;\n        card3Detail = mt4Dec.escapeDetail;\n        card3FooterHtml = mt4Dec.escapeFooterHtml;\n      }\n\n      // 如果已连接 MT4 实盘，渲染顶部实时状态横幅\n      let mt4StripHtml = '';\n      if (mt4 && mt4Dec) {\n        const ageSec = Math.max(0, Math.round((Date.now() - mt4.ts) / 1000));\n        const statusTag = isMockAcc\n          ? `<span class=\"pill MIXED\" style=\"cursor:pointer\" onclick=\"clearMt4Data()\" title=\"点击立即清除这条模拟测试数据\">🧪 网页模拟演示数据 (假测试账号 #${mt4.account} · 非您的真实MT4 · 点此清除)</span>`\n          : `<span class=\"pill RANGE\" style=\"background:rgba(56,189,248,0.2);color:#38bdf8;border:1px solid #38bdf8\">🟢 您的真实 MT4 已联动决策 (${ageSec}秒前 · 实时推演价 $${f2(mt4Dec.curPx)})</span>`;\n        mt4StripHtml = `\n          <div style=\"margin-bottom:10px;padding:9px 12px;background:${isMockAcc ? 'rgba(245,158,11,0.12)' : 'linear-gradient(90deg,rgba(14,116,144,0.24),rgba(15,23,42,0.92))'};border:1.5px solid ${isMockAcc ? 'rgba(245,158,11,0.55)' : 'rgba(56,189,248,0.6)'};border-radius:8px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;font-size:12px\">\n            <div style=\"display:flex;align-items:center;gap:8px;flex-wrap:wrap\">\n              ${statusTag}\n              <span>账户 <b>#${mt4.account || '-'}</b>${mt4.server ? ` (${mt4.server})` : ''}: 余额 <b style=\"color:var(--gold)\">$${f2(mt4.balance)}</b> / 净值 <b style=\"color:${mt4.equity < mt4.balance ? '#fb7185' : '#34d399'}\">$${f2(mt4.equity)}</b> (预付款比 <b style=\"color:${mt4.marginLevel < 200 ? '#fb7185' : '#38bdf8'}\">${f2(mt4.marginLevel)}%</b>)</span>\n              <span>| 多单(Buy): <b>${mt4.buyCount}层/${f2(mt4.buyLots)}手</b> ${mt4.buyAvgPrice ? `(均价$${f2(mt4.buyAvgPrice)} · <b style=\"color:${mt4.buyPnl >= 0 ? '#34d399' : '#fb7185'}\">$${f2(mt4.buyPnl)}</b>)` : ''}</span>\n              <span>| 空单(Sell): <b>${mt4.sellCount}层/${f2(mt4.sellLots)}手</b> ${mt4.sellAvgPrice ? `(均价$${f2(mt4.sellAvgPrice)} · <b style=\"color:${mt4.sellPnl >= 0 ? '#34d399' : '#fb7185'}\">$${f2(mt4.sellPnl)}</b>)` : ''}</span>\n              <span>| 净敞口: <b style=\"color:#fff\">${mt4Dec.netSigned > 0 ? '净多+' : mt4Dec.netSigned < 0 ? '净空' : '锁仓'}${f2(mt4Dec.netSigned)}手 ($${f2(mt4Dec.netLossPerUsd)}/美金)</b></span>\n            </div>\n            <div style=\"color:#e2e8f0;display:flex;align-items:center;gap:8px;flex-wrap:wrap\">\n              <span>🎯 ${mt4Dec.breakEvenSummary}</span>\n              <a href=\"#mt4CurveSec\" style=\"color:#38bdf8;font-weight:800;text-decoration:underline\">📈 查看余额/净值/收益曲线图 ↓</a>\n              ${isMockAcc ? `<button class=\"sm\" onclick=\"clearMt4Data()\" style=\"padding:1px 7px;color:#fb7185;border-color:#fb7185\">🗑️ 清除演示数据</button>` : ''}\n            </div>\n          </div>`;\n      }\n\n      $('masterDecisionSec').innerHTML = `\n        <div class=\"vhead\" style=\"margin-bottom:10px\">\n          <div>\n            <h2 style=\"margin:0\">🧭 马丁实盘「一锤定音」极简决策台 <span class=\"mut sm\" style=\"font-weight:400\">(${mt4 && !isMockAcc ? `已深度绑定您 #${mt4.account} 实盘多空持仓与预付款水位，直接给出加仓/锁仓/解套点位指令` : '不用再纠结看哪个指数！全站已合成为这 1 个总分 + 「空仓入场」与「被套去留」2 句直接指令'})</span></h2>\n          </div>\n          <span class=\"pill ${pb.patternCls}\" style=\"font-size:12.5px;padding:4px 10px\">${pb.patternBadge}</span>\n        </div>\n        ${mt4StripHtml}\n\n        <div class=\"grid3\" style=\"gap:12px\">\n          <!-- 卡片 1：唯一总指数（含单边10$但回调3$平仓赚钱的锯齿修正 + 实盘账户健康度） -->\n          <div style=\"background:linear-gradient(135deg,rgba(234,179,8,0.12),rgba(15,20,30,0.95));border:1.5px solid ${mCls === 'RANGE' ? 'rgba(16,185,129,0.55)' : mCls === 'MIXED' ? 'rgba(245,158,11,0.55)' : 'rgba(244,63,94,0.65)'};border-radius:10px;padding:12px 14px\">\n            <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:6px\">\n              <b style=\"color:var(--gold);font-size:13px\">① 全站唯一总分：马丁可做指数</b>\n              <span class=\"pill ${mCls}\">${mStatusTxt.slice(0, 8)}</span>\n            </div>\n            <div style=\"display:flex;align-items:baseline;gap:8px;margin:4px 0 8px;flex-wrap:wrap\">\n              <span class=\"num-chip fast-num\" style=\"font-size:38px;font-weight:900;line-height:1;color:${mCls === 'RANGE' ? '#34d399' : mCls === 'MIXED' ? '#fbbf24' : '#fb7185'}\">${martingaleScore}</span>\n              <span class=\"mut sm\">/ 100</span>\n              <span class=\"pill NEUT\" style=\"font-size:11px\">基础震荡 ${baseShortScore}分 ${pb.sawtoothBonus >= 0 ? `+ 锯齿回调 +${pb.sawtoothBonus}` : `− 无回调 ${pb.sawtoothBonus}`}</span>\n              ${mt4Dec && !isMockAcc ? `<span class=\"pill ${mt4Dec.healthCls}\" style=\"font-size:11px\">🛡️ 实盘账户安全分: ${mt4Dec.accountHealthScore}分</span>` : ''}\n            </div>\n            ${idxBar(martingaleScore)}\n            <div style=\"margin-top:8px;padding-top:8px;border-top:1px dashed var(--bd);font-size:12px;line-height:1.55;color:#cbd5e1\">\n              • 近90分钟总波幅: <b>$${f2(pb.span90m)}</b> | 满$2.7止盈回调: <b style=\"color:#34d399\">${pb.totalClears90m} 次</b> (最大回调 <b>$${f2(pb.maxPb90m)}</b>)<br>\n              • <b>当前连续未解套跨度</b>: <b style=\"color:${pb.activeUnretraced <= 5.5 ? '#34d399' : '#fb7185'}\">$${f2(pb.activeUnretraced)}</b> ${mt4Dec && !isMockAcc ? `| <b>实盘100%锁死线</b>: <b style=\"color:#fb7185\">$${f2(mt4Dec.margin100Px)}</b> (余$${f2(mt4Dec.distToMargin100)})` : `<span class=\"xs mut\">(≥60分即可正常做马丁)</span>`}\n            </div>\n          </div>\n\n          <!-- 卡片 2：实盘持仓加仓/锁仓指令 或 空仓入场指令 -->\n          <div style=\"background:rgba(15,20,30,0.92);border:1.5px solid ${entryBoxCls === 'RANGE' ? 'rgba(16,185,129,0.5)' : entryBoxCls === 'MIXED' ? 'rgba(245,158,11,0.5)' : 'rgba(244,63,94,0.6)'};border-radius:10px;padding:12px 14px;display:flex;flex-direction:column;justify-content:space-between\">\n            <div>\n              <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:6px\">\n                <b style=\"color:#fff;font-size:13px\">${card2Title}</b>\n                <span class=\"pill ${entryBoxCls}\">${card2Badge}</span>\n              </div>\n              <div style=\"font-size:15px;font-weight:900;color:${entryBoxCls === 'RANGE' ? '#34d399' : entryBoxCls === 'MIXED' ? '#fbbf24' : '#fb7185'};margin:6px 0\">\n                ${entryHeadline}\n              </div>\n              <div style=\"font-size:12px;line-height:1.55;color:#cbd5e1\">\n                ${entryDetail}\n              </div>\n            </div>\n            <div class=\"xs mut\" style=\"margin-top:8px;padding-top:6px;border-top:1px dashed var(--bd)\">\n              ${card2Footer}\n            </div>\n          </div>\n\n          <!-- 卡片 3：实盘浮亏精确解套点位 或 已被套去留决策 -->\n          <div style=\"background:rgba(15,20,30,0.92);border:1.5px solid ${card3Cls === 'RANGE' ? 'rgba(16,185,129,0.55)' : card3Cls === 'MIXED' ? 'rgba(245,158,11,0.55)' : 'rgba(244,63,94,0.65)'};border-radius:10px;padding:12px 14px;display:flex;flex-direction:column;justify-content:space-between\">\n            <div>\n              <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:6px\">\n                <b style=\"color:#fff;font-size:13px\">${card3Title}</b>\n                <span class=\"pill ${card3Cls}\">${card3Badge}</span>\n              </div>\n              <div style=\"font-size:14.5px;font-weight:900;color:${card3Cls === 'RANGE' ? '#34d399' : card3Cls === 'MIXED' ? '#fbbf24' : '#fb7185'};margin:6px 0\">\n                ${card3Headline}\n              </div>\n              <div style=\"font-size:12px;line-height:1.55;color:#cbd5e1\">\n                ${card3Detail}\n              </div>\n            </div>\n            <div style=\"margin-top:8px;padding-top:6px;border-top:1px dashed var(--bd);font-size:11.5px;display:flex;justify-content:space-between;flex-wrap:wrap;gap:4px\">\n              ${card3FooterHtml}\n            </div>\n          </div>\n        </div>`;\n\n      // 渲染「📈 MT4 实盘账户：余额 · 净值 · 实时收益曲线图 & 持仓生死线沙盘」\n      renderMt4CurveSection(d, mt4, mt4Dec, isMockAcc);\n    }\n\n    // 渲染 #eaActionBox：实时手动操作指令台 + 账户风控推演卡片\n    if ($('eaActionBox')) {\n      const bdrCol = eaDir.badgeCls === 'TREND' ? 'rgba(239,91,91,.55)' : eaDir.badgeCls === 'MIXED' ? 'rgba(240,180,41,.45)' : 'rgba(46,204,143,.45)';\n      const bgGrad = eaDir.badgeCls === 'TREND'\n        ? 'linear-gradient(135deg,rgba(239,91,91,.13),rgba(19,25,38,.96))'\n        : eaDir.badgeCls === 'MIXED'\n        ? 'linear-gradient(135deg,rgba(240,180,41,.11),rgba(19,25,38,.96))'\n        : 'linear-gradient(135deg,rgba(46,204,143,.10),rgba(19,25,38,.96))';\n      const statusCol = eaDir.badgeCls === 'TREND' ? 'var(--red)' : eaDir.badgeCls === 'MIXED' ? 'var(--gold)' : 'var(--green)';\n      const floatLossNote = ea.hasAvgPx\n        ? `实时净浮亏: <b style=\"color:${ea.actualNetFloatLoss > 0 ? 'var(--red)' : 'var(--green)'}\">${ea.actualNetFloatLoss >= 0 ? '-$' + f2(ea.actualNetFloatLoss) : '+$' + f2(-ea.actualNetFloatLoss)}</b> (净值预付款比 ${ea.marginLevelEq.toLocaleString()}%)`\n        : `买${f2(ea.buyLots)}手(≈${ea.buyInfo.layer}层) − 卖${f2(ea.sellLots)}手(≈${ea.sellInfo.layer}层) · 预付款比 <b>${ea.marginLevelBal.toLocaleString()}%</b>`;\n\n      $('eaActionBox').innerHTML = `\n        <div style=\"border:1.5px solid ${bdrCol};background:${bgGrad};border-radius:10px;padding:14px 16px;box-shadow:0 6px 20px rgba(0,0,0,.28)\">\n          <div style=\"display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;padding-bottom:10px;border-bottom:1px solid var(--border)\">\n            <div style=\"display:flex;align-items:center;gap:10px;flex-wrap:wrap\">\n              <span class=\"pill ${eaDir.badgeCls} fast-num\" style=\"font-size:13px;padding:5px 12px\">${eaDir.badgeTxt}</span>\n              <span style=\"font-size:15px;font-weight:800;color:${statusCol}\">${eaDir.pauseSideTxt}</span>\n            </div>\n            <div class=\"sm mut\">\n              黄金现价: <b class=\"fast-num\" style=\"color:var(--text);font-size:14px\">${f2(eaDir.price)}$</b> ·\n              1M/5M短线触发指数: <b class=\"fast-num\" style=\"color:${eaDir.fastIdx < 50 ? 'var(--red)' : eaDir.fastIdx < 58 ? 'var(--gold)' : 'var(--green)'}\">${eaDir.fastIdx}</b>\n              <span class=\"xs\">(1M:${eaDir.adj1} / 5M:${eaDir.adj5} / 单次跌:${eaDir.fastDrop}分)</span> ·\n              15M/1H趋势参考: <b>${eaDir.midIdx}</b> <span class=\"xs\">(15M:${eaDir.adj15} / 1H:${eaDir.adj60})</span>\n            </div>\n          </div>\n\n          <div style=\"margin-top:10px;font-size:13.5px;font-weight:700;color:var(--text);line-height:1.55\">\n            ${eaDir.headline}\n          </div>\n\n          <div class=\"grid4\" style=\"margin-top:10px;gap:8px\">\n            <div style=\"background:rgba(12,16,23,.75);border:1px solid var(--border);border-radius:7px;padding:8px 10px\">\n              <div class=\"xs mut\">① 多空相抵净敞口 N & 浮亏速度 (核心)</div>\n              <div style=\"font-size:14.5px;font-weight:800;color:#34d399;margin-top:2px\">\n                净敞口 N = <b>${f2(ea.netLots)}手</b> <span class=\"xs mut\">($${f2(ea.netLossPerUsd)}/美金)</span>\n              </div>\n              <div class=\"xs mut\" style=\"margin-top:2px\">${floatLossNote}</div>\n            </div>\n            <div style=\"background:rgba(12,16,23,.75);border:1px solid var(--border);border-radius:7px;padding:8px 10px\">\n              <div class=\"xs mut\">② 按可亏/爆仓线($${ea.riskLossUsd})推算抗单边 D</div>\n              <div style=\"font-size:15px;font-weight:800;color:var(--gold);margin-top:2px\">\n                可抗单边: <b>${f2(ea.warn.span)}$</b> <span class=\"xs mut\">(折合 <b>${ea.warn.pts}点</b>)</span>\n              </div>\n              <div class=\"xs mut\" style=\"margin-top:2px\">公式: $${ea.riskLossUsd} ÷ (${f2(ea.effNetLots)}手×100) · 重仓侧回调 <b>${f2(ea.curInfo.pullbackUsd)}$</b> 止盈</div>\n            </div>\n            <div style=\"background:rgba(12,16,23,.75);border:1px solid var(--border);border-radius:7px;padding:8px 10px\">\n              <div class=\"xs mut\">③ 按账户总本金($${ea.bal})推算极限抗单边</div>\n              <div style=\"font-size:15px;font-weight:800;color:var(--red);margin-top:2px\">\n                账户极限: <b>${f2(ea.hard.span)}$</b> <span class=\"xs mut\">(折合 <b>${ea.hard.pts}点</b>)</span>\n              </div>\n              <div class=\"xs mut\" style=\"margin-top:2px\">对比单边无对冲死加链: 强平20%约 <b>${f2(ea.uncontrolled20.span)}$</b> / 强平50%约 <b>${f2(ea.uncontrolled50.span)}$</b></div>\n            </div>\n            <div style=\"background:rgba(12,16,23,.75);border:1px solid var(--border);border-radius:7px;padding:8px 10px\">\n              <div class=\"xs mut\">④ 当前现价 ${f2(eaDir.price)}$ 净敞口防守边界</div>\n              <div style=\"font-size:13px;font-weight:700;color:var(--text);margin-top:2px\">\n                上防: <b style=\"color:var(--gold)\">${eaDir.upWarnPx}$</b> <span class=\"xs mut\">(极限 ${eaDir.upHardPx}$)</span><br>\n                下防: <b style=\"color:var(--gold)\">${eaDir.dnWarnPx}$</b> <span class=\"xs mut\">(极限 ${eaDir.dnHardPx}$)</span>\n              </div>\n            </div>\n          </div>\n\n          <div style=\"margin-top:10px;background:rgba(12,16,23,.82);border:1px solid var(--border);border-radius:8px;padding:10px 12px\">\n            <div style=\"font-size:12.5px;font-weight:700;color:var(--gold);margin-bottom:6px\">📋 具体怎么操作（MT4 / MT5 实盘操作步骤 · 核心目标：把多空净敞口 N 控制在 0.5~1.0 手以内，防止净敞口失控膨胀）：</div>\n            <ol style=\"margin:0;padding-left:18px;font-size:12.5px;line-height:1.7;color:var(--text)\">\n              ${eaDir.steps.map((s) => `<li style=\"margin-bottom:4px\">${s}</li>`).join('')}\n            </ol>\n            <div class=\"xs\" style=\"margin-top:8px;padding-top:6px;border-top:1px dashed var(--border);color:var(--muted)\">\n              🔄 <b>何时恢复双向自动运行</b>：${eaDir.resumeRule}\n            </div>\n          </div>\n        </div>`;\n    }\n\n    // 渲染 #tolResult：各周期实际波幅 vs 净敞口抗单跨度 + 净敞口速查表 & 4种情况对比 & 24层明细表\n    const tolRows = ['1M', '5M', '15M', '1H', '4H', '1D'].map((k) => {\n      const t = d.timeframes[k]; if (!t) return '';\n      const span = t.span14, s24 = t.span24;\n      const isFast = k === '1M' || k === '5M';\n      const roleTag = isFast ? `<span class=\"pill MIXED\" style=\"font-size:10px;padding:1px 5px\">主触发 65%</span>` : (k === '15M' || k === '1H') ? `<span class=\"pill FLAT\" style=\"font-size:10px;padding:1px 5px\">趋势参考 35%</span>` : '';\n      // 按当前多空净敞口 N 手 (每1美元波动净盈亏 = N * 100 美元) 折算该周期净单边波动的浮亏影响\n      const netMove = Math.abs(t.net14 || 0);\n      const effLoss = Math.round(netMove * ea.netLossPerUsd);\n      const spanLoss = Math.round(span * ea.netLossPerUsd);\n      const dirBadge = `<span class=\"pill ${t.trendDir}\">${t.trendDirText} (${t.net14 >= 0 ? '+' : ''}${f2(t.net14)}$)</span>`;\n      const fitBadge = span <= TOL\n        ? `<span class=\"pill RANGE\">✅ 在 ${f2(TOL)}$(${Math.round(TOL * 100)}点) 安全区内 (余量 ${f2(TOL - span)}$)</span>`\n        : span <= ea.hard.span\n        ? `<span class=\"pill MIXED\">⚠️ 超 $${ea.riskLossUsd} 风控线 (+${f2(span - TOL)}$) · 仍在 $${ea.bal} 极限 ${f2(ea.hard.span)}$ 内</span>`\n        : `<span class=\"pill TREND\">🛑 超出净敞口极限 (+${f2(span - ea.hard.span)}$)</span>`;\n      const lv = lvMap[k];\n      return `<tr>\n        <td><b>${k}</b> ${roleTag}</td>\n        <td><b>${f2(span)}$</b> <span class=\"mut sm\">(${Math.round(span * 100)}点 · ${f2(t.lo14)}~${f2(t.hi14)})</span></td>\n        <td>${f2(s24)}$ <span class=\"mut sm\">(${Math.round(s24 * 100)}点)</span></td>\n        <td>净涨跌折算 <b>$${effLoss}</b> <span class=\"mut sm\">(全振幅折算 $${spanLoss} · 占$${ea.riskLossUsd}的 ${r1(effLoss / ea.riskLossUsd * 100)}%)</span></td>\n        <td>${fitBadge}</td>\n        <td>${dirBadge}</td>\n        <td><b class=\"num-chip ${isFast ? 'fast-num' : ''}\" style=\"color:var(--gold);font-size:15px\">${adjMap[k]}</b> <span class=\"mut sm\">(原始 ${t.rangeIndex})</span> <span class=\"pill ${lv.cls}\">${lv.name}</span></td>\n      </tr>`;\n    }).join('');\n\n    const netExpRows = ea.netExposureTable.map((row) => {\n      const rowBg = row.isCurrent ? 'background:rgba(16,185,129,.18);' : '';\n      return `<tr style=\"${rowBg}\">\n        <td><b>${f2(row.nLot)} 手</b> ${row.isCurrent ? '<span class=\"pill RANGE\" style=\"font-size:10px;padding:1px 6px\">📍 当前净敞口</span>' : ''}</td>\n        <td><b>$${row.lossPerUsd}</b> / 美金</td>\n        <td style=\"color:var(--gold)\"><b>${f2(row.dRisk)} 美元</b></td>\n        <td style=\"color:var(--gold)\"><b>${row.ptsRisk.toLocaleString()} 点</b></td>\n        <td style=\"color:#34d399\"><b>${f2(row.dBal)} 美元</b></td>\n        <td style=\"color:#34d399\"><b>${row.ptsBal.toLocaleString()} 点</b></td>\n        <td><button class=\"sm\" onclick=\"pickQuickNetLots(${row.nLot})\" style=\"padding:2px 8px;font-size:11px\">代入 N=${f2(row.nLot)}手</button></td>\n      </tr>`;\n    }).join('');\n\n    const layerRows = ea.layers.map((r) => {\n      const isCur = ea.curLayerNum === r.n;\n      const isHard = r.ddUsd >= ea.bal;\n      const isWarn = !isHard && r.ddUsd >= ea.riskLossUsd;\n      const rowBg = isCur ? 'background:rgba(79,156,249,.18);' : isHard ? 'background:rgba(239,91,91,.13);' : isWarn ? 'background:rgba(240,180,41,.11);' : '';\n      const statusBadge = isCur\n        ? `<span class=\"pill RANGE\">📍 当前重仓侧对应层</span>`\n        : r.ddUsd >= ea.bal\n        ? `<span class=\"pill TREND\">🛑 单边无对冲死加至此层触及$${ea.bal}</span>`\n        : r.ddUsd >= ea.riskLossUsd\n        ? `<span class=\"pill MIXED\">⚠️ 单边无对冲触及$${ea.riskLossUsd}</span>`\n        : `<span class=\"pill RANGE\">🟢 安全层</span>`;\n      return `<tr style=\"${rowBg}\">\n        <td><b>第 ${r.n} 层</b> <span class=\"xs mut\">(n=${r.idx})</span></td>\n        <td><b>${f2(r.lot)}</b> 手 ${r.isCapped ? '<span class=\"xs\" style=\"color:var(--gold)\">[封顶]</span>' : ''}</td>\n        <td><b>${f2(r.cumLot)}</b> 手</td>\n        <td>$${f2(r.lossPerUsd)}/$</td>\n        <td style=\"color:var(--gold)\"><b>${f2(ea.riskLossUsd / r.lossPerUsd)}$</b> (${Math.round((ea.riskLossUsd / r.lossPerUsd) * 100)}点)</td>\n        <td><b>${f2(r.pullbackUsd)}$</b> <span class=\"xs mut\">(止盈+$${f2(r.tpUsd)})</span></td>\n        <td>$${f2(r.ddUsd)} <span class=\"xs mut\">(仅单边无对冲时适用)</span></td>\n        <td>${statusBadge}</td>\n      </tr>`;\n    }).join('');\n\n    $('tolResult').innerHTML = `\n      <div style=\"overflow-x:auto\"><table>\n        <tr><th>周期</th><th>近14根K线实际振幅</th><th>近24根K线振幅</th><th>按净敞口 N=${f2(ea.netLots)}手 ($${ea.netLossPerUsd}/$) 折算净浮亏</th><th>对比净敞口可抗区间 ${f2(TOL)}$ (${Math.round(TOL * 100)}点)</th><th>当前走势方向(14根净涨跌)</th><th>按净敞口修正后震荡指数 & 结论</th></tr>\n        ${tolRows}\n      </table></div>\n      <details id=\"fold-ea-layers\" ${window.OPEN_FOLDS && window.OPEN_FOLDS['fold-ea-layers'] ? 'open' : ''} ontoggle=\"window.OPEN_FOLDS&&(window.OPEN_FOLDS[this.id]=this.open)\" style=\"margin-top:10px;background:rgba(12,16,23,.65);border:1px solid var(--border);border-radius:8px;padding:8px 12px\">\n        <summary style=\"cursor:pointer;font-size:12.5px;font-weight:700;color:var(--gold);user-select:none\">\n          📊 展开查看：多空对冲净敞口反推表 (D = $${ea.riskLossUsd} ÷ [N×100]) + 4种实盘情况对比 + 1~${ea.cfg.totals}层单边手数明细表\n        </summary>\n        <div class=\"sm mut\" style=\"margin:6px 0 8px;line-height:1.6\">\n          💡 <b>核心结论（为什么实盘能扛 15~35+ 美元，远超理论单边链的 5~13 美元）</b>：马丁网格的“抗单边点数”<b>不等于“累计总手数 × 点数”</b>，而主要看<b>多空对冲后的净敞口 <code>N = |买单总手数 − 卖单总手数|</code></b>！双向都有单时，顺势单盈利会抵消逆势单亏损，且 EA 会不断把盈利方向整组平仓重置（<code>StopProfit=4.0$×层数</code>），只有<b>净敞口 N</b> 才决定净值下降速度：<code>可抗单边 D = 可亏金额 ÷ (N × 100)</code>。\n        </div>\n        <div class=\"grid2\" style=\"gap:10px;margin-bottom:10px\">\n          <div style=\"background:rgba(15,20,30,.85);border:1px solid var(--border);border-radius:7px;padding:8px 10px;overflow-x:auto\">\n            <div style=\"font-size:12px;font-weight:700;color:#34d399;margin-bottom:6px\">① 用“可亏 $${ea.riskLossUsd} / 账户 $${ea.bal}”反推不同净敞口 N 可抗单边 (D = L ÷ [N×100])</div>\n            <table>\n              <tr><th>多空净敞口 N</th><th>每1$波动净盈亏</th><th>亏 $${ea.riskLossUsd} 可抗单边 D</th><th>折合点数</th><th>亏 $${ea.bal}(全额) 可抗</th><th>折合点数</th><th>操作</th></tr>\n              ${netExpRows}\n            </table>\n          </div>\n          <div style=\"background:rgba(15,20,30,.85);border:1px solid var(--border);border-radius:7px;padding:8px 10px;overflow-x:auto\">\n            <div style=\"font-size:12px;font-weight:700;color:var(--gold);margin-bottom:6px\">② $${ea.bal} 账户 (1000倍杠杆) · 4种实盘情况真实抗单边对比</div>\n            <table>\n              <tr><th>实盘运行情况</th><th>净敞口 / 计费口径</th><th>大致能抗单边 (美元 / 点数)</th></tr>\n              <tr style=\"background:rgba(16,185,129,.14)\">\n                <td><b>📍 您当前实盘持仓 (买${f2(ea.buyLots)}手 / 卖${f2(ea.sellLots)}手)</b></td>\n                <td><b>净敞口 N = ${f2(ea.netLots)} 手</b> ($${ea.netLossPerUsd}/$)</td>\n                <td style=\"color:#34d399\"><b>${f2(ea.warn.span)} ~ ${f2(ea.hard.span)} 美元 (${ea.warn.pts} ~ ${ea.hard.pts} 点)</b></td>\n              </tr>\n              <tr>\n                <td><b>双向对冲 · 净敞口 0.5 手左右</b> (常态震荡/对冲良好)</td>\n                <td>净敞口 0.50 手 ($50/$)</td>\n                <td style=\"color:var(--gold)\"><b>约 ${f2(ea.riskLossUsd / 50)} ~ ${f2(ea.bal / 50)} 美元 (${Math.round(ea.riskLossUsd / 50 * 100)} ~ ${Math.round(ea.bal / 50 * 100)} 点)</b></td>\n              </tr>\n              <tr>\n                <td><b>双向对冲 · 净敞口 1.0 手左右</b> (中度单边偏离)</td>\n                <td>净敞口 1.00 手 ($100/$)</td>\n                <td style=\"color:var(--gold)\"><b>约 ${f2(ea.riskLossUsd / 100)} ~ ${f2(ea.bal / 100)} 美元 (${Math.round(ea.riskLossUsd / 100 * 100)} ~ ${Math.round(ea.bal / 100 * 100)} 点)</b></td>\n              </tr>\n              <tr>\n                <td><b>单边无对冲 · 一条链死加 (强平比例 20%)</b></td>\n                <td>0对冲 + 从0.02连续倍投至第${ea.uncontrolled20.layer}层</td>\n                <td class=\"mut\">约 <b>${f2(ea.uncontrolled20.span)} 美元 (${Math.round(ea.uncontrolled20.span * 100)} 点)</b> <span class=\"xs\">(仅无对冲死扛时适用)</span></td>\n              </tr>\n              <tr>\n                <td><b>单边无对冲 · 一条链死加 (强平比例 50%)</b></td>\n                <td>0对冲 + 从0.02连续倍投至第${ea.uncontrolled50.layer}层</td>\n                <td class=\"mut\">约 <b>${f2(ea.uncontrolled50.span)} 美元 (${Math.round(ea.uncontrolled50.span * 100)} 点)</b> <span class=\"xs\">(仅无对冲死扛时适用)</span></td>\n              </tr>\n            </table>\n          </div>\n        </div>\n        <div id=\"eaLayerScrollBox\" class=\"thin-scroll\" style=\"overflow-x:auto;max-height:320px;overflow-y:auto\">\n          <table>\n            <tr>\n              <th>单向层数</th>\n              <th>当层新加手数</th>\n              <th>该方向累计总手数</th>\n              <th>若无对冲每1$盈亏</th>\n              <th>若净敞口等于该手数可抗(亏$${ea.riskLossUsd})</th>\n              <th>该方向整组止盈所需回调</th>\n              <th>单边无对冲阶梯浮亏</th>\n              <th>说明</th>\n            </tr>\n            ${layerRows}\n          </table>\n        </div>\n      </details>`;\n\n    if ($('nav-tol')) $('nav-tol').textContent = f2(TOL) + '$';\n    if ($('nav-run')) { $('nav-run').textContent = adjRun; $('nav-run').className = 'pill ' + runLv.cls; }\n    for (const k of ['1M', '5M', '15M', '1H', '4H']) {\n      const el = $('nav-' + k);\n      if (el && adjMap[k] != null) {\n        el.textContent = adjMap[k];\n        el.className = 'pill ' + lvMap[k].cls + ((k === '1M' || k === '5M') ? ' fast-num' : '');\n      }\n    }\n\n    // ========== 前排「⚡ 实时异动监控区」：仅展示异动较大的指标，平稳指标一律静默隐藏 ==========\n    const anoms = [];\n    let quietCount = 0;\n\n    // 00. 检查顶部手动添加的重磅数据「前30分~后15分」红灯倒计时锁\n    const lockState = renderCustomEventBar();\n    if (lockState && lockState.activeLocks && lockState.activeLocks.length) {\n      for (const lkEv of lockState.activeLocks) {\n        anoms.push({\n          sev: 'high',\n          tag: '🚨 重磅红灯倒计时锁',\n          title: `${lkEv.time} ${lkEv.title}`,\n          val: lkEv.badge,\n          desc: `已进入您设定的 [前${lkEv.pre}分钟 ~ 后${lkEv.post}分钟] 重磅数据红灯锁定期，极易双向插针扫损，建议立即暂停EA新挂单或锁仓对冲！`,\n          href: '#topSessionSec'\n        });\n      }\n    } else quietCount++;\n\n    // 0. 检查 EA 实时手动操作指令是否触发锁方向/暂停挂单\n    if (eaDir.needManual) {\n      anoms.push({\n        sev: 'high',\n        tag: '🛡️ EA 实盘手动操作预警',\n        title: eaDir.badgeTxt.replace(/^[🚨🛑⚠️]+\\s*/, ''),\n        val: eaDir.pauseSideTxt,\n        desc: `${eaDir.headline}（$${ea.bal} 账户 65%警戒跨度 ${f2(ea.warn.span)}$ / 强平跨度 ${f2(ea.hard.span)}$）`,\n        href: '#tolSec'\n      });\n    } else quietCount++;\n\n    // 0.5 检查散户反指效应异动 & 关键清算位贴脸雷区\n    if (d.sentiment && (d.sentiment.retailLongPct >= 68 || d.sentiment.retailShortPct >= 62)) {\n      const st = d.sentiment;\n      anoms.push({\n        sev: (st.retailLongPct >= 73 || st.retailShortPct >= 68) ? 'high' : 'med',\n        tag: '📊 散户反指效应预警',\n        title: st.signal.replace(/^[🚨⚠️🟢]+\\s*/, ''),\n        val: `散户多头 ${st.retailLongPct}% vs 空头 ${st.retailShortPct}% (${st.retailRatio}:1) · 主动买盘 ${st.takerBuyPct}%`,\n        desc: st.eaAdvice,\n        href: '#sentimentSec'\n      });\n    } else quietCount++;\n\n    if (d.keyLevels && d.keyLevels.nearestDanger) {\n      const kl = d.keyLevels.nearestDanger;\n      anoms.push({\n        sev: kl.absDiff <= 1.4 ? 'high' : 'med',\n        tag: '🎯 关键清算位插针雷区',\n        title: `金价逼近【${kl.name} $${f2(kl.price)}】`,\n        val: `当前仅距 ${kl.absDiff}$ (${kl.pts}点 · ${kl.dir === 'UP' ? '上方阻力/止损池' : '下方支撑/止损池'})`,\n        desc: kl.desc + '（切勿在关键突破口密集挂逆势马丁单）',\n        href: '#keyLevelsSec'\n      });\n    } else quietCount++;\n\n    // 触发浏览器语音报警评估（自动按敏感度档位与冷却时间过滤）\n    evaluateVoiceAlerts(d, eaDir, lockState);\n\n    // A. 检查跨市场长周期指标异动 (不计入短周期震荡指数，仅在异动较大时浮现前排)\n    const mc = d.macro;\n    if (mc && mc.dxy) {\n      const dxy = mc.dxy || {}, us10 = mc.us10y || {}, xag = mc.xag || {}, vix = mc.vix || {};\n      if ((mc.dxyAdx != null && mc.dxyAdx >= 25) || Math.abs(dxy.chgPct || 0) >= 0.45) {\n        anoms.push({\n          sev: (mc.dxyAdx >= 32 || Math.abs(dxy.chgPct || 0) >= 0.7) ? 'high' : 'med',\n          tag: '跨市场长周期异动',\n          title: `美元指数 (DXY) 走单边趋势`,\n          val: `DXY ${f2(dxy.last)} (${dxy.chgPct >= 0 ? '+' : ''}${f2(dxy.chgPct)}%) · 15M ADX = ${f2(mc.dxyAdx)}`,\n          desc: `美元趋势强度超阈值(≥25)，易从外部驱动黄金走出单边行情（注：长周期指标未计入短周期震荡指数，仅作前排风控预警）`,\n          href: '#macroSec'\n        });\n      } else quietCount++;\n\n      if (mc.corrXauDxy != null && mc.corrXauDxy >= 0.35) {\n        anoms.push({\n          sev: 'high',\n          tag: '跨市场相关性异动',\n          title: `黄金与美元呈同涨正相关 (r = +${f2(mc.corrXauDxy)})`,\n          val: `20根K线相关系数 ${f2(mc.corrXauDxy)} (正常应为负相关)`,\n          desc: `同涨代表避险买盘强力主导，技术面超买极易钝化，严防单边逼空`,\n          href: '#macroSec'\n        });\n      } else quietCount++;\n\n      if (Math.abs(us10.chgPct || 0) >= 1.5) {\n        anoms.push({\n          sev: Math.abs(us10.chgPct) >= 2.5 ? 'high' : 'med',\n          tag: '跨市场利率异动',\n          title: `10年期美债收益率剧烈波动`,\n          val: `${f2(us10.last)}% (日内 ${us10.chgPct >= 0 ? '+' : ''}${f2(us10.chgPct)}%)`,\n          desc: `美债实际利率大幅波动，黄金定价锚正在重估，警惕趋势延续`,\n          href: '#macroSec'\n        });\n      } else quietCount++;\n\n      if (mc.agLead != null && Math.abs(mc.agLead) >= 0.8) {\n        anoms.push({\n          sev: Math.abs(mc.agLead) >= 1.4 ? 'high' : 'med',\n          tag: '贵金属联动异动',\n          title: `现货白银相对黄金明显${mc.agLead > 0 ? '领涨' : '领跌'}`,\n          val: `银-金日内强弱差 ${mc.agLead >= 0 ? '+' : ''}${f2(mc.agLead)}% (白银 ${xag.chgPct >= 0 ? '+' : ''}${f2(xag.chgPct)}%)`,\n          desc: `白银弹性高，常比黄金提前 15~30 分钟发动破位，需留意同向突破`,\n          href: '#macroSec'\n        });\n      } else quietCount++;\n\n      if ((vix.last || 0) >= 22 || Math.abs(vix.chgPct || 0) >= 8) {\n        anoms.push({\n          sev: (vix.last || 0) >= 26 ? 'high' : 'med',\n          tag: '宏观情绪异动',\n          title: `VIX 恐慌指数异动`,\n          val: `VIX ${f2(vix.last)} (${vix.chgPct >= 0 ? '+' : ''}${f2(vix.chgPct)}%)`,\n          desc: `市场避险情绪升温，跨资产波动放大`,\n          href: '#macroSec'\n        });\n      } else quietCount++;\n    }\n    if (d.gvz && d.gvz.pct1y >= 75) {\n      anoms.push({\n        sev: d.gvz.pct1y >= 88 ? 'high' : 'med',\n        tag: '期权隐波异动',\n        title: `GVZ 黄金波动率处于 1 年高分位`,\n        val: `GVZ ${f2(d.gvz.value)} (1年分位 ${d.gvz.pct1y}%)`,\n        desc: `期权市场定价高波动，建议放宽网格间距`,\n        href: '#sessionSec'\n      });\n    } else quietCount++;\n\n    if (d.attention && (d.attention.score >= 65 || (d.attention.comex && d.attention.comex.volRatio >= 1.45) || (d.attention.shfe && d.attention.shfe.volRatio >= 1.40) || (d.attention.news && d.attention.news.count1h >= 5))) {\n      const at = d.attention;\n      const cmx = at.comex || {}, sh = at.shfe || {}, nw = at.news || {};\n      anoms.push({\n        sev: at.score >= 76 || (cmx.volRatio >= 1.8) || (nw.count1h >= 8) ? 'high' : 'med',\n        tag: '🔥 黄金受关注度异动',\n        title: `全球黄金受关注度飙升 (${at.score}/100 · ${at.level})`,\n        val: `COMEX量比 ${cmx.volRatio ?? '-'}x · 沪金量比 ${sh.volRatio ?? '-'}x · 1h快讯 ${nw.count1h ?? 0}条`,\n        desc: at.eaTip || '全球交投或财经與情热度显著放大，警惕大资金顺势突破，严控马丁单边敞口',\n        href: '#attentionSec'\n      });\n    } else quietCount++;\n\n    // B. 检查各周期 K 线单次跳水、波幅超标、单侧悬空异动\n    for (const k of ['1M', '5M', '15M', '1H', '4H']) {\n      const t = d.timeframes[k];\n      if (!t) continue;\n      const lastE = eMap[k] ? eMap[k].last : {};\n      // 1) 单次跌幅异动\n      if ((lastE.effDrop1 || 0) >= 4.5 || (t.maxDrop14 || 0) >= 7.5) {\n        const isNow = (lastE.effDrop1 || 0) >= 4.5;\n        anoms.push({\n          sev: (lastE.effDrop1 >= 7.5 || t.maxDrop14 >= 10) ? 'high' : 'med',\n          tag: `${k} 周期跳水预警`,\n          title: isNow ? `${k} 震荡指数正在单次急跌 (-${lastE.effDrop1}分)` : `${k} 近14根内曾出现单次急跌 (-${t.maxDrop14}分)`,\n          val: `当前单次Δ ${lastE.effChg1 >= 0 ? '+' : ''}${lastE.effChg1}分 · 最大跌对应K线波幅 ${f2(t.maxDropBarSpan14)}$`,\n          desc: `震荡指数单次大跌往往伴随大阳/大阴线破位巨震，点击查看 ${k} 入场时序图`,\n          href: `#chart-${k}`\n        });\n      } else quietCount++;\n\n      // 2) 波幅超出策略容忍度区间 (针对 15M/1H/4H 提示，或 1M/5M 超出)\n      if (t.span14 > TOL) {\n        anoms.push({\n          sev: t.span14 > TOL * 1.35 ? 'high' : 'med',\n          tag: `${k} 波幅超标`,\n          title: `${k} 近14根实际波幅超出 ${f2(TOL)}$ 策略区间`,\n          val: `实际波幅 ${f2(t.span14)}$ (超标 +${f2(t.span14 - TOL)}$ · ${t.trendDirText})`,\n          desc: `当前周期波动跨度已超过您设定的 ${f2(TOL)}$ 容忍边界，策略指数已下调至 ${adjMap[k]} 分`,\n          href: `#chart-${k}`\n        });\n      } else quietCount++;\n\n      // 3) 20根穿MA20次数过少 (单侧悬空阴涨/阴跌)\n      if ((k === '15M' || k === '1H' || k === '4H') && t.maCross20 != null && t.maCross20 <= 1) {\n        anoms.push({\n          sev: 'med',\n          tag: `${k} 均线不回头`,\n          title: `${k} 近20根K线仅穿刺 MA20 中轨 ${t.maCross20} 次`,\n          val: `价格沿布林中轨单侧悬空运行 (${t.trendDirText})`,\n          desc: `缺乏围绕均线的来回折返，容易形成单向慢牛/阴跌推土机累单`,\n          href: `#ind-${k}`\n        });\n      } else quietCount++;\n    }\n\n    // C. 波动率挤压蓄势异动\n    if (m.squeeze && m.squeeze.strength >= 35) {\n      anoms.push({\n        sev: m.squeeze.strength >= 60 ? 'high' : 'med',\n        tag: '变盘蓄势异动',\n        title: `多周期波动率挤压预警 (强度 ${m.squeeze.strength}%)`,\n        val: m.squeeze.why.join(' · '),\n        desc: `盘面极度收窄蓄势，未来数小时至1~2天随时可能爆发单边突破`,\n        href: '#verdict'\n      });\n    } else quietCount++;\n\n    // D. 未来 4 小时内 ≥4 星重磅财经事件异动\n    const nowMs = Date.now();\n    const soonEvs = ((d.calendar && d.calendar.items) || []).filter((e) => {\n      if ((e.star || 0) < 4) return false;\n      const tMs = Date.parse(e.time);\n      return Number.isFinite(tMs) && tMs >= nowMs - 30 * 60e3 && tMs <= nowMs + 4 * 3600e3;\n    });\n    if (soonEvs.length) {\n      anoms.push({\n        sev: 'high',\n        tag: '重磅数据临近',\n        title: `未来 4 小时内有 ${soonEvs.length} 项 ★4~5星高危数据/事件`,\n        val: soonEvs.map((e) => `${e.time.slice(11, 16)} ${e.country}${e.summary || e.title}`).join('；'),\n        desc: `重大数据公布前后极易瞬间扫损拉出单边，建议提前暂停新开网格`,\n        href: '#calSec'\n      });\n    } else quietCount++;\n\n    // E. 特朗普言论实时监控异动 (仅近3小时内出现涉及关税/贸易/联储/地缘的中高冲击言论时才浮现前排)\n    if (d.trump && d.trump.items) {\n      const recentTrump = d.trump.items.filter((x) => x.ageMin <= 180 && (x.impact === 'HIGH' || x.impact === 'MED'));\n      if (recentTrump.length) {\n        const topT = recentTrump[0];\n        const ageStr = topT.ageMin < 60 ? `${topT.ageMin}分钟前` : `${(topT.ageMin / 60).toFixed(1)}小时前`;\n        anoms.push({\n          sev: topT.impact === 'HIGH' ? 'high' : 'med',\n          tag: `🦅 特朗普涉金言论 (${ageStr})`,\n          title: topT.title || topT.text.slice(0, 46) + '...',\n          val: `[${topT.tags.join('·')}] 冲击分 ${topT.impactScore}/100 · ${topT.goldBias}`,\n          desc: topT.text.slice(0, 95) + (topT.text.length > 95 ? '...' : ''),\n          href: '#trumpSec'\n        });\n      } else quietCount++;\n    }\n\n    if ($('nav-anom')) {\n      $('nav-anom').textContent = anoms.length ? `${anoms.length}项异动` : '平稳';\n      $('nav-anom').className = 'pill ' + (anoms.some((a) => a.sev === 'high') ? 'TREND' : anoms.length ? 'MIXED' : 'RANGE');\n    }\n\n    if (anoms.length) {\n      const highCnt = anoms.filter((a) => a.sev === 'high').length;\n      $('anomalySec').innerHTML = `\n        <div class=\"vhead\" style=\"margin-bottom:4px\">\n          <h2 style=\"margin:0\">⚡ 实时异动监控区 <span class=\"pill ${highCnt ? 'TREND' : 'MIXED'}\">当前检出 ${anoms.length} 项显著异动${highCnt ? ` (含 ${highCnt} 项高危)` : ''}</span></h2>\n          <span class=\"mut sm\">已自动静默过滤 ${quietCount} 项平稳指标 · 长周期跨市场指标不计入短周期震荡指数，仅在此处异动预警</span>\n        </div>\n        <div class=\"anom-grid\">\n          ${anoms.map((a) => `<div class=\"anom-card sev-${a.sev}\" onclick=\"location.hash='${a.href}'\">\n            <div style=\"display:flex;justify-content:space-between;align-items:center;gap:6px\">\n              <span class=\"pill ${a.sev === 'high' ? 'TREND' : 'MIXED'}\">${a.sev === 'high' ? '🚨 显著异动' : '⚠️ 偏离关注'} · ${a.tag}</span>\n              <span class=\"mut sm\">查看详情 →</span>\n            </div>\n            <div style=\"font-weight:700;color:#fff;font-size:13.5px;margin-top:2px\">${a.title}</div>\n            <div style=\"color:var(--gold);font-size:12.5px;font-weight:600\">${a.val}</div>\n            <div class=\"mut sm\" style=\"font-size:11.5px;line-height:1.4\">${a.desc}</div>\n          </div>`).join('')}\n        </div>`;\n    } else {\n      $('anomalySec').innerHTML = `\n        <div style=\"display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px\">\n          <div style=\"display:flex;align-items:center;gap:10px\">\n            <span class=\"pill RANGE\">✅ 全市场无重大异动</span>\n            <span class=\"sm\">当前跨市场长周期指标(DXY/美债/白银/VIX)、各周期震荡指数单次跌幅、策略波幅边界及近4h财经日历均处于平稳区间（共 ${quietCount} 项平稳指标已自动隐藏）。</span>\n          </div>\n          <a href=\"#macroSec\" class=\"mut sm\" style=\"text-decoration:none\">查看底部跨市场备查 →</a>\n        </div>`;\n    }\n\n    // ========== 核心总览区 (`#verdict`)：三大重点 Hero Focus Cards + 极简 5 周期矩阵 ==========\n    const tfStr = ['1M', '5M', '15M', '1H', '4H'].filter((k) => adjMap[k] != null).map((k) => `${k} <b style=\"color:#fff\" class=\"num-chip ${(k === '1M' || k === '5M') ? 'fast-num' : ''}\">${adjMap[k]}</b>`).join(' · ');\n    const adjStr = (m.runAdj || []).map((a) => `${a.name} <b>${a.v >= 0 ? '+' + a.v : a.v}</b>`).join(' , ');\n\n    const runHeroCls = runLv.cls === 'RANGE' ? 'hl-green' : runLv.cls === 'MIXED' ? 'hl-yel' : 'hl-red';\n    const entryHeroCls = mainEntry && mainEntry.entryCls === 'RANGE' ? 'hl-green' : mainEntry && mainEntry.entryCls === 'MIXED' ? 'hl-yel' : 'hl-red';\n    const refTf = d.timeframes['1H'] || d.timeframes['15M'] || {};\n    const priceHeroCls = (refTf.span14 || 0) <= TOL ? 'hl-gold' : 'hl-red';\n\n    const entryPillsRow = ['1M', '5M', '15M', '1H', '4H'].map((k) => {\n      const e = eMap[k] ? eMap[k].last : null;\n      if (!e) return '';\n      const shortSt = e.entryState === 'OK' ? '🟢适合' : e.entryState === 'WAIT' ? '🟡观望' : '🔴禁入';\n      return `<a href=\"#chart-${k}\" style=\"text-decoration:none\" title=\"${k}: ${e.entryTxt} (${e.entryScore}分) - ${e.entryReason}\"><span class=\"pill ${e.entryCls}\">${k} ${shortSt}</span></a>`;\n    }).join(' ');\n\n    const tfCards = ['1M', '5M', '15M', '1H', '4H'].map((k) => {\n      const t = d.timeframes[k];\n      if (!t || adjMap[k] == null) return '';\n      const lv = lvMap[k];\n      const isFast = k === '1M' || k === '5M';\n      const inRange = t.span14 <= TOL;\n      const lastE = eMap[k] ? eMap[k].last : { entryTxt: '-', entryCls: 'MIXED', entryScore: '-', effDrop1: t.idxDrop1 || 0, effChg1: t.idxChg1 || 0 };\n      const dropWarn = (lastE.effDrop1 >= 5)\n        ? `<span class=\"err\" style=\"font-weight:600\">⚡急跌-${lastE.effDrop1}分</span>`\n        : `<span class=\"mut\">单次Δ ${(lastE.effChg1 ?? 0) >= 0 ? '+' : ''}${lastE.effChg1 ?? 0}</span>`;\n      return `<div class=\"tfcard\" id=\"tfcard-${k}\" onclick=\"location.hash='#chart-${k}'\" title=\"点击跳转到 ${k} 一图一屏大图\">\n        <div class=\"vhead\" style=\"margin-bottom:4px\">\n          <span><b style=\"color:#fff;font-size:15px\">${k}</b> ${isFast ? '<span class=\"live-dot\" title=\"每15秒实时更新\"></span>' : ''}<span class=\"mut sm\">权重${Math.round((W[k] || 0) * 100)}%</span></span>\n          <span class=\"pill ${lv.cls}\">${lv.name.replace(/\\(.*?\\)/, '')}</span>\n        </div>\n        <div style=\"display:flex;align-items:baseline;justify-content:space-between;margin:4px 0\">\n          <div><span class=\"fcscore num-chip ${isFast ? 'fast-num' : ''}\">${lk(API[k], adjMap[k])}</span> <span class=\"mut sm\">/ 100 <span style=\"font-size:11px\">(原${t.rangeIndex})</span></span></div>\n          <span class=\"pill ${lastE.entryCls}\">${lastE.entryState === 'OK' ? '🟢适合入场' : lastE.entryState === 'WAIT' ? '🟡观望' : '🔴禁入'}(${lastE.entryScore})</span>\n        </div>\n        ${idxBar(adjMap[k])}\n        <div class=\"sm\" style=\"margin-top:8px;padding-top:6px;border-top:1px solid var(--bd);display:flex;justify-content:space-between;align-items:center;color:var(--mut)\">\n          <span>14根波幅 <b style=\"color:${inRange ? '#e2e8f0' : '#fb7185'}\">${f2(t.span14)}$</b>/${f2(TOL)}$</span>\n          ${dropWarn}\n        </div>\n        <div class=\"sm mut\" style=\"margin-top:3px;display:flex;justify-content:space-between\">\n          <span>${t.trendDirText}</span>\n          <span>ADX ${t.adx} · CHOP ${t.chop}</span>\n        </div>\n      </div>`;\n    }).join('');\n\n    $('verdict').innerHTML = `\n      <div class=\"vhead\" style=\"margin-bottom:12px\">\n        <h2 style=\"margin:0\">📊 核心量化决策总览 <span class=\"mut sm\" style=\"font-weight:400\">(已按 <b>${f2(TOL)}美元</b> 策略容忍区间校准 · 短周期指数纯由黄金K线驱动)</span></h2>\n        <span class=\"pill NEUT\">主导方向: ${m.overallDirText}</span>\n      </div>\n      <div class=\"hero-grid\">\n        <div class=\"hero-box ${runHeroCls}\">\n          <div class=\"hero-lbl\"><span>① 当前实盘运行震荡指数</span><span class=\"pill ${runLv.cls}\">${runLv.name}</span></div>\n          <div class=\"hero-val\"><span>${adjRun}</span><span class=\"mut\" style=\"font-size:14px;font-weight:400\">/ 100 (技术面 ${adjCurrent})</span></div>\n          ${idxBar(adjRun)}\n          <div class=\"sm\" style=\"margin-top:8px;color:#e2e8f0;font-weight:600\">📌 结论：${runLv.advice}</div>\n          <div class=\"mut sm\" style=\"margin-top:3px\">时段/日历修正: ${adjStr || '无'} · 分周期: ${tfStr}</div>\n        </div>\n        <div class=\"hero-box ${entryHeroCls}\">\n          <div class=\"hero-lbl\"><span>② 当前网格是否适合入场</span><a href=\"#entrySec\" class=\"mut sm\" style=\"text-decoration:none\">查看时序图 →</a></div>\n          <div class=\"hero-val\" style=\"font-size:30px;margin:8px 0 10px\">\n            <span class=\"pill ${mainEntry ? mainEntry.entryCls : 'MIXED'}\" style=\"font-size:18px;padding:4px 14px;min-height:34px\">${mainEntry ? mainEntry.entryTxt : '-'} (适宜度 ${mainEntry ? mainEntry.entryScore : '-'}分)</span>\n          </div>\n          <div style=\"display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px\">${entryPillsRow}</div>\n          <div class=\"mut sm\">主周期判定依据：<b style=\"color:#cbd5e1\">${mainEntry ? mainEntry.entryReason : '-'}</b></div>\n        </div>\n        <div class=\"hero-box ${priceHeroCls}\">\n          <div class=\"hero-lbl\"><span>③ 实时金价 & ${f2(TOL)}$ 容忍边界</span><span class=\"pill ${(refTf.span14 || 0) <= TOL ? 'RANGE' : 'TREND'}\">${(refTf.span14 || 0) <= TOL ? '✅ 主周期在区间内' : '⚠️ 主周期波幅超标'}</span></div>\n          <div class=\"hero-val\"><span class=\"num-chip fast-num\" style=\"color:var(--gold)\">${f2(d.timeframes['1M'] ? d.timeframes['1M'].price : refTf.price)}$</span><span class=\"mut\" style=\"font-size:13px;font-weight:400\">XAUUSD 0延迟</span></div>\n          <div class=\"sm\" style=\"margin-top:8px;display:flex;justify-content:space-between;color:var(--mut)\">\n            <span>15M近14根波幅: <b style=\"color:${(d.timeframes['15M'] && d.timeframes['15M'].span14 <= TOL) ? '#fff' : '#fb7185'}\">${d.timeframes['15M'] ? f2(d.timeframes['15M'].span14) : '-'}$</b></span>\n            <span>1H近14根波幅: <b style=\"color:${(d.timeframes['1H'] && d.timeframes['1H'].span14 <= TOL) ? '#fff' : '#fb7185'}\">${d.timeframes['1H'] ? f2(d.timeframes['1H'].span14) : '-'}$</b></span>\n          </div>\n          <div class=\"mut sm\" style=\"margin-top:6px\">可在下方 <a href=\"#tolSec\" style=\"color:var(--gold)\">🎯 策略区间校准器</a> 随时拖动滑块切换容忍度</div>\n        </div>\n      </div>\n      <div class=\"tfidx-grid\">${tfCards}</div>`;\n\n    // 渲染「🚦 入场/离场双线指数 × 黄金 K 线 1:1 上下对照历史大图」(#entrySec)\n    const curEntTf = ENTRY_CHART_TF || '5M';\n    const curEntSpRaw = (m.sparks && m.sparks[curEntTf]) || [];\n    const curEntSer = calcEntrySeries(curEntSpRaw, TOL);\n    const curEntLast = curEntSer[curEntSer.length - 1] || { entryFast: '-', entrySlow: '-', zoneName: '-', entryTxt: '-', entryCls: 'MIXED', entryReason: '-' };\n    const filteredFakeDropCnt = curEntSer.filter((p) => p.zoneName && p.zoneName.includes('均线护航')).length;\n    const okZonePct = curEntSer.length ? Math.round(curEntSer.filter((p) => p.entryState === 'OK').length / curEntSer.length * 100) : 0;\n    const exitZonePct = curEntSer.length ? Math.round(curEntSer.filter((p) => p.entryState === 'NO').length / curEntSer.length * 100) : 0;\n\n    const entryTfBtns = ['1M', '5M', '15M', '1H', '4H'].map((k) => {\n      const spK = calcEntrySeries((m.sparks && m.sparks[k]) || [], TOL);\n      const lK = spK[spK.length - 1];\n      const badge = lK ? `${lK.entrySlow}分` : '';\n      return `<button class=\"sm ${curEntTf === k ? 'on pri' : ''}\" onclick=\"setEntryChartTf('${k}')\">${k}${k === '5M' ? '(主推)' : ''} ${badge}</button>`;\n    }).join('');\n\n    const entryRowsHtml = ['1M', '5M', '15M', '1H', '4H'].map((k) => {\n      const t = d.timeframes[k];\n      if (!t) return '';\n      const sp = calcEntrySeries((m.sparks && m.sparks[k]) || [], TOL);\n      if (!sp.length) return '';\n      const lastE = sp[sp.length - 1];\n      const okCnt = sp.filter((p) => p.entryState === 'OK').length;\n      const okPct = Math.round(okCnt / sp.length * 100);\n      const fakeCnt = sp.filter((p) => p.zoneName && p.zoneName.includes('均线护航')).length;\n      const strip = sp.map((p) => {\n        const tm = fmtBJ(p.t);\n        const hPct = Math.max(25, p.entrySlow);\n        return `<div style=\"flex:1;height:26px;display:flex;align-items:flex-end;background:#0f1218\" title=\"${tm} | ${p.zoneName} | 慢均线EMA8:${p.entrySlow}分 / 快线:${p.entryFast}分 | K线:${f2(p.c)}$\"><div style=\"width:100%;height:${hPct}%;background:${p.entryCol};opacity:0.88\"></div></div>`;\n      }).join('');\n      const fTm = fmtBJ(sp[0].t), lTm = fmtBJ(sp[sp.length - 1].t);\n      const isFast = k === '1M' || k === '5M';\n      return `<div style=\"padding:9px 12px;background:#131720;border:1px solid ${curEntTf === k ? 'var(--gold)' : 'var(--bd)'};border-radius:9px;margin-bottom:8px;cursor:pointer\" onclick=\"setEntryChartTf('${k}')\" title=\"点击在上方大图中查看 ${k} 周期 K线 × 入场双线历史对照图\">\n        <div style=\"display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:5px\">\n          <div style=\"display:flex;align-items:center;flex-wrap:wrap;gap:8px\">\n            <b>${k} 周期 ${isFast ? '<span class=\"live-dot\"></span>' : ''}</b>\n            <span class=\"pill ${lastE.entryCls}\">${lastE.zoneName} (慢均线 ${lastE.entrySlow}分 / 快线 ${lastE.entryFast}分)</span>\n            <span class=\"mut sm\">${lastE.entryReason}</span>\n          </div>\n          <div class=\"sm\" style=\"display:flex;align-items:center;flex-wrap:wrap;gap:10px\">\n            <span class=\"mut\">入场区间占比: <b style=\"color:#34d399\">${okPct}%</b> (均线过滤假跌 <b style=\"color:#38bdf8\">${fakeCnt}次</b>)</span>\n          </div>\n        </div>\n        <div style=\"display:flex;gap:1px;border-radius:5px;overflow:hidden;border:1px solid #262d3b\">${strip}</div>\n        <div style=\"display:flex;justify-content:space-between;font-size:11px;color:var(--mut);margin-top:3px\"><span>${fTm}</span><span>← 点击切换上方 K线×双线大图为 ${k} 周期 →</span><span>${lTm} (当前)</span></div>\n      </div>`;\n    }).join('');\n\n    $('entrySec').innerHTML = `\n      <div class=\"vhead\" style=\"margin-bottom:10px\">\n        <div>\n          <h2 style=\"margin:0\">🚦 入场/离场「双线平滑指数」× 黄金 K 线 1:1 历史对照大图 <span class=\"mut sm\" style=\"font-weight:400\">(亮金粗线 = EMA8决策慢均线[防假跌乱跳] · 青白实线 = 3周期抗毛刺快线 · 上下1:1对齐K线回看历史入场区与离场区)</span></h2>\n        </div>\n        <div class=\"btns\">${entryTfBtns}</div>\n      </div>\n      <div class=\"meta-strip\" style=\"margin-bottom:10px\">\n        <div class=\"mchip\"><span>当前查看周期:</span><b style=\"color:var(--gold)\">${curEntTf}</b></div>\n        <div class=\"mchip\"><span>当前所在区间:</span><span class=\"pill ${curEntLast.entryCls}\">${curEntLast.zoneName}</span></div>\n        <div class=\"mchip\"><span>🟡 慢均线(EMA8·定海神针):</span><span class=\"big-num\" style=\"color:#fbbf24\">${curEntLast.entrySlow}</span><span class=\"mut\">分</span></div>\n        <div class=\"mchip\"><span>🔵 抗毛刺快线:</span><b style=\"color:#38bdf8;font-size:16px\">${curEntLast.entryFast}</b><span class=\"mut\">分</span></div>\n        <div class=\"mchip\"><span>🛡️ 均线过滤假跌毛刺:</span><b style=\"color:#38bdf8\">${filteredFakeDropCnt} 次</b><span class=\"mut\">(快线偶发下探但均线≥55未破)</span></div>\n        <div class=\"mchip\"><span>近120根统计:</span><span style=\"color:#34d399;font-weight:700\">🟢入场区 ${okZonePct}%</span><span class=\"mut\">·</span><span style=\"color:#fb7185;font-weight:700\">🔴离场区 ${exitZonePct}%</span></div>\n      </div>\n      <div class=\"chart-wrap\">${buildEntryKLineChartSvg(curEntSpRaw, curEntTf)}</div>\n      <div class=\"legend\" style=\"justify-content:space-between;margin-bottom:10px\">\n        <div style=\"display:flex;flex-wrap:wrap;gap:14px\">\n          <span><i style=\"background:#fbbf24;height:4px\"></i><b>亮金粗实线: EMA8 慢速决策均线 (核心基准，不破 55 分不轻易离场)</b></span>\n          <span><i style=\"background:#38bdf8\"></i>青白实线: 3周期抗毛刺快线</span>\n          <span><i style=\"background:#10b981\"></i>🟢 入场区间 (≥56分：双线共振可开EA)</span>\n          <span><i style=\"background:#38bdf8\"></i>🛡️ 均线护航 (快线短暂掉下但均线≥55未破 = 假跌毛刺，拿住等回调)</span>\n          <span><i style=\"background:#f43f5e\"></i>🔴 离场区间 (&lt;46分：双线共振破位，暂停逆势加仓/锁仓)</span>\n        </div>\n        <span>🎯 鼠标在图上左右移动即可 1:1 对齐回看历史 K 线与双线入场/离场点</span>\n      </div>\n      <details class=\"clean-fold\" id=\"fold-entry-all-tfs\" ${window.OPEN_FOLDS && window.OPEN_FOLDS['fold-entry-all-tfs'] ? 'open' : ''} ontoggle=\"window.OPEN_FOLDS&&(window.OPEN_FOLDS[this.id]=this.open)\">\n        <summary>📊 点击展开/收起：1M / 5M / 15M / 1H / 4H 全周期入场区间色带一览表 (点击任意周期可切换上方大图)</summary>\n        <div style=\"margin-top:8px\">${entryRowsHtml}</div>\n      </details>`;\n\n    // 渲染 5 个周期的「一图一屏幕」大型趋势图 (顶部标签全部采用 .mchip 严格水平等高对齐 + 内置是否适合入场时序图 + 蜡烛图对比开关按钮)\n    const TF_DESC = { '1M': '1分钟超短线 (每15秒0延迟更新)', '5M': '5分钟短线 (每15秒0延迟更新)', '15M': '15分钟波段 (每15秒0延迟更新)', '1H': '1小时主周期 (每15秒0延迟更新)', '4H': '4小时大周期 (每15秒0延迟更新)' };\n    $('bigCharts').innerHTML = ['1M', '5M', '15M', '1H', '4H'].map((k) => {\n      const t = d.timeframes[k];\n      if (!t) return '';\n      const lv = lvMap[k];\n      const sp = (m.sparks && m.sparks[k]) || [];\n      const eSer = calcEntrySeries(sp, TOL);\n      const lastE = eSer[eSer.length - 1] || { entryTxt: '-', entryCls: 'MIXED', entryScore: '-', effDrop1: t.idxDrop1 || 0, effChg1: t.idxChg1 || 0 };\n      const firstT = sp.length ? fmtBJ(sp[0].t) : '-', lastT = sp.length ? fmtBJ(sp[sp.length - 1].t) : '-';\n      const isFast = k === '1M' || k === '5M';\n      const inRange = t.span14 <= TOL;\n      const showC = !!SHOW_CANDLE[k];\n      const plungeCls = (lastE.effDrop1 >= 7.5) ? 'TREND' : (lastE.effDrop1 >= 4 ? 'MIXED' : 'RANGE');\n      const plungeTxt = (lastE.effDrop1 >= 7.5) ? '🚨单次急跌巨震' : (lastE.effDrop1 >= 4 ? '⚠️指数下滑' : '✅指数平稳');\n      return `<section class=\"card screen-card\" id=\"chart-${k}\" style=\"margin-bottom:18px\">\n        <div>\n          <div class=\"vhead\">\n            <h2 style=\"margin:0;font-size:18px;display:flex;align-items:center;flex-wrap:wrap;gap:6px\">${isFast ? '<span class=\"live-dot\"></span>' : ''}<span>📈 ${k} 实时震荡指数 & 是否适合入场大图</span><span class=\"mut sm\" style=\"font-weight:400\">— ${TF_DESC[k]} · 时间: ${firstT} 至 ${lastT}</span></h2>\n            <div class=\"btns\">\n              <button class=\"sm ${showC ? 'on' : ''}\" onclick=\"toggleCandle('${k}')\">🕯️ ${showC ? '隐藏黄金K线蜡烛图+布林带' : '显示黄金K线蜡烛图+布林带'}</button>\n              <a href=\"#ind-${k}\"><button class=\"sm\">🎛️ 查看 ${k} 10项指标明细</button></a>\n              <a href=\"${API[k]}\" target=\"_blank\" rel=\"noopener\"><button class=\"sm\">🔗 验证 ${k} 原始K线</button></a>\n            </div>\n          </div>\n          <div class=\"meta-strip\">\n            <div class=\"mchip\"><span>策略(${f2(TOL)}$)震荡指数:</span><span class=\"big-num num-chip ${isFast ? 'fast-num' : ''}\">${adjMap[k]}</span><span class=\"mut\">/100 (原${t.rangeIndex})</span><span class=\"pill ${lv.cls}\">${lv.name}</span></div>\n            <div class=\"mchip\"><span>当前是否适合入场:</span><span class=\"pill ${lastE.entryCls}\">${lastE.entryTxt} (${lastE.entryScore}分)</span></div>\n            <div class=\"mchip\"><span class=\"pill ${plungeCls}\">${plungeTxt}</span><span class=\"mut\">单次Δ:</span><b>${(lastE.effChg1 ?? 0) >= 0 ? '+' : ''}${lastE.effChg1 ?? 0}分</b><span class=\"mut\">(14根最大跌 <b>-${t.maxDrop14 ?? 0}分</b>)</span></div>\n            <div class=\"mchip\"><span class=\"pill ${t.trendDir}\">${t.trendDirText}</span><span class=\"mut\">14根净涨跌:</span><b>${t.net14 >= 0 ? '+' : ''}${f2(t.net14)}$</b></div>\n            <div class=\"mchip\"><span class=\"pill ${inRange ? 'RANGE' : 'TREND'}\">${inRange ? '✅ 在合理区间内' : '⚠️ 超出合理区间'}</span><span class=\"mut\">14根波幅:</span><b>${f2(t.span14)}$ / 目标${f2(TOL)}$</b></div>\n            <div class=\"mchip\"><span class=\"mut\">最新黄金价:</span><b class=\"num-chip ${isFast ? 'fast-num' : ''}\" style=\"color:var(--gold)\">${f2(t.price)}$</b><span class=\"mut\">(${fmtBJ(t.lastBarTime)})</span></div>\n          </div>\n        </div>\n        <div class=\"chart-wrap\">${bigChartSvg(sp, k)}</div>\n        <div class=\"legend\" style=\"justify-content:space-between\">\n          <div><span><i style=\"background:#e8b84a\"></i>金色实线: 策略震荡指数</span><span style=\"margin-left:12px\"><i style=\"background:#ffffff\"></i>白色实线: 入场适宜度(0-100)</span><span style=\"margin-left:12px\"><i style=\"background:#2ecc8f\"></i>🟢适合入场(≥60)</span><span style=\"margin-left:12px\"><i style=\"background:#f0b429\"></i>🟡谨慎观望(45-60)</span><span style=\"margin-left:12px\"><i style=\"background:#ef5b5b\"></i>🔴禁止入场(&lt;45或⚡单次急跌≥7分)</span>${showC ? `<span style=\"margin-left:12px\"><i style=\"background:#58a6ff\"></i>布林带BB(20,2)</span>` : ''}</div>\n          <span>🎯 鼠标移入显示十字准星(同时对齐震荡指数、是否适合入场、单次跌幅与K线价格)</span>\n        </div>\n      </section>`;\n    }).join('');\n\n    const knn = m.knn;\n    const knnNote = knn ? `<div class=\"mut sm\" style=\"margin-top:10px;padding-top:8px;border-top:1px solid var(--bd)\">\n      🧠 <b>10年日线 kNN 历史相似行情匹配</b> (样本 ${knn.samples} 天, 截止 ${knn.lastDate}, 日线震荡指数 <b>${knn.dailyIndex}</b>):\n      在过去10年中寻找与当前7维技术特征最相似的 150 个交易日, 统计其后 1~5 天的实际震荡日比例:\n      ${knn.horizons.map((h) => `T+${h.h}天 <b>${h.p}%</b>(历史基准${h.base}%)`).join(' · ')}。<br>\n      最相似历史日期(后3天走势): ${knn.similar.map((s) => `${s.date}(${s.next3})`).join('、')}。\n      ${knn.validation ? `模型在近500天样本外回测准确率: 预测低震荡组实际震荡率 ${knn.validation.lowGroup}% vs 预测高震荡组 ${knn.validation.highGroup}%(基准 ${knn.validation.all}%)。` : ''}\n    </div>` : '';\n\n    $('forecastSec').innerHTML = `<h2>🔮 未来 5 个交易日震荡指数预测 <span class=\"mut sm\" style=\"font-weight:400\">(当前日线方向: <b>${d.timeframes['1D'] ? d.timeframes['1D'].trendDirText : m.overallDirText}</b> · 综合技术面均值回归 + 10年kNN相似行情 + 波动率挤压释放 + GVZ + 金十日历冲击)</span></h2>\n      <div class=\"fcgrid\">${m.forecast.map((f) => {\n        const p = f.parts;\n        const fLv = levelFor(f.index, m.overallDir);\n        const evHtml = f.events.length ? f.events.map((e) => `<div>• ${e.time.slice(5, 16)} ${e.country} ${'★'.repeat(e.star)} ${e.title} <span class=\"err\">(-${e.p})</span></div>`).join('') : '<div>• 无重大高危事件</div>';\n        return `<div class=\"fccard\">\n          <div class=\"fchead\"><div><b>${f.label}</b> <span class=\"mut sm\">${f.date.slice(5)}</span></div><span class=\"pill ${fLv.cls}\">${fLv.name}</span></div>\n          <div><span class=\"fcscore\">${f.index}</span> <span class=\"mut sm\">/ 100</span>${idxBar(f.index)}</div>\n          <div class=\"sm\" style=\"font-weight:600\">${fLv.advice}</div>\n          <div class=\"fcparts\">\n            <span>技术延续: <b>${p.tech}</b></span>\n            <span>kNN相似: <b>${p.knn ?? '-'}</b>${p.knnP != null ? `(${p.knnP}%)` : ''}</span>\n            <span>挤压扣分: <b class=\"${p.squeeze < 0 ? 'err' : ''}\">${p.squeeze}</b></span>\n            <span>GVZ修正: <b>${p.gvz >= 0 ? '+' + p.gvz : p.gvz}</b></span>\n            <span style=\"grid-column:1/-1\">日历事件冲击: <b class=\"${p.events < 0 ? 'err' : ''}\">${p.events}</b></span>\n          </div>\n          <div class=\"fcevs\"><div style=\"margin-bottom:2px;color:var(--tx)\">主要风险事件:</div>${evHtml}</div>\n        </div>`;\n      }).join('')}</div>${knnNote}`;\n  }\n\n  // 渲染「🎯 关键清算位与整数关口“插针雷区”地图」(昨日高低点 PDH/PDL、今日亚盘高低点 Asian High/Low、今日高低点 HOD/LOD、$50/$10 整数关口)\n  const klv = d.keyLevels;\n  if ($('keyLevelsSec')) {\n    if (klv && Array.isArray(klv.levels) && klv.levels.length) {\n      if ($('nav-klv')) {\n        $('nav-klv').textContent = klv.dangerCount ? `${klv.dangerCount}雷区` : '安全';\n        $('nav-klv').className = 'pill ' + (klv.dangerCount ? 'TREND' : klv.statusCls || 'RANGE');\n      }\n      const upLevels = klv.levels.filter((x) => x.diff >= 0).sort((a, b) => a.absDiff - b.absDiff); // 从近到远排列上方阻力\n      const dnLevels = klv.levels.filter((x) => x.diff < 0).sort((a, b) => a.absDiff - b.absDiff);  // 从近到远排列下方支撑\n\n      const renderLvRow = (lv, isUp) => {\n        const badgeCls = lv.danger === 'DANGER' ? 'TREND' : lv.danger === 'WARN' ? 'MIXED' : 'RANGE';\n        const badgeTxt = lv.danger === 'DANGER' ? '🚨 贴脸雷区(≤2.2$)' : lv.danger === 'WARN' ? '⚠️ 临近警戒(≤4.5$)' : '🟢 安全距离';\n        const barPct = Math.max(6, Math.min(100, Math.round((1 - Math.min(lv.absDiff, 25) / 25) * 100)));\n        const col = lv.danger === 'DANGER' ? '#f43f5e' : lv.danger === 'WARN' ? '#f59e0b' : (isUp ? '#fb7185' : '#34d399');\n        return `<div style=\"padding:8px 10px;border-radius:8px;background:${lv.danger === 'DANGER' ? 'rgba(244,63,94,0.16)' : 'rgba(15,20,30,0.85)'};border:1px solid ${lv.danger === 'DANGER' ? '#f43f5e' : 'var(--bd)'};margin-bottom:7px\">\n          <div style=\"display:flex;justify-content:space-between;align-items:center;gap:6px;flex-wrap:wrap\">\n            <div>\n              <b style=\"color:#fff;font-size:13px\">${lv.name}</b>\n              <span class=\"pill NEUT\" style=\"padding:1px 6px;font-size:10.5px;margin-left:4px\">${lv.tag}</span>\n            </div>\n            <div style=\"display:flex;align-items:center;gap:8px\">\n              <b style=\"font-size:14.5px;color:var(--gold)\">$${f2(lv.price)}</b>\n              <span style=\"font-weight:800;font-size:12.5px;color:${isUp ? '#fb7185' : '#34d399'}\">${isUp ? '+' : ''}${f2(lv.diff)}$ (${lv.pts}点)</span>\n              <span class=\"pill ${badgeCls}\" style=\"padding:1px 7px;font-size:11px\">${badgeTxt}</span>\n            </div>\n          </div>\n          <div style=\"height:5px;background:#1a2232;border-radius:99px;margin:6px 0 4px;overflow:hidden\">\n            <div style=\"width:${barPct}%;height:100%;background:${col};border-radius:99px\"></div>\n          </div>\n          <div class=\"xs mut\">${lv.desc}</div>\n        </div>`;\n      };\n\n      $('keyLevelsSec').innerHTML = `\n        <div class=\"vhead\" style=\"margin-bottom:10px\">\n          <div>\n            <h2 style=\"margin:0\">🎯 关键清算位与整数关口「插针雷区」地图 <span class=\"mut sm\" style=\"font-weight:400\">(昨日高低点 PDH/PDL · 今日亚盘高低点 Asian High/Low · 今日高低点 HOD/LOD · $50/$10 整数生死线)</span></h2>\n          </div>\n          <span class=\"pill ${klv.statusCls}\" style=\"font-size:12px\">当前现价: $${f2(klv.curPrice)} · ${klv.dangerCount ? `🚨 ${klv.dangerCount}个清算池贴脸` : '🟢 处于真空安全带'}</span>\n        </div>\n        <div style=\"padding:10px 14px;border-radius:9px;margin-bottom:12px;background:${klv.statusCls === 'TREND' ? 'rgba(244,63,94,0.16)' : klv.statusCls === 'MIXED' ? 'rgba(245,158,11,0.14)' : 'rgba(16,185,129,0.12)'};border:1px solid ${klv.statusCls === 'TREND' ? '#f43f5e' : klv.statusCls === 'MIXED' ? '#f59e0b' : 'rgba(16,185,129,0.4)'};font-size:13px;font-weight:700;color:#fff\">\n          ${klv.headline}\n        </div>\n        <div class=\"grid2\" style=\"gap:12px\">\n          <div>\n            <div style=\"font-size:12.5px;font-weight:800;color:#fb7185;margin-bottom:8px;display:flex;justify-content:space-between\">\n              <span>📈 上方空头止损池 & 突破加速雷区 (按距现价由近到远)</span>\n              <span class=\"xs mut\">触及易向上扫损插针，防逆势死加空单(Sell)</span>\n            </div>\n            ${upLevels.length ? upLevels.map((x) => renderLvRow(x, true)).join('') : '<div class=\"mut sm\">上方暂无邻近阻力数据</div>'}\n          </div>\n          <div>\n            <div style=\"font-size:12.5px;font-weight:800;color:#34d399;margin-bottom:8px;display:flex;justify-content:space-between\">\n              <span>📉 下方多头止损池 & 破位下杀雷区 (按距现价由近到远)</span>\n              <span class=\"xs mut\">跌破易向下踩踏插针，防逆势死加多单(Buy)</span>\n            </div>\n            ${dnLevels.length ? dnLevels.map((x) => renderLvRow(x, false)).join('') : '<div class=\"mut sm\">下方暂无邻近支撑数据</div>'}\n          </div>\n        </div>`;\n    } else {\n      $('keyLevelsSec').innerHTML = `<h2>🎯 关键清算位与整数关口「插针雷区」地图</h2><span class=\"mut\">正在计算 PDH/PDL、亚盘高低点与整数关口清算位...</span>`;\n    }\n  }\n\n  // 渲染「📊 黄金散户反指效应指标」(全市场散户账户多空比 vs 大户持仓多空比 vs 15M主动吃单买卖比 vs 沪金主动买盘)\n  const sent = d.sentiment;\n  if ($('sentimentSec')) {\n    if (sent && sent.retailLongPct != null) {\n      if ($('nav-sent')) {\n        $('nav-sent').textContent = `多${sent.retailLongPct}%`;\n        $('nav-sent').className = 'pill ' + (sent.cls || 'NEUT');\n      }\n      const histBars = (sent.history && sent.history.length)\n        ? sent.history.map((h) => {\n            const col = h.longPct >= 72 ? '#f43f5e' : h.longPct >= 62 ? '#f59e0b' : '#10b981';\n            return `<div style=\"flex:1;display:flex;flex-direction:column;align-items:center;gap:2px\" title=\"${fmtBJ(h.t)} 散户做多占比 ${h.longPct}% (${h.ratio}:1)\">\n              <div style=\"width:100%;height:34px;background:#1a2232;border-radius:4px;display:flex;align-items:flex-end;overflow:hidden\">\n                <div style=\"width:100%;height:${Math.max(15, Math.min(100, h.longPct))}%;background:${col}\"></div>\n              </div>\n              <span class=\"xs mut\" style=\"font-size:9.5px\">${fmtBJ(h.t).slice(0, 5)}</span>\n            </div>`;\n          }).join('')\n        : '';\n\n      $('sentimentSec').innerHTML = `\n        <div class=\"vhead\" style=\"margin-bottom:10px\">\n          <div>\n            <h2 style=\"margin:0\">📊 黄金散户反指效应指标 (Retail Sentiment Contrarian Index) <span class=\"mut sm\" style=\"font-weight:400\">(核心规律：当散户单边多头 &ge;72% 时主力极易向下逼多洗盘；当散户空头 &ge;68% 时主力极易向上无回调逼空)</span></h2>\n          </div>\n          <div class=\"btns\">\n            <a href=\"${(sent.urls && sent.urls.globalAcc) || '#'}\" target=\"_blank\" rel=\"noopener\"><button class=\"sm\">🔗 验证全市场散户多空比</button></a>\n            <a href=\"${(sent.urls && sent.urls.topPos) || '#'}\" target=\"_blank\" rel=\"noopener\"><button class=\"sm\">🔗 验证大户持仓比</button></a>\n            <a href=\"${(sent.urls && sent.urls.taker) || '#'}\" target=\"_blank\" rel=\"noopener\"><button class=\"sm\">🔗 验证15M主动吃单比</button></a>\n          </div>\n        </div>\n        <div style=\"background:linear-gradient(90deg,rgba(244,63,94,.14),rgba(15,23,42,.92));border:1px solid rgba(244,63,94,.4);border-radius:10px;padding:12px 14px;margin-bottom:12px\">\n          <div style=\"display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:8px\">\n            <div style=\"display:flex;align-items:center;gap:10px;flex-wrap:wrap\">\n              <span class=\"pill ${sent.cls}\" style=\"font-size:13px;padding:4px 11px;font-weight:800\">${sent.signal}</span>\n              <span class=\"sm mut\">散户多空人数比: <b style=\"color:#fff\">${sent.retailRatio} : 1</b> (近3h多头占比变化 <b style=\"color:${sent.retailChg3h >= 0 ? '#34d399' : '#fb7185'}\">${sent.retailChg3h >= 0 ? '+' : ''}${sent.retailChg3h}%</b>)</span>\n            </div>\n            <span class=\"pill ${sent.riskScore >= 70 ? 'TREND' : sent.riskScore >= 55 ? 'MIXED' : 'RANGE'}\">反指挤压风险分: ${sent.riskScore}/100</span>\n          </div>\n          <div style=\"margin:8px 0\">\n            <div style=\"display:flex;justify-content:space-between;font-size:12.5px;font-weight:800;margin-bottom:4px\">\n              <span style=\"color:#34d399\">🐂 散户做多账户占比: ${sent.retailLongPct}% ${sent.retailLongPct >= 70 ? '(🚨 极度拥挤·防向下逼多)' : ''}</span>\n              <span style=\"color:#fb7185\">🐻 散户做空账户占比: ${sent.retailShortPct}% ${sent.retailShortPct >= 65 ? '(🚨 极度拥挤·防向上逼空)' : ''}</span>\n            </div>\n            <div style=\"height:14px;width:100%;background:#fb7185;border-radius:99px;overflow:hidden;display:flex;position:relative;border:1px solid rgba(255,255,255,0.15)\">\n              <div style=\"width:${sent.retailLongPct}%;height:100%;background:linear-gradient(90deg,#059669,#34d399)\"></div>\n              <div style=\"position:absolute;left:50%;top:0;bottom:0;width:2px;background:rgba(255,255,255,0.7)\" title=\"50% 多空均衡中轴线\"></div>\n              <div style=\"position:absolute;left:72%;top:0;bottom:0;width:2px;background:#f43f5e\" title=\"72% 散户多头极端反指警戒线\"></div>\n            </div>\n          </div>\n          <div style=\"margin-top:8px;padding:8px 12px;background:rgba(15,20,30,0.85);border-left:3px solid var(--gold);border-radius:6px;font-size:12.5px;line-height:1.55\">\n            <b style=\"color:var(--gold)\">🧭 散户反指对 M1 双向马丁 EA 的实盘指令：</b> ${sent.eaAdvice}\n          </div>\n        </div>\n        <div class=\"tfidx-grid\">\n          <div class=\"tfcard\" style=\"cursor:default\">\n            <div class=\"vhead\"><span><b>👥 全市场散户账户多空比</b></span><span class=\"pill ${sent.retailLongPct >= 72 || sent.retailShortPct >= 68 ? 'TREND' : 'MIXED'}\">反指核心基准</span></div>\n            <div style=\"margin:4px 0\"><span class=\"fcscore\">${sent.retailLongPct}% 多</span> <span class=\"mut sm\">/ ${sent.retailShortPct}% 空 (${sent.retailRatio}:1)</span></div>\n            <div style=\"display:flex;gap:3px;align-items:flex-end;margin-top:6px\">${histBars}</div>\n            <div class=\"xs mut\" style=\"margin-top:4px\">近3小时(12根15M)散户做多人数占比走势 · 散户越一致单边死扛，反指胜率越高</div>\n          </div>\n          <div class=\"tfcard\" style=\"cursor:default\">\n            <div class=\"vhead\"><span><b>🐋 顶级大户/机构持仓量多空比</b></span><span class=\"pill NEUT\">聪明钱对照</span></div>\n            <div style=\"margin:4px 0\"><span class=\"fcscore\">${sent.whaleLongPct}% 多</span> <span class=\"mut sm\">/ ${sent.whaleShortPct}% 空 (${sent.whaleRatio}:1)</span></div>\n            <div class=\"sm\" style=\"margin-top:6px\">散户-大户看多差值: <b style=\"color:${Math.abs(sent.retailWhaleDiff) >= 5 ? 'var(--gold)' : 'var(--tx)'}\">${sent.retailWhaleDiff >= 0 ? '+' : ''}${sent.retailWhaleDiff}%</b></div>\n            <div class=\"xs mut\" style=\"margin-top:4px\">对比散户人数比与大户真金白银持仓量比，识别散户是否在逆势接飞刀</div>\n          </div>\n          <div class=\"tfcard\" style=\"cursor:default\">\n            <div class=\"vhead\"><span><b>⚡ 15M 主动吃单买卖比 (Taker)</b></span><span class=\"pill ${sent.takerBuyPct >= 55 || sent.takerBuyPct <= 45 ? 'MIXED' : 'RANGE'}\">真金白银方向</span></div>\n            <div style=\"margin:4px 0\"><span class=\"fcscore\">${sent.takerBuyPct}%</span> <span class=\"mut sm\">市价主动买盘占比 (买卖比 <b>${sent.takerBuyRatio}</b>)</span></div>\n            <div class=\"sm\" style=\"margin-top:6px\">近1小时平均主动买卖比: <b>${sent.takerAvg1hRatio}</b> | 沪金外盘主动买盘: <b>${sent.shfeActiveBuyPct}%</b></div>\n            <div class=\"xs mut\" style=\"margin-top:4px\">若散户75%重仓做多，但主动吃单买盘 &lt;45%（全在市价砸盘），说明主力正在砸盘逼多！</div>\n          </div>\n        </div>`;\n    } else {\n      $('sentimentSec').innerHTML = `<h2>📊 黄金散户反指效应指标</h2><span class=\"mut\">正在加载全球散户多空持仓比与主动吃单数据...</span>`;\n    }\n  }\n\n  // 渲染「🔥 黄金受关注度综合指数」：汇总 COMEX期货量比 + 国内沪金主连量比/成交额 + 7x24快讯黄金密度 + SPDR GLD机构量比 + 全球百科搜索 & 链上黄金热度\n  const attn = d.attention;\n  if ($('attentionSec')) {\n    if (attn && attn.score != null) {\n      const aCls = attn.score >= 72 ? 'TREND' : attn.score >= 52 ? 'MIXED' : 'RANGE';\n      if ($('nav-attn')) {\n        $('nav-attn').textContent = `${attn.score}分`;\n        $('nav-attn').className = 'pill ' + aCls;\n      }\n      const cmx = attn.comex || {};\n      const sh = attn.shfe || {};\n      const nw = attn.news || {};\n      const gld = attn.gld || {};\n      const cr = attn.globalHeat || attn.crowd || {};\n      const hotNewsHtml = (nw.hotItems && nw.hotItems.length)\n        ? `<div class=\"thin-scroll\" style=\"margin-top:8px;max-height:115px;overflow-y:auto;padding-right:4px;border-top:1px dashed var(--bd);padding-top:6px;font-size:11.5px;display:flex;flex-direction:column;gap:4px\">\n            ${nw.hotItems.map((it) => `<div style=\"display:flex;gap:6px;align-items:baseline;line-height:1.4\">\n              <span class=\"mut xs\" style=\"flex-shrink:0\">${fmtBJ(it.time)}</span>\n              ${(it.score || it.imp || 1) >= 2 ? '<span class=\"pill TREND\" style=\"padding:0 5px;font-size:10px\">重磅</span>' : ''}\n              <a href=\"${it.uri || '#'}\" target=\"_blank\" rel=\"noopener\" style=\"color:${(it.score || it.imp || 1) >= 2 ? '#fda4af' : 'var(--tx)'};text-decoration:none\">${it.title ? '<b>' + it.title + '</b> ' : ''}${(it.text || '').slice(0, 110)}${(it.text || '').length > 110 ? '...' : ''}</a>\n            </div>`).join('')}\n          </div>`\n        : '';\n\n      $('attentionSec').innerHTML = `\n        <div class=\"vhead\" style=\"margin-bottom:10px\">\n          <div>\n            <h2 style=\"margin:0\">🔥 全球黄金受关注度综合指数 (Gold Attention & Crowd Heat Index) <span class=\"mut sm\" style=\"font-weight:400\">(5大维度实时汇总：COMEX主力期货量比 25% + 国内沪金散户量比 25% + 7×24全球快讯提及密度 25% + SPDR GLD机构ETF 15% + 全球搜索与链上黄金 10%)</span></h2>\n          </div>\n          <div class=\"btns\">\n            <a href=\"${sh.webUrl || sh.url || 'https://quote.eastmoney.com/qihuo/aum.html'}\" target=\"_blank\" rel=\"noopener\"><button class=\"sm\">🔗 验证沪金主力 (SHFE AU)</button></a>\n            <a href=\"${cmx.webUrl || cmx.url || 'https://finance.yahoo.com/quote/GC=F'}\" target=\"_blank\" rel=\"noopener\"><button class=\"sm\">🔗 验证 COMEX 黄金期货</button></a>\n            <a href=\"${gld.webUrl || gld.url || 'https://finance.yahoo.com/quote/GLD'}\" target=\"_blank\" rel=\"noopener\"><button class=\"sm\">🔗 验证 SPDR GLD ETF</button></a>\n            <a href=\"${cr.wikiUrl || '#'}\" target=\"_blank\" rel=\"noopener\"><button class=\"sm\">🔗 验证 Wiki 搜索量</button></a>\n          </div>\n        </div>\n        <div style=\"background:linear-gradient(90deg,rgba(245,158,11,.13),rgba(15,23,42,.9));border:1px solid rgba(245,158,11,.4);border-radius:10px;padding:12px 14px;margin-bottom:12px;display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px\">\n          <div style=\"display:flex;align-items:center;gap:14px;flex-wrap:wrap\">\n            <div>\n              <div class=\"xs mut\">黄金实时受关注度总分</div>\n              <div style=\"display:flex;align-items:baseline;gap:8px\">\n                <span style=\"font-size:32px;font-weight:900;color:var(--gold);line-height:1.1\">${attn.score}</span>\n                <span class=\"mut sm\">/ 100</span>\n                <span class=\"pill ${aCls}\" style=\"font-size:12.5px;padding:3px 10px\">${attn.level}</span>\n              </div>\n            </div>\n            <div style=\"min-width:180px;max-width:260px;flex:1\">\n              ${idxBar(100 - attn.score)}\n              <div class=\"xs mut\" style=\"margin-top:4px\">注：关注度越高(右端红区)代表资金与舆情越拥挤，越易爆发单边行情；关注度温和(左端绿区)更利好双向马丁刷单</div>\n            </div>\n          </div>\n          <div style=\"flex:1;min-width:280px;background:rgba(15,20,30,.85);border-left:3px solid var(--gold);padding:8px 12px;border-radius:6px;font-size:12.5px;line-height:1.55\">\n            <div style=\"font-weight:700;color:var(--gold);margin-bottom:2px\">🧭 关注度对 M1 双向马丁 EA 的实盘启示：</div>\n            <div>${attn.eaTip}</div>\n          </div>\n        </div>\n        <div class=\"tfidx-grid\">\n          <div class=\"tfcard\" style=\"cursor:default\">\n            <div class=\"vhead\"><span><b>🏛️ COMEX 黄金期货主力 (GC=F)</b></span><span class=\"pill ${(cmx.volRatio || 1) >= 1.45 ? 'TREND' : (cmx.volRatio || 1) >= 1.1 ? 'MIXED' : 'RANGE'}\">权重 25% · 得分 ${cmx.score ?? '-'}/100</span></div>\n            <div style=\"margin:4px 0\"><span class=\"fcscore\">${cmx.volRatio != null ? cmx.volRatio + 'x' : '-'}</span> <span class=\"mut sm\">实时小时量比 (5日分位 <b>${cmx.volPct ?? '-'}%</b>)</span></div>\n            <div class=\"sm\" style=\"margin-top:4px\">近4h平均成交: <b>${cmx.last4hAvg != null ? cmx.last4hAvg.toLocaleString() : '-'} 手/h</b> | 5日小时均量: <b>${cmx.avg5d != null ? cmx.avg5d.toLocaleString() : '-'} 手/h</b></div>\n            <div class=\"sm mut\" style=\"margin-top:3px\">衡量华尔街主力期货交投拥挤度（量比 &ge;1.45x 往往伴随单边破位）</div>\n          </div>\n          <div class=\"tfcard\" style=\"cursor:default\">\n            <div class=\"vhead\"><span><b>🇨🇳 国内沪金主连 (SHFE AU)</b></span><span class=\"pill ${(sh.volRatio || 1) >= 1.4 ? 'TREND' : (sh.volRatio || 1) >= 1.05 ? 'MIXED' : 'RANGE'}\">权重 25% · 得分 ${sh.score ?? '-'}/100</span></div>\n            <div style=\"margin:4px 0\"><span class=\"fcscore\">${sh.volRatio != null ? sh.volRatio + 'x' : '-'}</span> <span class=\"mut sm\">实时量比 · 日成交额 <b>${sh.turnoverBillion ?? '-'} 亿元</b></span></div>\n            <div class=\"sm\" style=\"margin-top:4px\">日成交量: <b>${sh.vol != null ? sh.vol.toLocaleString() : '-'} 手</b> | 持仓量: <b>${sh.openInterest != null ? sh.openInterest.toLocaleString() : '-'} 手</b></div>\n            <div class=\"sm mut\" style=\"margin-top:3px\">外盘主动买盘占比: <b style=\"color:${(sh.activeBuyPct || 50) >= 53 ? '#34d399' : (sh.activeBuyPct || 50) <= 47 ? '#fb7185' : 'var(--tx)'}\">${sh.activeBuyPct ?? '-'}%</b> · 衡量国内散户与内盘资金追捧热度</div>\n          </div>\n          <div class=\"tfcard\" style=\"cursor:default\">\n            <div class=\"vhead\"><span><b>📰 7×24 全球财经快讯「黄金」密度</b></span><span class=\"pill ${(nw.count1h || 0) >= 5 ? 'TREND' : (nw.count1h || 0) >= 2 ? 'MIXED' : 'RANGE'}\">权重 25% · 得分 ${nw.score ?? '-'}/100</span></div>\n            <div style=\"margin:4px 0\"><span class=\"fcscore\">${nw.count1h ?? 0} 条/1h</span> <span class=\"mut sm\">近4h <b>${nw.count4h ?? 0}条</b> · 近24h <b>${nw.count24h ?? 0}条</b></span></div>\n            <div class=\"sm\" style=\"margin-top:4px\">24h加红重磅涉金快讯: <b style=\"color:#fb7185\">${nw.imp24h ?? 0} 条</b></div>\n            ${hotNewsHtml || '<div class=\"sm mut\" style=\"margin-top:4px\">实时扫描华尔街见闻/金十全球快讯中提及「黄金/金价/XAU/央行购金」的突发频率</div>'}\n          </div>\n          <div class=\"tfcard\" style=\"cursor:default\">\n            <div class=\"vhead\"><span><b>🏦 全球最大黄金ETF (SPDR GLD)</b></span><span class=\"pill ${(gld.volRatio || 1) >= 1.35 ? 'TREND' : (gld.volRatio || 1) >= 1.0 ? 'MIXED' : 'RANGE'}\">权重 15% · 得分 ${gld.score ?? '-'}/100</span></div>\n            <div style=\"margin:4px 0\"><span class=\"fcscore\">${gld.volRatio != null ? gld.volRatio + 'x' : '-'}</span> <span class=\"mut sm\">机构日量比 (3个月分位 <b>${gld.volPct ?? '-'}%</b>)</span></div>\n            <div class=\"sm\" style=\"margin-top:4px\">最新成交: <b>${gld.lastVol != null ? (gld.lastVol / 1e6).toFixed(2) + 'M 股' : '-'}</b> | 20日均量: <b>${gld.avg20d != null ? (gld.avg20d / 1e6).toFixed(2) + 'M 股' : '-'}</b></div>\n            <div class=\"sm mut\" style=\"margin-top:3px\">衡量欧美机构与长线配置资金对黄金的交投关注度</div>\n          </div>\n          <div class=\"tfcard\" style=\"cursor:default\">\n            <div class=\"vhead\"><span><b>🌍 全球搜索 & 链上黄金 (PAXG+XAUT)</b></span><span class=\"pill ${(cr.score || 50) >= 70 ? 'TREND' : (cr.score || 50) >= 48 ? 'MIXED' : 'RANGE'}\">权重 10% · 得分 ${cr.score ?? '-'}/100</span></div>\n            <div style=\"margin:4px 0\"><span class=\"fcscore\">$${cr.onchainVolM ?? '-'}M</span> <span class=\"mut sm\">链上黄金 24h 真实成交额</span></div>\n            <div class=\"sm\" style=\"margin-top:4px\">Wikipedia「Gold」全球日浏览: <b>${cr.wikiViews != null ? cr.wikiViews.toLocaleString() : '-'} 次</b> (量比 <b>${cr.wikiRatio ?? '-'}x</b> · 30日分位 <b>${cr.wikiPct ?? '-'}%</b>)</div>\n            <div class=\"sm mut\" style=\"margin-top:3px\">7×24不休市的加密黄金代币(PAXG+XAUT)成交额 + 全球公众百科搜索分位</div>\n          </div>\n        </div>`;\n    } else {\n      $('attentionSec').innerHTML = `<h2>🔥 全球黄金受关注度综合指数</h2><span class=\"mut\">正在汇总 COMEX / 沪金主连 / 7×24快讯 / SPDR GLD / 链上黄金关注度数据...</span>`;\n    }\n  }\n\n  // 渲染「🌐 跨市场长周期先行指数备查区」：仅直接展示当前有显著异动的跨市场指标，平稳指标默认折叠收纳\n  const mc = d.macro;\n  if (mc && mc.dxy) {\n    const dxy = mc.dxy || {};\n    const us10 = mc.us10y || {};\n    const us2 = mc.us2y || {};\n    const xag = mc.xag || {};\n    const vix = mc.vix || {};\n    const autd = mc.autd || {};\n    const uReal = mc.realUrl;\n    const uDxy = mc.dxyKlineUrl;\n\n    const fmtChg = (o) => o && o.chgPct != null ? `<span style=\"color:${o.chgPct >= 0 ? '#34d399' : '#fb7185'};font-weight:600;font-size:12px\">${o.chgPct >= 0 ? '+' : ''}${f2(o.chgPct)}% (${o.chg >= 0 ? '+' : ''}${f2(o.chg)})</span>` : '-';\n\n    const macroCards = [\n      {\n        isAnom: (mc.dxyAdx != null && mc.dxyAdx >= 25) || Math.abs(dxy.chgPct || 0) >= 0.45 || (mc.corrXauDxy != null && mc.corrXauDxy >= 0.35),\n        html: `<div class=\"tfcard\" style=\"cursor:default\">\n          <div class=\"vhead\"><span><b>💵 美元指数 (DXY)</b> <span class=\"mut sm\">${dxy.time ? fmtBJ(dxy.time) : ''}</span></span><span class=\"pill ${(mc.dxyAdx || 0) >= 25 ? 'TREND' : 'NEUT'}\">${(mc.dxyAdx || 0) >= 25 ? '⚠️ 美元单边' : '平稳震荡'}</span></div>\n          <div><span class=\"fcscore\">${lk(uReal, f2(dxy.last))}</span> ${fmtChg(dxy)}</div>\n          <div class=\"sm\" style=\"margin-top:6px\">15M ADX趋势强度: <b>${lk(uDxy, f2(mc.dxyAdx))}</b> <span class=\"mut\">(${(mc.dxyAdx || 0) < 20 ? '盘整' : '趋势强劲'})</span></div>\n          <div class=\"sm\" style=\"margin-top:4px\">金-美20根相关性 r: <b style=\"color:${(mc.corrXauDxy || 0) > 0.3 ? '#fb7185' : '#e2e8f0'}\">${mc.corrXauDxy != null ? f2(mc.corrXauDxy) : '-'}</b> <span class=\"mut\">(${(mc.corrXauDxy || 0) < -0.3 ? '正常负相关' : (mc.corrXauDxy || 0) > 0.3 ? '⚠️同涨避险' : '弱相关'})</span></div>\n        </div>`\n      },\n      {\n        isAnom: Math.abs(us10.chgPct || 0) >= 1.5,\n        html: `<div class=\"tfcard\" style=\"cursor:default\">\n          <div class=\"vhead\"><span><b>🏛️ 美债收益率 (10Y / 2Y)</b></span><span class=\"pill ${Math.abs(us10.chgPct || 0) >= 1.5 ? 'TREND' : 'NEUT'}\">${Math.abs(us10.chgPct || 0) >= 1.5 ? '⚠️ 利率异动' : '利率平稳'}</span></div>\n          <div><span class=\"fcscore\">${lk(uReal, f2(us10.last) + '%')}</span> ${fmtChg(us10)}</div>\n          <div class=\"sm\" style=\"margin-top:6px\">2年期美债(US02Y): <b>${lk(uReal, f2(us2.last) + '%')}</b> (${us2.chgPct >= 0 ? '+' : ''}${f2(us2.chgPct)}%)</div>\n          <div class=\"sm\" style=\"margin-top:4px\">10Y-2Y 期限利差: <b>${mc.yieldSpread != null ? (mc.yieldSpread >= 0 ? '+' : '') + f2(mc.yieldSpread) + 'bp' : '-'}</b> <span class=\"mut\">(定价锚)</span></div>\n        </div>`\n      },\n      {\n        isAnom: mc.agLead != null && Math.abs(mc.agLead) >= 0.8,\n        html: `<div class=\"tfcard\" style=\"cursor:default\">\n          <div class=\"vhead\"><span><b>🥈 现货白银 & 金银比</b></span><span class=\"pill ${Math.abs(mc.agLead || 0) >= 0.8 ? 'MIXED' : 'NEUT'}\">${Math.abs(mc.agLead || 0) >= 0.8 ? '⚠️ 白银领涨跌' : '金银同步'}</span></div>\n          <div><span class=\"fcscore\">${lk(uReal, f2(xag.last) + '$')}</span> ${fmtChg(xag)}</div>\n          <div class=\"sm\" style=\"margin-top:6px\">实时金银比 (XAU/XAG): <b>${lk(uReal, f2(mc.gsr))}</b></div>\n          <div class=\"sm\" style=\"margin-top:4px\">银-金日内强弱差: <b style=\"color:${Math.abs(mc.agLead || 0) >= 0.8 ? '#fbbf24' : '#e2e8f0'}\">${mc.agLead != null ? (mc.agLead >= 0 ? '+' : '') + f2(mc.agLead) + '%' : '-'}</b></div>\n        </div>`\n      },\n      {\n        isAnom: (vix.last || 0) >= 22 || Math.abs(vix.chgPct || 0) >= 8,\n        html: `<div class=\"tfcard\" style=\"cursor:default\">\n          <div class=\"vhead\"><span><b>⚡ VIX 恐慌指数</b></span><span class=\"pill ${(vix.last || 0) >= 22 ? 'TREND' : 'NEUT'}\">${(vix.last || 0) >= 22 ? '⚠️ 市场恐慌' : '情绪温和'}</span></div>\n          <div><span class=\"fcscore\">${lk(uReal, f2(vix.last))}</span> ${fmtChg(vix)}</div>\n          <div class=\"sm\" style=\"margin-top:6px\">日内区间: <b>${f2(vix.low)} ~ ${f2(vix.high)}</b></div>\n          <div class=\"sm mut\" style=\"margin-top:4px\">VIX &lt; 20 利好黄金技术面震荡</div>\n        </div>`\n      },\n      {\n        isAnom: Math.abs(autd.chgPct || 0) >= 1.2,\n        html: `<div class=\"tfcard\" style=\"cursor:default\">\n          <div class=\"vhead\"><span><b>🇨🇳 上海黄金TD (AUTD)</b></span><span class=\"pill NEUT\">内盘联动</span></div>\n          <div><span class=\"fcscore\">${lk(uReal, f2(autd.last) + '元')}</span> ${fmtChg(autd)}</div>\n          <div class=\"sm\" style=\"margin-top:6px\">日内区间: <b>${f2(autd.low)} ~ ${f2(autd.high)} 元/克</b></div>\n          <div class=\"sm mut\" style=\"margin-top:4px\">亚盘时段内盘资金参考</div>\n        </div>`\n      }\n    ];\n\n    const anomMacro = macroCards.filter((c) => c.isAnom);\n    const calmMacro = macroCards.filter((c) => !c.isAnom);\n\n    if ($('nav-macro')) {\n      $('nav-macro').textContent = anomMacro.length ? `${anomMacro.length}异动` : '平稳';\n      $('nav-macro').className = 'pill ' + (anomMacro.length ? 'MIXED' : 'NEUT');\n    }\n\n    $('macroSec').innerHTML = `\n      <div class=\"vhead\">\n        <h2 style=\"margin:0\">🌐 跨市场长周期先行指标 <span class=\"mut sm\" style=\"font-weight:400\">(不计入短周期震荡指数 · 异动较大的指标已同步提取至顶部【⚡ 实时异动监控区】)</span></h2>\n        <div class=\"btns\">\n          <a href=\"${uReal}\" target=\"_blank\" rel=\"noopener\"><button class=\"sm\">🔗 验证跨市场 JSON</button></a>\n          <a href=\"${uDxy}\" target=\"_blank\" rel=\"noopener\"><button class=\"sm\">🔗 验证 DXY K线</button></a>\n        </div>\n      </div>\n      ${anomMacro.length ? `<div class=\"tfidx-grid\" style=\"margin-bottom:10px\">${anomMacro.map((c) => c.html).join('')}</div>` : ''}\n      ${calmMacro.length ? `<details class=\"clean-fold\" id=\"fold-macro-calm\" ${window.OPEN_FOLDS && window.OPEN_FOLDS['fold-macro-calm'] ? 'open' : ''} ontoggle=\"window.OPEN_FOLDS&&(window.OPEN_FOLDS[this.id]=this.open)\"><summary>➕ 当前有 ${calmMacro.length} 项跨市场指标波动平稳（点击展开查看平稳指标明细）</summary><div class=\"tfidx-grid\" style=\"margin-top:8px\">${calmMacro.map((c) => c.html).join('')}</div></details>` : ''}`;\n  } else {\n    $('macroSec').innerHTML = `<h2>🌐 跨市场长周期先行指标</h2><span class=\"mut\">正在加载跨市场实时数据...</span>`;\n  }\n\n  const s = d.session;\n  if (s) {\n    const [hh, mm] = (s.bjTime || '00:00').split(':').map(Number);\n    const curMin = (hh || 0) * 60 + (mm || 0);\n    const curPct = Math.max(0, Math.min(100, +(curMin / 1440 * 100).toFixed(2)));\n    const volCls = s.volatility.includes('峰值') || s.volatility.includes('最高') ? 'TREND' : s.volatility.includes('升高') ? 'MIXED' : 'RANGE';\n    if ($('nav-sess')) {\n      $('nav-sess').textContent = s.bjTime;\n      $('nav-sess').className = 'pill ' + volCls;\n    }\n\n    // 4大时段定义 (与表格完全一致: 亚洲 07-15 较低, 欧洲 15-24 逐渐升高, 美洲 21-05 最高, 欧美重叠 20-24 峰值)\n    const SESSIONS = [\n      { name: '亚洲时段', range: '07:00 - 15:00', shortRange: '07-15', start: 7 * 60, end: 15 * 60, vol: '较低', cls: 'RANGE', col: '#10b981', desc: '亚盘波幅温和，适合网格刷单' },\n      { name: '欧洲时段', range: '15:00 - 24:00', shortRange: '15-24', start: 15 * 60, end: 24 * 60, vol: '逐渐升高', cls: 'MIXED', col: '#f59e0b', desc: '伦敦开市，波动开始放大' },\n      { name: '美洲时段', range: '21:00 - 05:00(次日)', shortRange: '21-05', start: 21 * 60, end: 29 * 60, vol: '最高', cls: 'TREND', col: '#f43f5e', desc: '纽约主盘+重磅数据，单边高发' },\n      { name: '欧美重叠', range: '20:00 - 24:00', shortRange: '20-24', start: 20 * 60, end: 24 * 60, vol: '峰值', cls: 'TREND', col: '#f43f5e', desc: '全天波动峰值，严防突破' },\n    ];\n\n    const fmtDur = (m) => {\n      const h = Math.floor(m / 60), r = Math.round(m % 60);\n      return h > 0 ? `${h}小时${r ? r + '分' : ''}` : `${r}分钟`;\n    };\n\n    const sessCardsHtml = SESSIONS.map((item) => {\n      const dur = item.end - item.start;\n      let adjCur = curMin;\n      if (item.end > 1440 && curMin < (item.end - 1440)) adjCur = curMin + 1440;\n      const isActive = adjCur >= item.start && adjCur < item.end;\n      let elapsedPct = 0, statusHtml = '';\n      if (isActive) {\n        const elapsed = adjCur - item.start;\n        const rem = item.end - adjCur;\n        elapsedPct = Math.max(0, Math.min(100, Math.round(elapsed / dur * 100)));\n        statusHtml = `<span style=\"color:#fff;font-weight:700\">● 当前进行中 · 已过 ${elapsedPct}%</span> <span class=\"mut\">(剩 ${fmtDur(rem)})</span>`;\n      } else {\n        let wait = item.start - curMin;\n        if (wait <= 0) wait += 1440;\n        statusHtml = `<span class=\"mut\">○ 未开启 · 距开启 ${fmtDur(wait)}</span>`;\n      }\n\n      let segs = '';\n      if (item.end <= 1440) {\n        const left = (item.start / 1440 * 100).toFixed(2);\n        const width = (dur / 1440 * 100).toFixed(2);\n        const fillW = isActive ? ((adjCur - item.start) / 1440 * 100).toFixed(2) : '0';\n        segs = `<div style=\"position:absolute;left:${left}%;width:${width}%;height:100%;background:${isActive ? item.col : '#334155'};opacity:${isActive ? 0.28 : 0.35};border-radius:4px\"></div>` +\n               (isActive ? `<div style=\"position:absolute;left:${left}%;width:${fillW}%;height:100%;background:${item.col};opacity:0.9;border-radius:4px\"></div>` : '');\n      } else {\n        const w1 = ((1440 - item.start) / 1440 * 100).toFixed(2);\n        const l1 = (item.start / 1440 * 100).toFixed(2);\n        const w2 = ((item.end - 1440) / 1440 * 100).toFixed(2);\n        segs = `<div style=\"position:absolute;left:0%;width:${w2}%;height:100%;background:${isActive ? item.col : '#334155'};opacity:${isActive ? 0.28 : 0.35};border-radius:4px 0 0 4px\"></div>` +\n               `<div style=\"position:absolute;left:${l1}%;width:${w1}%;height:100%;background:${isActive ? item.col : '#334155'};opacity:${isActive ? 0.28 : 0.35};border-radius:0 4px 4px 0\"></div>`;\n        if (isActive) {\n          if (curMin >= item.start) {\n            const fw = ((curMin - item.start) / 1440 * 100).toFixed(2);\n            segs += `<div style=\"position:absolute;left:${l1}%;width:${fw}%;height:100%;background:${item.col};opacity:0.9;border-radius:0 4px 4px 0\"></div>`;\n          } else {\n            const fw2 = (curMin / 1440 * 100).toFixed(2);\n            segs += `<div style=\"position:absolute;left:${l1}%;width:${w1}%;height:100%;background:${item.col};opacity:0.9\"></div>` +\n                    `<div style=\"position:absolute;left:0%;width:${fw2}%;height:100%;background:${item.col};opacity:0.9;border-radius:4px 0 0 4px\"></div>`;\n          }\n        }\n      }\n\n      return `<div style=\"background:${isActive ? '#171e2c' : 'var(--card2)'};border:1px solid ${isActive ? item.col : 'var(--bd)'};border-radius:9px;padding:10px 12px;min-width:0;opacity:${isActive ? '1' : '0.72'}\">\n        <div style=\"display:flex;justify-content:space-between;align-items:center;gap:6px;margin-bottom:4px\">\n          <b style=\"color:${isActive ? '#fff' : '#cbd5e1'}\">${item.name} <span class=\"mut sm\">(${item.shortRange})</span></b>\n          <span class=\"pill ${isActive ? item.cls : 'NEUT'}\">波动: ${item.vol}</span>\n        </div>\n        <div class=\"sm\" style=\"margin-bottom:6px\">${statusHtml}</div>\n        <div class=\"bar\" style=\"background:#1a2130;height:8px;border-radius:99px\">\n          ${segs}\n          <div class=\"mk\" style=\"left:${curPct}%\" title=\"当前北京时间 ${s.bjTime}\"></div>\n        </div>\n        <div class=\"ticks\">\n          <span style=\"left:0%\">00</span><span style=\"left:29.17%\">07</span><span style=\"left:62.5%\">15</span><span style=\"left:83.33%\">20</span><span style=\"left:100%\">24</span>\n        </div>\n      </div>`;\n    }).join('');\n\n    const z0 = curMin < 300 ? 'z-active' : '';\n    const z1 = curMin >= 300 && curMin < 420 ? 'z-active' : '';\n    const z2 = curMin >= 420 && curMin < 900 ? 'z-active' : '';\n    const z3 = curMin >= 900 && curMin < 1200 ? 'z-active' : '';\n    const z4 = curMin >= 1200 ? 'z-active' : '';\n\n    // 将用户手动添加的「重磅数据前30分~后15分红灯锁」直接绘制在最开头的 24h 时间轴上！\n    const lkInfo = evalCustomLockState();\n    const lockZonesHtml = (lkInfo.items || []).filter((ev) => ev.enabled).map((ev) => {\n      const sPct = Math.max(0, Math.min(100, +(ev.startMin / 1440 * 100).toFixed(2)));\n      const ePct = Math.max(0, Math.min(100, +(ev.endMin / 1440 * 100).toFixed(2)));\n      const evPct = Math.max(0, Math.min(100, +(ev.evMin / 1440 * 100).toFixed(2)));\n      const wPct = Math.max(0.6, +(ePct >= sPct ? (ePct - sPct) : (100 - sPct)).toFixed(2));\n      const isNowLock = ev.isLocked;\n      return `\n        <div style=\"position:absolute;left:${sPct}%;width:${wPct}%;top:-2px;bottom:-2px;background:${isNowLock ? 'rgba(244,63,94,0.88)' : 'rgba(244,63,94,0.52)'};border:1px solid #fff;border-radius:3px;z-index:3;pointer-events:auto\" title=\"🚨 红灯锁窗口 [${ev.time} ${ev.title}]：前${ev.pre}分 ~ 后${ev.post}分\"></div>\n        <div style=\"position:absolute;left:${evPct}%;top:-19px;transform:translateX(-50%);background:${isNowLock ? '#f43f5e' : '#1e293b'};color:#fff;border:1px solid #f43f5e;border-radius:4px;padding:0px 5px;font-size:10px;font-weight:800;white-space:nowrap;z-index:4;box-shadow:0 2px 6px rgba(0,0,0,0.5)\" title=\"${ev.time} ${ev.title} (${ev.badge})\">🚨${ev.time} ${ev.title.slice(0, 8)}</div>\n      `;\n    }).join('');\n\n    const topDynEl = $('topSessionDynamic') || $('topSessionSec');\n    topDynEl.innerHTML = `\n      <div class=\"vhead\" style=\"margin-bottom:8px\">\n        <div style=\"display:flex;align-items:center;flex-wrap:wrap;gap:10px\">\n          <h2 style=\"margin:0\"><span class=\"live-dot\"></span>🕒 当前交易时段 (北京 <b style=\"color:var(--gold)\">${s.bjTime}</b>)</h2>\n          <span class=\"pill ${volCls}\">${s.active.join(' + ')} · 波动性: ${s.volatility}</span>\n          <span class=\"sm\" style=\"color:#cbd5e1\">${s.tip}</span>\n        </div>\n        <span class=\"mut sm\">全天进度 <b>${curPct}%</b></span>\n      </div>\n      <div style=\"margin-bottom:12px;padding:20px 12px 8px;background:var(--card2);border:1px solid var(--bd);border-radius:8px\">\n        <div class=\"bar\" style=\"height:12px;overflow:visible\">\n          <div class=\"${z0}\" style=\"width:20.83%;background:#f59e0b;border-radius:6px 0 0 6px\" title=\"00:00-05:00 美洲下半场\"></div>\n          <div class=\"${z1}\" style=\"width:8.34%;background:#10b981\" title=\"05:00-07:00 休整期\"></div>\n          <div class=\"${z2}\" style=\"width:33.33%;background:#10b981\" title=\"07:00-15:00 亚洲时段 (较低)\"></div>\n          <div class=\"${z3}\" style=\"width:20.83%;background:#f59e0b\" title=\"15:00-20:00 欧洲时段 (逐渐升高)\"></div>\n          <div class=\"${z4}\" style=\"width:16.67%;background:#f43f5e;border-radius:0 6px 6px 0\" title=\"20:00-24:00 欧美重叠+美盘 (峰值/最高)\"></div>\n          ${lockZonesHtml}\n          <div class=\"mk\" style=\"left:${curPct}%;z-index:5\" title=\"当前北京时间 ${s.bjTime}\"></div>\n        </div>\n        <div class=\"ticks\" style=\"height:14px;margin-top:5px\">\n          <span style=\"left:0%\">00:00</span>\n          <span style=\"left:20.83%\">05:00</span>\n          <span style=\"left:29.17%\">07:00(亚洲)</span>\n          <span style=\"left:62.5%\">15:00(欧洲)</span>\n          <span style=\"left:83.33%\">20:00(欧美重叠)</span>\n          <span style=\"left:100%\">24:00</span>\n        </div>\n      </div>\n      <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(225px,1fr));gap:10px\">\n        ${sessCardsHtml}\n      </div>`;\n    renderCustomEventBar();\n\n    $('session').innerHTML = `<h2>当前时段(北京 ${s.bjTime})</h2><p><b>${s.active.join(' + ')}</b><br>波动性:<b>${s.volatility}</b><br><span class=\"mut\">${s.tip}</span></p>\n      <table><tr><th>时段</th><th>北京时间</th><th>波动</th></tr><tr><td>亚洲</td><td>07-15</td><td>较低</td></tr><tr><td>欧洲</td><td>15-24</td><td>逐渐升高</td></tr><tr><td>美洲</td><td>21-05</td><td>最高</td></tr><tr><td>欧美重叠</td><td>20-24</td><td>峰值</td></tr></table>`;\n  }\n  const g = d.gvz;\n  $('gvz').innerHTML = g ? `<h2><a href=\"https://www.tradingview.com/symbols/CBOE-GVZ/\" target=\"_blank\" rel=\"noopener\">GVZ 黄金波动率指数 🔗</a></h2><p style=\"font-size:30px;margin:0\"><b>${lk(API.GVZ, f2(g.value))}</b> <span class=\"mut\" style=\"font-size:13px\">5日变化 ${g.change5d >= 0 ? '+' : ''}${f2(g.change5d)}</span></p>\n    <div id=\"gvzGauge\"></div><p class=\"mut sm\">区间 ${f2(g.min1y)} ~ ${f2(g.max1y)}<br>${g.note}</p>` : '<h2>GVZ</h2><span class=\"err\">获取失败</span>';\n  let blocks = '';\n  for (const k of ['1M', '5M', '15M', '1H', '4H', '1D']) {\n    const t = d.timeframes[k]; if (!t) continue;\n    const u = API[k];\n    const adj = adjBySpan(t.rangeIndex, t.span14, TOL);\n    const lv = levelFor(adj, t.trendDir);\n    const isFast = k === '1M' || k === '5M';\n    blocks += `<div class=\"tfblock\" id=\"ind-${k}\"><div class=\"tfh\">${isFast ? '<span class=\"live-dot\"></span>' : ''}<b>${k} 周期 10项指标明细</b> · 价格 <span class=\"num-chip ${isFast ? 'fast-num' : ''}\">${lk(u, f2(t.price) + '$')}</span> <span class=\"mut sm\">(${fmtBJ(t.lastBarTime)})</span> · 策略(${f2(TOL)}$)震荡指数 <b class=\"num-chip ${isFast ? 'fast-num' : ''}\">${adj ?? '-'}</b>/100 <span class=\"mut sm\">(原始 ${t.rangeIndex})</span> <span class=\"pill ${lv.cls}\">${lv.name}</span> <span class=\"pill ${t.trendDir}\">${t.trendDirText}</span> <span class=\"mut\">14根波幅 ${f2(t.span14)}$ · +DI ${t.pdi} / -DI ${t.mdi}</span> ${k !== '1D' ? `<a href=\"#chart-${k}\" style=\"margin-left:auto;color:var(--gold);font-size:12px\">↑ 回到 ${k} 大图</a>` : ''}</div><div class=\"gauges\">` +\n      GAUGES.map((g) => gauge(g, t[g.key], u, g.sub ? g.sub(t) : '')).join('') + `</div></div>`;\n  }\n  $('tf').innerHTML = blocks + `<div class=\"legend\"><span><i style=\"background:#2ecc8f\"></i>偏震荡/低波动</span><span><i style=\"background:#f0b429\"></i>过渡/中性</span><span><i style=\"background:#ef5b5b\"></i>偏趋势/高波动</span><span class=\"mut\">▼ 为当前位置</span></div>`;\n  if (g) $('gvzGauge').innerHTML = gauge({ name: 'GVZ 1年分位(%)', key: 'x', max: 100, zones: PCT_ZONES, tip: 'GVZ 在过去一年中的位置:低=市场平静, 高=波动剧烈' }, g.pct1y, API.GVZ, '');\n  renderTrump();\n  renderCal();\n  restoreUiState();\n}\n\nlet TRUMP_ONLY_GOLD = true;\nwindow.setTrumpFilter = (onlyGold) => {\n  TRUMP_ONLY_GOLD = !!onlyGold;\n  if ($('btnTrumpGold')) $('btnTrumpGold').classList.toggle('on', TRUMP_ONLY_GOLD);\n  if ($('btnTrumpAll')) $('btnTrumpAll').classList.toggle('on', !TRUMP_ONLY_GOLD);\n  if (D) { saveUiState(); renderTrump(); restoreUiState(); }\n};\n\nfunction fmtAge(min) {\n  if (min < 1) return '刚刚';\n  if (min < 60) return `${min}分钟前`;\n  if (min < 1440) return `${(min / 60).toFixed(1)}小时前`;\n  return `${(min / 1440).toFixed(1)}天前`;\n}\n\nfunction renderTrump() {\n  const tr = D && D.trump;\n  if (!tr || !tr.items) {\n    $('trumpSec').innerHTML = `<h2>🦅 特朗普言论 & 关税/地缘/美联储实时监控</h2><span class=\"mut\">正在加载7×24实时快讯流...</span>`;\n    return;\n  }\n  const allItems = tr.items || [];\n  const goldItems = allItems.filter((x) => x.isGoldRelevant || x.impact !== 'LOW');\n  const showItems = TRUMP_ONLY_GOLD ? goldItems : allItems;\n  const recentAlertCnt = allItems.filter((x) => x.ageMin <= 180 && (x.impact === 'HIGH' || x.impact === 'MED')).length;\n\n  if ($('nav-trump')) {\n    $('nav-trump').textContent = recentAlertCnt ? `${recentAlertCnt}条新` : '平稳';\n    $('nav-trump').className = 'pill ' + (recentAlertCnt ? 'MIXED' : 'NEUT');\n  }\n\n  const schedHtml = (tr.schedule && tr.schedule.length)\n    ? `<div style=\"margin-bottom:10px;padding:8px 12px;background:var(--card2);border:1px solid var(--bd);border-radius:8px;font-size:12.5px\">\n        <b style=\"color:var(--gold)\">📅 本周金十日历 · 特朗普/白宫重点日程：</b>\n        ${tr.schedule.map((s) => `<span class=\"pill NEUT\" style=\"margin:2px 4px\">${s.time.replace('T', ' ').slice(5, 16)} ${s.title}</span>`).join('')}\n      </div>`\n    : '';\n\n  const listHtml = showItems.length ? showItems.map((x) => {\n    const impCls = x.impact === 'HIGH' ? 'TREND' : x.impact === 'MED' ? 'MIXED' : 'NEUT';\n    const impTxt = x.impact === 'HIGH' ? `🚨 高危冲击(${x.impactScore}分)` : x.impact === 'MED' ? `⚠️ 中等关注(${x.impactScore}分)` : `⚪ 一般内政(${x.impactScore}分)`;\n    const isRecent = x.ageMin <= 180 && x.impact !== 'LOW';\n    const bdrStyle = isRecent ? (x.impact === 'HIGH' ? 'border-left:3px solid var(--red);background:rgba(244,63,94,0.05);' : 'border-left:3px solid var(--yel);background:rgba(245,158,11,0.04);') : '';\n    const tagPills = (x.tags || []).map((t) => `<span class=\"pill NEUT\">${t}</span>`).join(' ');\n    return `<div style=\"padding:10px 12px;background:var(--card2);border:1px solid var(--bd);border-radius:8px;margin-bottom:8px;${bdrStyle}\">\n      <div style=\"display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;margin-bottom:5px\">\n        <div style=\"display:flex;align-items:center;flex-wrap:wrap;gap:6px\">\n          <span class=\"pill ${impCls}\">${impTxt}</span>\n          <span class=\"pill ${x.biasCls || 'NEUT'}\">${x.goldBias}</span>\n          ${tagPills}\n          ${x.isDirect ? `<span class=\"pill\" style=\"background:rgba(234,179,8,0.14);color:var(--gold);border:1px solid rgba(234,179,8,0.3)\">🎙️ 直接表态/动作</span>` : ''}\n        </div>\n        <div class=\"sm mut\" style=\"display:flex;align-items:center;gap:8px\">\n          <span><b style=\"color:${x.ageMin <= 120 ? 'var(--gold)' : '#94a3b8'}\">${fmtAge(x.ageMin)}</b> (${fmtBJ(x.time)})</span>\n          <a href=\"${x.uri}\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none\">🔗 原文验证</a>\n        </div>\n      </div>\n      ${x.title ? `<div style=\"font-weight:700;color:#fff;font-size:13.5px;margin-bottom:3px\">${x.title}</div>` : ''}\n      <div class=\"sm\" style=\"color:#cbd5e1;line-height:1.5\">${x.text}</div>\n    </div>`;\n  }).join('') : `<div class=\"mut sm\">暂无符合筛选条件的言论动态</div>`;\n\n  $('trumpSec').innerHTML = `\n    <div class=\"vhead\" style=\"margin-bottom:10px\">\n      <div style=\"display:flex;align-items:center;flex-wrap:wrap;gap:8px\">\n        <h2 style=\"margin:0\"><span class=\"live-dot\"></span>🦅 特朗普言论 & 关税/联储/地缘实时监控 <span class=\"mut sm\" style=\"font-weight:400\">(7×24秒级快讯流 · 每15秒同步 · 近3h涉金异动自动置顶到页面最前方)</span></h2>\n        <span class=\"pill ${recentAlertCnt ? 'MIXED' : 'NEUT'}\">${recentAlertCnt ? `近3小时有 ${recentAlertCnt} 条涉金表态` : '近3小时无高危涉金突发言论'}</span>\n      </div>\n      <div class=\"btns\">\n        <button class=\"sm ${TRUMP_ONLY_GOLD ? 'on' : ''}\" id=\"btnTrumpGold\" onclick=\"setTrumpFilter(true)\">🎯 仅看黄金相关 (${goldItems.length})</button>\n        <button class=\"sm ${!TRUMP_ONLY_GOLD ? 'on' : ''}\" id=\"btnTrumpAll\" onclick=\"setTrumpFilter(false)\">📋 全部动态含内政 (${allItems.length})</button>\n        <a href=\"${tr.apiUrl}\" target=\"_blank\" rel=\"noopener\"><button class=\"sm\">🔗 验证实时快讯 JSON</button></a>\n      </div>\n    </div>\n    ${schedHtml}\n    <div id=\"trumpScrollBox\" class=\"thin-scroll\" style=\"max-height:460px;overflow-y:auto;padding-right:6px\">\n      ${listHtml}\n    </div>`;\n}\n\nlet CAL_RANGE = 'week'; // 'week' | '2d' | 'today'\nwindow.setCalRange = (mode) => {\n  CAL_RANGE = mode;\n  ['Week', '2d', 'Today'].forEach((k) => {\n    const el = $('calMode' + k);\n    if (el) el.classList.toggle('on', mode === k.toLowerCase());\n  });\n  if (D) renderCal();\n};\n\nfunction renderCal() {\n  if (D.calendar.url && $('calApi')) $('calApi').href = D.calendar.url;\n  const c = D.calendar, only = $('onlyImp').checked;\n  if (c.error && !(c.items && c.items.length)) {\n    $('cal').innerHTML = `<span class=\"err\">金十日历获取失败: ${c.error}</span><br><span class=\"mut\">可能被风控或网络不通,请点击「一键获取」重试,或直接访问 <a style=\"color:var(--gold)\" href=\"https://rili.jin10.com/\" target=\"_blank\">rili.jin10.com</a></span>`;\n    return;\n  }\n\n  // 1) 渲染与金十数据《一周财经日历(weeklyEconomic)》官网 1:1 完全一致的 7天周报总览表 (日期 | 重要数据公布 | 事件与假期)\n  let gridHtml = '';\n  if (c.weeklyGrid && c.weeklyGrid.length) {\n    const rows = c.weeklyGrid.map((g) => {\n      const bgStyle = g.isToday ? 'background:rgba(232,184,74,0.09);border-left:3px solid var(--gold);' : '';\n      const dayBadge = g.isToday\n        ? `<div style=\"font-weight:700;color:var(--gold);font-size:14px\">${g.md}<br><span class=\"pill MIXED\" style=\"margin-top:3px\">今 · ${g.wd}</span></div>`\n        : `<div style=\"font-weight:600;color:var(--tx);font-size:13px\">${g.md}<br><span class=\"mut sm\">${g.wd}</span></div>`;\n\n      const dataTags = g.dataTags && g.dataTags.length\n        ? g.dataTags.map((d) => {\n            const starCol = d.star >= 4 ? '#ef5b5b' : '#e8b84a';\n            const valStr = d.actual ? `公布:${d.actual}` : (d.consensus ? `预期:${d.consensus}` : (d.previous ? `前值:${d.previous}` : ''));\n            const tip = `${d.hm} [${d.country}] ${'★'.repeat(d.star)} ${d.title} | 前值:${d.previous || '-'} 预期:${d.consensus || '-'} 公布:${d.actual || '-'}`;\n            return `<span style=\"display:inline-flex;align-items:center;gap:4px;padding:3px 8px;margin:2px 4px 2px 0;border-radius:6px;background:#181e29;border:1px solid ${d.star >= 4 ? 'rgba(239,91,91,0.5)' : '#2a3242'};font-size:12px\" title=\"${tip}\">\n              <b style=\"color:${starCol}\">${d.summary}</b>\n              <span class=\"mut\" style=\"font-size:11px\">${d.hm}${valStr ? ' · ' + valStr : ''}</span>\n            </span>`;\n          }).join('')\n        : `<span class=\"mut sm\">无重要数据</span>`;\n\n      const evTags = [];\n      if (g.evTags && g.evTags.length) {\n        g.evTags.forEach((ev) => {\n          const tip = `${ev.hm || '待定'} [${ev.country}] ${ev.title}`;\n          if (ev.kind === 'holiday') {\n            evTags.push(`<span style=\"display:inline-flex;align-items:center;gap:4px;padding:3px 8px;margin:2px 4px 2px 0;border-radius:6px;background:rgba(240,180,41,0.14);border:1px solid rgba(240,180,41,0.4);color:#f0b429;font-size:12px\" title=\"${tip}\">🏖️ <b>${ev.summary}</b></span>`);\n          } else {\n            evTags.push(`<span style=\"display:inline-flex;align-items:center;gap:4px;padding:3px 8px;margin:2px 4px 2px 0;border-radius:6px;background:rgba(88,166,255,0.12);border:1px solid rgba(88,166,255,0.35);color:#8ec5ff;font-size:12px\" title=\"${tip}\">🎙️ <b>${ev.summary}</b>${ev.hm && ev.hm !== '待定' ? `<span class=\"mut\" style=\"font-size:11px\">${ev.hm}</span>` : ''}</span>`);\n          }\n        });\n      }\n      const evHtml = evTags.length ? evTags.join('') : `<span class=\"mut sm\">无重大事件/假期</span>`;\n\n      return `<tr style=\"${bgStyle}\">\n        <td style=\"width:82px;text-align:center;vertical-align:middle\">${dayBadge}</td>\n        <td style=\"vertical-align:middle;line-height:1.7\">${dataTags}</td>\n        <td style=\"width:34%;vertical-align:middle;line-height:1.7\">${evHtml}</td>\n      </tr>`;\n    }).join('');\n\n    gridHtml = `<div style=\"margin-bottom:14px\">\n      <div class=\"sm\" style=\"margin-bottom:6px;color:var(--mut);display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px\">\n        <span>📌 <b>金十数据《一周财经日历》官方周报同款 7天总览表</b>（词条取自官方接口 <code>summary</code> 字段，与官网周报 1:1 严格一致；鼠标悬停词条可看全称与前值/预期/公布值）</span>\n        <span class=\"mut\">红色边框 = ★4~5星高危数据 · 蓝色 = 央行/政要事件 · 黄色 = 休市假期</span>\n      </div>\n      <div style=\"overflow-x:auto\">\n        <table>\n          <tr><th style=\"width:82px;text-align:center\">日期</th><th>重要数据公布 (金十周报核心词条)</th><th style=\"width:34%\">事件与假期 (央行决议 / 讲话 / 休市)</th></tr>\n          ${rows}\n        </table>\n      </div>\n    </div>`;\n  }\n\n  // 2) 渲染分时明细表 (可切换 本周全部7天 / 今明两日 / 仅看今日)\n  const items = (c.items || []).filter((e) => {\n    if (only && e.star < 3 && e.kind !== 'holiday') return false;\n    if (CAL_RANGE === 'today') return e.date === c.today;\n    if (CAL_RANGE === '2d') return e.date === c.today || e.date === c.tomorrow;\n    return true;\n  });\n\n  const typeBadge = (e) => {\n    if (e.kind === 'holiday') return `<span class=\"pill MIXED\">🏖️休市</span>`;\n    if (e.kind === 'event') return `<span class=\"pill\" style=\"background:rgba(88,166,255,0.18);color:#8ec5ff\">🎙️事件</span>`;\n    return `<span class=\"pill\" style=\"background:#1c2331;color:var(--mut)\">📊数据</span>`;\n  };\n  const affectBadge = (af) => {\n    if (!af) return '-';\n    if (af.includes('利多金银')) return `<span style=\"color:#2ecc8f;font-weight:600\">${af}</span>`;\n    if (af.includes('利空金银')) return `<span style=\"color:#ef5b5b;font-weight:600\">${af}</span>`;\n    return `<span class=\"mut\">${af}</span>`;\n  };\n\n  $('cal').innerHTML = gridHtml +\n    `<div class=\"sm\" style=\"margin:10px 0 6px;font-weight:600;color:var(--gold)\">📋 分时详细数据表 (${CAL_RANGE === 'week' ? '本周全部7天' : CAL_RANGE === '2d' ? '今明两日' : '仅今日'} · 共 ${items.length} 条 · 已包含官方数值单位 % / 万人 / 万户 / 万桶)</div>` +\n    `<div style=\"overflow-x:auto\"><table><tr><th>时间(北京)</th><th>国家</th><th>类型</th><th>重要性</th><th>事件 / 指标全称 <span class=\"mut\">(金十周报词条)</span></th><th>前值</th><th>预期</th><th>公布</th><th>金十影响判定</th></tr>` +\n    items.map((e) => `<tr class=\"${e.star >= 4 ? 'imp' : ''}\">\n      <td style=\"white-space:nowrap\">${e.time.replace('T', ' ').slice(0, 16)}${e.date === c.today ? ' <span class=\"pill MIXED\" style=\"padding:0 4px;font-size:10px\">今</span>' : ''}</td>\n      <td>${e.country}</td>\n      <td>${typeBadge(e)}</td>\n      <td class=\"star\">${e.kind === 'holiday' ? '休市' : '★'.repeat(e.star)}</td>\n      <td>${e.title}</td>\n      <td>${e.previous || '-'}</td>\n      <td>${e.consensus || '-'}</td>\n      <td><b>${e.actual || '-'}</b></td>\n      <td>${affectBadge(e.affect)}</td>\n    </tr>`).join('') + '</table></div>';\n}\n\nfunction buildText() {\n  const d = D, m = d.model, L = [];\n  const ea = calcEaModel(ACC_BAL, EA_CFG, CUR_LAYERS, USED_MARGIN);\n  const adjMap = {}, eMap = {};\n  for (const k of ['1M', '5M', '15M', '1H', '4H', '1D']) {\n    const t = d.timeframes[k];\n    if (t && t.rangeIndex != null) adjMap[k] = adjBySpan(t.rangeIndex, t.span14, TOL);\n  }\n  for (const k of ['1M', '5M', '15M', '1H', '4H']) {\n    const sp = (m && m.sparks && m.sparks[k]) || [];\n    const ser = calcEntrySeries(sp, TOL);\n    eMap[k] = { ser, last: ser[ser.length - 1] || {} };\n  }\n  const eaDir = calcEaDirective(d, ea, adjMap, eMap);\n\n  L.push('【黄金(XAUUSD)震荡/单边量化数据 — 用于 M1 双向追踪倍投马丁 EA 实盘风控判断】');\n  L.push(`我的账户余额: $${ACC_BAL} | 当前/风控层数: ${ea.curLayerNum}层(累计${f2(ea.curInfo.cumLot)}手,建仓浮亏$${f2(ea.curInfo.ddUsd)}) | 已用预付款: $${ea.usedMargin} (实时预付款比例: ${ea.marginLevelBal}%)`);\n  L.push(`在 ${ea.curLayerNum} 层仓位下推导65%安全震荡容忍区间: ${f2(TOL)}$ | 100%强平极限跨度: ${f2(ea.hard.span)}$ (若不锁方向连续死加则在第${ea.uncontrolledWarn.layer}~${ea.uncontrolledHard.layer}层触发倍投警戒)`);\n  L.push(`EA核心参数: 首单lot=${ea.cfg.lot}, 倍投K_Lot=${ea.cfg.kLot}, 单笔上限Maxlot=${ea.cfg.maxLot}, 最大层数Totals=${ea.cfg.totals}, 间距Step=${ea.cfg.stepUsd}$(100点), 整组止盈StopProfit=${ea.cfg.tpPerOrder}$×层数`);\n  L.push(`实时手动操作指令(以1M+5M为主65%、15M+1H为辅35%): 【${eaDir.badgeTxt}】 ${eaDir.pauseSideTxt}`);\n  L.push(`  - 核心判断: ${eaDir.headline}`);\n  L.push(`  - 恢复双向条件: ${eaDir.resumeRule.replace(/<[^>]+>/g, '')}`);\n  L.push('全周期+跨市场实时更新时间(北京): ' + new Date(d.fastUpdatedAt || d.updatedAt).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false }));\n  L.push('全量更新时间(北京): ' + new Date(d.updatedAt).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false }));\n  L.push('数据源: ' + d.symbol);\n  if (m) {\n    L.push(`\\n■ 实时量化震荡指数 (0-100分, ≥70强震荡, 55-70偏震荡, 45-55过渡, 30-45偏单边, <30强单边)`);\n    L.push(`  - 当前主导趋势方向: ${m.overallDirText}`);\n    L.push(`  - 原始技术面震荡指数: ${m.current}/100 [${m.currentLevel.name}] | 实盘运行指数: ${m.run}/100 [${m.runLevel.name}]`);\n    L.push(`  - 分周期指数与波幅(对比 ${f2(TOL)}$ 区间): ` + ['1M', '5M', '15M', '1H', '4H', '1D'].filter((k) => d.timeframes[k]).map((k) => {\n      const t = d.timeframes[k], adj = adjBySpan(t.rangeIndex, t.span14, TOL);\n      return `${k}:策略指数${adj}(原${t.rangeIndex})/14根波幅${f2(t.span14)}$/${t.trendDirText}`;\n    }).join(' | '));\n    L.push(`  - 实时修正项: ` + (m.runAdj || []).map((a) => `${a.name} ${a.v >= 0 ? '+' + a.v : a.v}`).join(', '));\n    if (m.squeeze && m.squeeze.strength > 0) L.push(`  - 波动率挤压预警强度: ${m.squeeze.strength}% (${m.squeeze.why.join('、')})`);\n    L.push(`\\n■ 未来 5 个交易日震荡指数预测:`);\n    m.forecast.forEach((f) => {\n      const p = f.parts;\n      const evs = f.events.map((e) => `${e.time.slice(5, 16)} ${e.country}${e.title}(-${e.p})`).join('; ');\n      L.push(`  - ${f.date}(${f.label}): ${f.index}/100 [${levelFor(f.index, m.overallDir).name}] | 构成: 技术${p.tech}, kNN${p.knn ?? '-'}(${p.knnP ?? '-'}%), 挤压${p.squeeze}, GVZ${p.gvz >= 0 ? '+' + p.gvz : p.gvz}, 事件${p.events} | 风险事件: ${evs || '无'}`);\n    });\n    if (m.knn) {\n      L.push(`  - 10年日线kNN相似行情(${m.knn.samples}样本): ` + m.knn.horizons.map((h) => `T+${h.h}天震荡概率${h.p}%(基准${h.base}%)`).join(', ') + ` | 最相似日期: ` + m.knn.similar.map((s) => `${s.date}(${s.next3})`).join('、'));\n    }\n  }\n  if (d.macro && d.macro.dxy) {\n    const mc = d.macro;\n    const dxy = mc.dxy || {}, us10 = mc.us10y || {}, us2 = mc.us2y || {}, xag = mc.xag || {}, vix = mc.vix || {}, autd = mc.autd || {};\n    L.push(`\\n■ 跨市场实时先行指数矩阵 (0秒延迟):`);\n    L.push(`  - 美元指数(DXY): ${f2(dxy.last)} (${dxy.chgPct >= 0 ? '+' : ''}${f2(dxy.chgPct)}%) | DXY 15M ADX: ${f2(mc.dxyAdx)} | 金-美20根相关性 r=${f2(mc.corrXauDxy)}`);\n    L.push(`  - 美债收益率: 10年期 ${f2(us10.last)}% (${us10.chgPct >= 0 ? '+' : ''}${f2(us10.chgPct)}%) | 2年期 ${f2(us2.last)}% | 10Y-2Y利差 ${f2(mc.yieldSpread)}bp`);\n    L.push(`  - 现货白银(XAGUSD): ${f2(xag.last)}$ (${xag.chgPct >= 0 ? '+' : ''}${f2(xag.chgPct)}%) | 实时金银比 ${f2(mc.gsr)} | 白银-黄金日内强弱差 ${f2(mc.agLead)}%`);\n    L.push(`  - VIX恐慌指数: ${f2(vix.last)} (${vix.chgPct >= 0 ? '+' : ''}${f2(vix.chgPct)}%) | 上海黄金TD(AUTD): ${f2(autd.last)}元/克 (${autd.chgPct >= 0 ? '+' : ''}${f2(autd.chgPct)}%)`);\n  }\n  if (d.pullback) {\n    const pb = d.pullback;\n    L.push(`\\n■ 锯齿回调解套能力 & 被套去留决策分析 (近90分钟总波幅 $${f2(pb.span90m)}):`);\n    L.push(`  - 行情形态: ${pb.patternBadge} (锯齿回调修正加分: ${pb.sawtoothBonus >= 0 ? '+' : ''}${pb.sawtoothBonus}分)`);\n    L.push(`  - 止盈回调统计: 近90m内满$2.7止盈回调共 ${pb.totalClears90m} 次 (最大中途回调 $${f2(pb.maxPb90m)}) | 当前连续未解套跨度: $${f2(pb.activeUnretraced)} (${pb.pressureSideTxt}, 已反抽 $${f2(pb.activeCurRetrace)}, 距止盈平仓还需再回调 $${f2(pb.needMoreForClear)})`);\n    L.push(`  - 已被套去留决策 (未来15~30m回调解套概率 ${pb.reboundProb}%): ${pb.holdDecision}`);\n    L.push(`  - 具体指引: ${pb.holdAction.replace(/\\*\\*/g, '')}`);\n  }\n  if (d.keyLevels && Array.isArray(d.keyLevels.levels)) {\n    L.push(`\\n■ 关键清算位与整数关口「插针雷区」地图 (当前现价 $${f2(d.keyLevels.curPrice)}):`);\n    L.push(`  - 状态: ${d.keyLevels.headline}`);\n    (d.keyLevels.nearest || []).slice(0, 6).forEach((lv) => {\n      L.push(`  - [${lv.dir === 'UP' ? '上方阻力/止损池' : '下方支撑/止损池'}] ${lv.name} $${f2(lv.price)} (距现价 ${lv.diff >= 0 ? '+' : ''}${f2(lv.diff)}$ / ${lv.pts}点 | ${lv.danger})`);\n    });\n  }\n  if (d.sentiment && d.sentiment.retailLongPct != null) {\n    const st = d.sentiment;\n    L.push(`\\n■ 黄金散户反指效应指标 (Retail Sentiment Contrarian Index):`);\n    L.push(`  - 全市场散户多空人数比: 多头 ${st.retailLongPct}% vs 空头 ${st.retailShortPct}% (${st.retailRatio}:1, 近3h变化 ${st.retailChg3h >= 0 ? '+' : ''}${st.retailChg3h}%) | 顶级大户持仓多空比: 多头 ${st.whaleLongPct}% vs 空头 ${st.whaleShortPct}%`);\n    L.push(`  - 15M市价主动吃单买盘占比: ${st.takerBuyPct}% (买卖比 ${st.takerBuyRatio}) | 沪金外盘主动买盘: ${st.shfeActiveBuyPct}%`);\n    L.push(`  - 反指信号(${st.riskScore}/100): ${st.signal} | 实盘指令: ${st.eaAdvice}`);\n  }\n  if (d.attention && d.attention.score != null) {\n    const at = d.attention, cmx = at.comex || {}, sh = at.shfe || {}, nw = at.news || {}, gld = at.gld || {}, cr = at.globalHeat || at.crowd || {};\n    L.push(`\\n■ 黄金受关注度综合指数 (Gold Attention Index): ${at.score}/100 [${at.level}]`);\n    L.push(`  - COMEX黄金期货主力(GC=F)量比: ${cmx.volRatio ?? '-'}x (5日分位 ${cmx.volPct ?? '-'}%) | 国内沪金主连(SHFE AU)量比: ${sh.volRatio ?? '-'}x (日成交 ${sh.turnoverBillion ?? '-'}亿元, 外盘主动买盘占比 ${sh.activeBuyPct ?? '-'}%)`);\n    L.push(`  - 7×24财经快讯黄金提及密度: 近1h ${nw.count1h ?? 0}条 / 近4h ${nw.count4h ?? 0}条 / 近24h ${nw.count24h ?? 0}条 | SPDR GLD日量比: ${gld.volRatio ?? '-'}x | 链上黄金(PAXG+XAUT)24h成交: $${cr.onchainVolM ?? '-'}M | Wiki搜索30日分位: ${cr.wikiPct ?? '-'}%`);\n    L.push(`  - 关注度实盘启示: ${at.eaTip}`);\n  }\n  if (d.trump && d.trump.items) {\n    const tGold = d.trump.items.filter((x) => x.isGoldRelevant || x.impact !== 'LOW').slice(0, 6);\n    L.push(`\\n■ 特朗普言论 & 关税/联储/地缘实时监控 (近3h涉金表态 ${d.trump.recent2hCount || 0} 条):`);\n    if (tGold.length) {\n      tGold.forEach((x) => L.push(`  - [${fmtBJ(x.time)} | ${fmtAge(x.ageMin)} | 冲击:${x.impact}(${x.impactScore}分) | ${x.goldBias}] ${x.title ? x.title + ': ' : ''}${x.text.slice(0, 140)}`));\n    } else {\n      L.push('  - 近期无涉及关税/美联储/地缘冲突的高危言论');\n    }\n  }\n  L.push(`\\n■ 当前时段(北京 ${d.session.bjTime}): ${d.session.active.join('+')},波动性 ${d.session.volatility}。${d.session.tip}`);\n  L.push('\\n■ 多周期10项技术指标明细(阈值: ADX<20震荡/>25趋势; CHOP>61.8震荡/<38.2趋势; ATR14/ATR100 <0.82挤压/>1.25扩张)');\n  for (const k of ['1M', '5M', '15M', '1H', '4H', '1D']) {\n    const t = d.timeframes[k]; if (!t) continue;\n    const sp = (m && m.sparks && m.sparks[k]) || [];\n    const eLast = calcEntrySeries(sp, TOL).slice(-1)[0];\n    const eStr = eLast ? ` | 入场判断:${eLast.entryTxt}(适宜度${eLast.entryScore}/100,${eLast.entryReason})` : '';\n    L.push(`[${k} | ${fmtBJ(t.lastBarTime)}] 价格 ${f2(t.price)}$ | 方向:${t.trendDirText}(14根净涨跌 ${f2(t.net14)}$) | 14根波幅 ${f2(t.span14)}$(24根 ${f2(t.span24)}$) | 策略(${f2(TOL)}$)震荡指数 ${adjBySpan(t.rangeIndex, t.span14, TOL)}/100(原始 ${t.rangeIndex}) | 指数单次变化 ${t.idxChg1 >= 0 ? '+' : ''}${t.idxChg1 ?? 0}分(单次跌 ${t.idxDrop1 ?? 0}分,14根最大单次跌 ${t.maxDrop14 ?? 0}分)${eStr} | ADX ${t.adx}(+DI ${t.pdi}/-DI ${t.mdi}) | CHOP ${t.chop} | ATR比率 ${t.atrRatio}`);\n    L.push(`   扩展: 效率比ER ${t.er} | 布林带宽 ${t.bbw}%(分位 ${t.bbwPct}%) | 20根穿MA20次数 ${t.maCross20 ?? '-'}次 | ATR分位 ${t.atrPct}% | EMA50 ${f2(t.ema50)}$(偏离 ${t.emaDist} 倍ATR) | RSI ${t.rsi}`);\n  }\n  if (d.gvz) L.push(`\\n■ GVZ(黄金波动率指数): ${f2(d.gvz.value)},5日变化 ${f2(d.gvz.change5d)},1年分位 ${d.gvz.pct1y}%(1年区间 ${f2(d.gvz.min1y)}~${f2(d.gvz.max1y)}),${d.gvz.note}`);\n  L.push('\\n■ 金十数据《一周财经日历》(本周重点数据与事件,★3以上,北京时间)');\n  const items = (d.calendar.items || []).filter((e) => e.star >= 3 || e.kind === 'holiday');\n  if (!items.length) L.push(d.calendar.error ? '(获取失败: ' + d.calendar.error + ')' : '(无重要事件)');\n  items.forEach((e) => L.push(`${e.time.replace('T', ' ').slice(0, 16)} [${e.country}] ${e.kind === 'holiday' ? '[休市]' : '★'.repeat(e.star)} ${e.title} | 前值 ${e.previous || '-'} 预期 ${e.consensus || '-'} 公布 ${e.actual || '-'} ${e.affect ? '| ' + e.affect : ''}`));\n  if (d.errors.length) L.push('\\n(注意: 以下数据获取失败: ' + d.errors.join(' | ') + ')');\n  L.push(`\\n请基于以上数据(并结合我 $${ACC_BAL} 账户、${ea.curLayerNum}层仓位、预付款比例 ${ea.marginLevelBal}% 以及 ${f2(TOL)}$ 安全震荡区间)判断:当前是否需要手动暂停开多单(Buy)或开空单(Sell)?未来数小时黄金更可能是震荡还是单边行情?`);\n  return L.join('\\n');\n}\n\n// 初始化账户风控与EA参数输入框\nfunction syncEaInputs() {\n  if ($('accBalInput')) $('accBalInput').value = ACC_BAL;\n  if ($('riskLossInput')) $('riskLossInput').value = RISK_LOSS_USD;\n  if ($('buyLotsInput')) $('buyLotsInput').value = BUY_LOTS;\n  if ($('sellLotsInput')) $('sellLotsInput').value = SELL_LOTS;\n  if ($('buyAvgPxInput')) $('buyAvgPxInput').value = BUY_AVG_PX;\n  if ($('sellAvgPxInput')) $('sellAvgPxInput').value = SELL_AVG_PX;\n  if ($('stopOutPctInput')) $('stopOutPctInput').value = STOP_OUT_PCT;\n  if ($('curLayerInput')) $('curLayerInput').value = CUR_LAYERS;\n  if ($('usedMarginInput')) $('usedMarginInput').value = USED_MARGIN;\n  if ($('eaLot')) $('eaLot').value = EA_CFG.lot;\n  if ($('eaK')) $('eaK').value = EA_CFG.kLot;\n  if ($('eaMaxLot')) $('eaMaxLot').value = EA_CFG.maxLot;\n  if ($('eaTotals')) $('eaTotals').value = EA_CFG.totals;\n  if ($('eaStep')) $('eaStep').value = EA_CFG.stepUsd;\n  if ($('eaTp')) $('eaTp').value = EA_CFG.tpPerOrder;\n  if ($('tolSlider')) $('tolSlider').value = TOL;\n  if ($('tolInput')) $('tolInput').value = TOL;\n  if ($('tolValTxt')) $('tolValTxt').textContent = f2(TOL);\n  syncVoiceUi();\n  syncTolSecToggleUi();\n  renderCustomEventBar();\n}\n\n// 根据当前输入的账户金额 + 可亏线 + 买卖手数(净敞口N) + 已用预付款 + EA参数，自动按 D = L / (N * 100) 反推抗单跨度 TOL 并重算全站\nfunction applyAccountAndRecalc(customBal, triggerSource) {\n  if (customBal != null) {\n    ACC_BAL = Math.max(50, Math.min(1000000, Number(customBal) || 2700));\n    if (customBal === 2000 && RISK_LOSS_USD > 2000) RISK_LOSS_USD = 1500;\n  } else if ($('accBalInput')) {\n    ACC_BAL = Math.max(50, Math.min(1000000, Number($('accBalInput').value) || 2700));\n  }\n\n  if ($('riskLossInput') && customBal == null) RISK_LOSS_USD = Math.max(50, Math.min(1000000, Number($('riskLossInput').value) || 1500));\n  if ($('buyLotsInput')) BUY_LOTS = Math.max(0, Math.min(200, Number($('buyLotsInput').value) || 0));\n  if ($('sellLotsInput')) SELL_LOTS = Math.max(0, Math.min(200, Number($('sellLotsInput').value) || 0));\n  if ($('buyAvgPxInput')) BUY_AVG_PX = Math.max(0, Number($('buyAvgPxInput').value) || 0);\n  if ($('sellAvgPxInput')) SELL_AVG_PX = Math.max(0, Number($('sellAvgPxInput').value) || 0);\n  if ($('stopOutPctInput')) STOP_OUT_PCT = Math.max(0, Math.min(100, Number($('stopOutPctInput').value) || 20));\n  if ($('usedMarginInput')) USED_MARGIN = Math.max(1, Math.min(500000, Number($('usedMarginInput').value) || 14));\n  if ($('eaLot')) EA_CFG.lot = Math.max(0.01, Number($('eaLot').value) || 0.02);\n  if ($('eaK')) EA_CFG.kLot = Math.max(1.01, Number($('eaK').value) || 1.38);\n  if ($('eaMaxLot')) EA_CFG.maxLot = Math.max(EA_CFG.lot, Number($('eaMaxLot').value) || 1.32);\n  if ($('eaTotals')) EA_CFG.totals = Math.max(1, Math.min(60, Math.round(Number($('eaTotals').value) || 24)));\n  if ($('eaStep')) EA_CFG.stepUsd = Math.max(0.1, Number($('eaStep').value) || 1.00);\n  if ($('eaTp')) EA_CFG.tpPerOrder = Math.max(0.5, Number($('eaTp').value) || 4.0);\n\n  // 先用临时模型拿到各层累计手数序列，从而由买单/卖单手数自动识别层数\n  const tmpEa = calcEaModel(ACC_BAL, EA_CFG, CUR_LAYERS, USED_MARGIN);\n  if (triggerSource === 'layer') {\n    if ($('curLayerInput')) CUR_LAYERS = Math.max(1, Math.min(EA_CFG.totals, Number($('curLayerInput').value) || 7));\n    const targetCumLot = (tmpEa.layers[CUR_LAYERS - 1] || tmpEa.layers[0]).cumLot;\n    if (SELL_LOTS > BUY_LOTS) SELL_LOTS = targetCumLot;\n    else BUY_LOTS = targetCumLot;\n    if ($('buyLotsInput')) $('buyLotsInput').value = BUY_LOTS;\n    if ($('sellLotsInput')) $('sellLotsInput').value = SELL_LOTS;\n  } else {\n    // 优先由【当前买单手数 / 当前卖单手数】自动识别主层数，并以 |买-卖| 净敞口 N 计算抗单跨度\n    CUR_LAYERS = Math.max(1, tmpEa.buyInfo.layer, tmpEa.sellInfo.layer);\n    if ($('curLayerInput')) $('curLayerInput').value = CUR_LAYERS;\n  }\n\n  localStorage.setItem('gold_acc_bal', ACC_BAL);\n  localStorage.setItem('gold_risk_loss', RISK_LOSS_USD);\n  localStorage.setItem('gold_buy_lots', BUY_LOTS);\n  localStorage.setItem('gold_sell_lots', SELL_LOTS);\n  localStorage.setItem('gold_buy_avg_px', BUY_AVG_PX);\n  localStorage.setItem('gold_sell_avg_px', SELL_AVG_PX);\n  localStorage.setItem('gold_stop_out_pct', STOP_OUT_PCT);\n  localStorage.setItem('gold_cur_layers', CUR_LAYERS);\n  localStorage.setItem('gold_used_margin', USED_MARGIN);\n  localStorage.setItem('gold_ea_lot', EA_CFG.lot);\n  localStorage.setItem('gold_ea_klot', EA_CFG.kLot);\n  localStorage.setItem('gold_ea_maxlot', EA_CFG.maxLot);\n  localStorage.setItem('gold_ea_totals', EA_CFG.totals);\n  localStorage.setItem('gold_ea_step', EA_CFG.stepUsd);\n  localStorage.setItem('gold_ea_tp', EA_CFG.tpPerOrder);\n\n  const ea = calcEaModel(ACC_BAL, EA_CFG, CUR_LAYERS, USED_MARGIN);\n  TOL = ea.recommendedTol;\n  localStorage.setItem('gold_tol', TOL);\n  syncEaInputs();\n  render();\n  triggerFlash();\n  toast(`已重算：净敞口 N=${f2(ea.netLots)}手 ($${ea.netLossPerUsd}/$) · 亏$${ea.riskLossUsd}可抗 ${f2(TOL)}$ (${ea.warn.pts}点) · 账户极限 ${f2(ea.hard.span)}$`);\n}\n\nwindow.pickQuickNetLots = (nVal) => {\n  const targetNet = Math.max(0.02, Number(nVal) || 0.50);\n  const minor = 0.02;\n  if (SELL_LOTS > BUY_LOTS) {\n    BUY_LOTS = minor;\n    SELL_LOTS = Math.round((targetNet + minor) * 100) / 100;\n  } else {\n    SELL_LOTS = minor;\n    BUY_LOTS = Math.round((targetNet + minor) * 100) / 100;\n  }\n  syncEaInputs();\n  applyAccountAndRecalc(null, 'lots');\n};\n\nwindow.pickQuickLayer = (n) => {\n  if ($('curLayerInput')) $('curLayerInput').value = n;\n  applyAccountAndRecalc(null, 'layer');\n};\nwindow.setAccountBal = (v) => applyAccountAndRecalc(v);\nwindow.applyEaPreset = (mode) => {\n  if (mode === 'cur' || mode === 'current') {\n    EA_CFG = { lot: 0.02, kLot: 1.38, maxLot: 1.32, totals: 24, stepUsd: 1.00, tpPerOrder: 4.0 };\n    ACC_BAL = 2700;\n    RISK_LOSS_USD = 1500;\n    BUY_LOTS = 0.45;\n    SELL_LOTS = 0.02;\n    CUR_LAYERS = 7;\n    USED_MARGIN = 14;\n  } else if (mode === 'bal2000') {\n    EA_CFG = { lot: 0.02, kLot: 1.38, maxLot: 1.32, totals: 24, stepUsd: 1.00, tpPerOrder: 4.0 };\n    ACC_BAL = 2000;\n    RISK_LOSS_USD = 1500;\n    BUY_LOTS = 0.52;\n    SELL_LOTS = 0.02;\n    CUR_LAYERS = 7;\n    USED_MARGIN = 14;\n  } else if (mode === 'log') {\n    EA_CFG = { lot: 0.02, kLot: 1.38, maxLot: 3.50, totals: 50, stepUsd: 1.00, tpPerOrder: 4.0 };\n    ACC_BAL = 20000;\n    RISK_LOSS_USD = 15000;\n    BUY_LOTS = 0.45;\n    SELL_LOTS = 0.02;\n    CUR_LAYERS = 7;\n    USED_MARGIN = 14;\n  }\n  syncEaInputs();\n  applyAccountAndRecalc(ACC_BAL);\n};\n\n// 初始化时根据账户金额与净敞口同步一次 TOL\n{\n  const initEa = calcEaModel(ACC_BAL, EA_CFG, CUR_LAYERS, USED_MARGIN);\n  TOL = initEa.recommendedTol;\n  syncEaInputs();\n}\n\nif ($('btnCalcAccount')) $('btnCalcAccount').onclick = () => applyAccountAndRecalc();\nif ($('accBalInput')) $('accBalInput').onchange = () => applyAccountAndRecalc();\nif ($('riskLossInput')) $('riskLossInput').onchange = () => applyAccountAndRecalc();\nif ($('buyLotsInput')) $('buyLotsInput').onchange = () => applyAccountAndRecalc(null, 'lots');\nif ($('sellLotsInput')) $('sellLotsInput').onchange = () => applyAccountAndRecalc(null, 'lots');\nif ($('buyAvgPxInput')) $('buyAvgPxInput').onchange = () => applyAccountAndRecalc();\nif ($('sellAvgPxInput')) $('sellAvgPxInput').onchange = () => applyAccountAndRecalc();\nif ($('stopOutPctInput')) $('stopOutPctInput').onchange = () => applyAccountAndRecalc();\nif ($('curLayerInput')) $('curLayerInput').onchange = () => applyAccountAndRecalc(null, 'layer');\nif ($('usedMarginInput')) $('usedMarginInput').onchange = () => applyAccountAndRecalc();\n\nif ($('tolSlider')) $('tolSlider').oninput = (e) => {\n  if ($('tolInput')) $('tolInput').value = e.target.value;\n  if ($('tolValTxt')) $('tolValTxt').textContent = e.target.value;\n};\nif ($('tolInput')) $('tolInput').oninput = (e) => {\n  if ($('tolSlider')) $('tolSlider').value = e.target.value;\n  if ($('tolValTxt')) $('tolValTxt').textContent = e.target.value;\n};\nfunction applyTol(v) {\n  TOL = Math.max(3, Math.min(300, Number(v) || 14.2));\n  localStorage.setItem('gold_tol', TOL);\n  if ($('tolSlider')) $('tolSlider').value = TOL;\n  if ($('tolInput')) $('tolInput').value = TOL;\n  if ($('tolValTxt')) $('tolValTxt').textContent = f2(TOL);\n  syncVoiceUi();\n  renderCustomEventBar();\n  render();\n  triggerFlash();\n  toast(`已手动微调安全震荡区间为 ${f2(TOL)} 美元并重新计算全部指数`);\n}\nwindow.setTol = (v) => applyTol(v);\nif ($('btnCalcTol')) $('btnCalcTol').onclick = () => applyTol($('tolInput').value);\n\n$('btnFetch').onclick = () => load(true, false);\n$('btnFast').onclick = () => { load(false, true); toast('已刷新全周期+跨市场实时数据'); };\n$('onlyImp').onchange = () => D && renderCal();\n$('btnCopy').onclick = async () => {\n  if (!D) return;\n  const text = buildText();\n  try { await navigator.clipboard.writeText(text); }\n  catch { const ta = document.createElement('textarea'); ta.value = text; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); }\n  toast('已复制全部实时信息');\n};\n\n// ========== MT4 实盘实时同步接入逻辑 (3秒极速联动 + 一键生成/下载只读 MQL4 脚本) ==========\nwindow.toggleMt4Guide = function() {\n  const sec = $('mt4GuideSec');\n  if (!sec) return;\n  const isHidden = sec.style.display === 'none';\n  sec.style.display = isHidden ? 'block' : 'none';\n  if ($('mt4WhitelistUrl')) $('mt4WhitelistUrl').textContent = window.location.origin;\n  if (isHidden) sec.scrollIntoView({ behavior: 'smooth', block: 'start' });\n};\n\nfunction updateMt4UiStatus(mt4, ea) {\n  if ($('mt4WhitelistUrl')) $('mt4WhitelistUrl').textContent = window.location.origin;\n  const btn = $('btnMt4Guide');\n  const pill = $('mt4StatusPill');\n  const bar = $('mt4LiveDetailBar');\n  if (mt4) {\n    const isMockAcc = !!(mt4.isMock || mt4.account === '8861092' || mt4.account === '1');\n    const ageSec = Math.max(0, Math.round((Date.now() - mt4.ts) / 1000));\n    const pnlStr = `${mt4.totalPnl >= 0 ? '+' : ''}$${f2(mt4.totalPnl)}`;\n    if (btn) {\n      btn.innerHTML = isMockAcc\n        ? `🧪 MT4演示数据(#${mt4.account} · 非真实账号)`\n        : `🟢 MT4已同步 (#${mt4.account} · 买${mt4.buyCount}层/${f2(mt4.buyLots)}手 · 卖${mt4.sellCount}层/${f2(mt4.sellLots)}手 · ${pnlStr})`;\n      btn.style.borderColor = isMockAcc ? '#f59e0b' : '#10b981';\n      btn.style.color = isMockAcc ? '#fbbf24' : '#34d399';\n    }\n    if (pill) {\n      pill.textContent = isMockAcc\n        ? `🧪 当前为网页模拟演示数据 (假账号 #${mt4.account}) · 等待您真实的 MT4 推送覆盖`\n        : `🟢 真实MT4在线 (${ageSec}秒前更新 · 您的账号 #${mt4.account || '-'})`;\n      pill.className = isMockAcc ? 'pill MIXED' : 'pill RANGE';\n    }\n    if (bar) {\n      const headBadge = isMockAcc\n        ? `🧪 <b style=\"color:#fbbf24\">当前显示的是【网页模拟测试按钮】生成的假演示账号 (#${mt4.account})，不是您的真实 MT4！</b> <button class=\"sm\" onclick=\"clearMt4Data()\" style=\"padding:1px 7px;color:#fb7185;border-color:#fb7185\">🗑️ 立即清除假数据</button><br>`\n        : `🟢 <b>您的真实 MT4 实盘已连接</b> `;\n      bar.innerHTML = headBadge + `(账户 <b>#${mt4.account || '-'}</b> · ${mt4.server || 'Live'} · 品种 <b>${mt4.symbol || 'XAUUSD'}</b> 现价 <b>$${f2(mt4.bid)}</b> · 点差 <b>${mt4.spreadPts || mt4.spread || '-'}</b>) — ` +\n        `余额: <b style=\"color:var(--gold)\">$${f2(mt4.balance)}</b> | 净值: <b>$${f2(mt4.equity)}</b> | 已用预付款: <b>$${f2(mt4.margin)}</b> (${f2(mt4.marginLevel)}%) | ` +\n        `多单 Buy: <b>${mt4.buyCount}层 / ${f2(mt4.buyLots)}手</b> (均价 $${f2(mt4.buyAvgPrice)} · 浮盈 <b style=\"color:${mt4.buyPnl >= 0 ? '#34d399' : '#fb7185'}\">$${f2(mt4.buyPnl)}</b>) | ` +\n        `空单 Sell: <b>${mt4.sellCount}层 / ${f2(mt4.sellLots)}手</b> (均价 $${f2(mt4.sellAvgPrice)} · 浮盈 <b style=\"color:${mt4.sellPnl >= 0 ? '#34d399' : '#fb7185'}\">$${f2(mt4.sellPnl)}</b>) | ` +\n        `挂单: BuyStop ${mt4.buyStopCount || 0}笔 / SellStop ${mt4.sellStopCount || 0}笔`;\n    }\n  } else {\n    if (btn) {\n      btn.innerHTML = `🔌 MT4实盘同步(点击接入)`;\n      btn.style.borderColor = 'rgba(56,189,248,0.55)';\n      btn.style.color = '#38bdf8';\n    }\n    if (pill) {\n      pill.textContent = '等待您的真实 MT4 脚本推送数据...';\n      pill.className = 'pill NEUT';\n    }\n    if (bar) {\n      bar.innerHTML = `⚪ 当前尚未收到您的真实 MT4 终端推送。请确认：① MT4 <b>工具 → 选项 → EA交易</b> 已勾选「允许 WebRequest」并填入 <code style=\"color:#38bdf8\">${window.location.origin}</code>；② 将最新下载的脚本拖到图表上并勾选「允许实时自动交易」。`;\n    }\n  }\n}\n\nfunction buildMql4Source(kind) {\n  const isScript = kind === 'script';\n  const curApiUrl = window.location.origin + '/api/mt4';\n  const vercelApiUrl = window.location.origin.includes('localhost') || window.location.origin.includes('127.0.0.1')\n    ? 'https://gold-range-index-dashboard.vercel.app/api/mt4'\n    : curApiUrl;\n  const localApiUrl = 'http://localhost:3000/api/mt4';\n  const entryLines = isScript ? [\n    '// 脚本只运行一次，这里用循环常驻，直到手动移除脚本/关闭图表/关闭MT4',\n    'void OnStart() {',\n    '   Print(\"🚀 [GoldDashboardSync] 脚本已启动，正在向网站同步您的真实 MT4 账户 #\", AccountNumber());',\n    '   while(!IsStopped()) {',\n    '      PushAccountDataToWeb();',\n    '      Sleep(MathMax(1, SyncIntervalSec) * 1000);',\n    '   }',\n    '   Comment(\"\");',\n    '}'\n  ] : [\n    'int OnInit() {',\n    '   Print(\"🚀 [GoldDashboardSync] EA已启动，正在向网站同步您的真实 MT4 账户 #\", AccountNumber());',\n    '   EventSetTimer(MathMax(1, SyncIntervalSec));',\n    '   PushAccountDataToWeb();',\n    '   return(INIT_SUCCEEDED);',\n    '}',\n    '',\n    'void OnDeinit(const int reason) {',\n    '   EventKillTimer();',\n    '   Comment(\"\");',\n    '}',\n    '',\n    'void OnTick() {',\n    '   // 由 OnTimer 定时触发，避免 Tick 洪峰卡顿',\n    '}',\n    '',\n    'void OnTimer() {',\n    '   PushAccountDataToWeb();',\n    '}'\n  ];\n  return [\n    '//+------------------------------------------------------------------+',\n    isScript ? '//|                              GoldDashboardSyncScript.mq4 (脚本版) |' : '//|                                     GoldDashboardSync.mq4 (EA版) |',\n    '//|        黄金震荡指数 & 马丁EA风控台 — MT4 实盘数据实时同步脚本     |',\n    '//|   100%只读安全保证：绝不调用任何下单/改单/平仓函数，零交易干预！  |',\n    '//+------------------------------------------------------------------+',\n    '#property copyright \"Gold Range Index Dashboard\"',\n    '#property version   \"1.10\"',\n    '#property strict',\n    isScript ? '#property show_inputs' : '',\n    '',\n    'input string DashboardUrl    = \"' + vercelApiUrl + '\"; // 线上Vercel接收地址(需在MT4白名单添加域名)',\n    'input string LocalBackupUrl  = \"' + localApiUrl + '\";  // 本地备用接收地址(如开启本地服务也会同步)',\n    'input int    SyncIntervalSec = 5;               // 同步间隔秒数 (建议 3~10 秒)',\n    'input string GoldSymbolKey   = \"XAU\";           // 黄金品种匹配关键字 (自动兼容 XAUUSD / GOLD)',\n    'input int    MagicFilter     = 0;               // EA魔术号过滤 (0 = 统计账户内所有黄金订单)',\n    'input string SyncToken       = \"\";              // 推送口令 (与 Vercel 环境变量 MT4_TOKEN 一致；未设置则留空)',\n    '',\n    ...entryLines,\n    '',\n    'bool IsGoldSymbol(string sym) {',\n    '   if(sym == Symbol()) return true;',\n    '   if(StringFind(sym, GoldSymbolKey) >= 0) return true;',\n    '   if(StringFind(sym, \"GOLD\") >= 0 || StringFind(sym, \"Gold\") >= 0 || StringFind(sym, \"gold\") >= 0) return true;',\n    '   return false;',\n    '}',\n    '',\n    'void PushAccountDataToWeb() {',\n    '   RefreshRates();',\n    '   int    buyCount = 0, sellCount = 0, buyStopCount = 0, sellStopCount = 0;',\n    '   double buyLots = 0.0, sellLots = 0.0;',\n    '   double buyWeightedPx = 0.0, sellWeightedPx = 0.0;',\n    '   double buyPnl = 0.0, sellPnl = 0.0;',\n    '',\n    '   int total = OrdersTotal();',\n    '   for(int i = 0; i < total; i++) {',\n    '      if(!OrderSelect(i, SELECT_BY_POS, MODE_TRADES)) continue;',\n    '      if(MagicFilter > 0 && OrderMagicNumber() != MagicFilter) continue;',\n    '      if(!IsGoldSymbol(OrderSymbol())) continue;',\n    '',\n    '      int    type = OrderType();',\n    '      double lots = OrderLots();',\n    '      double oPx  = OrderOpenPrice();',\n    '      double pnl  = OrderProfit() + OrderSwap() + OrderCommission();',\n    '',\n    '      if(type == OP_BUY) {',\n    '         buyCount++;',\n    '         buyLots += lots;',\n    '         buyWeightedPx += lots * oPx;',\n    '         buyPnl += pnl;',\n    '      } else if(type == OP_SELL) {',\n    '         sellCount++;',\n    '         sellLots += lots;',\n    '         sellWeightedPx += lots * oPx;',\n    '         sellPnl += pnl;',\n    '      } else if(type == OP_BUYSTOP || type == OP_BUYLIMIT) {',\n    '         buyStopCount++;',\n    '      } else if(type == OP_SELLSTOP || type == OP_SELLLIMIT) {',\n    '         sellStopCount++;',\n    '      }',\n    '   }',\n    '',\n    '   double buyAvg  = (buyLots > 0.0)  ? (buyWeightedPx / buyLots)   : 0.0;',\n    '   double sellAvg = (sellLots > 0.0) ? (sellWeightedPx / sellLots) : 0.0;',\n    '   double totalPnl = buyPnl + sellPnl;',\n    '',\n    '   double bal    = AccountBalance();',\n    '   double eq     = AccountEquity();',\n    '   double mar    = AccountMargin();',\n    '   double freeM  = AccountFreeMargin();',\n    '   double mLevel = AccountInfoDouble(ACCOUNT_MARGIN_LEVEL);',\n    '   int    accNum = AccountNumber();',\n    '   string srv    = AccountServer();',\n    '   StringReplace(srv, \" \", \"_\");',\n    '   StringReplace(srv, \"#\", \"\");',\n    '   StringReplace(srv, \"&\", \"\");',\n    '   string symClean = Symbol();',\n    '   StringReplace(symClean, \" \", \"\");',\n    '   StringReplace(symClean, \"#\", \"\");',\n    '   int    sprd   = (int)MarketInfo(Symbol(), MODE_SPREAD);',\n    '',\n    '   string qs = StringConcatenate(',\n    '      \"?account=\", IntegerToString(accNum),',\n    '      \"&server=\", srv,',\n    '      \"&symbol=\", symClean,',\n    '      \"&bid=\", DoubleToString(Bid, 2),',\n    '      \"&ask=\", DoubleToString(Ask, 2),',\n    '      \"&spread=\", IntegerToString(sprd),',\n    '      \"&balance=\", DoubleToString(bal, 2),',\n    '      \"&equity=\", DoubleToString(eq, 2),',\n    '      \"&margin=\", DoubleToString(mar, 2),',\n    '      \"&freeMargin=\", DoubleToString(freeM, 2),',\n    '      \"&marginLevel=\", DoubleToString(mLevel, 2),',\n    '      \"&buyCount=\", IntegerToString(buyCount),',\n    '      \"&buyLots=\", DoubleToString(buyLots, 2),',\n    '      \"&buyAvgPrice=\", DoubleToString(buyAvg, 2),',\n    '      \"&buyPnl=\", DoubleToString(buyPnl, 2),',\n    '      \"&sellCount=\", IntegerToString(sellCount),',\n    '      \"&sellLots=\", DoubleToString(sellLots, 2),',\n    '      \"&sellAvgPrice=\", DoubleToString(sellAvg, 2),',\n    '      \"&sellPnl=\", DoubleToString(sellPnl, 2),',\n    '      \"&totalPnl=\", DoubleToString(totalPnl, 2),',\n    '      \"&buyStopCount=\", IntegerToString(buyStopCount),',\n    '      \"&sellStopCount=\", IntegerToString(sellStopCount),',\n    '      \"&token=\", SyncToken',\n    '   );',\n    '',\n    '   char postData[];',\n    '   char resultData[];',\n    '   string resultHeaders;',\n    '   ResetLastError();',\n    '   int res = WebRequest(\"GET\", DashboardUrl + qs, \"\", NULL, 3000, postData, 0, resultData, resultHeaders);',\n    '   int err = GetLastError();',\n    '   int resLocal = -1;',\n    '   if(StringLen(LocalBackupUrl) > 0 && LocalBackupUrl != DashboardUrl) {',\n    '      char resData2[]; string resHdr2;',\n    '      resLocal = WebRequest(\"GET\", LocalBackupUrl + qs, \"\", NULL, 1500, postData, 0, resData2, resHdr2);',\n    '   }',\n    '   if(res == 200 || resLocal == 200) {',\n    '      Comment(',\n    '         \"=== 🟢 黄金震荡指数网站 · 您的真实 MT4 实时同步已连接 ===\\\\n\",',\n    '         \"真实账号: #\", accNum, \" (\", srv, \") | 余额: $\", DoubleToString(bal, 2), \" | 净值: $\", DoubleToString(eq, 2), \"\\\\n\",',\n    '         \"买单(Buy): \", buyCount, \"层 / \", DoubleToString(buyLots, 2), \"手 (均价 $\", DoubleToString(buyAvg, 2), \" | 浮盈 $\", DoubleToString(buyPnl, 2), \")\\\\n\",',\n    '         \"卖单(Sell): \", sellCount, \"层 / \", DoubleToString(sellLots, 2), \"手 (均价 $\", DoubleToString(sellAvg, 2), \" | 浮盈 $\", DoubleToString(sellPnl, 2), \")\\\\n\",',\n    '         \"同步状态: 线上Vercel=\", (res == 200 ? \"🟢成功\" : \"⚪未通\"), \" | 本地localhost=\", (resLocal == 200 ? \"🟢成功\" : \"⚪未开\")',\n    '      );',\n    '   } else {',\n    '      Comment(',\n    '         \"=== ⚠️ MT4 同步等待授权 (错误码: \", err, \" / HTTP: \", res, \") ===\\\\n\",',\n    '         \"您的真实账号: #\", accNum, \" | 余额: $\", DoubleToString(bal, 2), \"\\\\n\",',\n    '         \"请在 MT4 顶部菜单点击：【工具(T) -> 选项(O) -> EA交易】\\\\n\",',\n    '         \"勾选 ☑【允许 WebRequest 用于所列 URL】，并在下方列表添加：\\\\n\",',\n    '         \"👉 https://gold-range-index-dashboard.vercel.app\\\\n\",',\n    '         \"👉 http://localhost:3000\"',\n    '      );',\n    '      Print(\"⚠️ [GoldDashboardSync] WebRequest 失败! 错误码=\", err, \" HTTP=\", res, \" 请将 https://gold-range-index-dashboard.vercel.app 添加到 MT4 工具->选项->EA交易->允许WebRequest白名单!\");',\n    '   }',\n    '}'\n  ].join('\\r\\n');\n}\n\nwindow.downloadMt4Script = function(kind) {\n  const isScript = kind === 'script';\n  const code = '\\ufeff' + buildMql4Source(kind);\n  const fname = isScript ? 'GoldDashboardSyncScript.mq4' : 'GoldDashboardSync.mq4';\n  const blob = new Blob([code], { type: 'text/plain;charset=utf-8' });\n  const a = document.createElement('a');\n  a.href = URL.createObjectURL(blob);\n  a.download = fname;\n  document.body.appendChild(a);\n  a.click();\n  a.remove();\n  toast(`已下载 ${fname}！请放入 MT4 的 MQL4/${isScript ? 'Scripts' : 'Experts'} 文件夹`);\n};\n\nwindow.copyMt4ScriptCode = async function(kind) {\n  const code = buildMql4Source(kind);\n  try { await navigator.clipboard.writeText(code); }\n  catch { const ta = document.createElement('textarea'); ta.value = code; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); }\n  toast(`已复制${kind === 'script' ? '脚本版' : 'EA版'}完整 MQL4 源码！可在 MetaEditor 新建${kind === 'script' ? '脚本' : 'EA'}粘贴编译`);\n};\n\nwindow.copyMt4WhitelistUrl = async function() {\n  const url = window.location.origin;\n  try { await navigator.clipboard.writeText(url); }\n  catch { const ta = document.createElement('textarea'); ta.value = url; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); }\n  toast('已复制白名单地址: ' + url);\n};\n\nwindow.simulateMt4Push = async function() {\n  const curPx = (D && D.gold && D.gold.price) ? D.gold.price : 3320.50;\n  const qs = new URLSearchParams({\n    mock: '1',\n    account: '8861092',\n    server: 'Demo-MockTest',\n    symbol: 'XAUUSD',\n    bid: f2(curPx),\n    ask: f2(curPx + 0.22),\n    spread: '22',\n    balance: String(ACC_BAL || 2700),\n    equity: String((ACC_BAL || 2700) - 96.4),\n    margin: '16.80',\n    freeMargin: String((ACC_BAL || 2700) - 113.2),\n    marginLevel: '15497.6',\n    buyCount: '7',\n    buyLots: '0.45',\n    buyAvgPrice: f2(curPx + 2.25),\n    buyPnl: '-101.25',\n    sellCount: '1',\n    sellLots: '0.02',\n    sellAvgPrice: f2(curPx + 2.42),\n    sellPnl: '4.85',\n    totalPnl: '-96.40',\n    buyStopCount: '0',\n    sellStopCount: '1'\n  }).toString();\n  try {\n    const r = await fetch('/api/mt4?' + qs);\n    const j = await r.json();\n    if (j && j.mt4 && D) {\n      D.mt4 = j.mt4;\n      render();\n      toast('🧪 已生成模拟演示数据 (#8861092，非您的真实MT4账号，可随时点「清除测试数据」)');\n    }\n  } catch (e) {\n    toast('模拟推送失败: ' + e.message);\n  }\n};\n\nwindow.clearMt4Data = async function() {\n  try {\n    await fetch('/api/mt4?clear=1');\n    if (D) {\n      delete D.mt4;\n      render();\n    }\n    toast('🗑️ 已清除模拟测试数据！正在等待您的真实 MT4 账户推送...');\n  } catch (e) {\n    toast('清除失败: ' + e.message);\n  }\n};\n\n// ========== MT4 实盘账户深度联动决策引擎 + 长期历史归档/峰值纪念碑/浮亏阶梯统计/入金测算 ==========\nconst MT4_CHART_STATE = { pts: null, mode: 'fast' }; // 'fast' (近2小时·30秒粒度) | 'long' (7~30天长周期·15分钟极值桶)\nconst MT4_DD_TIERS_DEF = [50, 100, 150, 200, 300, 400, 600, 800, 1000, 1500, 2000];\n\nwindow.setMt4CurveMode = function(m) {\n  MT4_CHART_STATE.mode = m;\n  if (D) render();\n};\n\nfunction fmtDuration(sec) {\n  const s = Math.max(0, Math.round(Number(sec) || 0));\n  if (s === 0) return '0秒';\n  if (s < 60) return `${s}秒`;\n  const m = Math.floor(s / 60), rs = s % 60;\n  if (m < 60) return `${m}分${rs > 0 ? rs + '秒' : ''}`;\n  const h = Math.floor(m / 60), rm = m % 60;\n  return `${h}小时${rm}分`;\n}\n\nfunction fmtSecTime(secOrMs) {\n  if (!secOrMs) return '-';\n  const ms = secOrMs < 1e11 ? secOrMs * 1000 : secOrMs;\n  return new Date(ms).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false, month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' }).replace(/\\//g, '-');\n}\n\nfunction getMergedMt4History(mt4) {\n  if (!mt4) return { history: [], historyLong: [], stats: null, initBal: 0 };\n  const acc = mt4.account || 'default';\n  const accFastKey = `gold_mt4_hist_v1_${acc}`;\n  const accLongKey = `gold_mt4_long_v1_${acc}`;\n  const accStatsKey = `gold_mt4_stats_v1_${acc}`;\n  const baseKey = `gold_mt4_base_v1_${acc}`;\n\n  // 1) 合并高频 30 秒序列 (history)\n  let localFast = [];\n  try { localFast = JSON.parse(localStorage.getItem(accFastKey) || '[]') || []; } catch (e) {}\n  const srvFast = Array.isArray(mt4.history) ? mt4.history : [];\n  const fastMap = new Map();\n  const addFastPt = (pt) => {\n    if (!pt || !pt.t) return;\n    const tMs = pt.t < 1e11 ? pt.t * 1000 : pt.t;\n    const bKey = Math.floor(tMs / 30000);\n    const dd = pt.dd != null ? pt.dd : r2(Math.max(0, -(pt.pnl || 0)));\n    const mar = r2(pt.mar || mt4.margin || 0);\n    const prev = fastMap.get(bKey);\n    if (!prev) {\n      fastMap.set(bKey, { ...pt, t: tMs, dd, mar });\n    } else {\n      fastMap.set(bKey, {\n        ...pt,\n        t: Math.max(prev.t, tMs),\n        eq: Math.min(prev.eq ?? pt.eq, pt.eq ?? prev.eq),\n        pnl: Math.min(prev.pnl ?? pt.pnl, pt.pnl ?? prev.pnl),\n        dd: Math.max(prev.dd || 0, dd),\n        mar: Math.max(prev.mar || 0, mar),\n        ml: (prev.ml > 0 && pt.ml > 0) ? Math.min(prev.ml, pt.ml) : (pt.ml || prev.ml || 0)\n      });\n    }\n  };\n  localFast.forEach(addFastPt);\n  srvFast.forEach(addFastPt);\n\n  const curPx = (mt4.buyLots > 0 && mt4.buyAvgPrice > 0)\n    ? r2(mt4.buyAvgPrice + (mt4.buyPnl || 0) / (mt4.buyLots * 100))\n    : (mt4.sellLots > 0 && mt4.sellAvgPrice > 0)\n    ? r2(mt4.sellAvgPrice - (mt4.sellPnl || 0) / (mt4.sellLots * 100))\n    : r2(mt4.bid || 0);\n  const curDd = r2(Math.max(0, -(mt4.totalPnl || 0)));\n  const nowPt = {\n    t: mt4.ts || Date.now(),\n    bal: r2(mt4.balance || 0),\n    eq: r2(mt4.equity || 0),\n    pnl: r2(mt4.totalPnl || 0),\n    dd: curDd,\n    mar: r2(mt4.margin || 0),\n    buyLots: r2(mt4.buyLots || 0),\n    sellLots: r2(mt4.sellLots || 0),\n    netLots: r2((mt4.buyLots || 0) - (mt4.sellLots || 0)),\n    ml: r1(mt4.marginLevel || 0),\n    px: curPx\n  };\n  addFastPt(nowPt);\n  const mergedFast = Array.from(fastMap.values()).sort((a, b) => a.t - b.t).slice(-240);\n  try { localStorage.setItem(accFastKey, JSON.stringify(mergedFast)); } catch (e) {}\n\n  // 2) 合并长周期 15 分钟极值归档序列 (historyLong，最多保存 720 个桶 = 7.5天 ~ 10个交易日)\n  let localLong = [];\n  try { localLong = JSON.parse(localStorage.getItem(accLongKey) || '[]') || []; } catch (e) {}\n  const srvLong = Array.isArray(mt4.historyLong) ? mt4.historyLong : [];\n  const longMap = new Map();\n  const addLongPt = (pt) => {\n    if (!pt || !pt.t) return;\n    const tMs = pt.t < 1e11 ? pt.t * 1000 : pt.t;\n    const bKey = Math.floor(tMs / 900000) * 900000;\n    const ddMax = r2(pt.ddMax != null ? pt.ddMax : (pt.dd != null ? pt.dd : Math.max(0, -(pt.pnl || 0))));\n    const marMax = r2(pt.marMax != null ? pt.marMax : (pt.mar || mt4.margin || 0));\n    const eqMin = r2(pt.eqMin != null ? pt.eqMin : (pt.eq || 0));\n    const prev = longMap.get(bKey);\n    if (!prev) {\n      longMap.set(bKey, { ...pt, t: bKey, eq: eqMin, eqMin, dd: ddMax, ddMax, mar: marMax, marMax });\n    } else {\n      longMap.set(bKey, {\n        ...prev,\n        ...pt,\n        t: bKey,\n        eq: Math.min(prev.eqMin, eqMin),\n        eqMin: Math.min(prev.eqMin, eqMin),\n        pnl: Math.min(prev.pnl || 0, pt.pnl || 0),\n        dd: Math.max(prev.ddMax || 0, ddMax),\n        ddMax: Math.max(prev.ddMax || 0, ddMax),\n        mar: Math.max(prev.marMax || 0, marMax),\n        marMax: Math.max(prev.marMax || 0, marMax),\n        ml: (prev.ml > 0 && pt.ml > 0) ? Math.min(prev.ml, pt.ml) : (pt.ml || prev.ml || 0)\n      });\n    }\n  };\n  localLong.forEach(addLongPt);\n  srvLong.forEach(addLongPt);\n  mergedFast.forEach(addLongPt);\n  const mergedLong = Array.from(longMap.values()).sort((a, b) => a.t - b.t).slice(-720);\n  try { localStorage.setItem(accLongKey, JSON.stringify(mergedLong)); } catch (e) {}\n\n  // 3) 合并与兜底历史峰值 & 浮亏阶梯统计 stats（结合云端 Redis 与本地浏览器缓存取最大值，绝不丢失任何一次历史峰值！）\n  let localStats = null;\n  try { localStats = JSON.parse(localStorage.getItem(accStatsKey) || 'null'); } catch (e) {}\n  let stats = mt4.stats && mt4.stats.peaks ? JSON.parse(JSON.stringify(mt4.stats)) : (localStats || {\n    sinceTs: Math.floor(Date.now() / 1000),\n    totalSamples: mergedFast.length,\n    peaks: {\n      maxDd: { val: 0, pct: 0, ts: 0, px: 0, buyCount: 0, buyLots: 0, sellCount: 0, sellLots: 0, netLots: 0, margin: 0, ml: 0 },\n      maxMargin: { val: 0, ts: 0, px: 0, buyCount: 0, buyLots: 0, sellCount: 0, sellLots: 0, totalLots: 0, dd: 0, ml: 0 },\n      minMarginLevel: { val: 0, freeMargin: 0, ts: 0, px: 0, dd: 0, margin: 0, buyCount: 0, sellCount: 0 },\n      minEquity: { val: mt4.equity || mt4.balance || 0, bal: mt4.balance || 0, ts: Math.floor(Date.now() / 1000), px: curPx, dd: curDd },\n      maxBalance: { val: mt4.balance || 0, ts: Math.floor(Date.now() / 1000) },\n      maxLayers: { val: 0, side: '-', lots: 0, netLots: 0, ts: 0, px: 0, dd: 0, margin: 0 }\n    },\n    tiers: MT4_DD_TIERS_DEF.map((th) => ({ th, waves: 0, recovered: 0, active: false, durSec: 0, maxDd: 0, maxMar: 0, lastTs: 0, lastPx: 0, lastPos: '-' })),\n    activeWave: null,\n    waveLog: []\n  });\n\n  // 与本地缓存的极值做合并保护（取两者中更极端的峰值）\n  if (localStats && localStats.peaks && stats.peaks) {\n    if ((localStats.peaks.maxDd && localStats.peaks.maxDd.val || 0) > (stats.peaks.maxDd.val || 0)) {\n      stats.peaks.maxDd = localStats.peaks.maxDd;\n    }\n    if ((localStats.peaks.maxMargin && localStats.peaks.maxMargin.val || 0) > (stats.peaks.maxMargin.val || 0)) {\n      stats.peaks.maxMargin = localStats.peaks.maxMargin;\n    }\n    if (localStats.peaks.minMarginLevel && localStats.peaks.minMarginLevel.val > 0 && (!stats.peaks.minMarginLevel.val || localStats.peaks.minMarginLevel.val < stats.peaks.minMarginLevel.val)) {\n      stats.peaks.minMarginLevel = localStats.peaks.minMarginLevel;\n    }\n    if (localStats.peaks.minEquity && localStats.peaks.minEquity.val > 0 && (!stats.peaks.minEquity.val || localStats.peaks.minEquity.val < stats.peaks.minEquity.val)) {\n      stats.peaks.minEquity = localStats.peaks.minEquity;\n    }\n    if ((localStats.peaks.maxLayers && localStats.peaks.maxLayers.val || 0) > (stats.peaks.maxLayers.val || 0)) {\n      stats.peaks.maxLayers = localStats.peaks.maxLayers;\n    }\n    if (Array.isArray(localStats.hourly) && localStats.hourly.length === 24) {\n      if (!Array.isArray(stats.hourly) || stats.hourly.length !== 24) {\n        stats.hourly = localStats.hourly;\n      } else {\n        stats.hourly = stats.hourly.map((h, i) => {\n          const l = localStats.hourly[i] || {};\n          const mx = (a, b) => (a || []).map((v, k) => Math.max(v || 0, (b || [])[k] || 0));\n          return { s: Math.max(h.s || 0, l.s || 0), dd: Math.max(h.dd || 0, l.dd || 0), mar: Math.max(h.mar || 0, l.mar || 0), w: mx(h.w, l.w), d: mx(h.d, l.d) };\n        });\n      }\n    }\n    if (Array.isArray(localStats.tiers) && Array.isArray(stats.tiers)) {\n      const lMap = new Map(localStats.tiers.map((x) => [x.th, x]));\n      stats.tiers = stats.tiers.map((t) => {\n        const lt = lMap.get(t.th);\n        if (!lt) return t;\n        return {\n          ...t,\n          waves: Math.max(t.waves || 0, lt.waves || 0),\n          recovered: Math.max(t.recovered || 0, lt.recovered || 0),\n          durSec: Math.max(t.durSec || 0, lt.durSec || 0),\n          maxDd: Math.max(t.maxDd || 0, lt.maxDd || 0),\n          maxMar: Math.max(t.maxMar || 0, lt.maxMar || 0),\n          lastTs: Math.max(t.lastTs || 0, lt.lastTs || 0) || t.lastTs,\n          lastPx: (t.lastTs || 0) >= (lt.lastTs || 0) ? t.lastPx : lt.lastPx,\n          lastPos: (t.lastTs || 0) >= (lt.lastTs || 0) ? t.lastPos : lt.lastPos\n        };\n      });\n    }\n  }\n\n  // 同时用当前帧兜底刷新一次极值\n  const nowSec = Math.floor(Date.now() / 1000);\n  if (curDd > (stats.peaks.maxDd.val || 0)) {\n    stats.peaks.maxDd = {\n      val: curDd,\n      pct: mt4.balance > 0 ? r1((curDd / mt4.balance) * 100) : 0,\n      ts: nowSec,\n      px: curPx,\n      buyCount: mt4.buyCount || 0,\n      buyLots: mt4.buyLots || 0,\n      sellCount: mt4.sellCount || 0,\n      sellLots: mt4.sellLots || 0,\n      netLots: mt4.netLots || 0,\n      margin: mt4.margin || 0,\n      ml: mt4.marginLevel || 0\n    };\n  }\n  if ((mt4.margin || 0) > (stats.peaks.maxMargin.val || 0)) {\n    stats.peaks.maxMargin = {\n      val: mt4.margin || 0,\n      ts: nowSec,\n      px: curPx,\n      buyCount: mt4.buyCount || 0,\n      buyLots: mt4.buyLots || 0,\n      sellCount: mt4.sellCount || 0,\n      sellLots: mt4.sellLots || 0,\n      totalLots: r2((mt4.buyLots || 0) + (mt4.sellLots || 0)),\n      dd: curDd,\n      ml: mt4.marginLevel || 0\n    };\n  }\n  if ((mt4.marginLevel || 0) > 0 && (!stats.peaks.minMarginLevel.val || mt4.marginLevel < stats.peaks.minMarginLevel.val)) {\n    stats.peaks.minMarginLevel = {\n      val: mt4.marginLevel,\n      freeMargin: mt4.freeMargin || 0,\n      ts: nowSec,\n      px: curPx,\n      dd: curDd,\n      margin: mt4.margin || 0,\n      buyCount: mt4.buyCount || 0,\n      sellCount: mt4.sellCount || 0\n    };\n  }\n  const curMaxLayer = Math.max(mt4.buyCount || 0, mt4.sellCount || 0);\n  if (curMaxLayer > (stats.peaks.maxLayers.val || 0)) {\n    stats.peaks.maxLayers = {\n      val: curMaxLayer,\n      side: (mt4.buyCount || 0) >= (mt4.sellCount || 0) ? `多单${mt4.buyCount}层` : `空单${mt4.sellCount}层`,\n      lots: r2((mt4.buyLots || 0) + (mt4.sellLots || 0)),\n      netLots: mt4.netLots || 0,\n      ts: nowSec,\n      px: curPx,\n      dd: curDd,\n      margin: mt4.margin || 0\n    };\n  }\n\n  try { localStorage.setItem(accStatsKey, JSON.stringify(stats)); } catch (e) {}\n\n  let initBal = Number(mt4.initBal) || 0;\n  try {\n    const savedBase = Number(localStorage.getItem(baseKey));\n    if (savedBase > 0) initBal = savedBase;\n    else if (mergedFast.length > 0 && mergedFast[0].bal > 0) {\n      initBal = mergedFast[0].bal;\n      localStorage.setItem(baseKey, String(initBal));\n    }\n  } catch (e) {}\n  if (!initBal && mt4.balance > 0) initBal = mt4.balance;\n\n  return { history: mergedFast, historyLong: mergedLong, stats, initBal };\n}\n\nwindow.resetMt4CurveBase = function() {\n  if (!D || !D.mt4) return;\n  const acc = D.mt4.account || 'default';\n  const curPx = (D.mt4.buyLots > 0 && D.mt4.buyAvgPrice > 0)\n    ? r2(D.mt4.buyAvgPrice + (D.mt4.buyPnl || 0) / (D.mt4.buyLots * 100))\n    : r2(D.mt4.bid || 0);\n  const nowPt = {\n    t: Date.now(),\n    bal: r2(D.mt4.balance || 0),\n    eq: r2(D.mt4.equity || 0),\n    pnl: r2(D.mt4.totalPnl || 0),\n    dd: r2(Math.max(0, -(D.mt4.totalPnl || 0))),\n    mar: r2(D.mt4.margin || 0),\n    buyLots: r2(D.mt4.buyLots || 0),\n    sellLots: r2(D.mt4.sellLots || 0),\n    netLots: r2((D.mt4.buyLots || 0) - (D.mt4.sellLots || 0)),\n    ml: r1(D.mt4.marginLevel || 0),\n    px: curPx\n  };\n  try {\n    localStorage.setItem(`gold_mt4_base_v1_${acc}`, String(r2(D.mt4.balance || 0)));\n    localStorage.setItem(`gold_mt4_hist_v1_${acc}`, JSON.stringify([nowPt]));\n  } catch (e) {}\n  if (D.mt4.history) D.mt4.history = [nowPt];\n  render();\n  toast('✅ 已将当前余额设为收益曲线新起点！（历史峰值与浮亏阶梯统计依然保留）');\n};\n\nwindow.resetMt4AllStats = async function() {\n  if (!D || !D.mt4) return;\n  if (!confirm('确定要清空所有历史浮亏峰值、预付款峰值及分阶段次数统计，从当前时刻重新开始统计吗？')) return;\n  const acc = D.mt4.account || 'default';\n  try {\n    localStorage.removeItem(`gold_mt4_stats_v1_${acc}`);\n    localStorage.removeItem(`gold_mt4_long_v1_${acc}`);\n    await fetch('/api/mt4?resetStats=1');\n    const r = await fetch('/api/mt4');\n    const j = await r.json();\n    if (j && j.mt4) D.mt4 = j.mt4;\n    render();\n    toast('🗑️ 已重置历史峰值与阶梯统计档案！');\n  } catch (e) {\n    toast('重置失败: ' + e.message);\n  }\n};\n\nfunction calcMt4LiveDecision(d, mt4, pb, adjMap, lkNow, martingaleScore) {\n  if (!mt4) return null;\n  const t1 = (d.timeframes && d.timeframes['1M']) || {};\n  const t5 = (d.timeframes && d.timeframes['5M']) || {};\n  const t15 = (d.timeframes && d.timeframes['15M']) || {};\n\n  // 1) 从实盘持仓浮盈亏精确反推 MT4 品种当前实时价格（彻底解决脚本循环未刷 Bid 或经纪商点差差异）\n  let curPx = mt4.bid || (d.gold && d.gold.price) || t1.price || 0;\n  if (mt4.buyLots > 0 && mt4.buyAvgPrice > 0) {\n    const imp = mt4.buyAvgPrice + (mt4.buyPnl || 0) / (mt4.buyLots * 100);\n    if (imp > 1000 && imp < 10000) curPx = r2(imp);\n  } else if (mt4.sellLots > 0 && mt4.sellAvgPrice > 0) {\n    const imp = mt4.sellAvgPrice - (mt4.sellPnl || 0) / (mt4.sellLots * 100);\n    if (imp > 1000 && imp < 10000) curPx = r2(imp);\n  }\n\n  const bal = Math.max(0, Number(mt4.balance) || 0);\n  const eq = Math.max(0, Number(mt4.equity) || bal);\n  const mar = Math.max(0, Number(mt4.margin) || 0);\n  const freeM = Number(mt4.freeMargin != null ? mt4.freeMargin : (eq - mar));\n  const ml = mar > 0 ? r1((eq / mar) * 100) : (Number(mt4.marginLevel) || 9999);\n\n  const buyCount = Number(mt4.buyCount) || 0;\n  const sellCount = Number(mt4.sellCount) || 0;\n  const buyLots = r2(Number(mt4.buyLots) || 0);\n  const sellLots = r2(Number(mt4.sellLots) || 0);\n  const hasPositions = (buyCount + sellCount) > 0 && (buyLots + sellLots) > 0;\n\n  const netSigned = r2(buyLots - sellLots); // >0 净多头, <0 净空头\n  const absNetLots = r2(Math.abs(netSigned));\n  const netLossPerUsd = r2(absNetLots * 100); // 金价每波动 $1，净值波动多少美金\n  const heavySide = netSigned > 0.005 ? 'BUY' : netSigned < -0.005 ? 'SELL' : 'HEDGED';\n  const heavyLayers = heavySide === 'BUY' ? buyCount : heavySide === 'SELL' ? sellCount : Math.max(buyCount, sellCount);\n  const lightLayers = heavySide === 'BUY' ? sellCount : heavySide === 'SELL' ? buyCount : Math.min(buyCount, sellCount);\n\n  const ddUsd = r2(Math.max(0, -Number(mt4.totalPnl || 0)));\n  const ddPct = bal > 0 ? r1((ddUsd / bal) * 100) : 0;\n\n  // 2) 计算 5 大核心生死价格锚点\n  // ① 重仓侧独立回本均价 (heavyBreakEvenPx) & 重仓侧整组止盈目标价 (heavyTpPx)\n  let heavyBreakEvenPx = curPx;\n  let heavyTpPx = curPx;\n  let needHeavyBeMove = 0;\n  let needHeavyTpMove = 0;\n  if (heavySide === 'BUY' && mt4.buyAvgPrice > 0 && buyLots > 0) {\n    heavyBreakEvenPx = r2(mt4.buyAvgPrice);\n    const tpProfitUsd = Math.max(4.0, buyCount * (EA_CFG.tpPerOrder || 3.5));\n    heavyTpPx = r2(heavyBreakEvenPx + tpProfitUsd / (buyLots * 100));\n    needHeavyBeMove = r2(Math.max(0, heavyBreakEvenPx - curPx));\n    needHeavyTpMove = r2(Math.max(0, heavyTpPx - curPx));\n  } else if (heavySide === 'SELL' && mt4.sellAvgPrice > 0 && sellLots > 0) {\n    heavyBreakEvenPx = r2(mt4.sellAvgPrice);\n    const tpProfitUsd = Math.max(4.0, sellCount * (EA_CFG.tpPerOrder || 3.5));\n    heavyTpPx = r2(heavyBreakEvenPx - tpProfitUsd / (sellLots * 100));\n    needHeavyBeMove = r2(Math.max(0, curPx - heavyBreakEvenPx));\n    needHeavyTpMove = r2(Math.max(0, curPx - heavyTpPx));\n  }\n\n  // ② 全账户多空对冲净值回本价 (netBreakEvenPx: 使 totalPnl == 0 即 净值回到余额)\n  let netBreakEvenPx = curPx;\n  let needNetBeMove = 0;\n  if (absNetLots >= 0.01 && mt4.totalPnl < 0 && curPx > 0) {\n    needNetBeMove = r2(Math.abs(mt4.totalPnl) / netLossPerUsd);\n    netBreakEvenPx = netSigned > 0 ? r2(curPx + needNetBeMove) : r2(curPx - needNetBeMove);\n  }\n\n  // ③ 100% 预付款比例锁死价 (margin100Px: 当 Equity == Margin 即 可用预付款 FreeMargin == 0，此时 MT4 将禁止再开任何新单甚至无法手动锁仓！)\n  const freeBufferUsd = Math.max(0, eq - mar);\n  const distToMargin100 = netLossPerUsd > 0 ? r2(freeBufferUsd / netLossPerUsd) : 999;\n  const margin100Px = netSigned > 0 ? r2(curPx - distToMargin100) : netSigned < 0 ? r2(curPx + distToMargin100) : 0;\n\n  // ④ 50% 强平警戒价 (stopOut50Px) 与 20% 极限爆仓价 (stopOut20Px)\n  const remTo50Usd = Math.max(0, eq - mar * 0.50);\n  const distTo50 = netLossPerUsd > 0 ? r2(remTo50Usd / netLossPerUsd) : 999;\n  const stopOut50Px = netSigned > 0 ? r2(curPx - distTo50) : netSigned < 0 ? r2(curPx + distTo50) : 0;\n\n  const remTo20Usd = Math.max(0, eq - mar * 0.20);\n  const distTo20 = netLossPerUsd > 0 ? r2(remTo20Usd / netLossPerUsd) : 999;\n  const stopOut20Px = netSigned > 0 ? r2(curPx - distTo20) : netSigned < 0 ? r2(curPx + distTo20) : 0;\n\n  // ⑤ 紧急手动对冲锁仓触发价 (hedgeTriggerPx): 在到达 100% 预付款锁死线之前预留 1.3$ (或剩余空间的 35%)，确保还有可用预付款开出反向锁仓单！\n  const safeBufferBefore100 = Math.min(distToMargin100 * 0.65, Math.max(0.8, distToMargin100 - 1.3));\n  const hedgeTriggerPx = netSigned > 0 ? r2(curPx - safeBufferBefore100) : netSigned < 0 ? r2(curPx + safeBufferBefore100) : 0;\n\n  // 3) 实盘账户安全健康度评分 (accountHealthScore: 0 ~ 100)\n  let health = 95;\n  if (ddPct > 5) health -= Math.min(42, (ddPct - 5) * 0.95);\n  if (ml < 300) health -= Math.min(35, (300 - ml) * 0.18);\n  if (heavyLayers >= 5) health -= (heavyLayers - 4) * 5;\n  if (distToMargin100 < 5.0) health -= Math.round((5.0 - distToMargin100) * 5);\n  const accountHealthScore = Math.max(5, Math.min(99, Math.round(health)));\n  const healthCls = accountHealthScore >= 65 ? 'RANGE' : accountHealthScore >= 42 ? 'MIXED' : 'TREND';\n\n  // 4) 结合盘面指标 (1M/5M RSI, 震荡指数, 锯齿回调概率) 计算实盘专属解套概率\n  const rsi1 = Number(t1.rsi) || 50;\n  const rsi5 = Number(t5.rsi) || 50;\n  let liveReboundProb = pb.reboundProb || 60;\n  if (heavySide === 'BUY') {\n    // 买单被套盼涨：若 1M/5M RSI 超卖 (<35) 则短线反弹概率上调；若 5M 仍在放量暴跌则下调\n    if (rsi1 < 34 || rsi5 < 36) liveReboundProb += 10;\n    if (needHeavyBeMove > 4.5) liveReboundProb -= Math.min(22, Math.round((needHeavyBeMove - 3.5) * 5));\n  } else if (heavySide === 'SELL') {\n    if (rsi1 > 66 || rsi5 > 64) liveReboundProb += 10;\n    if (needHeavyBeMove > 4.5) liveReboundProb -= Math.min(22, Math.round((needHeavyBeMove - 3.5) * 5));\n  }\n  liveReboundProb = Math.max(12, Math.min(92, Math.round(liveReboundProb)));\n\n  // 5) 生成顶部横幅回本摘要\n  let breakEvenSummary = '当前无净敞口或处于净浮盈安全状态';\n  if (absNetLots >= 0.01 && mt4.totalPnl < 0) {\n    const dirW = netSigned > 0 ? '反弹上涨' : '回落下跌';\n    breakEvenSummary = `金价需<b>${dirW} $${f2(needHeavyBeMove)}</b> 至 <b style=\"color:var(--gold)\">$${f2(heavyBreakEvenPx)}</b> 重仓回本 (涨至 <b style=\"color:#34d399\">$${f2(heavyTpPx)}</b> 整组止盈清仓)`;\n  } else if (mt4.totalPnl >= 0 && hasPositions) {\n    breakEvenSummary = `<b style=\"color:#34d399\">当前实盘篮子整体净浮盈 +$${f2(mt4.totalPnl)}，处于安全收割区</b>`;\n  }\n\n  // 6) 生成卡片 2（针对当前实盘持仓：加仓还是锁仓？）与卡片 3（针对当前实盘浮亏：去留与精确解套价）\n  let posActionBadge = '持仓决策';\n  let posCls = 'RANGE';\n  let posHeadline = '';\n  let posDetail = '';\n  let posFooter = '';\n\n  let escapeCls = 'RANGE';\n  let escapeHeadline = '';\n  let escapeDetail = '';\n  let escapeFooterHtml = '';\n\n  if (heavySide === 'BUY') {\n    const isUrgent = ml < 220 || ddPct >= 28 || heavyLayers >= 6 || distToMargin100 <= 4.0;\n    const isWarn = !isUrgent && (ml < 400 || ddPct >= 15 || heavyLayers >= 4 || martingaleScore < 52);\n    if (isUrgent) {\n      posActionBadge = `🚨 禁加第${buyCount + 1}层多单·备锁仓`;\n      posCls = 'TREND';\n      posHeadline = `🛑 严禁再加多单(已${buyCount}层/${f2(buyLots)}手)！保留空单对冲，跌破 $${f2(hedgeTriggerPx)} 立即锁仓`;\n      posDetail = `• <b>为什么不能再加多单</b>：您当前预付款比例已降至 <b style=\"color:#fb7185\">${f2(ml)}%</b>（可用预付款仅剩 <b>$${f2(freeM)}</b>），净多头敞口 <b>+${f2(absNetLots)}手</b>（金价每跌$1净值亏<b>$${f2(netLossPerUsd)}</b>）。若金价再跌 <b>$${f2(distToMargin100)}</b> 至 <b style=\"color:#fb7185\">$${f2(margin100Px)}</b>，预付款比例将跌破 100%，届时 MT4 将<b>禁止开出任何新单（连对冲锁仓都无法操作）</b>！<br>• <b>立即执行动作</b>：① 保持当前 <b>${sellCount}层空单(${f2(sellLots)}手 · 浮盈+$${f2(mt4.sellPnl)})</b> 顺势对冲回血，切勿过早手动平掉空单；② 若有上方未成交 <code>Buy Stop</code> 挂单立即删除；③ 若金价未能反弹反而向下跌破 <b style=\"color:var(--gold)\">$${f2(hedgeTriggerPx)}</b>，趁还有可用预付款立即手动补开 <b>${f2(absNetLots)}手 空单(Sell)</b> 锁死净敞口！`;\n      posFooter = `⚠️ 铁律：预付款比例低于 200% 时，保住可用预付款（防止跌破 $${f2(margin100Px)} 丧失锁仓权）永远是第一优先级！`;\n    } else if (isWarn) {\n      posActionBadge = `🟡 控层观察·勿追多`;\n      posCls = 'MIXED';\n      posHeadline = `🟡 多单已达 ${buyCount}层(${f2(buyLots)}手)：暂停新开追多挂单，依靠双向网格自然回调清仓`;\n      posDetail = `• 您当前净多头 <b>+${f2(absNetLots)}手</b>（每波动$1盈亏$${f2(netLossPerUsd)}），预付款比例 <b>${f2(ml)}%</b>。建议删除上方未成交的追踪 <code>Buy Stop</code> 挂单，仅让现有 ${buyCount} 层多单等待反弹至 <b>$${f2(heavyTpPx)}</b> 自动止盈。`;\n      posFooter = `💡 下方 100% 预付款警戒线位于 $${f2(margin100Px)}（可再抗 $${f2(distToMargin100)}），50% 强平线位于 $${f2(stopOut50Px)}。`;\n    } else {\n      posActionBadge = `🟢 持仓安全·正常运行`;\n      posCls = 'RANGE';\n      posHeadline = `🟢 当前多单 ${buyCount}层(${f2(buyLots)}手) 仓位极轻，预付款充裕(${f2(ml)}%)，保持 EA 自动运行`;\n      posDetail = `• 净敞口仅 <b>+${f2(absNetLots)}手</b>，金价只需微幅波动至 <b style=\"color:var(--gold)\">$${f2(heavyTpPx)}</b> 即可整组止盈重置，无需人工干预。`;\n      posFooter = `💡 下方安全缓冲空间高达 $${f2(distToMargin100)}（100%预付款线 $${f2(margin100Px)}）。`;\n    }\n\n    // 卡片 3：多单浮亏解套策略\n    if (mt4.totalPnl < 0) {\n      escapeCls = isUrgent ? (liveReboundProb >= 55 ? 'MIXED' : 'TREND') : 'RANGE';\n      escapeHeadline = needHeavyBeMove <= 3.5\n        ? `🎯 距多单回本仅差 $${f2(needHeavyBeMove)}：拿住等反抽至 $${f2(heavyBreakEvenPx)}~$${f2(heavyTpPx)} 减仓/清仓！`\n        : `⚠️ 距多单回本需涨 $${f2(needHeavyBeMove)} (至$${f2(heavyBreakEvenPx)})：逢反抽先减尾层大单降低敞口！`;\n      escapeDetail = `• <b>路线 A（反抽解套/减仓点位）</b>：您 6 层多单加权均价在 <b style=\"color:var(--gold)\">$${f2(heavyBreakEvenPx)}</b>（当前推演价 <b>$${f2(curPx)}</b>，仅需反弹 <b>+$${f2(needHeavyBeMove)}</b> 即可回本；反弹至 <b style=\"color:#34d399\">$${f2(heavyTpPx)}</b> 即可触发 EA 整组止盈清仓）。若金价反抽至 <b>$${f2(curPx + Math.max(1.2, needHeavyBeMove * 0.65))} ~ $${f2(heavyBreakEvenPx)}</b> 附近出现滞涨，建议先手动平掉最重的那 1~2 笔多单，把预付款比例拉回 300% 以上！<br>• <b>路线 B（向下破位保命底线）</b>：下方 <b>100%预付款禁开新单线在 <span style=\"color:#fb7185\">$${f2(margin100Px)}</span></b>（再跌 $${f2(distToMargin100)}）、<b>50%强平线在 <span style=\"color:#fb7185\">$${f2(stopOut50Px)}</span></b>（再跌 $${f2(distTo50)}）。一旦金价向下跌破 <b style=\"color:var(--gold)\">$${f2(hedgeTriggerPx)}</b>，切勿死扛，立即对冲锁仓或砍掉顶层浮亏单！`;\n      escapeFooterHtml = `\n        <span>多单回本价: <b style=\"color:var(--gold)\">$${f2(heavyBreakEvenPx)}</b> (需+$${f2(needHeavyBeMove)})</span>\n        <span>整组止盈价: <b style=\"color:#34d399\">$${f2(heavyTpPx)}</b></span>\n        <span>100%锁死/50%强平: <b style=\"color:#fb7185\">$${f2(margin100Px)} / $${f2(stopOut50Px)}</b></span>`;\n    } else {\n      escapeCls = 'RANGE';\n      escapeHeadline = `🟢 当前实盘整体净浮盈 +$${f2(mt4.totalPnl)}，可随时落袋或等 EA 自动止盈`;\n      escapeDetail = `• 您的多空持仓目前处于净盈利状态（净值 $${f2(eq)} > 余额 $${f2(bal)}），多单止盈目标价 <b>$${f2(heavyTpPx)}</b>。`;\n      escapeFooterHtml = `<span>实时净值: <b style=\"color:#34d399\">$${f2(eq)}</b></span><span>预付款比: <b>${f2(ml)}%</b></span>`;\n    }\n  } else if (heavySide === 'SELL') {\n    const isUrgent = ml < 220 || ddPct >= 28 || heavyLayers >= 6 || distToMargin100 <= 4.0;\n    const isWarn = !isUrgent && (ml < 400 || ddPct >= 15 || heavyLayers >= 4 || martingaleScore < 52);\n    if (isUrgent) {\n      posActionBadge = `🚨 禁加第${sellCount + 1}层空单·备锁仓`;\n      posCls = 'TREND';\n      posHeadline = `🛑 严禁再加空单(已${sellCount}层/${f2(sellLots)}手)！保留多单对冲，突破 $${f2(hedgeTriggerPx)} 立即锁仓`;\n      posDetail = `• <b>为什么不能再加空单</b>：当前预付款比例仅 <b style=\"color:#fb7185\">${f2(ml)}%</b>（可用预付款 <b>$${f2(freeM)}</b>），净空头敞口 <b>${f2(netSigned)}手</b>（金价每涨$1净值亏<b>$${f2(netLossPerUsd)}</b>）。若金价再涨 <b>$${f2(distToMargin100)}</b> 至 <b style=\"color:#fb7185\">$${f2(margin100Px)}</b>，预付款比例将跌破 100% 导致无法开新单！<br>• <b>立即执行动作</b>：① 保留多单(${f2(buyLots)}手)顺势对冲；② 删除下方未成交 <code>Sell Stop</code> 挂单；③ 若金价向上突破 <b style=\"color:var(--gold)\">$${f2(hedgeTriggerPx)}</b>，立即手动补开 <b>${f2(absNetLots)}手 多单(Buy)</b> 锁死净敞口！`;\n      posFooter = `⚠️ 铁律：预付款比例低于 200% 时，严防突破 $${f2(margin100Px)} 丧失对冲锁仓权！`;\n    } else if (isWarn) {\n      posActionBadge = `🟡 控层观察·勿追空`;\n      posCls = 'MIXED';\n      posHeadline = `🟡 空单已达 ${sellCount}层(${f2(sellLots)}手)：暂停新开追空挂单，等回落至 $${f2(heavyTpPx)} 止盈`;\n      posDetail = `• 当前净空头 <b>${f2(netSigned)}手</b>，建议删除下方未成交 <code>Sell Stop</code> 挂单，等金价回落至 <b>$${f2(heavyTpPx)}</b> 触发整组止盈。`;\n      posFooter = `💡 上方 100% 预付款警戒线位于 $${f2(margin100Px)}（可再抗 $${f2(distToMargin100)}），50% 强平线位于 $${f2(stopOut50Px)}。`;\n    } else {\n      posActionBadge = `🟢 持仓安全·正常运行`;\n      posCls = 'RANGE';\n      posHeadline = `🟢 当前空单 ${sellCount}层(${f2(sellLots)}手) 仓位极轻，预付款充裕(${f2(ml)}%)，保持 EA 自动运行`;\n      posDetail = `• 净敞口仅 <b>${f2(netSigned)}手</b>，金价回落至 <b style=\"color:var(--gold)\">$${f2(heavyTpPx)}</b> 即可整组止盈重置。`;\n      posFooter = `💡 上方安全缓冲空间高达 $${f2(distToMargin100)}（100%预付款线 $${f2(margin100Px)}）。`;\n    }\n\n    if (mt4.totalPnl < 0) {\n      escapeCls = isUrgent ? (liveReboundProb >= 55 ? 'MIXED' : 'TREND') : 'RANGE';\n      escapeHeadline = needHeavyBeMove <= 3.5\n        ? `🎯 距空单回本仅差 $${f2(needHeavyBeMove)}：拿住等回落至 $${f2(heavyBreakEvenPx)}~$${f2(heavyTpPx)} 清仓！`\n        : `⚠️ 距空单回本需跌 $${f2(needHeavyBeMove)} (至$${f2(heavyBreakEvenPx)})：逢回调先减尾层大单降低敞口！`;\n      escapeDetail = `• <b>路线 A（回调解套/减仓点位）</b>：空单加权均价在 <b style=\"color:var(--gold)\">$${f2(heavyBreakEvenPx)}</b>（当前推演价 <b>$${f2(curPx)}</b>，仅需回落 <b>-$${f2(needHeavyBeMove)}</b> 即可回本；跌至 <b style=\"color:#34d399\">$${f2(heavyTpPx)}</b> 整组止盈）。<br>• <b>路线 B（向上破位保命底线）</b>：上方 <b>100%预付款禁开新单线在 <span style=\"color:#fb7185\">$${f2(margin100Px)}</span></b>、<b>50%强平线在 <span style=\"color:#fb7185\">$${f2(stopOut50Px)}</span></b>。一旦向上突破 <b style=\"color:var(--gold)\">$${f2(hedgeTriggerPx)}</b> 立即锁仓！`;\n      escapeFooterHtml = `\n        <span>空单回本价: <b style=\"color:var(--gold)\">$${f2(heavyBreakEvenPx)}</b> (需-$${f2(needHeavyBeMove)})</span>\n        <span>整组止盈价: <b style=\"color:#34d399\">$${f2(heavyTpPx)}</b></span>\n        <span>100%锁死/50%强平: <b style=\"color:#fb7185\">$${f2(margin100Px)} / $${f2(stopOut50Px)}</b></span>`;\n    } else {\n      escapeCls = 'RANGE';\n      escapeHeadline = `🟢 当前实盘整体净浮盈 +$${f2(mt4.totalPnl)}，处于安全盈利区`;\n      escapeDetail = `• 空单整组止盈目标价 <b>$${f2(heavyTpPx)}</b>。`;\n      escapeFooterHtml = `<span>实时净值: <b style=\"color:#34d399\">$${f2(eq)}</b></span><span>预付款比: <b>${f2(ml)}%</b></span>`;\n    }\n  } else {\n    posActionBadge = hasPositions ? '⚖️ 完全锁仓中' : '🟢 空仓待命';\n    posCls = 'RANGE';\n    posHeadline = hasPositions ? `⚖️ 当前多空手数完全相等 (${f2(buyLots)}手 = ${f2(sellLots)}手)，净值已锁死` : `🟢 当前实盘空仓无持仓，可按盘面指数择机开启 EA`;\n    posDetail = hasPositions ? `• 多空完全对冲，金价无论涨跌净值几乎不变，请等待震荡指数回到 ≥60 分且出现明确拐点后再分批解锁。` : `• 账户余额 $${f2(bal)} 100% 安全待命。`;\n    posFooter = `💡 保持关注 1M/5M 震荡指数与重磅数据红灯锁。`;\n    escapeCls = 'RANGE';\n    escapeHeadline = hasPositions ? `⚖️ 锁仓状态下无单边爆仓风险` : `🟢 当前无被套持仓`;\n    escapeDetail = `• 请在波幅收窄、震荡指数 ≥60 分时先平顺势盈利侧并结合回调解套。`;\n    escapeFooterHtml = `<span>余额: <b>$${f2(bal)}</b></span><span>净值: <b>$${f2(eq)}</b></span>`;\n  }\n\n  return {\n    curPx,\n    bal,\n    eq,\n    mar,\n    freeM,\n    ml,\n    hasPositions,\n    netSigned,\n    absNetLots,\n    netLossPerUsd,\n    heavySide,\n    heavyLayers,\n    lightLayers,\n    ddUsd,\n    ddPct,\n    heavyBreakEvenPx,\n    heavyTpPx,\n    needHeavyBeMove,\n    needHeavyTpMove,\n    netBreakEvenPx,\n    needNetBeMove,\n    margin100Px,\n    distToMargin100,\n    stopOut50Px,\n    distTo50,\n    stopOut20Px,\n    distTo20,\n    hedgeTriggerPx,\n    accountHealthScore,\n    healthCls,\n    liveReboundProb,\n    breakEvenSummary,\n    posActionBadge,\n    posCls,\n    posHeadline,\n    posDetail,\n    posFooter,\n    escapeCls,\n    escapeHeadline,\n    escapeDetail,\n    escapeFooterHtml\n  };\n}\n\nfunction buildMt4AccountChartSvg(hist, mt4, mt4Dec, initBal, stats, mode) {\n  if (!hist || !hist.length) return '<div class=\"mut\">正在采集 MT4 实盘余额与净值时序数据...</div>';\n  const arr = hist.length === 1\n    ? [{ ...hist[0], t: hist[0].t - 30000 }, hist[0]]\n    : hist;\n\n  const W = 1200, H = 450, L = 68, R = 156, T = 26, B = 38;\n  const cw = W - L - R, n = arr.length;\n  const xOf = (i) => L + (i / Math.max(1, n - 1)) * cw;\n\n  // 上面板 (topTop ~ topBot): 账户余额 (Balance) + 实时净值 (Equity) + 已用预付款曲线 (Margin 橙线) + 历史最高预付款虚线\n  // 下面板 (botTop ~ botBot): 综合净收益折线 + 浮动盈亏/最大浮亏柱状图 + 历史最大浮亏峰值红线\n  const topTop = T, topH = 215, topBot = topTop + topH;\n  const botTop = topBot + 38, botH = H - B - botTop, botBot = botTop + botH;\n\n  const curMar = Number(mt4.margin) || 0;\n  const pkMaxMar = (stats && stats.peaks && stats.peaks.maxMargin && stats.peaks.maxMargin.val) || curMar;\n  const pkMaxDd = (stats && stats.peaks && stats.peaks.maxDd && stats.peaks.maxDd.val) || 0;\n\n  let vMin = Infinity, vMax = -Infinity;\n  arr.forEach((p) => {\n    const pMar = p.marMax != null ? p.marMax : (p.mar || 0);\n    const hi = Math.max(p.bal || 0, p.eq || 0, initBal || 0, pMar, pkMaxMar);\n    const lo = Math.min(p.bal || 0, p.eq || 0, initBal || 0, pMar > 0 ? pMar : Infinity);\n    if (hi > vMax) vMax = hi;\n    if (lo < vMin) vMin = lo;\n  });\n  if (!isFinite(vMin) || !isFinite(vMax) || vMax <= vMin) {\n    vMax = (mt4.balance || 100) + 20;\n    vMin = Math.max(0, (mt4.equity || 80) - 20);\n  }\n  const padV = Math.max(5, (vMax - vMin) * 0.14);\n  vMax += padV;\n  vMin = Math.max(0, vMin - padV);\n\n  let pMin = Math.min(0, -10, -pkMaxDd), pMax = Math.max(0, 10);\n  arr.forEach((p) => {\n    const netRet = r2((p.eq || 0) - initBal);\n    const fl = p.ddMax != null ? -p.ddMax : r2(p.pnl || 0);\n    pMax = Math.max(pMax, netRet, fl);\n    pMin = Math.min(pMin, netRet, fl);\n  });\n  const padP = Math.max(5, (pMax - pMin) * 0.15);\n  pMax += padP;\n  pMin -= padP;\n\n  const yTop = (v) => topTop + (1 - (v - vMin) / Math.max(1e-6, vMax - vMin)) * topH;\n  const yBot = (v) => botTop + (1 - (v - pMin) / Math.max(1e-6, pMax - pMin)) * botH;\n\n  MT4_CHART_STATE.pts = { arr, W, H, L, R, T, B, cw, topTop, topH, topBot, botTop, botH, botBot, vMin, vMax, pMin, pMax, initBal, mode };\n\n  const topTicks = [0, 0.25, 0.5, 0.75, 1].map((f) => {\n    const val = vMin + (1 - f) * (vMax - vMin);\n    const y = (topTop + f * topH).toFixed(1);\n    return `<line x1=\"${L}\" y1=\"${y}\" x2=\"${W - R}\" y2=\"${y}\" stroke=\"#262d3b\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/>\n      <text x=\"${L - 8}\" y=\"${+y + 4}\" text-anchor=\"end\" fill=\"#94a3b8\" font-size=\"11\">$${val.toFixed(1)}</text>`;\n  }).join('');\n\n  // 100% 预付款警戒线 & 历史最高预付款峰值线\n  let marginLineSvg = '';\n  if (curMar > 0 && curMar >= vMin && curMar <= vMax) {\n    const ym = yTop(curMar).toFixed(1);\n    marginLineSvg += `\n      <line x1=\"${L}\" y1=\"${ym}\" x2=\"${W - R}\" y2=\"${ym}\" stroke=\"#f43f5e\" stroke-width=\"1.4\" stroke-dasharray=\"5,4\"/>\n      <text x=\"${W - R + 6}\" y=\"${+ym + 4}\" fill=\"#fb7185\" font-size=\"11\" font-weight=\"700\">🚨 当前预付款 $${curMar.toFixed(2)}</text>`;\n  }\n  if (pkMaxMar > 0 && Math.abs(pkMaxMar - curMar) > 3 && pkMaxMar >= vMin && pkMaxMar <= vMax) {\n    const ypk = yTop(pkMaxMar).toFixed(1);\n    marginLineSvg += `\n      <line x1=\"${L}\" y1=\"${ypk}\" x2=\"${W - R}\" y2=\"${ypk}\" stroke=\"#fb923c\" stroke-width=\"1.2\" stroke-dasharray=\"2,3\"/>\n      <text x=\"${W - R + 6}\" y=\"${+ypk + 4}\" fill=\"#fb923c\" font-size=\"10.5\" font-weight=\"700\">🏦 峰值预付款 $${pkMaxMar.toFixed(2)}</text>`;\n  }\n\n  const balPts = arr.map((p, i) => `${xOf(i).toFixed(1)},${yTop(p.bal).toFixed(1)}`).join(' ');\n  const eqPts = arr.map((p, i) => `${xOf(i).toFixed(1)},${yTop(p.eq).toFixed(1)}`).join(' ');\n  const marPts = arr.map((p, i) => `${xOf(i).toFixed(1)},${yTop(p.marMax != null ? p.marMax : (p.mar || 0)).toFixed(1)}`).join(' ');\n  const eqArea = `${xOf(0).toFixed(1)},${topBot} ${eqPts} ${xOf(n - 1).toFixed(1)},${topBot}`;\n\n  const last = arr[n - 1];\n  const lastX = xOf(n - 1).toFixed(1);\n  const lastBalY = yTop(last.bal).toFixed(1);\n  const lastEqY = yTop(last.eq).toFixed(1);\n  const eqColor = last.eq >= last.bal ? '#34d399' : '#38bdf8';\n\n  // 下面板：0轴 + 浮动盈亏柱状图 + 综合净收益折线 + 历史最大浮亏峰值水平红线\n  const yZero = yBot(0).toFixed(1);\n  const botTicks = [0, 0.5, 1].map((f) => {\n    const val = pMin + (1 - f) * (pMax - pMin);\n    const y = (botTop + f * botH).toFixed(1);\n    return `<line x1=\"${L}\" y1=\"${y}\" x2=\"${W - R}\" y2=\"${y}\" stroke=\"#262d3b\" stroke-width=\"1\" stroke-dasharray=\"3,3\"/>\n      <text x=\"${L - 8}\" y=\"${+y + 4}\" text-anchor=\"end\" fill=\"#94a3b8\" font-size=\"11\">${val >= 0 ? '+' : ''}$${val.toFixed(1)}</text>`;\n  }).join('');\n\n  let maxDdLineSvg = '';\n  if (pkMaxDd > 0 && -pkMaxDd >= pMin && -pkMaxDd <= pMax) {\n    const ydd = yBot(-pkMaxDd).toFixed(1);\n    maxDdLineSvg = `\n      <line x1=\"${L}\" y1=\"${ydd}\" x2=\"${W - R}\" y2=\"${ydd}\" stroke=\"#f43f5e\" stroke-width=\"1.3\" stroke-dasharray=\"4,3\"/>\n      <text x=\"${W - R + 6}\" y=\"${+ydd + 4}\" fill=\"#fb7185\" font-size=\"10.5\" font-weight=\"800\">🔥 浮亏峰值 -$${pkMaxDd.toFixed(2)}</text>`;\n  }\n\n  const bw = Math.max(2.5, Math.min(9, cw / Math.max(8, n) * 0.62));\n  const pnlBars = arr.map((p, i) => {\n    const x = xOf(i);\n    const fl = mode === 'long' && p.ddMax != null ? -p.ddMax : (p.pnl || 0);\n    const yVal = yBot(fl);\n    const y0 = yBot(0);\n    const yt = Math.min(yVal, y0).toFixed(1);\n    const bh = Math.max(1.5, Math.abs(yVal - y0)).toFixed(1);\n    const col = fl >= 0 ? '#34d399' : '#fb7185';\n    return `<rect x=\"${(x - bw / 2).toFixed(1)}\" y=\"${yt}\" width=\"${bw.toFixed(1)}\" height=\"${bh}\" fill=\"${col}\" opacity=\"0.4\" rx=\"1\"/>`;\n  }).join('');\n\n  const retPts = arr.map((p, i) => `${xOf(i).toFixed(1)},${yBot((p.eq || 0) - initBal).toFixed(1)}`).join(' ');\n  const closedPts = arr.map((p, i) => `${xOf(i).toFixed(1)},${yBot((p.bal || 0) - initBal).toFixed(1)}`).join(' ');\n  const lastRet = r2((last.eq || 0) - initBal);\n  const lastClosed = r2((last.bal || 0) - initBal);\n\n  // X轴时间刻度\n  const xStep = Math.max(1, Math.floor((n - 1) / 6));\n  let xTicks = '';\n  for (let i = 0; i < n; i += xStep) {\n    const x = xOf(i).toFixed(1);\n    const dObj = new Date(arr[i].t);\n    const tm = mode === 'long'\n      ? dObj.toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false, month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }).replace(/\\//g, '-')\n      : dObj.toLocaleTimeString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false });\n    xTicks += `<line x1=\"${x}\" y1=\"${topTop}\" x2=\"${x}\" y2=\"${botBot}\" stroke=\"#262d3b\" stroke-width=\"1\" opacity=\"0.45\"/>\n      <text x=\"${x}\" y=\"${H - 12}\" text-anchor=\"middle\" fill=\"#94a3b8\" font-size=\"11\">${tm}</text>`;\n  }\n\n  return `<svg class=\"big-svg\" id=\"svg-mt4-curve\" style=\"height:415px;min-height:370px;max-height:460px\" viewBox=\"0 0 ${W} ${H}\" preserveAspectRatio=\"none\" onmousemove=\"onMt4ChartMove(event)\" onmouseleave=\"onMt4ChartLeave()\">\n    <defs>\n      <linearGradient id=\"mt4EqGrad\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n        <stop offset=\"0%\" stop-color=\"${eqColor}\" stop-opacity=\"0.28\"/>\n        <stop offset=\"100%\" stop-color=\"${eqColor}\" stop-opacity=\"0.02\"/>\n      </linearGradient>\n    </defs>\n\n    <!-- 上面板：余额 & 净值 & 已用预付款曲线 -->\n    <text x=\"${L + 6}\" y=\"${topTop - 7}\" fill=\"#fbbf24\" font-size=\"12.5\" font-weight=\"bold\">💰 账户余额(金实线) vs 实时最低净值(青蓝线) vs 已用预付款占用(橙虚线)  [${mode === 'long' ? `长周期15m极值归档 · ${hist.length}个桶` : `高频30s流 · ${hist.length}个快照`}]</text>\n    ${topTicks}\n    ${marginLineSvg}\n    <polygon points=\"${eqArea}\" fill=\"url(#mt4EqGrad)\"/>\n    <polyline fill=\"none\" stroke=\"#fb923c\" stroke-width=\"1.6\" stroke-dasharray=\"3,2\" points=\"${marPts}\" opacity=\"0.88\"/>\n    <polyline fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"2.6\" points=\"${balPts}\"/>\n    <polyline fill=\"none\" stroke=\"${eqColor}\" stroke-width=\"2.4\" points=\"${eqPts}\"/>\n    <circle cx=\"${lastX}\" cy=\"${lastBalY}\" r=\"5\" fill=\"#fbbf24\" stroke=\"#0f172a\" stroke-width=\"1.5\"/>\n    <circle cx=\"${lastX}\" cy=\"${lastEqY}\" r=\"5.5\" fill=\"${eqColor}\" stroke=\"#0f172a\" stroke-width=\"1.5\"/>\n    <text x=\"${W - R + 6}\" y=\"${+lastBalY + 4}\" fill=\"#fbbf24\" font-size=\"11.5\" font-weight=\"800\">余额 $${last.bal.toFixed(2)}</text>\n    <text x=\"${W - R + 6}\" y=\"${Math.abs(lastEqY - lastBalY) < 14 ? (+lastBalY + 18) : (+lastEqY + 4)}\" fill=\"${eqColor}\" font-size=\"11.5\" font-weight=\"800\">净值 $${last.eq.toFixed(2)}</text>\n\n    <!-- 下面板：实时收益曲线 & 浮亏柱状图 & 浮亏峰值红线 -->\n    <line x1=\"${L}\" y1=\"${topBot + 14}\" x2=\"${W - R}\" y2=\"${topBot + 14}\" stroke=\"#262d3b\" stroke-width=\"1.5\"/>\n    <text x=\"${L + 6}\" y=\"${botTop - 7}\" fill=\"#38bdf8\" font-size=\"12.5\" font-weight=\"bold\">📈 收益与浮亏极值轨迹：已落袋收益(金虚线 ${lastClosed >= 0 ? '+' : ''}$${lastClosed.toFixed(2)}) · 综合净收益(紫线 ${lastRet >= 0 ? '+' : ''}$${lastRet.toFixed(2)}) · 浮动盈亏(红绿柱) · 历史最大浮亏(-$${pkMaxDd.toFixed(2)})</text>\n    ${botTicks}\n    <line x1=\"${L}\" y1=\"${yZero}\" x2=\"${W - R}\" y2=\"${yZero}\" stroke=\"#64748b\" stroke-width=\"1.2\" stroke-dasharray=\"4,2\"/>\n    ${maxDdLineSvg}\n    ${pnlBars}\n    <polyline fill=\"none\" stroke=\"#fbbf24\" stroke-width=\"1.8\" stroke-dasharray=\"4,3\" points=\"${closedPts}\"/>\n    <polyline fill=\"none\" stroke=\"#a78bfa\" stroke-width=\"2.2\" points=\"${retPts}\"/>\n    <text x=\"${W - R + 6}\" y=\"${yBot(lastClosed) + 4}\" fill=\"#fbbf24\" font-size=\"11\" font-weight=\"700\">已落袋 ${lastClosed >= 0 ? '+' : ''}$${lastClosed.toFixed(2)}</text>\n    <text x=\"${W - R + 6}\" y=\"${Math.abs(yBot(lastRet) - yBot(lastClosed)) < 14 ? (yBot(lastClosed) + 17) : (yBot(lastRet) + 4)}\" fill=\"#a78bfa\" font-size=\"11\" font-weight=\"700\">净收益 ${lastRet >= 0 ? '+' : ''}$${lastRet.toFixed(2)}</text>\n    ${xTicks}\n\n    <!-- 十字准星浮窗 -->\n    <g id=\"xh-mt4\" style=\"display:none;pointer-events:none\">\n      <line id=\"xh-mt4-v\" x1=\"0\" y1=\"${topTop}\" x2=\"0\" y2=\"${botBot}\" stroke=\"#ffffff\" stroke-width=\"1\" stroke-dasharray=\"4,4\" opacity=\"0.85\"/>\n      <circle id=\"xh-mt4-bal\" cx=\"0\" cy=\"0\" r=\"5.5\" fill=\"#fbbf24\" stroke=\"#fff\" stroke-width=\"1.8\"/>\n      <circle id=\"xh-mt4-eq\" cx=\"0\" cy=\"0\" r=\"5.5\" fill=\"#38bdf8\" stroke=\"#fff\" stroke-width=\"1.8\"/>\n      <rect id=\"xh-mt4-box\" x=\"0\" y=\"0\" width=\"510\" height=\"70\" rx=\"6\" fill=\"rgba(15,18,24,0.95)\" stroke=\"#38bdf8\" stroke-width=\"1.2\"/>\n      <text id=\"xh-mt4-t1\" x=\"0\" y=\"0\" fill=\"#fbbf24\" font-size=\"12.5\" font-weight=\"bold\"></text>\n      <text id=\"xh-mt4-t2\" x=\"0\" y=\"0\" fill=\"#38bdf8\" font-size=\"12.5\" font-weight=\"bold\"></text>\n      <text id=\"xh-mt4-t3\" x=\"0\" y=\"0\" fill=\"#cbd5e1\" font-size=\"12\"></text>\n    </g>\n  </svg>`;\n}\n\nwindow.onMt4ChartMove = function(ev) {\n  const cfg = MT4_CHART_STATE.pts;\n  const svg = $('svg-mt4-curve'), g = $('xh-mt4');\n  if (!cfg || !svg || !g) return;\n  const rect = svg.getBoundingClientRect();\n  const mx = (ev.clientX - rect.left) / rect.width * cfg.W;\n  const n = cfg.arr.length;\n  const idx = Math.max(0, Math.min(n - 1, Math.round((mx - cfg.L) / cfg.cw * Math.max(1, n - 1))));\n  const p = cfg.arr[idx];\n  const x = cfg.L + (idx / Math.max(1, n - 1)) * cfg.cw;\n  const yBal = cfg.topTop + (1 - (p.bal - cfg.vMin) / Math.max(1e-6, cfg.vMax - cfg.vMin)) * cfg.topH;\n  const yEq = cfg.topTop + (1 - (p.eq - cfg.vMin) / Math.max(1e-6, cfg.vMax - cfg.vMin)) * cfg.topH;\n\n  g.style.display = 'block';\n  $('xh-mt4-v').setAttribute('x1', x);\n  $('xh-mt4-v').setAttribute('x2', x);\n  $('xh-mt4-bal').setAttribute('cx', x);\n  $('xh-mt4-bal').setAttribute('cy', yBal);\n  $('xh-mt4-eq').setAttribute('cx', x);\n  $('xh-mt4-eq').setAttribute('cy', yEq);\n\n  const boxW = 515, boxH = 70;\n  const bx = x + 16 + boxW > cfg.W - cfg.R ? Math.max(cfg.L + 4, x - boxW - 16) : x + 16;\n  const by = cfg.topTop + 8;\n  const box = $('xh-mt4-box'), t1 = $('xh-mt4-t1'), t2 = $('xh-mt4-t2'), t3 = $('xh-mt4-t3');\n  box.setAttribute('x', bx); box.setAttribute('y', by);\n  t1.setAttribute('x', bx + 10); t1.setAttribute('y', by + 20);\n  t2.setAttribute('x', bx + 10); t2.setAttribute('y', by + 41);\n  t3.setAttribute('x', bx + 10); t3.setAttribute('y', by + 60);\n\n  const tm = new Date(p.t).toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false });\n  const closedPnl = r2((p.bal || 0) - cfg.initBal);\n  const netRet = r2((p.eq || 0) - cfg.initBal);\n  const pMar = p.marMax != null ? p.marMax : (p.mar || 0);\n  t1.textContent = `🕒 ${tm}  |  余额: $${f2(p.bal)}  |  最低净值: $${f2(p.eq)}  |  已用预付款: $${f2(pMar)}  |  金价: $${f2(p.px)}`;\n  t2.textContent = `💰 已平仓落袋: ${closedPnl >= 0 ? '+' : ''}$${f2(closedPnl)}  |  浮动盈亏: ${p.pnl >= 0 ? '+' : ''}$${f2(p.pnl)}  |  综合净收益: ${netRet >= 0 ? '+' : ''}$${f2(netRet)}`;\n  t3.textContent = `📊 持仓敞口: 买${f2(p.buyLots)}手 / 卖${f2(p.sellLots)}手 (净敞口 ${p.netLots >= 0 ? '+' : ''}${f2(p.netLots)}手)  |  最低预付款比例: ${f2(p.ml)}%`;\n};\n\nwindow.onMt4ChartLeave = function() {\n  const g = $('xh-mt4');\n  if (g) g.style.display = 'none';\n};\n\n// ========== 24 小时 (北京时间) 浮亏高危时段热力表：行=浮亏阶梯，列=小时，一眼看出哪些时段容易被深套 ==========\nfunction buildMt4HourHeatmap(stats, mt4Dec) {\n  const hourly = (stats && Array.isArray(stats.hourly) && stats.hourly.length === 24) ? stats.hourly : null;\n  if (!hourly) return '<div class=\"xs mut\">时段档案正在建立中，下一次实盘推送后即开始按小时累计…</div>';\n  const TH = MT4_DD_TIERS_DEF;\n  const bjNowH = new Date(Date.now() + 8 * 3600000).getUTCHours();\n  const bjNowM = new Date(Date.now() + 8 * 3600000).getUTCMinutes();\n  const sessOf = (h) => h >= 8 && h < 15 ? ['亚盘', '#38bdf8'] : h >= 15 && h < 20 ? ['欧盘', '#a78bfa'] : h >= 20 || h < 4 ? ['美盘', '#fb923c'] : ['清淡', '#64748b'];\n\n  // 每小时风险分：阶梯越深权重越高 (独立发生次数×th/50) + 峰值浮亏/50 + 深套停留分钟/10\n  const rows = hourly.map((h, i) => {\n    const w = h.w || [], dd = h.d || [];\n    let score = 0, w100 = 0, w200 = 0, dur100 = 0;\n    TH.forEach((th, k) => {\n      score += (w[k] || 0) * (th / 50) + (dd[k] || 0) / 600 * (th / 100);\n      if (th >= 100) { w100 += (w[k] || 0); dur100 += (dd[k] || 0); }\n      if (th >= 200) w200 += (w[k] || 0);\n    });\n    score += (h.dd || 0) / 50;\n    return { hour: i, s: h.s || 0, dd: h.dd || 0, mar: h.mar || 0, w, d: dd, score: +score.toFixed(1), w100, w200, dur100 };\n  });\n  const monitored = rows.filter((r) => r.s >= 60);\n  const maxScore = Math.max(1, ...rows.map((r) => r.score));\n  const level = (r) => {\n    if (r.s < 60) return { t: '无数据', c: '#475569', e: '⚪' };\n    if (r.score >= maxScore * 0.66 && r.score >= 3) return { t: '高危', c: '#f43f5e', e: '⛔' };\n    if (r.score >= maxScore * 0.33 && r.score >= 1.5) return { t: '警惕', c: '#f59e0b', e: '🟠' };\n    if (r.score > 0.3) return { t: '轻微', c: '#fbbf24', e: '🟡' };\n    return { t: '安全', c: '#34d399', e: '🟢' };\n  };\n  const rank = monitored.filter((r) => r.score > 0.3).sort((a, b) => b.score - a.score).slice(0, 6);\n  const fmtRange = (h) => String(h).padStart(2, '0') + ':00-' + String((h + 1) % 24).padStart(2, '0') + ':00';\n\n  const head = rows.map((r) => {\n    const [sn, sc] = sessOf(r.hour);\n    return '<th style=\"padding:3px 2px;text-align:center;min-width:34px;border-bottom:2px solid ' + sc + ';' + (r.hour === bjNowH ? 'background:rgba(56,189,248,0.25);' : '') + '\"><div style=\"font-size:11px\">' + String(r.hour).padStart(2, '0') + '</div><div style=\"font-size:9px;color:' + sc + '\">' + sn + '</div></th>';\n  }).join('');\n\n  const tierRows = TH.map((th, k) => {\n    const cells = rows.map((r) => {\n      const wv = r.w[k] || 0, dv = r.d[k] || 0;\n      let bg, txt, col = '#e2e8f0';\n      if (r.s < 60) { bg = 'rgba(71,85,105,0.12)'; txt = '·'; col = '#475569'; }\n      else if (wv === 0 && dv === 0) { bg = 'rgba(16,185,129,0.08)'; txt = '0'; col = '#4b5d52'; }\n      else {\n        const inten = Math.min(1, 0.25 + wv * 0.18 + dv / 3600);\n        bg = (th >= 400 ? 'rgba(244,63,94,' : th >= 200 ? 'rgba(249,115,22,' : 'rgba(245,158,11,') + inten.toFixed(2) + ')';\n        txt = wv > 0 ? String(wv) : '~'; col = '#fff';\n      }\n      const tip = r.s < 60 ? '该小时尚无持仓监测数据' : (String(r.hour).padStart(2, '0') + '时 浮亏≥$' + th + ': 独立发生' + wv + '次, 累计停留' + fmtDuration(dv));\n      return '<td title=\"' + tip + '\" style=\"text-align:center;padding:3px 0;font-size:12px;font-weight:800;background:' + bg + ';color:' + col + ';' + (r.hour === bjNowH ? 'outline:1px solid #38bdf8;' : '') + '\">' + txt + '</td>';\n    }).join('');\n    return '<tr><td style=\"padding:3px 8px;white-space:nowrap;font-weight:800;color:' + (th >= 400 ? '#fb7185' : th >= 200 ? '#fb923c' : '#fbbf24') + '\">浮亏 ≥ $' + th + '</td>' + cells + '</tr>';\n  }).join('');\n\n  const numRow = (label, fn, colFn) => '<tr><td style=\"padding:3px 8px;white-space:nowrap;font-size:11.5px;color:#94a3b8\">' + label + '</td>' + rows.map((r) => '<td style=\"text-align:center;font-size:11px;padding:3px 0;' + (r.hour === bjNowH ? 'outline:1px solid #38bdf8;' : '') + 'color:' + colFn(r) + '\">' + fn(r) + '</td>').join('') + '</tr>';\n  const ddRow = numRow('时段最大浮亏 $', (r) => r.s < 60 ? '·' : (r.dd > 0 ? Math.round(r.dd) : '0'), (r) => r.dd >= 200 ? '#fb7185' : r.dd >= 100 ? '#fb923c' : r.dd > 0 ? '#fbbf24' : '#64748b');\n  const marRow = numRow('时段最高预付款 $', (r) => r.s < 60 ? '·' : (r.mar > 0 ? Math.round(r.mar) : '0'), () => '#94a3b8');\n  const monRow = numRow('累计监测(分钟)', (r) => r.s < 60 ? '·' : Math.round(r.s / 60), () => '#64748b');\n  const lvRow = '<tr><td style=\"padding:4px 8px;white-space:nowrap;font-weight:800;color:#fff\">综合风险评级</td>' + rows.map((r) => { const L = level(r); return '<td title=\"风险分 ' + r.score + '\" style=\"text-align:center;font-size:13px;padding:4px 0;' + (r.hour === bjNowH ? 'outline:1px solid #38bdf8;' : '') + '\">' + L.e + '</td>'; }).join('') + '</tr>';\n\n  // 时段汇总 (亚盘/欧盘/美盘/清淡)\n  const sessDefs = [['🌏 亚盘', 8, 15, '#38bdf8'], ['🌍 欧盘', 15, 20, '#a78bfa'], ['🗽 美盘(20-24点)', 20, 24, '#fb923c'], ['🌙 美盘后半/夜盘(0-4点)', 0, 4, '#f97316'], ['😴 清淡期(4-8点)', 4, 8, '#64748b']];\n  const sessCards = sessDefs.map(([nm, a, b, col]) => {\n    const rs = rows.filter((r) => r.hour >= a && r.hour < b);\n    const mon = rs.reduce((x, r) => x + r.s, 0);\n    const w100 = rs.reduce((x, r) => x + r.w100, 0), w200 = rs.reduce((x, r) => x + r.w200, 0);\n    const mdd = Math.max(0, ...rs.map((r) => r.dd));\n    const sc = rs.reduce((x, r) => x + r.score, 0);\n    return '<div style=\"flex:1;min-width:150px;background:rgba(15,19,28,0.9);border:1px solid ' + col + '66;border-radius:8px;padding:7px 9px\"><div style=\"font-weight:800;color:' + col + ';font-size:12.5px\">' + nm + '</div><div class=\"xs\" style=\"line-height:1.55;color:#cbd5e1\">' + (mon < 60 ? '<span class=\"mut\">暂无监测数据</span>' : '深套≥$100: <b>' + w100 + '</b>次 · ≥$200: <b style=\"color:#fb923c\">' + w200 + '</b>次<br>最大浮亏 <b style=\"color:#fb7185\">-$' + Math.round(mdd) + '</b> · 风险分 <b>' + sc.toFixed(1) + '</b>') + '</div></div>';\n  }).join('');\n\n  const cur = rows[bjNowH], curLv = level(cur);\n  const curMsg = curLv.t === '高危' || curLv.t === '警惕'\n    ? '<span style=\"color:#fb7185;font-weight:800\">⚠️ 现在北京时间 ' + String(bjNowH).padStart(2, '0') + ':' + String(bjNowM).padStart(2, '0') + ' 正处于历史【' + curLv.t + '】时段，建议减少新开仓、控制层数</span>'\n    : curLv.t === '无数据' ? '<span class=\"mut\">当前时段(' + fmtRange(bjNowH) + ')尚无历史数据，持续监测中</span>'\n    : '<span style=\"color:#34d399;font-weight:800\">✅ 现在是历史【' + curLv.t + '】时段(' + fmtRange(bjNowH) + ')</span>';\n\n  const rankHtml = rank.length\n    ? rank.map((r, i) => { const L = level(r); return '<span class=\"pill ' + (L.t === '高危' ? 'TREND' : 'MIXED') + '\" style=\"font-size:11.5px;padding:3px 9px\">' + (i === 0 ? '🥇' : i === 1 ? '🥈' : i === 2 ? '🥉' : '#' + (i + 1)) + ' <b>' + fmtRange(r.hour) + '</b> ' + sessOf(r.hour)[0] + ' · 最大浮亏-$' + Math.round(r.dd) + ' · 深套' + r.w100 + '次</span>'; }).join(' ')\n    : '<span class=\"xs mut\">目前各时段尚未出现明显深套 (浮亏≥$50)，数据积累越久越准</span>';\n\n  return '<div style=\"margin-top:12px;background:linear-gradient(135deg,rgba(244,63,94,0.08),rgba(15,20,30,0.95));border:1.5px solid rgba(244,63,94,0.4);border-radius:10px;padding:11px 13px\">'\n    + '<div style=\"display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;margin-bottom:6px\"><b style=\"color:#fff;font-size:13.5px\">🕒 浮亏高危时段热力表 (北京时间 24 小时 × 浮亏阶梯 · 格内数字=该小时独立深套发生次数，颜色越红越危险)</b><span class=\"xs\">' + curMsg + '</span></div>'\n    + '<div style=\"margin-bottom:8px;display:flex;flex-wrap:wrap;gap:6px;align-items:center\"><b class=\"xs\" style=\"color:#fbbf24\">🚫 建议避开开仓的高危时段榜：</b>' + rankHtml + '</div>'\n    + '<div style=\"overflow-x:auto\"><table style=\"border-collapse:collapse;width:100%;font-size:12px\"><thead><tr><th style=\"text-align:left;padding:3px 8px;color:#94a3b8;font-size:11px\">阶梯 \\ 时(北京)</th>' + head + '</tr></thead><tbody>' + tierRows + ddRow + marRow + monRow + lvRow + '</tbody></table></div>'\n    + '<div style=\"display:flex;gap:8px;flex-wrap:wrap;margin-top:9px\">' + sessCards + '</div>'\n    + '<div class=\"xs mut\" style=\"margin-top:6px\">说明：以持仓期间每 5 秒采样累计；「·」=该小时尚无持仓数据，「~」=该级曾停留但未新增波次；蓝框=当前小时。风险分 = 深套次数×阶梯权重 + 深套停留时长 + 峰值浮亏，已统计 ' + monitored.length + '/24 个小时。数据随运行天数增加越来越有参考价值。</div>'\n    + '</div>';\n}\n\nfunction renderMt4CurveSection(d, mt4, mt4Dec, isMockAcc) {\n  const sec = $('mt4CurveSec');\n  if (!sec) return;\n  if (!mt4 || !mt4Dec) {\n    sec.style.display = 'none';\n    return;\n  }\n  sec.style.display = 'block';\n  const { history, historyLong, stats, initBal } = getMergedMt4History(mt4);\n  const closedProfit = r2((mt4.balance || 0) - initBal);\n  const netTotalProfit = r2((mt4.equity || 0) - initBal);\n  const closedPct = initBal > 0 ? r1((closedProfit / initBal) * 100) : 0;\n  const netRetPct = initBal > 0 ? r1((netTotalProfit / initBal) * 100) : 0;\n\n  const mode = MT4_CHART_STATE.mode || 'fast';\n  const useHist = mode === 'long' && historyLong.length ? historyLong : history;\n  const chartSvg = buildMt4AccountChartSvg(useHist, mt4, mt4Dec, initBal, stats, mode);\n\n  const pk = (stats && stats.peaks) || {\n    maxDd: { val: mt4Dec.ddUsd, pct: mt4Dec.ddPct, ts: mt4.ts, px: mt4Dec.curPx, buyCount: mt4.buyCount, buyLots: mt4.buyLots, sellCount: mt4.sellCount, sellLots: mt4.sellLots, netLots: mt4Dec.absNetLots, margin: mt4.margin, ml: mt4Dec.ml },\n    maxMargin: { val: mt4.margin, ts: mt4.ts, px: mt4Dec.curPx, buyCount: mt4.buyCount, buyLots: mt4.buyLots, sellCount: mt4.sellCount, sellLots: mt4.sellLots, totalLots: r2((mt4.buyLots || 0) + (mt4.sellLots || 0)), dd: mt4Dec.ddUsd, ml: mt4Dec.ml },\n    minMarginLevel: { val: mt4Dec.ml, freeMargin: mt4Dec.freeM, ts: mt4.ts, px: mt4Dec.curPx, dd: mt4Dec.ddUsd, margin: mt4.margin, buyCount: mt4.buyCount, sellCount: mt4.sellCount },\n    minEquity: { val: mt4.equity, bal: mt4.balance, ts: mt4.ts, px: mt4Dec.curPx, dd: mt4Dec.ddUsd },\n    maxBalance: { val: mt4.balance, ts: mt4.ts },\n    maxLayers: { val: Math.max(mt4.buyCount || 0, mt4.sellCount || 0), side: '-', lots: r2((mt4.buyLots || 0) + (mt4.sellLots || 0)), netLots: mt4Dec.absNetLots, ts: mt4.ts }\n  };\n\n  // ========== 基于历史峰值的「账户到底该放多少钱」3档科学本金测算模型 ==========\n  // 原理：账户资金 = 历史最大浮亏 × 安全放大倍数 + 历史最高预付款 × 目标最低预付款比例\n  const obsMaxDd = Math.max(pk.maxDd.val || 0, mt4Dec.ddUsd || 0, 80);\n  const obsMaxMar = Math.max(pk.maxMargin.val || 0, mt4.margin || 0, 40);\n  // 1) 保底不断头本金：扛住 1.25倍历史峰值浮亏 且 预付款比例 ≥ 135%（保证不断开仓/锁仓权）\n  const capTier1 = Math.ceil((obsMaxDd * 1.25 + obsMaxMar * 1.35) / 10) * 10;\n  // 2) 稳健标准本金（推荐）：扛住 1.6倍历史峰值浮亏（或至少$350浮亏）且 预付款比例稳守 ≥ 220%\n  const capTier2 = Math.ceil((Math.max(obsMaxDd * 1.6, 300) + obsMaxMar * 2.2) / 50) * 50;\n  // 3) 机构级抗大单边本金：扛住 2.5倍历史峰值浮亏（或$600~$800大单边阶梯）且 预付款比例 ≥ 320%\n  const capTier3 = Math.ceil((Math.max(obsMaxDd * 2.5, 650) + obsMaxMar * 3.2) / 50) * 50;\n\n  const curBal = mt4.balance || 0;\n  const gapTier1 = r2(Math.max(0, capTier1 - curBal));\n  const gapTier2 = r2(Math.max(0, capTier2 - curBal));\n  const gapTier3 = r2(Math.max(0, capTier3 - curBal));\n\n  // ========== 浮亏分阶段突破次数统计表 ($50 / $100 / $150 / $200 / $300 / $400 / $600 / $800 / $1000 / $1500 / $2000) ==========\n  const tiers = (stats && Array.isArray(stats.tiers) && stats.tiers.length)\n    ? stats.tiers\n    : MT4_DD_TIERS_DEF.map((th) => ({ th, waves: 0, recovered: 0, active: false, durSec: 0, maxDd: 0, maxMar: 0, lastTs: 0, lastPx: 0, lastPos: '-' }));\n\n  const tierRowsHtml = tiers.map((t) => {\n    const isHitEver = (t.waves || 0) > 0 || (t.durSec || 0) > 0;\n    const isNowActive = mt4Dec.ddUsd >= t.th;\n    const isKeyMilestone = [100, 200, 400, 600, 800, 1000, 1500, 2000].includes(t.th);\n    const needCapForThisTier = Math.ceil((t.th * 1.2 + Math.max(t.maxMar || obsMaxMar, t.th * 0.55) * 1.5) / 20) * 20;\n    const canCurrentBalSurvive = curBal >= (t.th + (t.maxMar || obsMaxMar) * 0.5);\n    const rowBg = isNowActive\n      ? 'rgba(244,63,94,0.18)'\n      : isHitEver\n      ? 'rgba(245,158,11,0.08)'\n      : 'transparent';\n    return `<tr style=\"background:${rowBg};${isKeyMilestone ? 'font-weight:700;' : ''}\">\n      <td>\n        <span style=\"color:${t.th >= 400 ? '#fb7185' : t.th >= 200 ? '#fbbf24' : '#38bdf8'};font-weight:800\">浮亏 ≥ $${t.th}</span>\n        ${isNowActive ? `<span class=\"pill TREND\" style=\"margin-left:4px;padding:1px 6px;font-size:10px\">🔥 当前正处此级</span>` : ''}\n      </td>\n      <td><b style=\"font-size:14.5px;color:${(t.waves || 0) > 0 ? '#fbbf24' : '#64748b'}\">${t.waves || 0} 次</b></td>\n      <td><span style=\"color:#34d399;font-weight:700\">${t.recovered || 0} 次解套</span></td>\n      <td>${t.durSec > 0 ? `<b style=\"color:#e2e8f0\">${fmtDuration(t.durSec)}</b>` : '<span class=\"mut\">0秒</span>'}</td>\n      <td>${t.maxMar > 0 ? `预付款 <b>$${f2(t.maxMar)}</b> / 峰值亏 <b style=\"color:#fb7185\">-$${f2(t.maxDd)}</b>` : '<span class=\"mut\">未触及</span>'}</td>\n      <td class=\"xs\">${t.lastTs ? `${fmtSecTime(t.lastTs)} · $${f2(t.lastPx)} · ${t.lastPos || ''}` : '<span class=\"mut\">-</span>'}</td>\n      <td>\n        <b style=\"color:var(--gold)\">建议 ≥ $${needCapForThisTier}</b>\n        <span class=\"pill ${canCurrentBalSurvive ? 'RANGE' : 'TREND'}\" style=\"font-size:10px;padding:1px 5px;margin-left:4px\">${canCurrentBalSurvive ? '当前余额可扛' : '当前余额会爆仓'}</span>\n      </td>\n    </tr>`;\n  }).join('');\n\n  // 重大深套战役日志 (含当前进行中的 activeWave + 历史已结束的 waveLog)\n  const waveItems = [];\n  if (stats && stats.activeWave) {\n    waveItems.push({ ...stats.activeWave, status: 'ACTIVE', durSec: Math.max(5, Math.floor(Date.now() / 1000) - stats.activeWave.startTs) });\n  }\n  if (stats && Array.isArray(stats.waveLog)) {\n    waveItems.push(...stats.waveLog.slice(0, 12));\n  }\n  const waveLogHtml = waveItems.length\n    ? waveItems.map((w, idx) => {\n        const isLive = w.status === 'ACTIVE';\n        return `<div style=\"padding:7px 10px;border-radius:7px;background:${isLive ? 'rgba(244,63,94,0.16)' : 'rgba(15,23,42,0.75)'};border:1px solid ${isLive ? 'rgba(244,63,94,0.6)' : 'var(--bd)'};font-size:12px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px\">\n          <div>\n            <span class=\"pill ${isLive ? 'TREND' : 'RANGE'}\" style=\"font-size:10.5px;margin-right:6px\">${isLive ? '🔥 当前正在扛单中' : '✅ 已止盈解套'}</span>\n            <b>战役 #${waveItems.length - idx}</b> (${fmtSecTime(w.startTs)} ${isLive ? '至今' : `~ ${fmtSecTime(w.endTs)}`} · 历时 <b>${fmtDuration(w.durSec)}</b>)\n          </div>\n          <div style=\"display:flex;gap:10px;flex-wrap:wrap\">\n            <span>最大浮亏峰值: <b style=\"color:#fb7185\">-$${f2(w.peakDd)} (${w.peakDdPct || 0}%)</b></span>\n            <span>最高预付款: <b style=\"color:#fbbf24\">$${f2(w.peakMargin)}</b></span>\n            <span>最低预付款比: <b style=\"color:${(w.minMl || 999) < 150 ? '#fb7185' : '#38bdf8'}\">${f2(w.minMl)}%</b></span>\n            <span>最高层数/手数: <b>${w.posAtPeak || (w.maxLayers + '层/' + w.maxLots + '手')}</b></span>\n          </div>\n        </div>`;\n      }).join('')\n    : `<div class=\"xs mut\">暂无浮亏超过 $30 的深套战役记录（系统正每 5 秒全天候自动监测记录中）</div>`;\n\n  sec.innerHTML = `\n    <div class=\"vhead\" style=\"margin-bottom:10px\">\n      <div style=\"display:flex;align-items:center;gap:10px;flex-wrap:wrap\">\n        <h2 style=\"margin:0\">💰 MT4 实盘账户：历史峰值档案 · 浮亏阶梯次数统计 · 入金备付决策 &amp; 收益曲线图</h2>\n        <span class=\"pill ${mt4Dec.healthCls}\">账户 #${mt4.account} (${mt4.server || 'MT4'}) · 安全分 ${mt4Dec.accountHealthScore}/100</span>\n        <span class=\"xs mut\">📦 云端 Redis 永久归档 + 本地双备份 · 已累计监测 <b>${stats ? (stats.totalSamples || 1) : 1}</b> 次实盘切片 (自 ${stats ? fmtSecTime(stats.sinceTs) : '今日'} 起)</span>\n      </div>\n      <div class=\"btns\">\n        <button class=\"sm ${mode === 'fast' ? 'on' : ''}\" onclick=\"setMt4CurveMode('fast')\">⚡ 高频曲线 (近2小时·30s极值)</button>\n        <button class=\"sm ${mode === 'long' ? 'on' : ''}\" onclick=\"setMt4CurveMode('long')\">📅 长周期历史归档 (7~30天·15m极值包络)</button>\n        <button class=\"sm\" onclick=\"resetMt4CurveBase()\" title=\"以当前余额 $${f2(mt4.balance)} 作为新的零点基准重算累计收益曲线\">🎯 重置收益起点</button>\n        <button class=\"sm\" onclick=\"resetMt4AllStats()\" style=\"color:#94a3b8\" title=\"清空历史峰值与阶梯次数，重新开始统计\">🧹 清零峰值统计</button>\n      </div>\n    </div>\n\n    <!-- 第一排：实时状态 4 大 KPI -->\n    <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(235px,1fr));gap:10px;margin-bottom:12px\">\n      <div style=\"background:rgba(15,23,42,0.9);border:1px solid rgba(251,191,36,0.45);border-radius:9px;padding:10px 12px\">\n        <div class=\"xs mut\" style=\"display:flex;justify-content:space-between\"><span>💰 账户实时余额 (Balance)</span><span>起点基准 $${f2(initBal)}</span></div>\n        <div style=\"display:flex;align-items:baseline;justify-content:space-between;margin:4px 0\">\n          <b style=\"font-size:23px;color:var(--gold)\">$${f2(mt4.balance)}</b>\n          <span class=\"pill ${closedProfit >= 0 ? 'RANGE' : 'TREND'}\">已落袋 ${closedProfit >= 0 ? '+' : ''}$${f2(closedProfit)} (${closedPct >= 0 ? '+' : ''}${closedPct}%)</span>\n        </div>\n        <div class=\"xs mut\">历史最高余额: <b>$${f2(pk.maxBalance.val || mt4.balance)}</b></div>\n      </div>\n\n      <div style=\"background:rgba(15,23,42,0.9);border:1px solid ${mt4.totalPnl >= 0 ? 'rgba(16,185,129,0.5)' : 'rgba(244,63,94,0.55)'};border-radius:9px;padding:10px 12px\">\n        <div class=\"xs mut\" style=\"display:flex;justify-content:space-between\"><span>📉 账户实时净值 (Equity)</span><span>当前回撤 ${mt4Dec.ddPct}%</span></div>\n        <div style=\"display:flex;align-items:baseline;justify-content:space-between;margin:4px 0\">\n          <b style=\"font-size:23px;color:${mt4.totalPnl >= 0 ? '#34d399' : '#38bdf8'}\">$${f2(mt4.equity)}</b>\n          <span class=\"pill ${mt4.totalPnl >= 0 ? 'RANGE' : 'TREND'}\">当前浮盈亏 ${mt4.totalPnl >= 0 ? '+' : ''}$${f2(mt4.totalPnl)}</span>\n        </div>\n        <div class=\"xs\" style=\"color:#cbd5e1\">历史最低净值谷底: <b style=\"color:#fb7185\">$${f2(pk.minEquity.val || mt4.equity)}</b></div>\n      </div>\n\n      <div style=\"background:rgba(15,23,42,0.9);border:1px solid rgba(56,189,248,0.45);border-radius:9px;padding:10px 12px\">\n        <div class=\"xs mut\" style=\"display:flex;justify-content:space-between\"><span>🎯 实盘多空回本与整组止盈价</span><span>实时推演价 $${f2(mt4Dec.curPx)}</span></div>\n        <div style=\"margin:4px 0;font-size:12.5px;line-height:1.5\">\n          • 重仓回本均价: <b style=\"color:var(--gold);font-size:14px\">$${f2(mt4Dec.heavyBreakEvenPx)}</b> <span class=\"xs mut\">(差 $${f2(mt4Dec.needHeavyBeMove)})</span><br>\n          • <b>马丁整组止盈清仓价</b>: <b style=\"color:#34d399;font-size:14px\">$${f2(mt4Dec.heavyTpPx)}</b> <span class=\"xs mut\">(差 $${f2(mt4Dec.needHeavyTpMove)})</span>\n        </div>\n        <div class=\"xs mut\">买${mt4.buyCount}层/${f2(mt4.buyLots)}手($${f2(mt4.buyAvgPrice)}) | 卖${mt4.sellCount}层/${f2(mt4.sellLots)}手($${f2(mt4.sellAvgPrice)})</div>\n      </div>\n\n      <div style=\"background:rgba(15,23,42,0.9);border:1px solid ${mt4Dec.ml < 220 ? 'rgba(244,63,94,0.65)' : 'rgba(148,163,184,0.35)'};border-radius:9px;padding:10px 12px\">\n        <div class=\"xs mut\" style=\"display:flex;justify-content:space-between\"><span>🛡️ 实时预付款比例 &amp; 生死线</span><span>已用 $${f2(mt4.margin)} / 可用 $${f2(mt4Dec.freeM)}</span></div>\n        <div style=\"display:flex;align-items:baseline;justify-content:space-between;margin:4px 0\">\n          <b style=\"font-size:22px;color:${mt4Dec.ml < 200 ? '#fb7185' : mt4Dec.ml < 350 ? '#fbbf24' : '#34d399'}\">${f2(mt4Dec.ml)}%</b>\n          <span class=\"xs\" style=\"color:#fb7185;font-weight:700\">🚨 100%锁死价: $${f2(mt4Dec.margin100Px)}</span>\n        </div>\n        <div class=\"xs\" style=\"color:#cbd5e1\">⚡ 对冲防线: <b style=\"color:var(--gold)\">$${f2(mt4Dec.hedgeTriggerPx)}</b> | 50%强平: <b style=\"color:#fb7185\">$${f2(mt4Dec.stopOut50Px)}</b></div>\n      </div>\n    </div>\n\n    <!-- 第二排：🏆 账户历史 4 大极值峰值纪念碑（专为评估账户最大压力与资金配置设计） -->\n    <div style=\"margin-bottom:12px;padding:11px 13px;background:linear-gradient(135deg,rgba(244,63,94,0.11),rgba(15,23,42,0.95));border:1.5px solid rgba(244,63,94,0.45);border-radius:10px\">\n      <div style=\"display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;margin-bottom:8px\">\n        <b style=\"color:#fff;font-size:13.5px\">🏆 您的账户历史「峰值压力档案」 (每 5 秒捕捉极值 · 刷新历史峰值时立即永久写入云端 Redis，绝不漏掉任何一次插针)</b>\n        <span class=\"pill MIXED\" style=\"font-size:11px\">决定您账户最少要放多少本金的核心依据</span>\n      </div>\n      <div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:10px\">\n        <!-- 峰值 1：历史最大浮亏峰值 -->\n        <div style=\"background:rgba(15,19,28,0.92);border:1px solid rgba(244,63,94,0.5);border-radius:8px;padding:9px 11px\">\n          <div class=\"xs mut\">🔥 ① 历史最大浮亏峰值 (Max Drawdown)</div>\n          <div style=\"display:flex;align-items:baseline;justify-content:space-between;margin:4px 0\">\n            <b style=\"font-size:22px;color:#fb7185\">-$${f2(pk.maxDd.val)}</b>\n            <span class=\"pill TREND\">占当时本金 ${pk.maxDd.pct || 0}%</span>\n          </div>\n          <div class=\"xs\" style=\"color:#cbd5e1;line-height:1.45\">\n            • 发生时间: <b>${fmtSecTime(pk.maxDd.ts)}</b> (金价 $${f2(pk.maxDd.px)})<br>\n            • 当时持仓: <b>买${pk.maxDd.buyCount || 0}层(${f2(pk.maxDd.buyLots)}手)/卖${pk.maxDd.sellCount || 0}层(${f2(pk.maxDd.sellLots)}手)</b><br>\n            • 当时预付款: <b>$${f2(pk.maxDd.margin)}</b> (比例 ${f2(pk.maxDd.ml)}%)\n          </div>\n        </div>\n\n        <!-- 峰值 2：历史最高预付款占用峰值 -->\n        <div style=\"background:rgba(15,19,28,0.92);border:1px solid rgba(251,191,36,0.5);border-radius:8px;padding:9px 11px\">\n          <div class=\"xs mut\">🏦 ② 历史最高预付款峰值 (Peak Margin)</div>\n          <div style=\"display:flex;align-items:baseline;justify-content:space-between;margin:4px 0\">\n            <b style=\"font-size:22px;color:#fbbf24\">$${f2(pk.maxMargin.val)}</b>\n            <span class=\"pill MIXED\">合计 ${f2(pk.maxMargin.totalLots)} 手</span>\n          </div>\n          <div class=\"xs\" style=\"color:#cbd5e1;line-height:1.45\">\n            • 发生时间: <b>${fmtSecTime(pk.maxMargin.ts)}</b> (金价 $${f2(pk.maxMargin.px)})<br>\n            • 当时层数: <b>买${pk.maxMargin.buyCount || 0}层(${f2(pk.maxMargin.buyLots)}手)/卖${pk.maxMargin.sellCount || 0}层(${f2(pk.maxMargin.sellLots)}手)</b><br>\n            • 伴随浮亏: <b style=\"color:#fb7185\">-$${f2(pk.maxMargin.dd)}</b> (预付款比 ${f2(pk.maxMargin.ml)}%)\n          </div>\n        </div>\n\n        <!-- 峰值 3：历史最低预付款比例险情值 -->\n        <div style=\"background:rgba(15,19,28,0.92);border:1px solid rgba(244,63,94,0.5);border-radius:8px;padding:9px 11px\">\n          <div class=\"xs mut\">🚨 ③ 历史最低预付款比例 (Min Margin Level)</div>\n          <div style=\"display:flex;align-items:baseline;justify-content:space-between;margin:4px 0\">\n            <b style=\"font-size:22px;color:${(pk.minMarginLevel.val || 999) < 150 ? '#fb7185' : '#fbbf24'}\">${f2(pk.minMarginLevel.val)}%</b>\n            <span class=\"pill ${(pk.minMarginLevel.val || 999) < 130 ? 'TREND' : 'MIXED'}\">仅余可用 $${f2(pk.minMarginLevel.freeMargin)}</span>\n          </div>\n          <div class=\"xs\" style=\"color:#cbd5e1;line-height:1.45\">\n            • 发生时间: <b>${fmtSecTime(pk.minMarginLevel.ts)}</b> (金价 $${f2(pk.minMarginLevel.px)})<br>\n            • 距100%锁死线仅差: <b style=\"color:#fb7185\">${f2(Math.max(0, (pk.minMarginLevel.val || 100) - 100))}%</b><br>\n            • 当时状态: 浮亏 <b>-$${f2(pk.minMarginLevel.dd)}</b> + 预付款 <b>$${f2(pk.minMarginLevel.margin)}</b>\n          </div>\n        </div>\n\n        <!-- 峰值 4：历史最高马丁层数 & 资金配置建议摘要 -->\n        <div style=\"background:rgba(15,19,28,0.92);border:1px solid rgba(56,189,248,0.5);border-radius:8px;padding:9px 11px\">\n          <div class=\"xs mut\">📐 ④ 历史最高层数 &amp; 峰值总资金占用 (浮亏+预付款)</div>\n          <div style=\"display:flex;align-items:baseline;justify-content:space-between;margin:4px 0\">\n            <b style=\"font-size:20px;color:#38bdf8\">最高 ${pk.maxLayers.val || 0} 层 (${f2(pk.maxLayers.lots)}手)</b>\n            <span class=\"pill RANGE\">净敞口 ${f2(pk.maxLayers.netLots)}手</span>\n          </div>\n          <div class=\"xs\" style=\"color:#cbd5e1;line-height:1.45\">\n            • <b>历史极值总占用 (峰值浮亏+峰值预付款)</b>: <b style=\"color:var(--gold)\">$${f2((pk.maxDd.val || 0) + (pk.maxMargin.val || 0))}</b><br>\n            • <b>保底不断头需放</b>: <b style=\"color:#fbbf24\">$${capTier1}</b> ${gapTier1 > 0 ? `(当前差 <b style=\"color:#fb7185\">+$${f2(gapTier1)}</b>)` : '(✅已达标)'}<br>\n            • <b>稳健推荐配置本金</b>: <b style=\"color:#34d399\">$${capTier2}</b> ${gapTier2 > 0 ? `(建议补 <b style=\"color:var(--gold)\">+$${f2(gapTier2)}</b>)` : '(✅已达标)'}\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <!-- 第三排：实时余额/净值/预付款/收益双面板交互曲线图 -->\n    ${chartSvg}\n\n    <!-- 第三排半：24小时浮亏高危时段热力表 -->\n    ${buildMt4HourHeatmap(stats, mt4Dec)}\n\n    <!-- 第四排：📊 浮亏分阶段突破次数统计表 ($50 ~ $2000) & 💰 后期账户放多少钱决策测算器 -->\n    <div style=\"display:grid;grid-template-columns:1.45fr 1fr;gap:12px;margin-top:12px\">\n      <!-- 左侧：浮亏超过 50 / 100 / 200 / 400 / 600 / 800 / 1000... 阶段次数统计表 -->\n      <div style=\"background:rgba(15,20,30,0.92);border:1px solid var(--bd);border-radius:10px;padding:11px 13px;overflow-x:auto\">\n        <div style=\"display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;margin-bottom:8px\">\n          <b style=\"color:var(--gold);font-size:13.5px\">📊 账户浮亏分阶段突破次数统计表 (独立深套波次计数 · 含 $200 / $400 / $600 / $1000+ 阶梯)</b>\n          <span class=\"xs mut\">同一轮马丁扛单不重复刷次数，平仓解套重置后再次突破才计为下一波</span>\n        </div>\n        <table class=\"tbl\" style=\"font-size:12px\">\n          <thead>\n            <tr>\n              <th>浮亏金额阶梯</th>\n              <th>独立发生次数</th>\n              <th>成功解套次数</th>\n              <th>累计停留时长</th>\n              <th>该级最大预付款 / 峰值浮亏</th>\n              <th>最近一次触发记录</th>\n              <th>扛过该级所需本金</th>\n            </tr>\n          </thead>\n          <tbody>\n            ${tierRowsHtml}\n          </tbody>\n        </table>\n      </div>\n\n      <!-- 右侧：💰 后期往账户放多少钱？三档本金配置决策器 + 历史深套战役档案 -->\n      <div style=\"display:flex;flex-direction:column;gap:10px\">\n        <div style=\"background:linear-gradient(135deg,rgba(16,185,129,0.10),rgba(15,23,42,0.95));border:1px solid rgba(16,185,129,0.45);border-radius:10px;padding:11px 13px\">\n          <b style=\"color:#34d399;font-size:13.5px\">💰 决策模型：根据您的实盘峰值，账户到底该放多少钱？</b>\n          <div class=\"xs mut\" style=\"margin:4px 0 8px\">基于您实测录得的 <b>最大浮亏 (-$${f2(pk.maxDd.val)})</b> + <b>最高预付款 ($${f2(pk.maxMargin.val)})</b> 自动推演：</div>\n\n          <div style=\"display:flex;flex-direction:column;gap:7px;font-size:12px\">\n            <div style=\"padding:8px 10px;background:rgba(15,19,28,0.9);border-left:3px solid #fbbf24;border-radius:6px\">\n              <div style=\"display:flex;justify-content:space-between\">\n                <b>① 🛡️ 保底不断头本金（防100%预付款锁死）</b>\n                <b style=\"color:#fbbf24;font-size:14px\">建议放 $${capTier1}</b>\n              </div>\n              <div class=\"xs mut\" style=\"margin-top:2px\">\n                可扛住历史最大浮亏再扩大 25%（约 -$${Math.round(obsMaxDd * 1.25)}）且预付款比例 ≥135% 不断开仓权。\n                ${gapTier1 > 0 ? `<b style=\"color:#fb7185\">您当前余额 $${f2(curBal)}，至少需补 +$${f2(gapTier1)}！</b>` : `<b style=\"color:#34d399\">您当前余额 $${f2(curBal)} 已满足此档！</b>`}\n              </div>\n            </div>\n\n            <div style=\"padding:8px 10px;background:rgba(15,19,28,0.9);border-left:3px solid #34d399;border-radius:6px\">\n              <div style=\"display:flex;justify-content:space-between\">\n                <b>② ⚖️ 稳健标准本金（推荐 · 扛住 $200~$350 阶梯）</b>\n                <b style=\"color:#34d399;font-size:14px\">建议放 $${capTier2}</b>\n              </div>\n              <div class=\"xs mut\" style=\"margin-top:2px\">\n                当遭遇 7~8 层单边（浮亏达 $${Math.max(300, Math.round(obsMaxDd * 1.6))}、预付款达 $${Math.round(obsMaxMar * 1.5)}）时，预付款比例依然稳居 220%+，可从容等待 $2.7 反抽清仓。\n                ${gapTier2 > 0 ? `<span style=\"color:var(--gold)\">距当前余额差 <b>+$${f2(gapTier2)}</b></span>` : `<b style=\"color:#34d399\">已达标</b>`}\n              </div>\n            </div>\n\n            <div style=\"padding:8px 10px;background:rgba(15,19,28,0.9);border-left:3px solid #38bdf8;border-radius:6px\">\n              <div style=\"display:flex;justify-content:space-between\">\n                <b>③ 🏰 抗极端大单边本金（扛住 $400~$650+ 阶梯）</b>\n                <b style=\"color:#38bdf8;font-size:14px\">建议放 $${capTier3}</b>\n              </div>\n              <div class=\"xs mut\" style=\"margin-top:2px\">\n                专为应对美盘 CPI/非农或无回调推土机行情（浮亏冲上 $400~$600 阶梯）设计，建议采用<b>「账户内放 $${capTier2} + 场外备付金 $${capTier3 - capTier2} 随时秒入金」</b>的隔离风控模式！\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- 历史重大深套战役日志 -->\n        <div style=\"background:rgba(15,20,30,0.92);border:1px solid var(--bd);border-radius:10px;padding:11px 13px\">\n          <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:6px\">\n            <b style=\"color:#fff;font-size:13px\">📜 历次深套扛单战役档案 (浮亏 ≥ $30 自动立档)</b>\n            <span class=\"xs mut\">共记录 ${waveItems.length} 场战役</span>\n          </div>\n          <div style=\"display:flex;flex-direction:column;gap:6px;max-height:210px;overflow-y:auto\">\n            ${waveLogHtml}\n          </div>\n        </div>\n      </div>\n    </div>\n  `;\n}\n\n// 每 8 秒轻量检查一次 /api/mt4 是否有最新 MT4 实盘推送 (配合服务端 8s 内存缓存与页面后台休眠，极致节省 Redis 额度)\nsetInterval(async () => {\n  if (!D || document.hidden) return; // 页面在后台时暂停轮询，节省 Redis 额度\n  try {\n    const r = await fetch('/api/mt4');\n    if (!r.ok) return;\n    const j = await r.json();\n    if (j && j.connected && j.mt4) {\n      const prevTs = D.mt4 ? D.mt4.ts : 0;\n      if (j.mt4.ts !== prevTs) {\n        D.mt4 = j.mt4;\n        render();\n      }\n    } else if (j && !j.connected && D.mt4) {\n      delete D.mt4;\n      render();\n    }\n  } catch (e) {}\n}, 8000);\n// 1) 打开网页瞬间(0ms)：立即从浏览器 localStorage 恢复上次缓存秒开渲染，杜绝白屏等待\ntry {\n  const cachedStr = localStorage.getItem(LOCAL_DATA_CACHE_KEY);\n  if (cachedStr) {\n    const parsed = JSON.parse(cachedStr);\n    if (parsed && parsed.timeframes) {\n      D = parsed;\n      render();\n    }\n  }\n} catch (e) {}\n\n// 2) 紧接着立即请求 fast=1 极速实时接口(~0.4s)，秒级更新 1M/5M/15M/1H/4H 黄金价格与震荡指数、跨市场报价与特朗普快讯\nload(false, true);\nsetInterval(() => load(false, true), 15 * 1000);       // 经常更新的数据(1M~4H/跨市场/特朗普)每 15 秒实时获取\nsetInterval(() => load(false, false, true), 15 * 60 * 1000); // 低频数据(日线kNN/GVZ/金十周历)每 15 分钟后台静默同步\n</script>\n</body>\n</html>\n";
